-- DTC Veritabanı: OBDex (foerbsnavi/OBDex, MIT) — 9204 kod
CREATE TABLE IF NOT EXISTS dtc_codes (
  code TEXT PRIMARY KEY,
  category TEXT,
  title_en TEXT,
  title_de TEXT,
  desc_en TEXT,
  desc_de TEXT,
  parts TEXT,
  causes TEXT,
  repair TEXT,
  mil INTEGER DEFAULT 0
);

INSERT OR IGNORE INTO dtc_codes VALUES('P0001','P','Fuel Volume Regulator A Control Circuit/Open','Kraftstoffmengenregelventil A Schaltkreis unterbrochen','The ECU detects an open circuit in the control of fuel volume regulator A (often the metering valve on the high-pressure fuel pump). The actuator does not respond, so rail pressure cannot be controlled accurately.','Die Motorsteuerung erkennt einen unterbrochenen Schaltkreis am Kraftstoffmengenregelventil A (meist das Zumessventil der Hochdruckpumpe). Der Aktuator reagiert nicht, der Raildruck kann nicht geregelt werden.','["fuel_volume_regulator", "high_pressure_fuel_pump", "fvr_wiring", "fvr_connector"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break or unplugged connector", "de": "Kabelbruch oder abgezogener Stecker"}, {"id": "regulator_coil_open", "p": "medium", "en": "Regulator solenoid coil open", "de": "Magnetspule im Regelventil unterbrochen"}, {"id": "ecu_driver_fault", "p": "low", "en": "ECU output driver failed", "de": "Endstufe im Steuerger\u00e4t defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0002','P','Fuel Volume Regulator A Control Circuit Range/Performance','Kraftstoffmengenregelventil A Schaltkreis Bereich/Leistung','The control signal of fuel volume regulator A is electrically present but the actual rail pressure does not follow the target value within tolerance. Indicates a mechanical or hydraulic issue rather than pure wiring.','Das Steuersignal des Kraftstoffmengenregelventils A liegt elektrisch an, der tatsächliche Raildruck folgt jedoch nicht innerhalb der Toleranz. Hinweis auf ein mechanisches oder hydraulisches Problem statt reiner Verkabelung.','["fuel_volume_regulator", "high_pressure_fuel_pump", "fuel_rail_pressure_sensor"]','[{"id": "pump_wear", "p": "high", "en": "High-pressure pump worn or leaking internally", "de": "Hochdruckpumpe verschlissen oder intern undicht"}, {"id": "regulator_sticking", "p": "medium", "en": "Regulator valve sticking from contamination", "de": "Regelventil klemmt durch Verschmutzung"}, {"id": "pressure_sensor_drift", "p": "medium", "en": "Rail pressure sensor reading drifted", "de": "Raildrucksensor liefert verschobenen Messwert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0003','P','Fuel Volume Regulator A Control Circuit Low','Kraftstoffmengenregelventil A Schaltkreis niedrig','The ECU sees the control voltage of fuel volume regulator A pulled below the expected range, typically a short to ground or a low-resistance fault in the wiring or coil.','Die Steuerspannung am Kraftstoffmengenregelventil A liegt unter dem Sollbereich. Meist Kurzschluss gegen Masse oder niederohmige Verkabelung/Spule.','["fuel_volume_regulator", "fvr_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "coil_short", "p": "medium", "en": "Regulator coil internal short", "de": "Magnetspule mit Windungsschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0004','P','Fuel Volume Regulator A Control Circuit High','Kraftstoffmengenregelventil A Schaltkreis hoch','The ECU sees the control voltage of fuel volume regulator A above the expected range, typically a short to power or open ground return.','Die Steuerspannung am Kraftstoffmengenregelventil A liegt über dem Sollbereich. Meist Kurzschluss gegen Plus oder unterbrochener Masserückleiter.','["fuel_volume_regulator", "fvr_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "open_ground", "p": "medium", "en": "Open ground return path", "de": "Masser\u00fcckleiter unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0005','P','Fuel Shutoff Valve A Control Circuit/Open','Kraftstoffabsperrventil A Schaltkreis unterbrochen','Open circuit detected at the fuel shutoff valve A solenoid (used on diesels to stop fuel flow at engine-off and as anti-theft). Engine may not start or not stop cleanly.','Unterbrechung am Kraftstoffabsperrventil A (bei Dieseln zum Motorstopp und als Diebstahlschutz). Motor startet evtl. nicht oder läuft nach.','["fuel_shutoff_valve", "shutoff_wiring", "shutoff_connector"]','[{"id": "open_wiring", "p": "high", "en": "Open wiring or unplugged connector", "de": "Kabelbruch oder loser Stecker"}, {"id": "solenoid_open", "p": "medium", "en": "Shutoff solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [70, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0006','P','Fuel Shutoff Valve A Control Circuit Low','Kraftstoffabsperrventil A Schaltkreis niedrig','Control voltage of fuel shutoff valve A is below the expected range, typically caused by a short to ground or low-resistance fault in the solenoid circuit.','Die Steuerspannung am Kraftstoffabsperrventil A liegt unter dem Sollbereich. Meist Masseschluss oder niederohmiger Fehler im Magnetkreis.','["fuel_shutoff_valve", "shutoff_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "solenoid_short", "p": "medium", "en": "Shutoff solenoid internal short", "de": "Magnetspule mit Windungsschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [70, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0007','P','Fuel Shutoff Valve A Control Circuit High','Kraftstoffabsperrventil A Schaltkreis hoch','Control voltage of fuel shutoff valve A is above the expected range, typically caused by a short to power or open ground return.','Die Steuerspannung am Kraftstoffabsperrventil A liegt über dem Sollbereich. Meist Plus-Schluss oder unterbrochene Masse.','["fuel_shutoff_valve", "shutoff_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "open_ground", "p": "medium", "en": "Open ground return path", "de": "Masser\u00fcckleiter unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [70, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0008','P','Engine Position System Performance Bank 1','Motorpositions-System Leistung Bank 1','The ECU detects an implausible relationship between crankshaft and camshaft signals on bank 1, indicating timing chain stretch, jumped tooth, or sensor reluctor wear.','Die Motorsteuerung erkennt eine unplausible Lage zwischen Kurbel- und Nockenwellensignal auf Bank 1. Hinweis auf gelängte Steuerkette, übergesprungenen Zahn oder verschlissene Geberrad.','["timing_chain", "crankshaft_position_sensor", "camshaft_position_sensor", "reluctor_ring"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain stretched, guides worn", "de": "Steuerkette gel\u00e4ngt, Gleitschienen verschlissen"}, {"id": "jumped_tooth", "p": "medium", "en": "Chain jumped one tooth", "de": "Kette um einen Zahn \u00fcbergesprungen"}, {"id": "sensor_misalignment", "p": "low", "en": "Crankshaft or camshaft sensor misaligned", "de": "Kurbel- oder Nockenwellensensor falsch sitzend"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [4, 12]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0009','P','Engine Position System Performance Bank 2','Motorpositions-System Leistung Bank 2','Same fault pattern as P0008 but on bank 2 of a V or boxer engine. Crank/cam correlation outside spec on the second cylinder bank.','Gleicher Fehler wie P0008, jedoch auf Bank 2 eines V- oder Boxermotors. Korrelation Kurbel/Nockenwelle Bank 2 außerhalb der Spezifikation.','["timing_chain", "crankshaft_position_sensor", "camshaft_position_sensor", "reluctor_ring"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain bank 2 stretched", "de": "Steuerkette Bank 2 gel\u00e4ngt"}, {"id": "jumped_tooth", "p": "medium", "en": "Chain jumped one tooth on bank 2", "de": "Kette auf Bank 2 \u00fcbergesprungen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [4, 12]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000A','P','A Camshaft Position Slow Response Bank 1','A-Nockenwellenposition langsame Reaktion Bank 1','The intake camshaft phaser on bank 1 responds too slowly to commanded position changes. Often caused by VVT solenoid sticking, oil aging, or low oil pressure.','Der Einlass-Nockenwellenversteller auf Bank 1 reagiert zu langsam auf Sollwerte. Häufig durch klemmendes VVT-Magnetventil, Ölalterung oder zu geringen Öldruck.','["vvt_solenoid_intake_bank1", "cam_phaser_intake", "engine_oil"]','[{"id": "vvt_solenoid_clogged", "p": "high", "en": "VVT solenoid clogged with sludge", "de": "VVT-Magnetventil durch Schlamm verstopft"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure or wrong oil viscosity", "de": "Zu geringer \u00d6ldruck oder falsche Viskosit\u00e4t"}, {"id": "phaser_wear", "p": "medium", "en": "Cam phaser worn internally", "de": "Nockenwellenversteller intern verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 1200], "estimated_hours": [0.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000B','P','B Camshaft Position Slow Response Bank 1','B-Nockenwellenposition langsame Reaktion Bank 1','The exhaust camshaft phaser on bank 1 responds too slowly to commanded position changes. Same root causes as P000A but on the exhaust cam.','Der Auslass-Nockenwellenversteller auf Bank 1 reagiert zu langsam. Gleiche Ursachen wie P000A, jedoch an der Auslassnockenwelle.','["vvt_solenoid_exhaust_bank1", "cam_phaser_exhaust", "engine_oil"]','[{"id": "vvt_solenoid_clogged", "p": "high", "en": "Exhaust VVT solenoid clogged", "de": "Auslass-VVT-Magnetventil verstopft"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure", "de": "Zu geringer \u00d6ldruck"}, {"id": "phaser_wear", "p": "medium", "en": "Exhaust cam phaser worn", "de": "Auslass-Nockenwellenversteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 1200], "estimated_hours": [0.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000C','P','A Camshaft Position Slow Response Bank 2','A-Nockenwellenposition langsame Reaktion Bank 2','Intake camshaft phaser on bank 2 responds too slowly. Same fault pattern as P000A on the second cylinder bank.','Einlass-Nockenwellenversteller auf Bank 2 reagiert zu langsam. Gleiches Muster wie P000A auf der zweiten Bank.','["vvt_solenoid_intake_bank2", "cam_phaser_intake", "engine_oil"]','[{"id": "vvt_solenoid_clogged", "p": "high", "en": "VVT solenoid clogged", "de": "VVT-Magnetventil verstopft"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure", "de": "Zu geringer \u00d6ldruck"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 1200], "estimated_hours": [0.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000D','P','B Camshaft Position Slow Response Bank 2','B-Nockenwellenposition langsame Reaktion Bank 2','Exhaust camshaft phaser on bank 2 responds too slowly. Same fault pattern as P000B on the second cylinder bank.','Auslass-Nockenwellenversteller auf Bank 2 reagiert zu langsam. Gleiches Muster wie P000B auf der zweiten Bank.','["vvt_solenoid_exhaust_bank2", "cam_phaser_exhaust", "engine_oil"]','[{"id": "vvt_solenoid_clogged", "p": "high", "en": "Exhaust VVT solenoid clogged", "de": "Auslass-VVT-Magnetventil verstopft"}, {"id": "phaser_wear", "p": "medium", "en": "Cam phaser worn", "de": "Nockenwellenversteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 1200], "estimated_hours": [0.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000E','P','Fuel Volume Regulator Control Exceeded Learning Limit','Kraftstoffmengenregelung Adaptionsgrenze überschritten','The ECU''s adaptive correction of fuel volume regulator A has reached its learning limit. Indicates a long-term drift between commanded and actual rail pressure that could no longer be compensated.','Die Adaption der Kraftstoffmengenregelung hat ihre Lerngrenze erreicht. Hinweis auf eine länger anhaltende Abweichung zwischen Soll- und Ist-Raildruck, die nicht mehr kompensiert werden konnte.','["high_pressure_fuel_pump", "fuel_volume_regulator", "fuel_filter", "fuel_rail_pressure_sensor"]','[{"id": "pump_wear", "p": "high", "en": "HP pump worn out", "de": "Hochdruckpumpe verschlissen"}, {"id": "clogged_fuel_filter", "p": "medium", "en": "Fuel filter clogged, restricted supply", "de": "Kraftstofffilter verstopft, Vorf\u00f6rderung gedrosselt"}, {"id": "leak_in_rail", "p": "medium", "en": "Internal leak (injector or rail)", "de": "Interne Leckage (Injektor oder Rail)"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P000F','P','Fuel System Over Pressure Relief Valve Activated','Kraftstoffsystem Überdruck-Sicherheitsventil ausgelöst','The mechanical pressure relief valve on the fuel rail has opened due to overpressure. Indicates a malfunction of the rail pressure regulation that drove pressure beyond the safe limit.','Das mechanische Überdruckventil am Kraftstoffrail hat durch Überdruck geöffnet. Hinweis auf eine fehlerhafte Raildruck-Regelung, die den Druck über den Sicherheitswert getrieben hat.','["pressure_relief_valve", "fuel_rail", "fuel_pressure_regulator", "fuel_rail_pressure_sensor"]','[{"id": "pressure_regulator_stuck", "p": "high", "en": "Pressure regulator valve stuck closed", "de": "Druckregelventil h\u00e4ngt geschlossen"}, {"id": "pressure_sensor_fault", "p": "medium", "en": "Rail pressure sensor reading low", "de": "Raildrucksensor liefert zu niedrigen Wert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [250, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0010','P','"A" Camshaft Position Actuator Circuit (Bank 1)','Nockenwellenversteller "A" Schaltung (Bank 1)','An electrical fault in the bank 1 intake camshaft position actuator solenoid (variable valve timing). The ECU monitors current and feedback on the oil control valve and sets this code when the circuit is open, shorted, or out of range.','Elektrischer Fehler am Nockenwellenversteller-Magnetventil der Einlassnockenwelle Bank 1 (variable Ventilsteuerung). Die Motorsteuerung überwacht Strom und Rückmeldung des Ölsteuerventils und setzt diesen Code bei offenem, kurzgeschlossenem oder auße','["camshaft_position_actuator", "oil_control_valve", "actuator_wiring"]','[{"id": "oil_control_valve_failed", "p": "high", "en": "Oil control valve electrically failed", "de": "\u00d6lsteuerventil elektrisch defekt"}, {"id": "actuator_wiring_fault", "p": "medium", "en": "Wiring or connector fault to actuator", "de": "Kabel-/Steckerfehler am Stellglied"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0011','P','"A" Camshaft Position - Timing Over-Advanced or System Performance (Bank 1)','Nockenwellenposition "A" — Steuerzeit zu früh oder Systemleistung (Bank 1)','The bank 1 intake camshaft is more advanced than commanded, or the actuator does not respond as expected. Often caused by stuck-open oil control valves, sludge in VVT passages, or low oil pressure.','Die Einlassnockenwelle Bank 1 ist weiter als angefordert verstellt, oder das Stellglied reagiert nicht wie erwartet. Häufige Ursachen — hängendes Ölsteuerventil, Schlamm in VVT-Kanälen oder niedriger Öldruck.','["camshaft_position_actuator", "oil_control_valve", "engine_oil"]','[{"id": "ocv_stuck_advance", "p": "high", "en": "Oil control valve stuck (advance position)", "de": "\u00d6lsteuerventil h\u00e4ngend (Verstellrichtung fr\u00fch)"}, {"id": "oil_sludge_vvt", "p": "medium", "en": "Sludge or debris in VVT oil passages", "de": "Schlamm oder Sp\u00e4ne in VVT-\u00d6lkan\u00e4len"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low engine oil pressure or wrong oil viscosity", "de": "Niedriger \u00d6ldruck oder falsche \u00d6lviskosit\u00e4t"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0012','P','"A" Camshaft Position - Timing Over-Retarded (Bank 1)','Nockenwellenposition "A" — Steuerzeit zu spät (Bank 1)','The bank 1 intake camshaft remains retarded compared to commanded position. Common causes include a stuck-closed oil control valve, blocked oil passages, or a worn cam phaser.','Die Einlassnockenwelle Bank 1 bleibt gegenüber dem Sollwert in Spätstellung. Häufige Ursachen — geschlossen hängendes Ölsteuerventil, verstopfte Ölkanäle oder verschlissener Phasensteller.','["camshaft_position_actuator", "oil_control_valve", "cam_phaser"]','[{"id": "ocv_stuck_retard", "p": "high", "en": "Oil control valve stuck (retard position)", "de": "\u00d6lsteuerventil h\u00e4ngend (Verstellrichtung sp\u00e4t)"}, {"id": "cam_phaser_worn", "p": "medium", "en": "Cam phaser internally worn", "de": "Phasensteller intern verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0013','P','"B" Camshaft Position Actuator Circuit (Bank 1)','Nockenwellenversteller "B" Schaltung (Bank 1)','Electrical fault in the bank 1 exhaust camshaft position actuator solenoid. Same diagnostic principle as P0010 but on the exhaust cam.','Elektrischer Fehler am Nockenwellenversteller-Magnetventil der Auslassnockenwelle Bank 1. Gleiche Diagnoselogik wie P0010, jedoch an der Auslassnockenwelle.','["camshaft_position_actuator", "oil_control_valve"]','[{"id": "ocv_failed", "p": "high", "en": "Oil control valve electrically failed", "de": "\u00d6lsteuerventil elektrisch defekt"}, {"id": "actuator_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel-/Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0014','P','"B" Camshaft Position - Timing Over-Advanced (Bank 1)','Nockenwellenposition "B" — Steuerzeit zu früh (Bank 1)','Exhaust camshaft position bank 1 over-advanced or system performance — the actual cam phase exceeds the commanded value. Usually caused by a stuck-open oil control valve, low oil pressure, sludged passages, or a worn cam phaser. Confirm with a scan t','Auslassnockenwellen-Position Bank 1 zu weit vorverstellt oder Systemverhalten — die tatsächliche Nockenphase überschreitet den Sollwert. Meist durch ein offen klemmendes Ölsteuerventil, geringen Öldruck, verschlammte Kanäle oder einen verschlissenen ','["camshaft_position_actuator", "oil_control_valve", "cam_phaser"]','[{"id": "ocv_stuck_advance", "p": "high", "en": "Oil control valve stuck (advance)", "de": "\u00d6lsteuerventil h\u00e4ngend (fr\u00fch)"}, {"id": "oil_sludge_vvt", "p": "medium", "en": "Sludge in VVT oil passages", "de": "Schlamm in VVT-\u00d6lkan\u00e4len"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0015','P','"B" Camshaft Position - Timing Over-Retarded (Bank 1)','Nockenwellenposition "B" — Steuerzeit zu spät (Bank 1)','The bank 1 exhaust camshaft remains retarded relative to commanded position. Same root causes as P0012 but on the exhaust cam.','Die Auslassnockenwelle Bank 1 bleibt gegenüber dem Sollwert in Spätstellung. Gleiche Grundursachen wie P0012, jedoch an der Auslassnockenwelle.','["camshaft_position_actuator", "oil_control_valve", "cam_phaser"]','[{"id": "ocv_stuck_retard", "p": "high", "en": "Oil control valve stuck (retard)", "de": "\u00d6lsteuerventil h\u00e4ngend (sp\u00e4t)"}, {"id": "cam_phaser_worn", "p": "medium", "en": "Cam phaser worn", "de": "Phasensteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0016','P','Crankshaft Position - Camshaft Position Correlation (Bank 1 Sensor A)','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 1, Sensor A)','Crankshaft Position - Camshaft Position Correlation (Bank 1 Sensor A): the value does not correlate with the related sensor or expected pattern. This relates to engine timing; a fault can cause rough running, a no-start, or timing errors.','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 1, Sensor A): der Wert stimmt nicht mit dem zugehörigen Sensor oder dem erwarteten Muster überein. Dies betrifft die Motorsteuerzeiten; ein Fehler kann unrunden Lauf, Startverweigerung oder Steu','["timing_chain", "timing_chain_tensioner", "camshaft_position_sensor", "crankshaft_position_sensor"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain stretched", "de": "Steuerkette gel\u00e4ngt"}, {"id": "tensioner_worn", "p": "medium", "en": "Chain tensioner worn or stuck", "de": "Kettenspanner verschlissen oder h\u00e4ngend"}, {"id": "cam_phaser_failed", "p": "medium", "en": "Cam phaser internally failed", "de": "Phasensteller intern defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [3.0, 12.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0017','P','Crankshaft Position - Camshaft Position Correlation (Bank 1 Sensor B)','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 1, Sensor B)','Crankshaft Position - Camshaft Position Correlation (Bank 1 Sensor B): the value does not correlate with the related sensor or expected pattern. This relates to engine timing; a fault can cause rough running, a no-start, or timing errors.','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 1, Sensor B): der Wert stimmt nicht mit dem zugehörigen Sensor oder dem erwarteten Muster überein. Dies betrifft die Motorsteuerzeiten; ein Fehler kann unrunden Lauf, Startverweigerung oder Steu','["timing_chain", "camshaft_position_sensor", "crankshaft_position_sensor"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain stretched", "de": "Steuerkette gel\u00e4ngt"}, {"id": "cam_phaser_failed", "p": "medium", "en": "Exhaust cam phaser failed", "de": "Auslass-Phasensteller defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [3.0, 12.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0018','P','Crankshaft Position - Camshaft Position Correlation (Bank 2 Sensor A)','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 2, Sensor A)','Crankshaft Position - Camshaft Position Correlation (Bank 2 Sensor A): the value does not correlate with the related sensor or expected pattern. This relates to engine timing; a fault can cause rough running, a no-start, or timing errors.','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 2, Sensor A): der Wert stimmt nicht mit dem zugehörigen Sensor oder dem erwarteten Muster überein. Dies betrifft die Motorsteuerzeiten; ein Fehler kann unrunden Lauf, Startverweigerung oder Steu','["timing_chain", "camshaft_position_sensor", "crankshaft_position_sensor"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain stretched (bank 2)", "de": "Steuerkette gel\u00e4ngt (Bank 2)"}, {"id": "cam_phaser_failed", "p": "medium", "en": "Bank 2 cam phaser failed", "de": "Phasensteller Bank 2 defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [3.0, 12.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0019','P','Crankshaft Position - Camshaft Position Correlation (Bank 2 Sensor B)','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 2, Sensor B)','Crankshaft Position - Camshaft Position Correlation (Bank 2 Sensor B): the value does not correlate with the related sensor or expected pattern. This relates to engine timing; a fault can cause rough running, a no-start, or timing errors.','Korrelation Kurbelwellen- zu Nockenwellenposition (Bank 2, Sensor B): der Wert stimmt nicht mit dem zugehörigen Sensor oder dem erwarteten Muster überein. Dies betrifft die Motorsteuerzeiten; ein Fehler kann unrunden Lauf, Startverweigerung oder Steu','["timing_chain", "camshaft_position_sensor", "crankshaft_position_sensor"]','[{"id": "timing_chain_stretched", "p": "high", "en": "Timing chain stretched", "de": "Steuerkette gel\u00e4ngt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [3.0, 12.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001A','P','A Camshaft Profile Actuator A Control Circuit/Open Bank 1','A-Nockenwellen-Profilaktuator A Schaltkreis unterbrochen Bank 1','Open circuit at the camshaft profile actuator (intake, profile A, bank 1). Used by systems with discrete cam-lift levels (e.g. BMW Valvetronic, Honda VTEC, Audi AVS) — the actuator that selects the lift profile cannot be driven.','Unterbrochener Schaltkreis am Nockenwellen-Profilaktuator (Einlass, Profil A, Bank 1). Bei Systemen mit umschaltbarem Ventilhub (z. B. BMW Valvetronic, Honda VTEC, Audi AVS) — die Hub-Umschaltung lässt sich nicht ansteuern.','["cam_profile_actuator", "actuator_wiring", "actuator_connector"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break or unplugged connector", "de": "Kabelbruch oder loser Stecker"}, {"id": "actuator_coil_open", "p": "medium", "en": "Actuator coil open", "de": "Aktuator-Spule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001B','P','A Camshaft Profile Actuator A Control Circuit Low Bank 1','A-Nockenwellen-Profilaktuator A Schaltkreis niedrig Bank 1','Low control voltage at the cam profile actuator (intake, profile A, bank 1). Typically a short to ground in the wiring or actuator coil.','Zu niedrige Steuerspannung am Profilaktuator (Einlass, Profil A, Bank 1). Meist Kurzschluss gegen Masse in Verkabelung oder Spule.','["cam_profile_actuator", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "coil_short", "p": "medium", "en": "Actuator coil shorted internally", "de": "Aktuator-Spule mit Windungsschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001C','P','A Camshaft Profile Actuator A Control Circuit High Bank 1','A-Nockenwellen-Profilaktuator A Schaltkreis hoch Bank 1','Excessively high control voltage at the cam profile actuator (intake, profile A, bank 1). Typically a short to power or open ground.','Zu hohe Steuerspannung am Profilaktuator (Einlass, Profil A, Bank 1). Meist Plus-Schluss oder unterbrochene Masse.','["cam_profile_actuator", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "open_ground", "p": "medium", "en": "Open ground return path", "de": "Masser\u00fcckleiter unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001D','P','A Camshaft Profile Actuator A Control Circuit/Open Bank 2','A-Nockenwellen-Profilaktuator A Schaltkreis unterbrochen Bank 2','Open circuit at the cam profile actuator (intake, profile A, bank 2). Same fault as P001A but on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes be','Unterbrochener Schaltkreis am Profilaktuator (Einlass, Profil A, Bank 2). Wie P001A, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren D','["cam_profile_actuator", "actuator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "actuator_coil_open", "p": "medium", "en": "Actuator coil open", "de": "Aktuator-Spule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001E','P','A Camshaft Profile Actuator A Control Circuit Low Bank 2','A-Nockenwellen-Profilaktuator A Schaltkreis niedrig Bank 2','Low control voltage at the cam profile actuator (intake, profile A, bank 2). Same fault as P001B on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes','Zu niedrige Steuerspannung am Profilaktuator (Einlass, Profil A, Bank 2). Wie P001B, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren D','["cam_profile_actuator", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P001F','P','A Camshaft Profile Actuator A Control Circuit High Bank 2','A-Nockenwellen-Profilaktuator A Schaltkreis hoch Bank 2','Excessively high control voltage at the cam profile actuator (intake, profile A, bank 2). Same fault as P001C on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw corr','Zu hohe Steuerspannung am Profilaktuator (Einlass, Profil A, Bank 2). Wie P001C, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehz','["cam_profile_actuator", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0020','P','"A" Camshaft Position Actuator Circuit (Bank 2)','Nockenwellenversteller "A" Schaltung (Bank 2)','Electrical fault in the bank 2 intake camshaft position actuator. Same diagnostic principle as P0010 but on the second cylinder bank.','Elektrischer Fehler am Einlass-Nockenwellenversteller Bank 2. Gleiche Diagnoselogik wie P0010, jedoch an der zweiten Zylinderbank.','["camshaft_position_actuator", "oil_control_valve"]','[{"id": "ocv_failed", "p": "high", "en": "Oil control valve electrically failed", "de": "\u00d6lsteuerventil elektrisch defekt"}, {"id": "actuator_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel-/Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0021','P','"A" Camshaft Position - Timing Over-Advanced (Bank 2)','Nockenwellenposition "A" — Steuerzeit zu früh (Bank 2)','The bank 2 intake camshaft is more advanced than commanded, or the actuator does not respond as expected. Often caused by stuck-open oil control valves, sludge in VVT passages, or low oil pressure.','Die Einlassnockenwelle Bank 2 ist weiter als angefordert verstellt, oder das Stellglied reagiert nicht wie erwartet. Häufige Ursachen — hängendes Ölsteuerventil, Schlamm in VVT-Kanälen oder niedriger Öldruck.','["camshaft_position_actuator", "oil_control_valve"]','[{"id": "ocv_stuck_advance", "p": "high", "en": "Oil control valve stuck (advance)", "de": "\u00d6lsteuerventil h\u00e4ngend (fr\u00fch)"}, {"id": "oil_sludge_vvt", "p": "medium", "en": "Sludge in VVT passages", "de": "Schlamm in VVT-Kan\u00e4len"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0022','P','"A" Camshaft Position - Timing Over-Retarded (Bank 2)','Nockenwellenposition "A" — Steuerzeit zu spät (Bank 2)','The bank 2 intake camshaft remains retarded compared to commanded position. Common causes include a stuck-closed oil control valve, blocked oil passages, or a worn cam phaser.','Die Einlassnockenwelle Bank 2 bleibt gegenüber dem Sollwert in Spätstellung. Häufige Ursachen — geschlossen hängendes Ölsteuerventil, verstopfte Ölkanäle oder verschlissener Phasensteller.','["camshaft_position_actuator", "oil_control_valve", "cam_phaser"]','[{"id": "ocv_stuck_retard", "p": "high", "en": "Oil control valve stuck (retard)", "de": "\u00d6lsteuerventil h\u00e4ngend (sp\u00e4t)"}, {"id": "cam_phaser_worn", "p": "medium", "en": "Cam phaser worn", "de": "Phasensteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0023','P','"B" Camshaft Position Actuator Circuit (Bank 2)','Nockenwellenversteller "B" Schaltung (Bank 2)','Electrical fault in the bank 2 exhaust camshaft position actuator. Same diagnostic principle as P0013 but on the second cylinder bank.','Elektrischer Fehler am Auslass-Nockenwellenversteller Bank 2. Gleiche Diagnoselogik wie P0013, jedoch an der zweiten Zylinderbank.','["camshaft_position_actuator", "oil_control_valve"]','[{"id": "ocv_failed", "p": "high", "en": "Oil control valve electrically failed", "de": "\u00d6lsteuerventil elektrisch defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0024','P','"B" Camshaft Position - Timing Over-Advanced (Bank 2)','Nockenwellenposition "B" — Steuerzeit zu früh (Bank 2)','The bank 2 exhaust camshaft is more advanced than commanded. Same root causes as P0011 but on the exhaust cam.','Die Auslassnockenwelle Bank 2 ist weiter als angefordert verstellt. Gleiche Grundursachen wie P0011, jedoch an der Auslassnockenwelle.','["camshaft_position_actuator", "oil_control_valve"]','[{"id": "ocv_stuck_advance", "p": "high", "en": "Oil control valve stuck (advance)", "de": "\u00d6lsteuerventil h\u00e4ngend (fr\u00fch)"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0025','P','"B" Camshaft Position - Timing Over-Retarded (Bank 2)','Nockenwellenposition "B" — Steuerzeit zu spät (Bank 2)','The bank 2 exhaust camshaft remains retarded relative to commanded position. Same root causes as P0012 but on the exhaust cam.','Die Auslassnockenwelle Bank 2 bleibt gegenüber dem Sollwert in Spätstellung. Gleiche Grundursachen wie P0012, jedoch an der Auslassnockenwelle.','["camshaft_position_actuator", "oil_control_valve", "cam_phaser"]','[{"id": "ocv_stuck_retard", "p": "high", "en": "Oil control valve stuck (retard)", "de": "\u00d6lsteuerventil h\u00e4ngend (sp\u00e4t)"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0026','P','Intake Valve Control Solenoid Circuit Range/Performance (Bank 1)','Einlassventil-Steuermagnetventil — Bereich/Leistung (Bank 1)','The ECU detected that the bank 1 intake valve oil control solenoid does not respond as expected. Common causes are sludge in the oil passages, a sticking solenoid, or low oil pressure that prevents proper VVT phasing on the intake side.','Die Motorsteuerung erkennt, dass das Ölsteuerventil der Einlassnockenwelle Bank 1 nicht wie erwartet reagiert. Übliche Ursachen — Verschlammung der Ölkanäle, hängendes Magnetventil oder zu geringer Öldruck, der die Phasenverstellung der Einlassseite ','["oil_control_valve", "camshaft_position_actuator", "engine_oil"]','[{"id": "oil_control_valve_stuck", "p": "high", "en": "Oil control valve mechanically stuck", "de": "\u00d6lsteuerventil mechanisch h\u00e4ngend"}, {"id": "oil_sludge", "p": "medium", "en": "Sludge or debris in oil passages", "de": "Verschlammung oder Sp\u00e4ne in den \u00d6lkan\u00e4len"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure or wrong oil viscosity", "de": "Niedriger \u00d6ldruck oder falsche \u00d6lviskosit\u00e4t"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0027','P','Exhaust Valve Control Solenoid Circuit Range/Performance Bank 1','Abgasnockenwellen-Steuerventil Funktionsbereich Bank 1','The ECU detects that the exhaust camshaft oil control valve on bank 1 does not respond to commanded duty cycle within expected limits. Camshaft phase deviates from target during phaser actuation tests.','Die Motorsteuerung erkennt, dass das Ölsteuerventil der Auslassnockenwelle Bank 1 nicht im erwarteten Bereich auf das angeforderte Tastverhältnis reagiert. Die Nockenwellenposition weicht vom Sollwert ab.','["exhaust_camshaft_oil_control_valve", "camshaft_phaser", "engine_oil", "timing_chain"]','[{"id": "ocv_clogged", "p": "high", "en": "Oil control valve clogged with sludge", "de": "\u00d6lsteuerventil mit Schlamm verstopft"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure or wrong oil viscosity", "de": "Niedriger \u00d6ldruck oder falsche \u00d6lviskosit\u00e4t"}, {"id": "phaser_wear", "p": "medium", "en": "Camshaft phaser worn", "de": "Nockenwellenversteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0028','P','Intake Valve Control Solenoid Circuit Range/Performance (Bank 2)','Einlassventil-Steuermagnetventil — Bereich/Leistung (Bank 2)','The ECU detected that the bank 2 intake valve oil control solenoid does not respond as expected. Common causes are sludge in the oil passages, a sticking solenoid, or low oil pressure that prevents proper VVT phasing on the intake side.','Die Motorsteuerung erkennt, dass das Ölsteuerventil der Einlassnockenwelle Bank 2 nicht wie erwartet reagiert. Übliche Ursachen — Verschlammung der Ölkanäle, hängendes Magnetventil oder zu geringer Öldruck, der die Phasenverstellung der Einlassseite ','["oil_control_valve", "camshaft_position_actuator", "engine_oil"]','[{"id": "oil_control_valve_stuck", "p": "high", "en": "Oil control valve mechanically stuck", "de": "\u00d6lsteuerventil mechanisch h\u00e4ngend"}, {"id": "oil_sludge", "p": "medium", "en": "Sludge or debris in oil passages", "de": "Verschlammung oder Sp\u00e4ne in den \u00d6lkan\u00e4len"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0029','P','Exhaust Valve Control Solenoid Circuit Range/Performance Bank 2','Abgasnockenwellen-Steuerventil Funktionsbereich Bank 2','The ECU detects that the exhaust camshaft oil control valve on bank 2 does not respond to commanded duty cycle within expected limits. Camshaft phase deviates from target during phaser actuation tests.','Die Motorsteuerung erkennt, dass das Ölsteuerventil der Auslassnockenwelle Bank 2 nicht im erwarteten Bereich auf das angeforderte Tastverhältnis reagiert. Die Nockenwellenposition weicht vom Sollwert ab.','["exhaust_camshaft_oil_control_valve", "camshaft_phaser", "engine_oil", "timing_chain"]','[{"id": "ocv_clogged", "p": "high", "en": "Oil control valve clogged with sludge", "de": "\u00d6lsteuerventil mit Schlamm verstopft"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure or wrong oil viscosity", "de": "Niedriger \u00d6ldruck oder falsche \u00d6lviskosit\u00e4t"}, {"id": "phaser_wear", "p": "medium", "en": "Camshaft phaser worn", "de": "Nockenwellenversteller verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002A','P','B Camshaft Profile Actuator A Control Circuit/Open Bank 1','B-Nockenwellen-Profilaktuator A Schaltkreis unterbrochen Bank 1','Open circuit at the cam profile actuator on the exhaust cam (profile A, bank 1). Same diagnosis as P001A but for the exhaust profile actuator.','Unterbrochener Schaltkreis am Profilaktuator der Auslassnockenwelle (Profil A, Bank 1). Wie P001A, jedoch Auslass.','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "actuator_coil_open", "p": "medium", "en": "Actuator coil open", "de": "Aktuator-Spule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002B','P','B Camshaft Profile Actuator A Control Circuit Low Bank 1','B-Nockenwellen-Profilaktuator A Schaltkreis niedrig Bank 1','Low control voltage at the exhaust cam profile actuator (profile A, bank 1). Short to ground in wiring or coil.','Zu niedrige Steuerspannung am Auslass-Profilaktuator (Profil A, Bank 1). Masseschluss in Verkabelung oder Spule.','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002C','P','B Camshaft Profile Actuator A Control Circuit High Bank 1','B-Nockenwellen-Profilaktuator A Schaltkreis hoch Bank 1','Excessively high control voltage at the exhaust cam profile actuator (profile A, bank 1). Short to power or open ground.','Zu hohe Steuerspannung am Auslass-Profilaktuator (Profil A, Bank 1). Plus-Schluss oder offene Masse.','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002D','P','B Camshaft Profile Actuator A Control Circuit/Open Bank 2','B-Nockenwellen-Profilaktuator A Schaltkreis unterbrochen Bank 2','Open circuit at the exhaust cam profile actuator (profile A, bank 2). Same as P002A on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes between cam ','Unterbrochener Schaltkreis am Auslass-Profilaktuator (Profil A, Bank 2). Wie P002A, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Dr','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002E','P','B Camshaft Profile Actuator A Control Circuit Low Bank 2','B-Nockenwellen-Profilaktuator A Schaltkreis niedrig Bank 2','Low control voltage at the exhaust cam profile actuator (profile A, bank 2). Same as P002B on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes betwe','Zu niedrige Steuerspannung am Auslass-Profilaktuator (Profil A, Bank 2). Wie P002B, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Dr','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P002F','P','B Camshaft Profile Actuator A Control Circuit High Bank 2','B-Nockenwellen-Profilaktuator A Schaltkreis hoch Bank 2','Excessively high control voltage at the exhaust cam profile actuator (profile A, bank 2). Same as P002C on bank 2. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlatio','Zu hohe Steuerspannung am Auslass-Profilaktuator (Profil A, Bank 2). Wie P002C, jedoch Bank 2. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehza','["cam_profile_actuator_exhaust", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery voltage", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0030','P','HO2S Heater Control Circuit (Bank 1 Sensor 1)','Lambdasonden-Heizung Schaltung (Bank 1, Sonde 1)','HO2S Heater Control Circuit (Bank 1 Sensor 1): the control circuit has an electrical fault. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Schaltung (Bank 1, Sonde 1): im Steuerkreis liegt ein elektrischer Fehler vor. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor", "oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_open_circuit", "p": "high", "en": "Heater element open or burnt out", "de": "Heizelement unterbrochen oder durchgebrannt"}, {"id": "heater_fuse_blown", "p": "medium", "en": "Heater supply fuse blown", "de": "Heizungs-Versorgungssicherung defekt"}, {"id": "sensor_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel-/Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0031','P','HO2S Heater Control Circuit Low (Bank 1 Sensor 1)','Lambdasonden-Heizung Stromkreis niedrig (Bank 1, Sonde 1)','O2 sensor heater control circuit on bank 1, sensor 1 reports low voltage. Likely shorted to ground or open in the heater control wire. The heater warms the sensor element to operating temperature (~600 °C); without it the sensor stays inactive in clo','Lambdasonden-Heizung an Bank 1, Sonde 1 meldet niedrige Spannung im Steuerkreis. Wahrscheinlich Masseschluss oder Unterbrechung in der Heizungs-Steuerleitung. Die Heizung bringt das Sondenelement auf Betriebstemperatur (~600 °C); ohne sie bleibt die ','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_ground", "p": "high", "en": "Heater control wire shorted to ground", "de": "Heizungs-Steuerleitung gegen Masse kurzgeschlossen"}, {"id": "heater_internal_short", "p": "medium", "en": "Heater element internally shorted", "de": "Heizelement intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0032','P','HO2S Heater Control Circuit High (Bank 1 Sensor 1)','Lambdasonden-Heizung Stromkreis hoch (Bank 1, Sonde 1)','O2 sensor heater control circuit on bank 1, sensor 1 reports high voltage. Likely shorted to B+ or open in the heater element itself. The heater warms the sensor element to operating temperature (~600 °C); without it the sensor stays inactive in clos','Lambdasonden-Heizung an Bank 1, Sonde 1 meldet hohe Spannung im Steuerkreis. Wahrscheinlich Kurzschluss nach B+ oder Unterbrechung im Heizelement selbst. Die Heizung bringt das Sondenelement auf Betriebstemperatur (~600 °C); ohne sie bleibt die Sonde','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_voltage", "p": "high", "en": "Heater wire shorted to supply voltage", "de": "Heizleitung gegen Versorgungsspannung kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0033','P','Turbocharger Bypass Valve Control Circuit','Turbolader-Bypassventil Steuerkreis','The ECU detects an electrical fault in the turbocharger bypass (wastegate) valve control circuit. Voltage or current measured on the solenoid output deviates from expected values during commanded actuation.','Die Motorsteuerung erkennt einen elektrischen Fehler im Steuerkreis des Turbolader-Bypassventils (Wastegate). Spannung oder Strom am Magnetventilausgang weichen bei angesteuerter Betätigung vom Sollwert ab.','["turbocharger_bypass_valve", "wastegate_solenoid", "wiring_harness", "ecm"]','[{"id": "solenoid_failed", "p": "high", "en": "Bypass solenoid failed", "de": "Bypass-Magnetventil defekt"}, {"id": "wiring_open", "p": "medium", "en": "Open or shorted wiring to solenoid", "de": "Unterbrechung oder Kurzschluss zum Magnetventil"}, {"id": "connector_corrosion", "p": "low", "en": "Connector corrosion or poor contact", "de": "Steckerkorrosion oder schlechter Kontakt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0034','P','Turbocharger Bypass Valve Control Circuit Low','Turbolader-Bypassventil Steuerkreis Signal niedrig','The bypass valve solenoid control circuit reports a voltage below threshold, indicating a short to ground or open driver. The ECU disables boost control until the fault clears.','Der Steuerkreis des Bypassventils meldet eine Spannung unterhalb des Schwellenwerts, was auf einen Kurzschluss nach Masse oder einen offenen Endstufentreiber hindeutet. Die Ladedruckregelung wird deaktiviert.','["turbocharger_bypass_valve", "wastegate_solenoid", "wiring_harness"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung gegen Masse kurzgeschlossen"}, {"id": "solenoid_internal_short", "p": "medium", "en": "Solenoid internal short", "de": "Interner Kurzschluss im Magnetventil"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0035','P','Turbocharger Bypass Valve Control Circuit High','Turbolader-Bypassventil Steuerkreis Signal hoch','The bypass valve solenoid control circuit reports a voltage above threshold, indicating a short to power or open circuit. Boost control is disabled while the fault is active.','Der Steuerkreis des Bypassventils meldet eine Spannung oberhalb des Schwellenwerts, was auf einen Kurzschluss nach Plus oder eine Leitungsunterbrechung hindeutet. Die Ladedruckregelung wird deaktiviert.','["turbocharger_bypass_valve", "wastegate_solenoid", "wiring_harness"]','[{"id": "short_to_power", "p": "high", "en": "Signal wire shorted to battery voltage", "de": "Signalleitung gegen Bordnetzspannung kurzgeschlossen"}, {"id": "open_circuit", "p": "medium", "en": "Open circuit in wiring or solenoid", "de": "Unterbrechung in Verkabelung oder Magnetventil"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0036','P','HO2S Heater Control Circuit (Bank 1 Sensor 2)','Lambdasonden-Heizung Schaltung (Bank 1, Sonde 2)','HO2S Heater Control Circuit (Bank 1 Sensor 2): the control circuit has an electrical fault. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Schaltung (Bank 1, Sonde 2): im Steuerkreis liegt ein elektrischer Fehler vor. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor", "oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_open_circuit", "p": "high", "en": "Heater element open", "de": "Heizelement unterbrochen"}, {"id": "heater_fuse_blown", "p": "medium", "en": "Heater fuse blown", "de": "Heizungssicherung defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0037','P','HO2S Heater Control Circuit Low (Bank 1 Sensor 2)','Lambdasonden-Heizung Stromkreis niedrig (Bank 1, Sonde 2)','O2 sensor heater control circuit on bank 1, sensor 2 reports low voltage. Likely shorted to ground or open in the heater control wire. The heater warms the sensor element to operating temperature (~600 °C); without it the sensor stays inactive in clo','Lambdasonden-Heizung an Bank 1, Sonde 2 meldet niedrige Spannung im Steuerkreis. Wahrscheinlich Masseschluss oder Unterbrechung in der Heizungs-Steuerleitung. Die Heizung bringt das Sondenelement auf Betriebstemperatur (~600 °C); ohne sie bleibt die ','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_ground", "p": "high", "en": "Heater wire shorted to ground", "de": "Heizleitung gegen Masse kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0038','P','HO2S Heater Control Circuit High (Bank 1 Sensor 2)','Lambdasonden-Heizung Stromkreis hoch (Bank 1, Sonde 2)','The heater control line for the upstream bank 1 oxygen sensor reads above the expected voltage, typical of a short to supply.','Die Steuerleitung der Heizung der Vor-Kat-Lambdasonde Bank 1 liegt über der erwarteten Spannung — typisch für einen Kurzschluss gegen Versorgungsspannung.','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_voltage", "p": "high", "en": "Heater wire shorted to supply", "de": "Heizleitung gegen Versorgung kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0039','P','Turbocharger/Supercharger Bypass Valve A Control Circuit Range/Performance','Turbolader/Kompressor Bypassventil A Schaltkreis Bereich/Leistung','The wastegate or bypass valve A on the turbo/supercharger does not respond mechanically as expected to its control signal. Boost pressure deviates from target.','Wastegate bzw. Bypassventil A am Turbolader/Kompressor reagiert mechanisch nicht wie erwartet. Ladedruck weicht vom Sollwert ab.','["wastegate_actuator", "bypass_valve", "boost_pressure_sensor"]','[{"id": "wastegate_stuck", "p": "high", "en": "Wastegate sticking from carbon", "de": "Wastegate h\u00e4ngt durch Verkokung"}, {"id": "vacuum_leak", "p": "medium", "en": "Vacuum/boost line leaking", "de": "Unterdruck-/Ladedruckleitung undicht"}, {"id": "actuator_worn", "p": "medium", "en": "Wastegate actuator worn", "de": "Wastegate-Aktuator verschlissen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003A','P','Turbocharger/Supercharger Boost Control A Position Exceeded Learning Limit','Turbolader/Kompressor Ladedruck-Regelung A Adaptionsgrenze überschritten','Turbocharger/Supercharger Boost Control A Position Exceeded Learning Limit: the control module has detected this fault condition. This affects turbo/supercharger boost-pressure control.','Turbolader/Kompressor Ladedruck-Regelung A Adaptionsgrenze überschritten: das Steuergerät hat diesen Fehlerzustand erkannt. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["wastegate_actuator", "turbocharger", "position_sensor"]','[{"id": "actuator_worn", "p": "high", "en": "Wastegate actuator worn or sticking", "de": "Wastegate-Aktuator verschlissen oder klemmt"}, {"id": "linkage_loose", "p": "medium", "en": "Linkage rod stretched or loose", "de": "Stellgest\u00e4nge gel\u00e4ngt oder lose"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1.5, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003B','P','Turbocharger/Supercharger Boost Control B Position Exceeded Learning Limit','Turbolader/Kompressor Ladedruck-Regelung B Adaptionsgrenze überschritten','Turbocharger/Supercharger Boost Control B Position Exceeded Learning Limit: the control module has detected this fault condition. This affects turbo/supercharger boost-pressure control.','Turbolader/Kompressor Ladedruck-Regelung B Adaptionsgrenze überschritten: das Steuergerät hat diesen Fehlerzustand erkannt. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["wastegate_actuator_b", "turbocharger_b"]','[{"id": "actuator_worn", "p": "high", "en": "Actuator B worn or sticking", "de": "Aktuator B verschlissen oder klemmt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1.5, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003C','P','A Camshaft Profile Actuator A Control Performance/Stuck Off Bank 1','A-Nockenwellen-Profilaktuator A klemmt in Aus-Stellung Bank 1','The intake cam profile actuator (profile A, bank 1) does not engage when commanded — stays in low-lift profile. Often hydraulic pin sticking or low oil pressure.','Der Einlass-Profilaktuator (Profil A, Bank 1) schaltet bei Anforderung nicht zu — bleibt im Klein-Hub. Häufig hängender Hydraulikpin oder zu geringer Öldruck.','["cam_profile_actuator", "oil_control_valve", "engine_oil"]','[{"id": "ocv_stuck", "p": "high", "en": "Oil control valve stuck", "de": "\u00d6lsteuerventil klemmt"}, {"id": "low_oil_pressure", "p": "medium", "en": "Low oil pressure", "de": "Zu geringer \u00d6ldruck"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003D','P','A Camshaft Profile Actuator A Control Stuck On Bank 1','A-Nockenwellen-Profilaktuator A klemmt in Ein-Stellung Bank 1','The intake cam profile actuator (profile A, bank 1) stays engaged when commanded off — stuck in high-lift profile. Idle quality and emissions affected.','Der Einlass-Profilaktuator (Profil A, Bank 1) bleibt zugeschaltet, obwohl Sollwert auf Aus — hängt im Groß-Hub. Beeinträchtigt Leerlauf und Emissionen.','["cam_profile_actuator", "oil_control_valve"]','[{"id": "pin_stuck_engaged", "p": "high", "en": "Locking pin stuck engaged", "de": "Verriegelungspin sitzt fest"}, {"id": "ocv_stuck_open", "p": "medium", "en": "Oil control valve stuck open", "de": "\u00d6lsteuerventil klemmt offen"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003E','P','A Camshaft Profile Actuator A Control Performance/Stuck Off Bank 2','A-Nockenwellen-Profilaktuator A klemmt in Aus-Stellung Bank 2','The intake cam profile actuator (profile A, bank 2) does not engage when commanded — stays in low-lift profile. Often hydraulic pin sticking or low oil pressure.','Der Einlass-Profilaktuator (Profil A, Bank 2) schaltet bei Anforderung nicht zu — bleibt im Klein-Hub. Häufig hängender Hydraulikpin oder zu geringer Öldruck.','["cam_profile_actuator", "oil_control_valve"]','[{"id": "ocv_stuck", "p": "high", "en": "Oil control valve stuck", "de": "\u00d6lsteuerventil klemmt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P003F','P','A Camshaft Profile Actuator A Control Stuck On Bank 2','A-Nockenwellen-Profilaktuator A klemmt in Ein-Stellung Bank 2','The intake cam profile actuator (profile A, bank 2) stays engaged when commanded off — stuck in high-lift profile. Idle quality and emissions affected.','Der Einlass-Profilaktuator (Profil A, Bank 2) bleibt zugeschaltet, obwohl Sollwert auf Aus — hängt im Groß-Hub. Beeinträchtigt Leerlauf und Emissionen.','["cam_profile_actuator", "oil_control_valve"]','[{"id": "pin_stuck_engaged", "p": "high", "en": "Locking pin stuck engaged", "de": "Verriegelungspin sitzt fest"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0040','P','O2 Sensor Signals Swapped Bank 1 Sensor 1/Bank 2 Sensor 1','O2-Sensorsignale vertauscht Bank 1 Sensor 1/Bank 2 Sensor 1','The pre-cat oxygen sensors of bank 1 and bank 2 appear to be wired the wrong way around — bank 1 reacts when bank 2 should and vice versa. Typically after recent service.','Die Vorkatalysator-Lambdasonden von Bank 1 und Bank 2 sind offenbar vertauscht angeschlossen — Bank 1 reagiert auf Bank-2-Bedingungen und umgekehrt. Häufig nach Werkstattarbeit.','["oxygen_sensor_b1s1", "oxygen_sensor_b2s1", "sensor_wiring"]','[{"id": "sensors_swapped", "p": "high", "en": "Sensors swapped after recent replacement", "de": "Sensoren nach Tausch vertauscht angeschlossen"}, {"id": "wiring_routed_wrong", "p": "medium", "en": "Wiring harness routed across banks", "de": "Kabelbaum bank\u00fcbergreifend verlegt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0041','P','O2 Sensor Signals Swapped Bank 1 Sensor 2/Bank 2 Sensor 2','O2-Sensorsignale vertauscht Bank 1 Sensor 2/Bank 2 Sensor 2','The post-cat oxygen sensors of bank 1 and bank 2 appear to be wired the wrong way around — bank 1 reacts when bank 2 should and vice versa. Typically after recent service.','Die Nachkatalysator-Lambdasonden von Bank 1 und Bank 2 sind offenbar vertauscht angeschlossen — Bank 1 reagiert auf Bank-2-Bedingungen und umgekehrt. Häufig nach Werkstattarbeit.','["oxygen_sensor_b1s2", "oxygen_sensor_b2s2", "sensor_wiring"]','[{"id": "sensors_swapped", "p": "high", "en": "Sensors swapped after replacement", "de": "Sensoren nach Tausch vertauscht"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0042','P','HO2S Heater Control Circuit Bank 1 Sensor 3','Lambdasondenheizung Schaltkreis Bank 1 Sensor 3','Generic electrical fault in the heater control of the bank 1, sensor 3 oxygen sensor (typically a third sensor downstream of multi-stage cat or NOx trap).','Allgemeiner elektrischer Fehler an der Heizungsansteuerung der Lambdasonde Bank 1 Sensor 3 (meist dritter Sensor hinter Mehrstufen-Kat oder NOx-Speicherkat).','["oxygen_sensor_b1s3_heater", "heater_wiring"]','[{"id": "heater_open", "p": "high", "en": "Heater element open", "de": "Heizelement unterbrochen"}, {"id": "heater_wiring", "p": "medium", "en": "Heater wiring or connector fault", "de": "Heizungsverkabelung oder Stecker fehlerhaft"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0043','P','HO2S Heater Control Circuit Low Bank 1 Sensor 3','Lambdasondenheizung Schaltkreis niedrig Bank 1 Sensor 3','Heater control voltage of the bank 1, sensor 3 oxygen sensor is below the expected range — short to ground or low-resistance fault.','Heizungs-Steuerspannung der Lambdasonde Bank 1 Sensor 3 unter Sollbereich — Masseschluss oder niederohmiger Fehler.','["oxygen_sensor_b1s3_heater", "heater_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Heater wiring shorted to ground", "de": "Heizungsverkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0044','P','HO2S Heater Control Circuit High Bank 1 Sensor 3','Lambdasondenheizung Schaltkreis hoch Bank 1 Sensor 3','Heater control voltage of the bank 1, sensor 3 oxygen sensor is above the expected range — short to power or open ground.','Heizungs-Steuerspannung der Lambdasonde Bank 1 Sensor 3 über Sollbereich — Plus-Schluss oder offene Masse.','["oxygen_sensor_b1s3_heater", "heater_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Heater wiring shorted to battery", "de": "Heizungsverkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0045','P','Turbocharger/Supercharger Boost Control A Circuit/Open','Turbolader/Kompressor Ladedruck-Regelung A Schaltkreis unterbrochen','Open circuit at the boost control solenoid/actuator A. The ECU cannot drive the wastegate or VGT vanes.','Unterbrochener Schaltkreis am Ladedruck-Aktuator A. Wastegate oder VTG-Schaufeln können vom Steuergerät nicht angesteuert werden.','["boost_control_solenoid", "actuator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break or unplugged connector", "de": "Kabelbruch oder loser Stecker"}, {"id": "solenoid_open", "p": "medium", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0046','P','Turbocharger/Supercharger Boost Control A Circuit Range/Performance','Turbolader/Kompressor Ladedruck-Regelung A Schaltkreis Bereich/Leistung','Boost control actuator A is electrically active but boost pressure deviates from target. Mechanical or hydraulic limitation.','Ladedruck-Aktuator A ist elektrisch aktiv, der Ladedruck weicht jedoch vom Sollwert ab. Mechanische oder hydraulische Begrenzung.','["boost_control_solenoid", "wastegate", "vacuum_lines"]','[{"id": "vacuum_leak", "p": "high", "en": "Vacuum/boost line leak", "de": "Unterdruck-/Ladedruckleitung undicht"}, {"id": "wastegate_stuck", "p": "medium", "en": "Wastegate sticking", "de": "Wastegate klemmt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0047','P','Turbocharger/Supercharger Boost Control A Circuit Low','Turbolader/Kompressor Ladedruck-Regelung A Schaltkreis niedrig','Boost control circuit A voltage below expected range — short to ground or low-resistance fault in solenoid wiring.','Spannung am Ladedruck-Schaltkreis A unter Sollbereich — Masseschluss oder niederohmiger Fehler in der Solenoid-Verkabelung.','["boost_control_solenoid", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0048','P','Turbocharger/Supercharger Boost Control A Circuit High','Turbolader/Kompressor Ladedruck-Regelung A Schaltkreis hoch','Boost control circuit A voltage above expected range — short to power or open ground in solenoid wiring.','Spannung am Ladedruck-Schaltkreis A über Sollbereich — Plus-Schluss oder offene Masse in der Solenoid-Verkabelung.','["boost_control_solenoid", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0049','P','Turbocharger/Supercharger A Turbine Overspeed','Turbolader/Kompressor A Turbinenüberdrehzahl','The turbocharger A turbine speed exceeded its safe limit. Risk of bearing damage and shaft fracture. Often caused by a stuck-closed wastegate or boost control fault.','Die Turbinendrehzahl des Turboladers A hat den Sicherheitswert überschritten. Risiko von Lager- und Wellenschaden. Häufig durch geschlossen klemmendes Wastegate oder Regelfehler.','["turbocharger", "wastegate", "turbine_speed_sensor"]','[{"id": "wastegate_stuck_closed", "p": "high", "en": "Wastegate stuck closed", "de": "Wastegate klemmt geschlossen"}, {"id": "boost_control_fault", "p": "medium", "en": "Boost control loop fault", "de": "Ladedruckregelkreis fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 3000], "estimated_hours": [2, 10]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004A','P','Turbocharger/Supercharger Boost Control B Circuit/Open','Turbolader/Kompressor Ladedruck-Regelung B Schaltkreis unterbrochen','Open circuit at boost control solenoid B (twin-turbo or two-stage system). Same diagnosis as P0045 on actuator B.','Unterbrochener Schaltkreis am Ladedruck-Aktuator B (Twin-Turbo oder zweistufig). Wie P0045, jedoch Aktuator B.','["boost_control_solenoid_b", "actuator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004B','P','Turbocharger/Supercharger Boost Control B Circuit Range/Performance','Turbolader/Kompressor Ladedruck-Regelung B Schaltkreis Bereich/Leistung','Boost control B mechanical/hydraulic deviation from target. Same as P0046 on actuator B. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested press','Mechanische/hydraulische Abweichung am Ladedruck-Aktuator B. Wie P0046, jedoch Aktuator B. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den ','["boost_control_solenoid_b", "wastegate_b"]','[{"id": "vacuum_leak", "p": "high", "en": "Vacuum/boost line leak", "de": "Unterdruck-/Ladedruckleitung undicht"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004C','P','Turbocharger/Supercharger Boost Control B Circuit Low','Turbolader/Kompressor Ladedruck-Regelung B Schaltkreis niedrig','Boost control B circuit voltage below expected range. Same as P0047 on actuator B. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Spannung am Ladedruck-Schaltkreis B unter Sollbereich. Wie P0047, jedoch Aktuator B. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geford','["boost_control_solenoid_b", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004D','P','Turbocharger/Supercharger Boost Control B Circuit High','Turbolader/Kompressor Ladedruck-Regelung B Schaltkreis hoch','Boost control B circuit voltage above expected range. Same as P0048 on actuator B. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Spannung am Ladedruck-Schaltkreis B über Sollbereich. Wie P0048, jedoch Aktuator B. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforde','["boost_control_solenoid_b", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004E','P','Turbocharger/Supercharger Boost Control A Circuit Intermittent/Erratic','Turbolader/Kompressor Ladedruck-Regelung A sporadisch/unstetig','Intermittent dropouts or noise on boost control A circuit. Loose connector, partial wiring break, or solenoid degrading.','Sporadische Aussetzer oder Störungen am Ladedruck-Schaltkreis A. Wackelkontakt, partieller Kabelbruch oder Solenoid in Verschlechterung.','["boost_control_solenoid", "connector"]','[{"id": "loose_connector", "p": "high", "en": "Connector loose or corroded", "de": "Stecker locker oder korrodiert"}, {"id": "chafed_wiring", "p": "medium", "en": "Wiring chafed inside loom", "de": "Kabelbaum scheuert intern"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P004F','P','Turbocharger/Supercharger Boost Control B Circuit Intermittent/Erratic','Turbolader/Kompressor Ladedruck-Regelung B sporadisch/unstetig','Same intermittent fault pattern as P004E on boost control B. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Gleiches sporadisches Fehlermuster wie P004E auf Ladedruck-Schaltkreis B. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck','["boost_control_solenoid_b", "connector"]','[{"id": "loose_connector", "p": "high", "en": "Connector loose or corroded", "de": "Stecker locker oder korrodiert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0050','P','HO2S Heater Control Circuit (Bank 2 Sensor 1)','Lambdasonden-Heizung Schaltung (Bank 2, Sonde 1)','HO2S Heater Control Circuit (Bank 2 Sensor 1): the control circuit has an electrical fault. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Schaltung (Bank 2, Sonde 1): im Steuerkreis liegt ein elektrischer Fehler vor. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor", "oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_open_circuit", "p": "high", "en": "Heater element open", "de": "Heizelement unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0051','P','HO2S Heater Control Circuit Low (Bank 2 Sensor 1)','Lambdasonden-Heizung Stromkreis niedrig (Bank 2, Sonde 1)','HO2S Heater Control Circuit Low (Bank 2 Sensor 1): the control-circuit voltage is below the expected range. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Stromkreis niedrig (Bank 2, Sonde 1): die Spannung im Steuerkreis liegt unter dem erwarteten Bereich. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_ground", "p": "high", "en": "Heater wire shorted to ground", "de": "Heizleitung gegen Masse kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0052','P','HO2S Heater Control Circuit High (Bank 2 Sensor 1)','Lambdasonden-Heizung Stromkreis hoch (Bank 2, Sonde 1)','HO2S Heater Control Circuit High (Bank 2 Sensor 1): the control-circuit voltage is above the expected range. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Stromkreis hoch (Bank 2, Sonde 1): die Spannung im Steuerkreis liegt über dem erwarteten Bereich. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_short_to_voltage", "p": "high", "en": "Heater wire shorted to supply", "de": "Heizleitung gegen Versorgung kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0053','P','HO2S Heater Resistance Bank 1 Sensor 1','Lambdasondenheizung Widerstand Bank 1 Sensor 1','The heater resistance of the bank 1, sensor 1 oxygen sensor is outside its specified range. Sensor heater aging or short between heater and signal.','Der Heizungswiderstand der Lambdasonde Bank 1 Sensor 1 liegt außerhalb der Spezifikation. Heizung gealtert oder Kurzschluss zwischen Heizung und Signal.','["oxygen_sensor_b1s1"]','[{"id": "heater_aged", "p": "high", "en": "Heater element aged, resistance high", "de": "Heizelement gealtert, Widerstand hoch"}, {"id": "sensor_failed", "p": "medium", "en": "Oxygen sensor failed", "de": "Lambdasonde defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0054','P','HO2S Heater Resistance Bank 1 Sensor 2','Lambdasondenheizung Widerstand Bank 1 Sensor 2','The heater resistance of the bank 1, sensor 2 oxygen sensor is outside its specified range. Sensor heater aging or short between heater and signal.','Der Heizungswiderstand der Lambdasonde Bank 1 Sensor 2 liegt außerhalb der Spezifikation. Heizung gealtert oder Kurzschluss zwischen Heizung und Signal.','["oxygen_sensor_b1s2"]','[{"id": "heater_aged", "p": "high", "en": "Heater element aged", "de": "Heizelement gealtert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
