INSERT OR IGNORE INTO dtc_codes VALUES('P0056','P','HO2S Heater Control Circuit (Bank 2 Sensor 2)','Lambdasonden-Heizung Schaltung (Bank 2, Sonde 2)','HO2S Heater Control Circuit (Bank 2 Sensor 2): the control circuit has an electrical fault. The heater brings the oxygen sensor to operating temperature for closed-loop fuel control.','Lambdasonden-Heizung Schaltung (Bank 2, Sonde 2): im Steuerkreis liegt ein elektrischer Fehler vor. Die Heizung bringt die Lambdasonde auf Betriebstemperatur für den Lambda-Regelbetrieb.','["oxygen_sensor", "oxygen_sensor_heater", "sensor_wiring"]','[{"id": "heater_open_circuit", "p": "high", "en": "Heater element open", "de": "Heizelement unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',1);
