INSERT OR IGNORE INTO dtc_codes VALUES('P0059','P','HO2S Heater Resistance Bank 2 Sensor 1','Lambdasondenheizung Widerstand Bank 2 Sensor 1','Heater resistance out of range on bank 2 sensor 1 (pre-cat). Same diagnostic as P0053 on the second bank.','Heizungswiderstand außerhalb des Bereichs an Bank 2 Sensor 1 (vor Kat). Gleiche Diagnose wie P0053, jedoch zweite Bank.','["oxygen_sensor_b2s1"]','[{"id": "heater_aged", "p": "high", "en": "Heater element aged", "de": "Heizelement gealtert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005A','P','B Camshaft Profile Actuator A Control Performance/Stuck Off Bank 1','B-Nockenwellen-Profilaktuator A klemmt in Aus-Stellung Bank 1','Exhaust cam profile actuator A on bank 1 stuck disengaged. Same fault pattern as P003C but on the exhaust cam. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation co','Auslass-Profilaktuator A auf Bank 1 bleibt aus. Gleiches Fehlerbild wie P003C, jedoch Auslass. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehza','["cam_profile_actuator_exhaust", "oil_control_valve"]','[{"id": "ocv_stuck", "p": "high", "en": "Oil control valve stuck", "de": "\u00d6lsteuerventil klemmt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005B','P','B Camshaft Profile Actuator A Control Stuck On Bank 1','B-Nockenwellen-Profilaktuator A klemmt in Ein-Stellung Bank 1','Exhaust cam profile actuator A on bank 1 stuck engaged. Same fault pattern as P003D on the exhaust cam. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes bet','Auslass-Profilaktuator A auf Bank 1 bleibt zugeschaltet. Wie P003D, jedoch Auslass. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehzahlbereich u','["cam_profile_actuator_exhaust", "oil_control_valve"]','[{"id": "pin_stuck_engaged", "p": "high", "en": "Locking pin stuck engaged", "de": "Verriegelungspin sitzt fest"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005C','P','B Camshaft Profile Actuator A Control Performance/Stuck Off Bank 2','B-Nockenwellen-Profilaktuator A klemmt in Aus-Stellung Bank 2','Exhaust cam profile actuator A on bank 2 stuck disengaged. Same fault pattern as P003C but on the exhaust cam. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation co','Auslass-Profilaktuator A auf Bank 2 bleibt aus. Gleiches Fehlerbild wie P003C, jedoch Auslass. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehza','["cam_profile_actuator_exhaust", "oil_control_valve"]','[{"id": "ocv_stuck", "p": "high", "en": "Oil control valve stuck", "de": "\u00d6lsteuerventil klemmt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005D','P','B Camshaft Profile Actuator A Control Stuck On Bank 2','B-Nockenwellen-Profilaktuator A klemmt in Ein-Stellung Bank 2','Exhaust cam profile actuator A on bank 2 stuck engaged. Same fault pattern as P003D on the exhaust cam. The cam phaser actuator adjusts intake/exhaust timing under load — a stuck or slow phaser kills mid-rpm torque and can throw correlation codes bet','Auslass-Profilaktuator A auf Bank 2 bleibt zugeschaltet. Wie P003D, jedoch Auslass. Der Nockenwellen-Versteller passt Einlass-/Auslass-Steuerzeiten unter Last an — ein klemmender oder träger Versteller kostet Drehmoment im mittleren Drehzahlbereich u','["cam_profile_actuator_exhaust", "oil_control_valve"]','[{"id": "pin_stuck_engaged", "p": "high", "en": "Locking pin stuck engaged", "de": "Verriegelungspin sitzt fest"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005E','P','Turbocharger/Supercharger Boost Control B Supply Voltage Circuit Low','Turbolader/Kompressor Ladedruck-Regelung B Versorgungsspannung niedrig','Supply voltage feeding boost control actuator B is below the expected range. Likely fuse, supply wiring or relay fault.','Versorgungsspannung des Ladedruck-Aktuators B unter Sollbereich. Wahrscheinlich Sicherung, Versorgungsleitung oder Relais defekt.','["boost_actuator_b_supply", "relay", "fuse"]','[{"id": "blown_fuse", "p": "high", "en": "Supply fuse blown or relay failed", "de": "Versorgungssicherung defekt oder Relais ausgefallen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [10, 200], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P005F','P','Turbocharger/Supercharger Boost Control B Supply Voltage Circuit High','Turbolader/Kompressor Ladedruck-Regelung B Versorgungsspannung hoch','Supply voltage feeding boost control actuator B is above the expected range. Likely charging system overvoltage or wiring shorted to a higher potential.','Versorgungsspannung des Ladedruck-Aktuators B über Sollbereich. Wahrscheinlich Überspannung im Bordnetz oder Plus-Schluss auf höheres Potential.','["boost_actuator_b_supply", "charging_system"]','[{"id": "charging_overvoltage", "p": "high", "en": "Alternator regulator failed (overvoltage)", "de": "Lichtmaschinenregler defekt (\u00dcberspannung)"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0060','P','HO2S Heater Resistance Bank 2 Sensor 2','Lambdasondenheizung Widerstand Bank 2 Sensor 2','Heater resistance out of range on bank 2 sensor 2 (post-cat). Same diagnostic as P0053 on second bank, post-cat.','Heizungswiderstand außerhalb des Bereichs an Bank 2 Sensor 2 (nach Kat). Wie P0053, jedoch zweite Bank, nach Kat.','["oxygen_sensor_b2s2"]','[{"id": "heater_aged", "p": "high", "en": "Heater element aged", "de": "Heizelement gealtert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0061','P','HO2S Heater Resistance Bank 2 Sensor 3','Lambdasondenheizung Widerstand Bank 2 Sensor 3','Heater resistance out of range on bank 2 sensor 3. The sensor heater warms the element to operating temperature (~600 °C); without it the lambda sensor stays inactive in closed loop and the ECM cannot trim mixture.','Heizungswiderstand außerhalb des Bereichs an Bank 2 Sensor 3. Die Sondenheizung bringt das Element auf Betriebstemperatur (~600 °C); ohne sie bleibt die Lambdasonde im geschlossenen Regelkreis inaktiv und das Steuergerät kann das Gemisch nicht regeln','["oxygen_sensor_b2s3"]','[{"id": "heater_aged", "p": "high", "en": "Heater element aged", "de": "Heizelement gealtert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0062','P','HO2S Heater Control Circuit Bank 2 Sensor 3','Lambdasondenheizung Schaltkreis Bank 2 Sensor 3','Generic electrical fault in the heater control of bank 2 sensor 3. The sensor heater warms the element to operating temperature (~600 °C); without it the lambda sensor stays inactive in closed loop and the ECM cannot trim mixture.','Allgemeiner elektrischer Fehler an der Heizungsansteuerung Bank 2 Sensor 3. Die Sondenheizung bringt das Element auf Betriebstemperatur (~600 °C); ohne sie bleibt die Lambdasonde im geschlossenen Regelkreis inaktiv und das Steuergerät kann das Gemisc','["oxygen_sensor_b2s3_heater", "heater_wiring"]','[{"id": "heater_open", "p": "high", "en": "Heater element open", "de": "Heizelement unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0063','P','HO2S Heater Control Circuit Low Bank 2 Sensor 3','Lambdasondenheizung Schaltkreis niedrig Bank 2 Sensor 3','Heater control voltage of bank 2 sensor 3 below the expected range. The sensor heater warms the element to operating temperature (~600 °C); without it the lambda sensor stays inactive in closed loop and the ECM cannot trim mixture.','Heizungs-Steuerspannung Bank 2 Sensor 3 unter Sollbereich. Die Sondenheizung bringt das Element auf Betriebstemperatur (~600 °C); ohne sie bleibt die Lambdasonde im geschlossenen Regelkreis inaktiv und das Steuergerät kann das Gemisch nicht regeln.','["oxygen_sensor_b2s3_heater", "heater_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Heater wiring shorted to ground", "de": "Heizungsverkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0064','P','HO2S Heater Control Circuit High Bank 2 Sensor 3','Lambdasondenheizung Schaltkreis hoch Bank 2 Sensor 3','Heater control voltage of bank 2 sensor 3 above the expected range. The sensor heater warms the element to operating temperature (~600 °C); without it the lambda sensor stays inactive in closed loop and the ECM cannot trim mixture.','Heizungs-Steuerspannung Bank 2 Sensor 3 über Sollbereich. Die Sondenheizung bringt das Element auf Betriebstemperatur (~600 °C); ohne sie bleibt die Lambdasonde im geschlossenen Regelkreis inaktiv und das Steuergerät kann das Gemisch nicht regeln.','["oxygen_sensor_b2s3_heater", "heater_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Heater wiring shorted to battery", "de": "Heizungsverkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0065','P','Air Assisted Injector Control Range/Performance','Luftunterstützte Einspritzdüsen-Regelung Bereich/Leistung','The air-assist injector control system (used on some lean-burn or direct-injection engines to atomize fuel with air) shows a performance deviation from the expected behavior.','Das luftunterstützte Einspritzsystem (bei manchen Magerlauf- oder Direkteinspritzern zur Kraftstoffzerstäubung) zeigt eine Abweichung vom Sollverhalten.','["air_assist_valve", "air_supply"]','[{"id": "clogged_air_passage", "p": "high", "en": "Air passage clogged with carbon", "de": "Luftkanal durch Verkokung verstopft"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0066','P','Air Assisted Injector Control Circuit Low','Luftunterstützte Einspritzdüsen-Regelung Schaltkreis niedrig','Control voltage of the air-assist injector valve is below the expected range — short to ground or low-resistance fault.','Steuerspannung des Luftunterstützungsventils unter Sollbereich — Masseschluss oder niederohmiger Fehler.','["air_assist_valve", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0067','P','Air Assisted Injector Control Circuit High','Luftunterstützte Einspritzdüsen-Regelung Schaltkreis hoch','Control voltage of the air-assist injector valve is above the expected range — short to power or open ground. A flow-deviating injector throws off cylinder balance — adjacent cylinders run leaner/richer to compensate, often masking the root cause unt','Steuerspannung des Luftunterstützungsventils über Sollbereich — Plus-Schluss oder offene Masse. Ein abweichender Injektor stört die Zylinderbalance — Nachbarzylinder laufen kompensatorisch magerer/fetter, was die Ursache oft maskiert, bis das Trim-Li','["air_assist_valve", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0068','P','MAP/MAF - Throttle Position Correlation','Korrelation MAP/MAF und Drosselklappenstellung','The ECU detects implausibility between throttle position and the airflow or intake manifold pressure measured. At a given throttle angle the air mass deviates beyond rationality limits.','Die Motorsteuerung erkennt eine Unplausibilität zwischen Drosselklappenstellung und gemessener Luftmasse oder Saugrohrdruck. Bei gegebenem Drosselklappenwinkel weicht die Luftmasse über Rationalitätsgrenzen hinaus ab.','["throttle_position_sensor", "mass_air_flow_sensor", "manifold_absolute_pressure_sensor", "intake_manifold", "throttle_body"]','[{"id": "vacuum_leak_large", "p": "high", "en": "Large unmetered vacuum leak", "de": "Gro\u00dfe Falschluftleckage"}, {"id": "throttle_body_dirty", "p": "medium", "en": "Throttle body dirty or sticking", "de": "Drosselklappe verschmutzt oder klemmt"}, {"id": "maf_drift", "p": "medium", "en": "MAF sensor drift", "de": "LMM-Drift"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0069','P','Manifold Absolute Pressure - Barometric Pressure Correlation','Korrelation Saugrohrdruck und Umgebungsdruck','At engine cranking or key-on the intake manifold pressure should equal barometric pressure within tolerance. The ECU detects a deviation indicating sensor drift or vacuum line issues.','Beim Anlassen oder bei Zündung-Ein sollte der Saugrohrdruck dem Umgebungsdruck entsprechen. Die Motorsteuerung erkennt eine Abweichung, die auf Sensordrift oder Probleme an Unterdruckleitungen hindeutet.','["manifold_absolute_pressure_sensor", "barometric_pressure_sensor", "vacuum_hose"]','[{"id": "map_sensor_failed", "p": "high", "en": "MAP sensor failed or drifted", "de": "MAP-Sensor defekt oder drift"}, {"id": "vacuum_hose_leak", "p": "medium", "en": "Vacuum hose to MAP sensor leaking", "de": "Unterdruckschlauch zum MAP-Sensor undicht"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006A','P','MAP - Mass or Volume Air Flow Correlation Bank 1','MAP-Saugrohrdruck zu Luftmasse Korrelation Bank 1','The expected relationship between manifold absolute pressure (MAP) and mass airflow (MAF) on bank 1 is violated. One of the two sensors is reading incorrectly.','Die erwartete Beziehung zwischen Saugrohrdrucksensor (MAP) und Luftmassenmesser (MAF) auf Bank 1 ist verletzt. Einer der beiden Sensoren liest fehlerhaft.','["map_sensor", "mass_air_flow_sensor", "intake_system"]','[{"id": "maf_contaminated", "p": "high", "en": "MAF sensor contaminated", "de": "LMM verschmutzt"}, {"id": "vacuum_leak", "p": "high", "en": "Intake/vacuum leak", "de": "Saugrohr- oder Unterdruckleck"}, {"id": "map_sensor_drift", "p": "medium", "en": "MAP sensor reading drifted", "de": "MAP-Sensor mit verschobenem Messwert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006B','P','MAP - Exhaust Pressure Correlation','MAP-Saugrohrdruck zu Abgasdruck Korrelation','The relationship between manifold absolute pressure and exhaust back pressure is implausible. One of the two pressure sensors is faulty or there is a major leak in either path.','Die Beziehung zwischen Saugrohrdruck und Abgasgegendruck ist unplausibel. Einer der beiden Drucksensoren ist defekt oder es liegt ein größeres Leck vor.','["map_sensor", "exhaust_pressure_sensor"]','[{"id": "exhaust_pressure_sensor", "p": "high", "en": "Exhaust back-pressure sensor faulty", "de": "Abgasgegendrucksensor defekt"}, {"id": "dpf_or_exhaust_leak", "p": "medium", "en": "DPF or exhaust path leak", "de": "DPF- oder Abgaswegleckage"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006C','P','MAP - Turbocharger/Supercharger Inlet Pressure Correlation','MAP-Saugrohrdruck zu Turbo-Eingangsdruck Korrelation','The relationship between manifold absolute pressure and turbocharger inlet pressure is implausible. Indicates a leak between turbo inlet and intake manifold or a sensor fault.','Die Beziehung zwischen Saugrohrdruck und Turbo-Eingangsdruck ist unplausibel. Hinweis auf Leck zwischen Turbo-Eingang und Saugrohr oder Sensorfehler.','["map_sensor", "turbo_inlet_pressure_sensor", "charge_pipe"]','[{"id": "charge_pipe_leak", "p": "high", "en": "Charge pipe leak between turbo and intake", "de": "Ladeluftrohr undicht zwischen Turbo und Ansaugung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006D','P','Barometric Pressure - Turbocharger/Supercharger Inlet Pressure Correlation Bank 1','Atmosphärendruck zu Turbo-Eingangsdruck Korrelation Bank 1','The relationship between barometric pressure and turbo inlet pressure (bank 1) is implausible — at engine off the two should match. Indicates an inlet sensor or barometric sensor fault.','Die Beziehung zwischen Atmosphärendruck und Turbo-Eingangsdruck (Bank 1) ist unplausibel — bei stehendem Motor sollten beide übereinstimmen. Hinweis auf Defekt am Eingangs- oder Atmosphärendrucksensor.','["barometric_pressure_sensor", "turbo_inlet_pressure_sensor"]','[{"id": "inlet_sensor_drift", "p": "high", "en": "Turbo inlet pressure sensor drifted", "de": "Turbo-Eingangsdrucksensor mit verschobenem Wert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006E','P','Turbocharger/Supercharger Boost Control A Supply Voltage Circuit Low','Turbolader/Kompressor Ladedruck-Regelung A Versorgungsspannung niedrig','Supply voltage to boost control actuator A below expected range. Same as P005E but on actuator A. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the reques','Versorgungsspannung des Ladedruck-Aktuators A unter Sollbereich. Wie P005E, jedoch Aktuator A. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht ','["boost_actuator_supply", "relay", "fuse"]','[{"id": "blown_fuse", "p": "high", "en": "Supply fuse blown or relay failed", "de": "Versorgungssicherung oder Relais defekt"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [10, 200], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P006F','P','Turbocharger/Supercharger Boost Control A Supply Voltage Circuit High','Turbolader/Kompressor Ladedruck-Regelung A Versorgungsspannung hoch','Supply voltage to boost control actuator A above expected range. Same as P005F but on actuator A. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the reques','Versorgungsspannung des Ladedruck-Aktuators A über Sollbereich. Wie P005F, jedoch Aktuator A. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht d','["boost_actuator_supply", "charging_system"]','[{"id": "charging_overvoltage", "p": "high", "en": "Alternator regulator failed", "de": "Lichtmaschinenregler defekt"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0070','P','Ambient Air Temperature Sensor Circuit A','Außenlufttemperatursensor Schaltkreis A','Generic electrical fault in the ambient air temperature sensor A circuit. Used by the ECU for cold-start corrections, climate logic, and intake-air calculations.','Allgemeiner elektrischer Fehler am Außenlufttemperatursensor A. Wird vom Steuergerät für Kaltstart-Korrektur, Klimalogik und Ansauglufttemperatur-Berechnungen genutzt.','["ambient_air_temp_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor element failed", "de": "Sensor defekt"}, {"id": "open_wiring", "p": "medium", "en": "Wiring open or connector loose", "de": "Verkabelung offen oder Stecker locker"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0071','P','Ambient Air Temperature Sensor Circuit A Range/Performance','Außenlufttemperatursensor A Bereich/Leistung','The ambient air temperature reading is electrically valid but implausible compared to other temperature sources (intake air temp, coolant at cold start).','Der Wert des Außenlufttemperatursensors A ist elektrisch plausibel, aber unstimmig im Vergleich zu anderen Temperaturquellen (Ansaug, Kühlmittel bei Kaltstart).','["ambient_air_temp_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Messwert des Sensors verschoben"}, {"id": "sensor_location_heat", "p": "medium", "en": "Sensor exposed to engine heat", "de": "Sensor wird durch Motorw\u00e4rme erw\u00e4rmt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0072','P','Ambient Air Temperature Sensor Circuit A Low','Außenlufttemperatursensor A Schaltkreis niedrig','Ambient air temperature sensor A signal voltage below the expected range — typically a short to ground.','Signalspannung des Außenlufttemperatursensors A unter Sollbereich — meist Masseschluss.','["ambient_air_temp_sensor", "sensor_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0073','P','Ambient Air Temperature Sensor Circuit A High','Außenlufttemperatursensor A Schaltkreis hoch','Ambient air temperature sensor A signal voltage above the expected range — typically open circuit (broken wire or sensor) or short to power.','Signalspannung des Außenlufttemperatursensors A über Sollbereich — meist Unterbrechung (Kabelbruch/Sensor) oder Plus-Schluss.','["ambient_air_temp_sensor", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open", "de": "Signalleitung unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0074','P','Ambient Air Temperature Sensor Circuit A Intermittent/Erratic','Außenlufttemperatursensor A sporadisch/unstetig','Intermittent dropouts or noise on the ambient air temperature sensor A signal — typically a loose connector or chafed wiring.','Sporadische Aussetzer oder Störungen am Signal des Außenlufttemperatursensors A — meist Wackelkontakt oder gescheuerter Kabelbaum.','["ambient_air_temp_sensor", "sensor_wiring"]','[{"id": "loose_connector", "p": "high", "en": "Connector loose or corroded", "de": "Stecker locker oder korrodiert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 150], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0075','P','Intake Valve Control Solenoid Circuit Bank 1','Einlassventilsteuerungs-Magnetventil Schaltkreis Bank 1','Generic electrical fault on the intake-valve control solenoid for bank 1 (used to switch valve lift, deactivation or VVL profiles).','Allgemeiner elektrischer Fehler am Einlassventilsteuerungs-Magnetventil Bank 1 (für Ventilhub-Umschaltung, Zylinderabschaltung oder VVL).','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "solenoid_failed", "p": "high", "en": "Solenoid coil failed", "de": "Magnetspule defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0076','P','Intake Valve Control Solenoid Circuit Low Bank 1','Einlassventilsteuerungs-Magnetventil Schaltkreis niedrig Bank 1','Intake valve solenoid bank 1 control voltage below expected range. Short to ground or low-resistance fault.','Steuerspannung am Einlassventil-Magnetventil Bank 1 unter Sollbereich. Masseschluss oder niederohmiger Fehler.','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0077','P','Intake Valve Control Solenoid Circuit High Bank 1','Einlassventilsteuerungs-Magnetventil Schaltkreis hoch Bank 1','Intake valve solenoid bank 1 control voltage above expected range. Short to power or open ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code','Steuerspannung am Einlassventil-Magnetventil Bank 1 über Sollbereich. Plus-Schluss oder offene Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0078','P','Exhaust Valve Control Solenoid Circuit Bank 1','Auslassventilsteuerungs-Magnetventil Schaltkreis Bank 1','Generic electrical fault on the exhaust-valve control solenoid for bank 1. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigger limp mode.','Allgemeiner elektrischer Fehler am Auslassventilsteuerungs-Magnetventil Bank 1. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmoment-Mapping und kann ','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "solenoid_failed", "p": "high", "en": "Solenoid coil failed", "de": "Magnetspule defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0079','P','Exhaust Valve Control Solenoid Circuit Low Bank 1','Auslassventilsteuerungs-Magnetventil Schaltkreis niedrig Bank 1','Exhaust valve solenoid bank 1 control voltage below expected range. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigger limp mode.','Steuerspannung am Auslassventil-Magnetventil Bank 1 unter Sollbereich. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmoment-Mapping und kann Notlauf a','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007A','P','Charge Air Cooler Temperature Sensor Circuit Bank 1','Ladeluftkühler-Temperatursensor Schaltkreis Bank 1','Generic electrical fault on the charge air cooler (intercooler) outlet temperature sensor on bank 1. Used to monitor intercooler effectiveness and to correct boost calculations.','Allgemeiner elektrischer Fehler am Temperatursensor des Ladeluftkühlers (Intercoolers) Bank 1. Überwacht die Kühlerleistung und korrigiert Ladedruck-Berechnungen.','["cac_temperature_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007B','P','Charge Air Cooler Temperature Sensor Circuit Range/Performance Bank 1','Ladeluftkühler-Temperatursensor Bereich/Leistung Bank 1','Charge air cooler temperature sensor reading on bank 1 is electrically valid but implausible — does not match expected behavior under load, ambient conditions or after long soak.','Wert des Ladeluftkühler-Temperatursensors Bank 1 elektrisch plausibel, aber unstimmig — passt nicht zu Last, Umgebungstemperatur oder Standzeit.','["cac_temperature_sensor", "intercooler"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007C','P','Charge Air Cooler Temperature Sensor Circuit Low Bank 1','Ladeluftkühler-Temperatursensor Schaltkreis niedrig Bank 1','Charge air cooler temperature sensor signal voltage on bank 1 below expected range. Typically a short to ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness','Signalspannung des Ladeluftkühler-Temperatursensors Bank 1 unter Sollbereich. Meist Masseschluss. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kab','["cac_temperature_sensor", "sensor_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007D','P','Charge Air Cooler Temperature Sensor Circuit High Bank 1','Ladeluftkühler-Temperatursensor Schaltkreis hoch Bank 1','Charge air cooler temperature sensor signal voltage on bank 1 above expected range. Typically open circuit or short to power.','Signalspannung des Ladeluftkühler-Temperatursensors Bank 1 über Sollbereich. Meist Unterbrechung oder Plus-Schluss.','["cac_temperature_sensor", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open", "de": "Signalleitung unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007E','P','Charge Air Cooler Temperature Sensor Circuit Intermittent/Erratic Bank 1','Ladeluftkühler-Temperatursensor sporadisch/unstetig Bank 1','Intermittent dropouts or noise on the charge air cooler temperature sensor signal on bank 1. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is a','Sporadische Aussetzer oder Störungen am Signal des Ladeluftkühler-Temperatursensors Bank 1. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum','["cac_temperature_sensor", "sensor_wiring"]','[{"id": "loose_connector", "p": "high", "en": "Connector loose or corroded", "de": "Stecker locker oder korrodiert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 300], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P007F','P','Charge Air Cooler Temperature Sensor Bank1/Bank2 Correlation','Ladeluftkühler-Temperatursensor Bank 1/Bank 2 Korrelation','The charge air cooler temperature sensors of bank 1 and bank 2 deviate from each other beyond plausible limits. One of the two has drifted.','Die Ladeluftkühler-Temperatursensoren Bank 1 und Bank 2 weichen über das plausible Maß voneinander ab. Einer der beiden ist verschoben.','["cac_temperature_sensor_b1", "cac_temperature_sensor_b2"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0080','P','Exhaust Valve Control Solenoid Circuit High Bank 1','Auslassventilsteuerungs-Magnetventil Schaltkreis hoch Bank 1','Exhaust valve solenoid bank 1 control voltage above expected range. Short to power or open ground. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigg','Steuerspannung am Auslassventil-Magnetventil Bank 1 über Sollbereich. Plus-Schluss oder offene Masse. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmo','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0081','P','Intake Valve Control Solenoid Circuit Bank 2','Einlassventilsteuerungs-Magnetventil Schaltkreis Bank 2','Generic electrical fault on the intake-valve control solenoid for bank 2 (used to switch valve lift, deactivation or VVL profiles).','Allgemeiner elektrischer Fehler am Einlassventilsteuerungs-Magnetventil Bank 2 (für Ventilhub-Umschaltung, Zylinderabschaltung oder VVL).','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "solenoid_failed", "p": "high", "en": "Solenoid coil failed", "de": "Magnetspule defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0082','P','Intake Valve Control Solenoid Circuit Low Bank 2','Einlassventilsteuerungs-Magnetventil Schaltkreis niedrig Bank 2','Intake valve solenoid bank 2 control voltage below expected range. Short to ground or low-resistance fault.','Steuerspannung am Einlassventil-Magnetventil Bank 2 unter Sollbereich. Masseschluss oder niederohmiger Fehler.','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0083','P','Intake Valve Control Solenoid Circuit High Bank 2','Einlassventilsteuerungs-Magnetventil Schaltkreis hoch Bank 2','Intake valve solenoid bank 2 control voltage above expected range. Short to power or open ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code','Steuerspannung am Einlassventil-Magnetventil Bank 2 über Sollbereich. Plus-Schluss oder offene Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am','["intake_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0084','P','Exhaust Valve Control Solenoid Circuit Bank 2','Auslassventilsteuerungs-Magnetventil Schaltkreis Bank 2','Generic electrical fault on the exhaust-valve control solenoid for bank 2. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigger limp mode.','Allgemeiner elektrischer Fehler am Auslassventilsteuerungs-Magnetventil Bank 2. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmoment-Mapping und kann ','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "solenoid_failed", "p": "high", "en": "Solenoid coil failed", "de": "Magnetspule defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0085','P','Exhaust Valve Control Solenoid Circuit Low Bank 2','Auslassventilsteuerungs-Magnetventil Schaltkreis niedrig Bank 2','Exhaust valve solenoid bank 2 control voltage below expected range. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigger limp mode.','Steuerspannung am Auslassventil-Magnetventil Bank 2 unter Sollbereich. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmoment-Mapping und kann Notlauf a','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0086','P','Exhaust Valve Control Solenoid Circuit High Bank 2','Auslassventilsteuerungs-Magnetventil Schaltkreis hoch Bank 2','Exhaust valve solenoid bank 2 control voltage above expected range. Short to power or open ground. The exhaust control valve modulates exhaust backpressure or routing (EGR feed, sound, regen support); a malfunction shifts torque mapping and may trigg','Steuerspannung am Auslassventil-Magnetventil Bank 2 über Sollbereich. Plus-Schluss oder offene Masse. Das Abgas-Steuerventil reguliert Abgas-Gegendruck oder -Führung (EGR-Speisung, Sound, Regenerations-Stütze); eine Fehlfunktion verschiebt das Drehmo','["exhaust_valve_solenoid", "solenoid_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0087','P','Fuel Rail/System Pressure Too Low','Kraftstoffdruck zu niedrig','The ECU detects fuel rail pressure below the desired setpoint despite maximum pump and metering valve commands. Common in direct injection diesel and gasoline systems where high-pressure pump or rail pressure regulator fails.','Die Motorsteuerung erkennt Kraftstoffdruck unterhalb des Sollwerts trotz maximaler Pumpen- und Zumessventilansteuerung. Häufig bei Direkteinspritzern, wenn Hochdruckpumpe oder Druckregler defekt sind.','["high_pressure_fuel_pump", "fuel_pressure_regulator", "fuel_rail", "fuel_filter", "fuel_injector"]','[{"id": "hpfp_worn", "p": "high", "en": "High-pressure fuel pump worn", "de": "Hochdruckpumpe verschlissen"}, {"id": "regulator_stuck", "p": "medium", "en": "Pressure regulator stuck open", "de": "Druckregler offen klemmend"}, {"id": "fuel_filter_clogged", "p": "medium", "en": "Fuel filter clogged", "de": "Kraftstofffilter verstopft"}, {"id": "injector_leak", "p": "low", "en": "Injector leaking back", "de": "Injektor mit zu hoher R\u00fccklaufmenge"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0088','P','Fuel Rail/System Pressure Too High','Kraftstoffdruck zu hoch','The ECU detects fuel rail pressure above the desired setpoint and cannot reduce it through pressure regulator commands. Risk of injector damage and rail seal failure if not addressed.','Die Motorsteuerung erkennt Kraftstoffdruck oberhalb des Sollwerts und kann ihn über den Druckregler nicht absenken. Risiko von Injektorschäden und undichten Dichtungen bei anhaltendem Fehler.','["fuel_pressure_regulator", "high_pressure_fuel_pump", "fuel_rail_pressure_sensor"]','[{"id": "regulator_stuck_closed", "p": "high", "en": "Pressure regulator stuck closed", "de": "Druckregler geschlossen klemmend"}, {"id": "rail_pressure_sensor_drift", "p": "medium", "en": "Rail pressure sensor drift", "de": "Drift des Raildrucksensors"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1.5, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0089','P','Fuel Pressure Regulator 1 Performance','Kraftstoffdruckregler 1 Funktion','The ECU detects that fuel rail pressure does not respond to commanded changes of the pressure regulator within expected dynamics. Indicates a sluggish or partially failed regulator.','Die Motorsteuerung erkennt, dass der Kraftstoffdruck nicht in der erwarteten Dynamik auf Stellbefehle des Druckreglers reagiert. Hinweis auf trägen oder teildefekten Regler.','["fuel_pressure_regulator", "fuel_rail", "high_pressure_fuel_pump"]','[{"id": "regulator_sluggish", "p": "high", "en": "Regulator sluggish or partially blocked", "de": "Regler tr\u00e4ge oder teilweise blockiert"}, {"id": "fuel_contamination", "p": "medium", "en": "Fuel contamination", "de": "Kraftstoffverunreinigung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1.5, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008A','P','Low Pressure Fuel System Pressure - Too Low','Niederdruck-Kraftstoffsystem Druck zu niedrig','The low-pressure (lift pump) fuel pressure is below the expected value. Insufficient supply to the high-pressure pump leads to power loss and possible HP pump cavitation.','Der Druck im Niederdruckkreis (Vorförderpumpe) liegt unter dem Sollwert. Mangelhafte Zufuhr zur Hochdruckpumpe führt zu Leistungsverlust und möglicher Kavitation der HD-Pumpe.','["lift_pump", "fuel_filter", "low_pressure_sensor"]','[{"id": "clogged_filter", "p": "high", "en": "Fuel filter clogged", "de": "Kraftstofffilter verstopft"}, {"id": "lift_pump_weak", "p": "high", "en": "Lift pump weak or failing", "de": "Vorf\u00f6rderpumpe schwach oder defekt"}, {"id": "leak_in_low_pressure_line", "p": "medium", "en": "Leak or air ingress in low-pressure line", "de": "Leck oder Luftansaugung im Niederdruckkreis"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 800], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008B','P','Low Pressure Fuel System Pressure - Too High','Niederdruck-Kraftstoffsystem Druck zu hoch','The low-pressure fuel pressure is above the expected value. Often caused by a stuck-closed fuel return valve or a faulty pressure regulator.','Der Druck im Niederdruckkreis liegt über dem Sollwert. Häufig durch geschlossen klemmendes Rücklaufventil oder defekten Druckregler.','["low_pressure_regulator", "fuel_return_valve", "low_pressure_sensor"]','[{"id": "regulator_stuck", "p": "high", "en": "Pressure regulator stuck closed", "de": "Druckregler h\u00e4ngt geschlossen"}, {"id": "return_blocked", "p": "medium", "en": "Return line blocked", "de": "R\u00fccklauf blockiert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008C','P','Fuel Cooler Pump Control Circuit/Open','Kraftstoffkühlerpumpe Schaltkreis unterbrochen','Open circuit at the fuel cooler pump control. The pump that circulates fuel through a cooler (used on diesels and some hot-fuel applications) cannot be driven.','Unterbrochener Schaltkreis an der Kraftstoffkühlerpumpe. Die Pumpe, die Kraftstoff durch einen Kühler fördert (bei Dieseln und heißen Anwendungen), lässt sich nicht ansteuern.','["fuel_cooler_pump", "pump_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break or unplugged connector", "de": "Kabelbruch oder loser Stecker"}, {"id": "pump_motor_open", "p": "medium", "en": "Pump motor open", "de": "Pumpenmotor unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008D','P','Fuel Cooler Pump Control Circuit Low','Kraftstoffkühlerpumpe Schaltkreis niedrig','Control voltage of the fuel cooler pump is below the expected range — short to ground or low-resistance fault.','Steuerspannung der Kraftstoffkühlerpumpe unter Sollbereich — Masseschluss oder niederohmiger Fehler.','["fuel_cooler_pump", "pump_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008E','P','Fuel Cooler Pump Control Circuit High','Kraftstoffkühlerpumpe Schaltkreis hoch','Control voltage of the fuel cooler pump is above the expected range — short to power or open ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the c','Steuerspannung der Kraftstoffkühlerpumpe über Sollbereich — Plus-Schluss oder offene Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum','["fuel_cooler_pump", "pump_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P008F','P','Engine Coolant Temperature/Fuel Temperature Correlation','Kühlmitteltemperatur zu Kraftstofftemperatur Korrelation','Engine coolant temperature and fuel temperature readings are inconsistent — at long soak both should be near ambient and converge under load. One sensor has drifted.','Kühlmittel- und Kraftstofftemperatur sind nicht stimmig — nach längerer Standzeit sollten beide nahe Umgebungstemperatur liegen und sich unter Last angleichen. Ein Sensor ist verschoben.','["coolant_temp_sensor", "fuel_temp_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "One temperature sensor reading drifted", "de": "Einer der Temperatursensoren liefert verschobenen Messwert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0090','P','Fuel Pressure Regulator A Control Circuit/Open','Kraftstoffdruckregler A Schaltkreis unterbrochen','Open circuit at fuel pressure regulator A. The actuator that controls rail pressure cannot be driven.','Unterbrechung am Kraftstoffdruckregler A. Der Aktuator zur Raildruckregelung kann nicht angesteuert werden.','["fuel_pressure_regulator", "regulator_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break or unplugged connector", "de": "Kabelbruch oder loser Stecker"}, {"id": "regulator_coil_open", "p": "medium", "en": "Regulator solenoid open", "de": "Druckregler-Magnetspule unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0091','P','Fuel Pressure Regulator A Control Circuit Low','Kraftstoffdruckregler A Schaltkreis niedrig','Fuel pressure regulator A control voltage below expected range — short to ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often','Steuerspannung am Kraftstoffdruckregler A unter Sollbereich — Masseschluss. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Cod','["fuel_pressure_regulator", "regulator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0092','P','Fuel Pressure Regulator A Control Circuit High','Kraftstoffdruckregler A Schaltkreis hoch','Fuel pressure regulator A control voltage above expected range — short to power or open ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code i','Steuerspannung am Kraftstoffdruckregler A über Sollbereich — Plus-Schluss oder offene Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbau','["fuel_pressure_regulator", "regulator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0093','P','Fuel System Leak Detected - Large Leak','Kraftstoffsystem-Leckage erkannt - großes Leck','The ECU detected a large leak in the fuel system. Rail pressure cannot be maintained, often visible as fuel odor or visible drips.','Die Motorsteuerung hat ein großes Leck im Kraftstoffsystem erkannt. Raildruck kann nicht gehalten werden, oft als Kraftstoffgeruch oder sichtbarer Austritt.','["fuel_lines", "fuel_rail", "injector_seals"]','[{"id": "fuel_line_leak", "p": "high", "en": "Fuel line cracked or fitting loose", "de": "Kraftstoffleitung gerissen oder Verschraubung locker"}, {"id": "injector_o_ring", "p": "medium", "en": "Injector O-ring failed", "de": "Injektor-O-Ring defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0094','P','Fuel System Leak Detected - Small Leak','Kraftstoffsystem-Leckage erkannt - kleines Leck','A small fuel system leak detected by long-term pressure drop pattern. Often a slowly weeping injector or hairline crack in a fitting.','Kleines Leck im Kraftstoffsystem über Langzeit-Druckabfallmuster erkannt. Häufig ein leicht tropfender Injektor oder Haarriss an einer Verschraubung.','["fuel_lines", "injector_seals"]','[{"id": "weeping_injector", "p": "high", "en": "Injector seal slowly leaking", "de": "Injektor-Dichtung tropft langsam"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0095','P','Intake Air Temperature Sensor 2 Circuit Bank 1','Ansauglufttemperatursensor 2 Schaltkreis Bank 1','Generic electrical fault on intake air temperature sensor 2 (typically post-intercooler) on bank 1. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold readi','Allgemeiner elektrischer Fehler am Ansauglufttemperatursensor 2 (meist nach Ladeluftkühler) Bank 1. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse falsch und schiebt da','["iat_sensor_2", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor element failed", "de": "Sensor defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0096','P','Intake Air Temperature Sensor 2 Circuit Range/Performance Bank 1','Ansauglufttemperatursensor 2 Bereich/Leistung Bank 1','IAT sensor 2 reading on bank 1 is electrically valid but implausible — does not match other temperature sources or expected behavior.','Wert des IAT-Sensors 2 Bank 1 elektrisch plausibel, aber unstimmig — passt nicht zu anderen Temperaturquellen oder erwartetem Verhalten.','["iat_sensor_2"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0097','P','Intake Air Temperature Sensor 2 Circuit Low Bank 1','Ansauglufttemperatursensor 2 Schaltkreis niedrig Bank 1','IAT sensor 2 bank 1 signal voltage below expected range — short to ground. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold reading) or rich (hot reading)','Signalspannung IAT-Sensor 2 Bank 1 unter Sollbereich — Masseschluss. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse falsch und schiebt das Gemisch mager (zu kalter Wert','["iat_sensor_2", "sensor_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0098','P','Intake Air Temperature Sensor 2 Circuit High Bank 1','Ansauglufttemperatursensor 2 Schaltkreis hoch Bank 1','IAT sensor 2 bank 1 signal voltage above expected range — open circuit or short to power. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold reading) or ric','Signalspannung IAT-Sensor 2 Bank 1 über Sollbereich — Unterbrechung oder Plus-Schluss. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse falsch und schiebt das Gemisch mag','["iat_sensor_2", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open", "de": "Signalleitung unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0099','P','Intake Air Temperature Sensor 2 Circuit Intermittent/Erratic Bank 1','Ansauglufttemperatursensor 2 sporadisch/unstetig Bank 1','Intermittent dropouts or noise on IAT sensor 2 bank 1 signal. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold reading) or rich (hot reading).','Sporadische Aussetzer oder Störungen am Signal des IAT-Sensors 2 Bank 1. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse falsch und schiebt das Gemisch mager (zu kalter ','["iat_sensor_2", "sensor_wiring"]','[{"id": "loose_connector", "p": "high", "en": "Connector loose or corroded", "de": "Stecker locker oder korrodiert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009A','P','Intake Air Temperature/Ambient Air Temperature Correlation','Ansauglufttemperatur zu Außenlufttemperatur Korrelation','Intake air temperature and ambient air temperature readings deviate beyond plausible limits — at engine off both should match within tolerance.','Ansauglufttemperatur und Außenlufttemperatur weichen über plausibles Maß ab — bei stehendem Motor sollten beide übereinstimmen.','["iat_sensor", "ambient_air_temp_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009B','P','Fuel Pressure Relief Control Circuit/Open','Kraftstoff-Druckentlastung Schaltkreis unterbrochen','Open circuit at fuel pressure relief solenoid (used to bleed off rail pressure during certain operating modes).','Unterbrechung am Druckentlastungs-Magnetventil (entlastet den Raildruck in bestimmten Betriebsmodi).','["pressure_relief_solenoid", "solenoid_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009C','P','Fuel Pressure Relief Control Circuit Low','Kraftstoff-Druckentlastung Schaltkreis niedrig','Pressure relief solenoid control voltage below expected range — short to ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often ','Steuerspannung Druckentlastungs-Magnetventil unter Sollbereich — Masseschluss. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem ','["pressure_relief_solenoid", "solenoid_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009D','P','Fuel Pressure Relief Control Circuit High','Kraftstoff-Druckentlastung Schaltkreis hoch','Pressure relief solenoid control voltage above expected range — short to power or open ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is','Steuerspannung Druckentlastungs-Magnetventil über Sollbereich — Plus-Schluss oder offene Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabel','["pressure_relief_solenoid", "solenoid_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009E','P','Fuel Pressure Relief Control Performance/Stuck Off','Kraftstoff-Druckentlastung Leistung/klemmt aus','Pressure relief solenoid does not relieve pressure when commanded — stuck closed.','Druckentlastungs-Magnetventil entlastet den Druck bei Anforderung nicht — klemmt geschlossen.','["pressure_relief_solenoid"]','[{"id": "solenoid_stuck_closed", "p": "high", "en": "Solenoid stuck closed by contamination", "de": "Magnetventil durch Verschmutzung geschlossen klemmend"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P009F','P','Fuel Pressure Relief Control Stuck On','Kraftstoff-Druckentlastung klemmt zugeschaltet','Pressure relief solenoid stays open when not commanded — rail pressure cannot build up properly.','Druckentlastungs-Magnetventil bleibt offen, obwohl nicht angesteuert — Raildruck kann nicht richtig aufgebaut werden.','["pressure_relief_solenoid"]','[{"id": "solenoid_stuck_open", "p": "high", "en": "Solenoid stuck open", "de": "Magnetventil h\u00e4ngt offen"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 700], "estimated_hours": [0.5, 3]}',1);
