INSERT OR IGNORE INTO dtc_codes VALUES('P00BD','P','Mass or Volume Air Flow A Circuit Range/Performance - Air Flow Too High','Luftmassenmesser A Bereich/Leistung - Luftstrom zu hoch','Mass or Volume Air Flow A Circuit Range/Performance - Air Flow Too High: the signal is implausible or outside the valid range.','Luftmassenmesser A Bereich/Leistung - Luftstrom zu hoch: das Signal ist unplausibel bzw. außerhalb des gültigen Bereichs.','["mass_air_flow_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "MAF reading drifted high", "de": "LMM-Wert nach oben verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 400], "estimated_hours": [0.3, 2]}',1);
