INSERT OR IGNORE INTO dtc_codes VALUES('P00C0','P','Turbocharger/Supercharger Bypass Valve B Control Circuit','Turbolader/Kompressor Bypassventil B Schaltkreis','Generic electrical fault on bypass valve B control. Same family as P0039 on actuator B. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressu','Allgemeiner elektrischer Fehler an der Ansteuerung des Bypassventils B. Wie P0039, jedoch Aktuator B. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator','["bypass_valve_b", "actuator_wiring"]','[{"id": "solenoid_failed", "p": "high", "en": "Solenoid failed", "de": "Magnetventil defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P00C1','P','Turbocharger/Supercharger Bypass Valve B Control Circuit Low','Turbolader/Kompressor Bypassventil B Schaltkreis niedrig','Bypass valve B control voltage below expected range — short to ground. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Steuerspannung Bypassventil B unter Sollbereich — Masseschluss. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["bypass_valve_b", "actuator_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P00C2','P','Turbocharger/Supercharger Bypass Valve B Control Circuit High','Turbolader/Kompressor Bypassventil B Schaltkreis hoch','Bypass valve B control voltage above expected range. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Steuerspannung Bypassventil B über Sollbereich. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["bypass_valve_b", "actuator_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P00C3','P','Turbocharger/Supercharger Bypass Valve B Control Circuit Range/Performance','Turbolader/Kompressor Bypassventil B Schaltkreis Bereich/Leistung','Bypass valve B does not respond to commands as expected. Mechanical issue. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Bypassventil B reagiert nicht erwartungsgemäß auf Anforderungen. Mechanisches Problem. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den gefo','["bypass_valve_b"]','[{"id": "valve_stuck", "p": "high", "en": "Valve sticking from carbon", "de": "Ventil h\u00e4ngt durch Verkokung"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1, 6]}',1);
