INSERT OR IGNORE INTO dtc_codes VALUES('P00C9','P','Fuel Pressure Regulator A Solenoid Supply Voltage Control Circuit Low','Kraftstoffdruckregler A Magnet-Versorgungsspannung niedrig','Supply voltage to fuel pressure regulator A solenoid below expected range — fuse, relay or wiring fault.','Versorgungsspannung zum Kraftstoffdruckregler A unter Sollbereich — Sicherung, Relais oder Verkabelung defekt.','["regulator_supply", "fuse", "relay"]','[{"id": "blown_fuse", "p": "high", "en": "Supply fuse blown or relay failed", "de": "Versorgungssicherung oder Relais defekt"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [10, 200], "estimated_hours": [0.3, 1.5]}',1);
