INSERT OR IGNORE INTO dtc_codes VALUES('P00CE','P','Intake Air Temperature Measurement System - Multiple Sensor Correlation Bank 1','Ansauglufttemperatur-Messsystem - Multi-Sensor Korrelation Bank 1','Multiple intake air temperature sensors on bank 1 disagree beyond plausible limits. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold reading) or rich (hot','Mehrere Ansauglufttemperatursensoren auf Bank 1 weichen über das plausible Maß ab. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse falsch und schiebt das Gemisch mager (','["iat_sensor_1", "iat_sensor_2"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
