INSERT OR IGNORE INTO dtc_codes VALUES('P00D7','P','Turbocharger/Supercharger Bypass Valve A Temperature Too High','Turbolader/Kompressor Bypassventil A Temperatur zu hoch','Turbocharger/Supercharger Bypass Valve A Temperature Too High: the component is overheating, typically from extended load or slip. This affects turbo/supercharger boost-pressure control.','Turbolader/Kompressor Bypassventil A Temperatur zu hoch: das Bauteil überhitzt, meist durch andauernde Last oder Schlupf. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["bypass_valve_a", "intercooler"]','[{"id": "cooling_failure", "p": "high", "en": "Cooling system not adequately removing heat", "de": "K\u00fchlsystem f\u00fchrt nicht ausreichend W\u00e4rme ab"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P00D8','P','Turbocharger/Supercharger Bypass Valve B Temperature Too High','Turbolader/Kompressor Bypassventil B Temperatur zu hoch','Turbocharger/Supercharger Bypass Valve B Temperature Too High: the component is overheating, typically from extended load or slip. This affects turbo/supercharger boost-pressure control.','Turbolader/Kompressor Bypassventil B Temperatur zu hoch: das Bauteil überhitzt, meist durch andauernde Last oder Schlupf. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["bypass_valve_b", "intercooler"]','[{"id": "cooling_failure", "p": "high", "en": "Cooling system inadequate", "de": "K\u00fchlsystem unzureichend"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P00D9','P','Ambient Air Temperature Sensor Circuit B','Außenlufttemperatursensor Schaltkreis B','Generic electrical fault on ambient air temperature sensor B (second sensor for redundancy or second measurement location).','Allgemeiner elektrischer Fehler am Außenlufttemperatursensor B (zweiter Sensor für Redundanz oder andere Messstelle).','["ambient_air_temp_sensor_b", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
