INSERT OR IGNORE INTO dtc_codes VALUES('P00E3','P','Exhaust Heat Exchanger Exhaust Bypass Valve A Stuck Open','Abgaswärmetauscher Bypassventil A klemmt offen','The exhaust heat exchanger bypass valve A is stuck open. Engine warms up too slowly because exhaust does not heat the heat exchanger.','Das Bypassventil A des Abgaswärmetauschers klemmt offen. Motor erwärmt sich zu langsam, weil Abgas den Wärmetauscher nicht aufheizt.','["exhaust_bypass_valve_a", "heat_exchanger"]','[{"id": "valve_stuck_open", "p": "high", "en": "Valve stuck open by carbon", "de": "Ventil offen klemmend durch Verkokung"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [2, 6]}',1);
