INSERT OR IGNORE INTO dtc_codes VALUES('P00E5','P','Intake Air Temperature/Fuel Temperature Correlation','Ansauglufttemperatur zu Kraftstofftemperatur Korrelation','Intake air and fuel temperature readings are inconsistent — at long soak both should match ambient. The intake air temperature sensor feeds the ECM''s density calculation — a drifted reading miscalculates fuel mass and pushes mixture lean (cold readi','Ansaugluft- und Kraftstofftemperatur sind nicht stimmig — nach längerer Standzeit sollten beide der Umgebung entsprechen. Der Ansaugluft-Temperatursensor speist die Dichteberechnung des Steuergeräts — ein driftender Wert berechnet die Kraftstoffmasse','["iat_sensor", "fuel_temp_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
