INSERT OR IGNORE INTO dtc_codes VALUES('P0243','P','Turbocharger/Supercharger Wastegate Actuator A','Turbolader/Kompressor Wastegate-Aktuator A','Generic fault on wastegate actuator A. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Allgemeiner Fehler am Wastegate-Aktuator A. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["wastegate_actuator_a", "actuator_wiring"]','[{"id": "actuator_failed", "p": "high", "en": "Actuator failed", "de": "Aktuator defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1, 6]}',1);
