INSERT OR IGNORE INTO dtc_codes VALUES('P0245','P','Turbocharger/Supercharger Wastegate Solenoid "A" Low','Lader-Wastegate-Magnetventil "A" niedrig','Turbocharger/Supercharger Wastegate Solenoid "A" Low: the control module has detected this fault condition. This affects turbo/supercharger boost-pressure control.','Lader-Wastegate-Magnetventil "A" niedrig: das Steuergerät hat diesen Fehlerzustand erkannt. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["wastegate_solenoid", "solenoid_wiring", "turbocharger"]','[{"id": "wastegate_solenoid_open", "p": "high", "en": "Solenoid winding open", "de": "Magnetwicklung unterbrochen"}, {"id": "solenoid_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.3, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0246','P','Turbocharger/Supercharger Wastegate Solenoid "A" High','Lader-Wastegate-Magnetventil "A" hoch','Turbocharger/Supercharger Wastegate Solenoid "A" High: the control module has detected this fault condition. This affects turbo/supercharger boost-pressure control.','Lader-Wastegate-Magnetventil "A" hoch: das Steuergerät hat diesen Fehlerzustand erkannt. Dies betrifft die Ladedruckregelung des Turbo-/Kompressors.','["wastegate_solenoid", "solenoid_wiring"]','[{"id": "wastegate_solenoid_short_supply", "p": "high", "en": "Solenoid circuit shorted to supply", "de": "Stromkreis Kurzschluss gegen Versorgung"}, {"id": "ecu_driver_failed", "p": "low", "en": "ECU driver damaged", "de": "Endstufe im Steuerger\u00e4t besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.3, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0247','P','Turbocharger Wastegate Solenoid B Low','Turbolader-Wastegate-Magnetventil B niedrig','The control circuit for wastegate solenoid B reports a voltage below the expected range. Likely a short to ground, open winding or wiring fault.','Der Ansteuerkreis des Wastegate-Magnetventils B meldet eine Spannung unterhalb des erwarteten Bereichs. Ursache ist meist Masseschluss, offene Wicklung oder Kabelfehler.','["wastegate_solenoid", "turbocharger", "solenoid_wiring"]','[{"id": "wastegate_solenoid_fault", "p": "high", "en": "Wastegate solenoid B defective", "de": "Wastegate-Magnetventil B defekt"}, {"id": "solenoid_wiring_short", "p": "medium", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector corroded", "de": "Stecker korrodiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',1);
