INSERT OR IGNORE INTO dtc_codes VALUES('P027E','P','Cold Start Fuel Injection Quantity A Lower Than Expected','Kaltstart-Einspritzmenge A geringer als erwartet','During cold start the injection quantity A is below the commanded amount. Hard starting in cold conditions.','Beim Kaltstart liegt die Einspritzmenge A unter dem Sollwert. Schwerer Start bei Kälte.','["fuel_injectors", "high_pressure_fuel_pump"]','[{"id": "injector_clogged", "p": "high", "en": "Injector clogged", "de": "Injektor verstopft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1.5, 8]}',1);
