INSERT OR IGNORE INTO dtc_codes VALUES('P0299','P','Turbocharger/Supercharger "A" Underboost Condition','Turbolader/Kompressor "A" Unterdruck','Boost pressure under load is below the commanded value. Very common on turbodiesel and direct-injection turbo gasoline engines as the turbo system ages — typically a leaking boost pipe, a sticky variable-geometry vane assembly, or a wastegate that no','Der Ladedruck unter Last bleibt unter dem Sollwert. Sehr häufig bei Turbodiesel und direkteinspritzenden Turbo-Benzinern mit zunehmendem Alter — meist ein undichtes Ladeluftrohr, festsitzende variable Turbinengeometrie oder ein Wastegate, das nicht m','["turbocharger", "intercooler", "intercooler_pipe", "wastegate_actuator", "vgt_actuator"]','[{"id": "boost_leak", "p": "high", "en": "Leak in intercooler pipe or hose", "de": "Leck in Ladeluftrohr oder -schlauch"}, {"id": "vgt_sticking", "p": "high", "en": "VGT vanes stuck (diesel, soot buildup)", "de": "VTG-Leitschaufeln festgesetzt (Diesel, Russ)"}, {"id": "wastegate_stuck_open", "p": "medium", "en": "Wastegate stuck open or weak spring", "de": "Wastegate h\u00e4ngt offen oder Feder zu schwach"}, {"id": "turbo_bearing_worn", "p": "low", "en": "Turbo bearing worn (preceded by oil consumption / smoke)", "de": "Turbolader-Lager verschlissen (vorab \u00d6lverbrauch / Rauch)"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 3000], "estimated_hours": [0.5, 10.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P029A','P','Cylinder 1 - Fuel Trim at Max Limit','Zylinder 1 - Gemischadaption am Maximum','Per-cylinder fuel trim on cylinder 1 has reached its maximum correction limit. Cylinder running too lean structurally.','Zylinderindividuelle Gemischadaption Zylinder 1 hat das Maximum erreicht. Zylinder strukturell zu mager.','["injector_cyl1", "intake_system"]','[{"id": "injector_clogged", "p": "high", "en": "Injector clogged on cylinder 1", "de": "Injektor Zylinder 1 verstopft"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 1000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P029B','P','Cylinder 1 - Fuel Trim at Min Limit','Zylinder 1 - Gemischadaption am Minimum','Per-cylinder fuel trim on cylinder 1 has reached its minimum correction limit. Cylinder running too rich structurally.','Zylinderindividuelle Gemischadaption Zylinder 1 hat das Minimum erreicht. Zylinder strukturell zu fett.','["injector_cyl1"]','[{"id": "injector_leak", "p": "high", "en": "Injector leaking on cylinder 1", "de": "Injektor Zylinder 1 undicht"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 1000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P029C','P','Cylinder 1 - Injector Restricted','Zylinder 1 - Injektor verstopft','Cylinder 1 injector flow restricted — partial blockage detected. A flow-deviating injector throws off cylinder balance — adjacent cylinders run leaner/richer to compensate, often masking the root cause until the trim limit is hit.','Injektor Zylinder 1 mit eingeschränktem Durchfluss — teilweise Verstopfung erkannt. Ein abweichender Injektor stört die Zylinderbalance — Nachbarzylinder laufen kompensatorisch magerer/fetter, was die Ursache oft maskiert, bis das Trim-Limit erreicht','["injector_cyl1"]','[{"id": "injector_clogged", "p": "high", "en": "Injector nozzle clogged", "de": "Injektord\u00fcse verstopft"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 800], "estimated_hours": [1, 4]}',1);
