INSERT OR IGNORE INTO dtc_codes VALUES('P0388','P','Crankshaft Position Sensor B Circuit High','Kurbelwellenpositionssensor B Schaltkreis hoch','Crank sensor B above upper plausibility — open signal or short to B+. The crankshaft position sensor provides RPM and crank angle — without a valid signal, no ignition and no injection. Engine will not start or stalls instantly.','Kurbelsensor B über oberer Plausibilität — offenes Signal oder Kurzschluss nach Plus. Der Kurbelwellen-Positionssensor liefert Drehzahl und Kurbelwinkel — ohne gültiges Signal keine Zündung und keine Einspritzung. Motor startet nicht oder stirbt sofo','["crankshaft_position_sensor"]','[{"id": "ckp_b_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0389','P','Crankshaft Position Sensor B Circuit Intermittent','Kurbelwellenpositionssensor B Schaltkreis sporadisch','Crank sensor B signal jumps or drops out intermittently — connector or wiring issue. The crankshaft position sensor provides RPM and crank angle — without a valid signal, no ignition and no injection. Engine will not start or stalls instantly.','Kurbelsensor-B-Signal springt oder fällt sporadisch aus — Stecker- oder Kabelbaumproblem. Der Kurbelwellen-Positionssensor liefert Drehzahl und Kurbelwinkel — ohne gültiges Signal keine Zündung und keine Einspritzung. Motor startet nicht oder stirbt ','["crankshaft_position_sensor"]','[{"id": "ckp_b_intermittent", "p": "high", "en": "Intermittent connector", "de": "Wackliger Stecker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P038A','P','Ignition I Control Signal Circuit/Open','Zündung I Steuersignal-Schaltkreis/offen','The ignition I control signal circuit is open — typically the PCM drive line for the first ignition coil group has lost continuity.','Der Steuerkreis des Zündsignals I ist offen — meist hat die Steuerleitung des Steuergeräts zur ersten Zündspulengruppe ihre Verbindung verloren.','["ignition_coil"]','[{"id": "ign_i_open_wiring", "p": "high", "en": "Open wire between PCM and coil", "de": "Unterbrechung zwischen Steuerger\u00e4t und Spule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 2.5]}',1);
