INSERT OR IGNORE INTO dtc_codes VALUES('P03AE','P','Cylinder 3 Pressure Too Low','Zylinder 3 Brennraumdruck zu niedrig','Cylinder 3 measured peak combustion pressure is below the calibrated minimum — typically low compression, weak injection, or stuck-open exhaust valve.','Der gemessene Spitzendruck im Brennraum von Zylinder 3 liegt unter dem kalibrierten Minimum — meist niedrige Kompression, schwache Einspritzung oder offen festsitzendes Auslassventil.','["cylinder_pressure_sensor"]','[{"id": "cyl3_press_too_low_comp", "p": "high", "en": "Low compression on cylinder 3", "de": "Niedrige Kompression an Zylinder 3"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 4000], "estimated_hours": [2.0, 8.0]}',1);
