INSERT OR IGNORE INTO dtc_codes VALUES('P03B9','P','Cylinder 4 Pressure Too High','Zylinder 4 Brennraumdruck zu hoch','Cylinder 4 measured peak combustion pressure is above the calibrated maximum — typically pre-ignition, knock, over-fuelling, or runaway combustion.','Der gemessene Spitzendruck im Brennraum von Zylinder 4 liegt über dem kalibrierten Maximum — meist Vorzündung, Klopfen, Überfettung oder ausser Kontrolle geratene Verbrennung.','["cylinder_pressure_sensor"]','[{"id": "cyl4_press_too_high_knock", "p": "high", "en": "Pre-ignition or knock", "de": "Vorz\u00fcndung oder Klopfen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 4000], "estimated_hours": [2.0, 8.0]}',1);
