INSERT OR IGNORE INTO dtc_codes VALUES('P03C5','P','Cylinder 5 Pressure Variation High','Zylinder 5 Brennraumdruck-Variation hoch','Cylinder-to-cylinder pressure variation on cylinder 5 is above the calibrated maximum — combustion is unstable cycle-to-cycle, typical of partial misfire or injector seat erosion.','Die Zyklus-Variation des Brennraumdrucks an Zylinder 5 liegt über dem kalibrierten Maximum — Verbrennung ist instabil, typisch für teilweise Aussetzer oder erodierten Injektorsitz.','["cylinder_pressure_sensor"]','[{"id": "cyl5_press_variation_high", "p": "high", "en": "Partial misfire", "de": "Teilweise Aussetzer"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1.0, 6.0]}',1);
