INSERT OR IGNORE INTO dtc_codes VALUES('P03FA','P','Ignition K Control Signal Circuit/Open','Zündung K Steuersignal-Schaltkreis/offen','Ignition K Control Signal Circuit/Open: the circuit is open. This line drives an ignition coil group; a fault causes misfire on those cylinders.','Zündung K Steuersignal-Schaltkreis/offen: der Stromkreis ist unterbrochen. Diese Leitung steuert eine Zündspulengruppe; ein Fehler verursacht Aussetzer an diesen Zylindern.','["ignition_coil"]','[{"id": "ign_k_open_wiring", "p": "high", "en": "Open wire between PCM and coil", "de": "Unterbrechung zwischen Steuerger\u00e4t und Spule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 2.5]}',1);
