INSERT OR IGNORE INTO dtc_codes VALUES('P0470','P','Exhaust Pressure Sensor A Circuit','Abgasdrucksensor A Schaltkreis','A general electrical fault on exhaust pressure sensor A — used to monitor backpressure across the DPF or to control variable-geometry turbo.','Allgemeiner elektrischer Fehler am Abgasdrucksensor A — überwacht den Gegendruck über den DPF oder steuert die VTG-Aufladung.','["exhaust_pressure_sensor"]','[{"id": "exh_press_a_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
