INSERT OR IGNORE INTO dtc_codes VALUES('P04C3','P','Fuel Fill Door Lock Position Sensor Circuit','Tankklappen-Verriegelung Lagesensor Stromkreis','A general circuit fault is detected on the fuel fill door lock position sensor or switch. Without it the ECU cannot determine whether the lock has actually engaged or released.','An dem Lagesensor oder Schalter der Tankklappenverriegelung wird ein allgemeiner Stromkreisfehler erkannt. Ohne ihn kann das Steuergerät nicht prüfen, ob die Verriegelung tatsächlich gegriffen oder gelöst hat.','["fuel_fill_door_lock_position_sensor"]','[{"id": "open_circuit", "p": "high", "en": "Open in sensor circuit", "de": "Unterbrechung im Sensorkreis"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 280], "estimated_hours": [0.5, 1.4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('P04C4','P','Fuel Fill Door Lock Position Sensor Circuit Range or Performance','Tankklappen-Verriegelung Lagesensor Stromkreis - Bereich/Funktion','Same as P04C3 with feedback in plausible range yet not matching the commanded lock state.','Wie P04C3, mit Rückmeldung im plausiblen Bereich, die aber nicht zum befohlenen Verriegelungszustand passt.','["fuel_fill_door_lock_position_sensor"]','[{"id": "signal_offset", "p": "high", "en": "Sensor signal offset", "de": "Sensorsignal mit Offset"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 280], "estimated_hours": [0.5, 1.4]}',0);
