INSERT OR IGNORE INTO dtc_codes VALUES('P059A','P','Active Grille Air Shutter A Position Sensor Circuit','Aktive Kühlerklappe A Lagesensor Stromkreis','Active Grille Air Shutter A Position Sensor Circuit: an electrical fault is present in the circuit. Active grille shutters manage airflow for engine cooling and aerodynamics.','Aktive Kühlerklappe A Lagesensor Stromkreis: im Stromkreis liegt ein elektrischer Fehler vor. Aktive Kühlerklappen steuern den Luftstrom für Motorkühlung und Aerodynamik.','["active_grille_shutter_a", "active_grille_position_sensor_a"]','[{"id": "open_circuit", "p": "high", "en": "Open in sensor or wiring", "de": "Unterbrechung in Sensor oder Verkabelung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 500], "estimated_hours": [0.6, 2.0]}',1);
