INSERT OR IGNORE INTO dtc_codes VALUES('P059E','P','Active Grille Air Shutter A Position Sensor Circuit Intermittent','Aktive Kühlerklappe A Lagesensor Stromkreis - aussetzend','Same as P059A with intermittent signal. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Wie P059A, mit aussetzendem Signal. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["active_grille_position_sensor_a", "active_grille_wiring_a"]','[{"id": "intermittent_contact", "p": "high", "en": "Intermittent contact at connector", "de": "Wackelkontakt am Stecker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 500], "estimated_hours": [0.6, 2.0]}',1);
