INSERT OR IGNORE INTO dtc_codes VALUES('P05A9','P','Active Grille Air Shutter B Position Sensor Circuit','Aktive Kühlerklappe B Lagesensor Stromkreis','Active Grille Air Shutter B Position Sensor Circuit: an electrical fault is present in the circuit. Active grille shutters manage airflow for engine cooling and aerodynamics.','Aktive Kühlerklappe B Lagesensor Stromkreis: im Stromkreis liegt ein elektrischer Fehler vor. Aktive Kühlerklappen steuern den Luftstrom für Motorkühlung und Aerodynamik.','["active_grille_position_sensor_b"]','[{"id": "open_circuit", "p": "high", "en": "Open in sensor or wiring", "de": "Unterbrechung in Sensor oder Verkabelung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 500], "estimated_hours": [0.6, 2.0]}',1);
