INSERT OR IGNORE INTO dtc_codes VALUES('P0666','P','Control Module Internal Temperature Sensor A Circuit','Steuermodul Innentemperatur-Sensor A Stromkreis','A general circuit fault on the ECU''s internal temperature sensor A - the sensor that monitors module operating temperature for thermal protection.','Allgemeiner Stromkreisfehler am Innentemperatur-Sensor A des Steuergeräts - dieser Sensor überwacht die Modul-Betriebstemperatur zum thermischen Schutz.','["ecu_internal_temperature_sensor_a"]','[{"id": "sensor_internal", "p": "high", "en": "Internal sensor fault", "de": "Interner Sensorfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0667','P','Control Module Internal Temperature Sensor A Range or Performance','Steuermodul Innentemperatur-Sensor A - Bereich/Funktion','Same as P0666 with the signal in plausible range yet not matching the engine bay environment.','Wie P0666, mit Signal im plausiblen Bereich, das aber nicht zur Motorraum-Umgebung passt.','["ecu_internal_temperature_sensor_a"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor element drifted", "de": "Sensorelement hat Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0668','P','Control Module Internal Temperature Sensor A Circuit Low','Steuermodul Innentemperatur-Sensor A Stromkreis - niedrig','Same as P0666 with the signal voltage below the plausible range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the loc','Wie P0666, mit Signalspannung unterhalb des plausiblen Bereichs. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisie','["ecu_internal_temperature_sensor_a"]','[{"id": "sensor_short", "p": "high", "en": "Sensor internal short", "de": "Interner Sensorkurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
