INSERT OR IGNORE INTO dtc_codes VALUES('P066A','P','Cylinder 1 Glow Plug Control Circuit Low','Zylinder 1 Glühkerze Steuerkreis - niedrig','The control line for the glow plug on cylinder 1 is shorted to ground or the plug is internally shorted.','Die Steuerleitung der Glühkerze an Zylinder 1 ist gegen Masse kurzgeschlossen oder die Kerze ist intern kurzgeschlossen.','["glow_plug_cyl_1", "glow_plug_wiring_cyl_1"]','[{"id": "short_to_ground", "p": "high", "en": "Control line shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 250], "estimated_hours": [0.4, 1.4]}',1);
