INSERT OR IGNORE INTO dtc_codes VALUES('P06AA','P','Control Module Internal Temperature B Too High','Steuermodul-Innentemperatur B zu hoch','Control Module Internal Temperature B Too High: the control module has detected this fault condition.','Steuermodul-Innentemperatur B zu hoch: das Steuergerät hat diesen Fehlerzustand erkannt.','["ecm"]','[{"id": "heat_soak", "p": "high", "en": "Heat soak around ECU", "de": "Hitzeeintrag rund um das Steuerger\u00e4t"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P06AB','P','Control Module Internal Temperature Sensor B Circuit','Steuermodul Innentemperatur-Sensor B Stromkreis','A general circuit fault on the ECU''s internal temperature sensor B - the sensor that monitors module operating temperature for thermal protection.','Allgemeiner Stromkreisfehler am Innentemperatur-Sensor B des Steuergeräts - dieser Sensor überwacht die Modul-Betriebstemperatur zum thermischen Schutz.','["ecu_internal_temperature_sensor_b"]','[{"id": "sensor_internal", "p": "high", "en": "Internal sensor fault", "de": "Interner Sensorfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P06AC','P','Control Module Internal Temperature Sensor B Range or Performance','Steuermodul Innentemperatur-Sensor B - Bereich/Funktion','Same as P0667 on internal sensor B.','Wie P0667, an Innensensor B.','["ecu_internal_temperature_sensor_b"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor element drifted", "de": "Sensorelement hat Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P06AD','P','Control Module Internal Temperature Sensor B Circuit Low','Steuermodul Innentemperatur-Sensor B Stromkreis - niedrig','Same as P0668 on internal sensor B. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Wie P0668, an Innensensor B. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["ecu_internal_temperature_sensor_b"]','[{"id": "sensor_short", "p": "high", "en": "Sensor internal short", "de": "Interner Sensorkurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2.0, 6.0]}',1);
