INSERT OR IGNORE INTO dtc_codes VALUES('P0769','P','Shift Solenoid D Intermittent','Schaltmagnetventil D aussetzend','Shift solenoid D shows intermittent electrical or hydraulic dropouts.','Das Schaltmagnetventil D zeigt sporadische elektrische oder hydraulische Aussetzer.','["shift_solenoid_d", "tcm"]','[{"id": "loose_connector", "p": "high", "en": "Loose connector at the transmission", "de": "Lockerer Stecker am Getriebe"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P076A','P','Shift Solenoid H','Schaltmagnetventil H','General fault on shift solenoid H — used in 8/9/10-speed transmissions where multiple shift solenoids manage the larger gear matrix. The TCM detects an electrical or hydraulic anomaly without yet being able to attribute it to a specific failure mode.','Allgemeiner Fehler am Schaltmagnetventil H — eingesetzt in 8-/9-/10-Gang-Getrieben, wo mehrere Schaltmagnete die größere Gangmatrix verwalten. Die Getriebesteuerung erkennt eine elektrische oder hydraulische Anomalie, ohne sie direkt einem spezifisch','["shift_solenoid_h", "valve_body"]','[{"id": "solenoid_fault", "p": "high", "en": "Solenoid electrical or hydraulic fault", "de": "Elektrischer oder hydraulischer Fehler am Magnetventil"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P076B','P','Shift Solenoid H Performance/Stuck Off','Schaltmagnetventil H Leistung/Aus festgesteckt','Shift solenoid H is electrically intact but does not engage hydraulically when commanded — corresponding clutch or band does not lock up.','Das Schaltmagnetventil H ist elektrisch in Ordnung, schaltet aber bei Befehl hydraulisch nicht — die zugehörige Kupplung oder Bremsband rastet nicht ein.','["shift_solenoid_h", "valve_body"]','[{"id": "stuck_closed_solenoid", "p": "high", "en": "Solenoid stuck closed by debris", "de": "Magnetventil durch Schmutz geschlossen festgesteckt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P076C','P','Shift Solenoid H Stuck On','Schaltmagnetventil H dauerhaft geschaltet','Shift solenoid H remains hydraulically active when commanded off — corresponding clutch or band cannot release, blocking dependent shifts.','Das Schaltmagnetventil H bleibt hydraulisch aktiv, wenn Aus befohlen wird — die zugehörige Kupplung oder Bremsband kann nicht öffnen und blockiert abhängige Schaltvorgänge.','["shift_solenoid_h", "valve_body"]','[{"id": "stuck_open_solenoid", "p": "high", "en": "Solenoid stuck open", "de": "Magnetventil offen festgesteckt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}, {"id": "component_age_wear", "p": "low", "en": "Component wear with age - mechanical play", "de": "Bauteil-Verschlei\u00df mit Alter - mechanisches Spiel"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2.0, 8.0]}',1);
