INSERT OR IGNORE INTO dtc_codes VALUES('P07CB','P','Transmission Fluid Thermostat Performance','Getriebeöl-Thermostat Leistung','The transmission fluid thermostat (similar in function to a coolant thermostat — opens at a calibrated temperature to route ATF through the cooler) does not regulate temperature within the expected band. Either stuck open (ATF stays cold, friction mo','Der Getriebeöl-Thermostat (ähnlich wie der Kühlmittel-Thermostat — öffnet ab einer kalibrierten Temperatur, um ATF durch den Kühler zu leiten) regelt die Temperatur nicht im erwarteten Band. Entweder offen festgesteckt (ATF bleibt kalt, Reibmodifikat','["transmission_fluid_thermostat", "transmission_cooler"]','[{"id": "stuck_open", "p": "high", "en": "Thermostat stuck open", "de": "Thermostat offen festgesteckt"}, {"id": "stuck_closed", "p": "medium", "en": "Thermostat stuck closed", "de": "Thermostat geschlossen festgesteckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',1);
