INSERT OR IGNORE INTO dtc_codes VALUES('P088C','P','Reverse Inhibit Control Circuit Low','Rückwärtsgang-Sperrsteuerkreis niedrig','Voltage on the reverse inhibit control circuit is below the expected window. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often conf','Spannung am Rückwärtsgang-Sperrsteuerkreis liegt unter dem erwarteten Bereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem ','["reverse_inhibit_control", "wiring_harness", "tcm"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "actuator_short", "p": "medium", "en": "Actuator internal short", "de": "Aktuator intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
