INSERT OR IGNORE INTO dtc_codes VALUES('P0A00','P','Motor Electronics Coolant Temperature Sensor Circuit','Leistungselektronik Kühlmitteltemperatursensor Stromkreis','The hybrid control module detects an out-of-range signal from the temperature sensor of the inverter/motor electronics coolant loop. This sensor protects power electronics from overheating.','Das Hybridsteuergerät erkennt ein Signal außerhalb des Bereichs vom Temperatursensor des Kühlkreislaufs der Leistungselektronik. Der Sensor schützt die Inverterelektronik vor Überhitzung.','["motor_electronics_coolant_temperature_sensor", "hybrid_inverter", "wiring_harness"]','[{"id": "sensor_failed", "p": "high", "en": "Temperature sensor failed", "de": "Temperatursensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1.5, 5.0]}',1);
