INSERT OR IGNORE INTO dtc_codes VALUES('P0A19','P','Motor Torque Sensor Circuit Low','Motor-Drehmomentsensor Stromkreis niedrig','The drive motor torque sensor reports a circuit low fault. Motor torque feedback is unreliable. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code i','Der Antriebsmotor-Drehmomentsensor meldet einen Fehler "Stromkreis niedrig". Die Motor-Drehmomentrückmeldung ist unzuverlässig. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückte','["motor_torque_sensor", "wiring_harness", "hybrid_control_module"]','[{"id": "sensor_failed", "p": "high", "en": "Torque sensor failed", "de": "Drehmomentsensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
