INSERT OR IGNORE INTO dtc_codes VALUES('P0A1B','P','Drive Motor A Control Module Performance','Antriebsmotor A Steuermodul Verhalten','The drive motor a control module reports a generic fault. Internal self-tests fail or response time outside calibration.','Das Antriebsmotor A Steuermodul Verhalten meldet einen allgemeinen Fehler. Interne Selbsttests schlagen fehl oder die Reaktionszeit liegt außerhalb der Kalibrierung.','["drive_motor_a_control_module"]','[{"id": "module_internal", "p": "high", "en": "Internal module fault", "de": "Interner Modulfehler"}, {"id": "communication_lost", "p": "medium", "en": "Communication degraded", "de": "Kommunikation verschlechtert"}, {"id": "needs_reflash", "p": "low", "en": "Module software outdated, reflash may resolve", "de": "Modul-Software veraltet, Reflash kann helfen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 3500], "estimated_hours": [3, 12]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A1C','P','Drive Motor A Phase U Current Sensor Circuit','Antriebsmotor A Phase U Stromsensor Stromkreis','The motor controller detects an electrical fault on the phase U current sensor of drive motor A. Phase current sensing is required for vector control of the synchronous machine.','Der Motorcontroller erkennt einen elektrischen Fehler am Phase-U-Stromsensor des Antriebsmotors A. Die Phasenstromerfassung ist Voraussetzung für die feldorientierte Regelung der Synchronmaschine.','["drive_motor_a", "phase_current_sensor", "inverter"]','[{"id": "sensor_failed", "p": "high", "en": "Current sensor failed", "de": "Stromsensor defekt"}, {"id": "inverter_fault", "p": "medium", "en": "Inverter internal fault", "de": "Interner Inverterfehler"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [800, 4500], "estimated_hours": [3.0, 12.0]}',1);
