INSERT OR IGNORE INTO dtc_codes VALUES('P0A1F','P','Battery Energy Control Module','Batterie-Energie-Steuermodul','A generic fault is reported by the battery energy control module of a hybrid or electric vehicle. The module manages charge balancing, temperature and contactor logic for the high-voltage battery.','Ein allgemeiner Fehler wird vom Batterie-Energie-Steuermodul eines Hybrid- oder Elektrofahrzeugs gemeldet. Das Modul verwaltet Ladungsausgleich, Temperatur und Schützlogik der Hochvoltbatterie.','["battery_energy_control_module", "hv_battery"]','[{"id": "becm_internal_fault", "p": "high", "en": "BECM internal fault", "de": "Interner Fehler im BECM"}, {"id": "becm_communication_lost", "p": "medium", "en": "Communication with BECM lost", "de": "Kommunikation mit BECM verloren"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [500, 4000], "estimated_hours": [2.0, 8.0]}',1);
