INSERT OR IGNORE INTO dtc_codes VALUES('P0A2A','P','Drive Motor A Temperature Sensor Circuit','Antriebsmotor A Temperatursensor Stromkreis','Electrical fault on the temperature sensor inside drive motor A windings. The sensor is used to derate motor torque when winding temperature approaches the insulation limit.','Elektrischer Fehler am Temperatursensor in den Wicklungen des Antriebsmotors A. Der Sensor dient zur Drehmomentreduktion, wenn die Wicklungstemperatur die Isolationsgrenze erreicht.','["drive_motor_a", "motor_temperature_sensor", "wiring_harness"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [500, 3500], "estimated_hours": [2.0, 10.0]}',1);
