INSERT OR IGNORE INTO dtc_codes VALUES('P0A88','P','14 Volt Power Module Current Sensor A Circuit Low','14-Volt-Leistungsmodul Stromsensor A Stromkreis niedrig','The current sensor A of the 14V DC/DC converter module reports a circuit low fault. 12V system current measurement is unreliable.','Der Stromsensor A des 14V-DC/DC-Wandlermoduls meldet einen Fehler "Stromkreis niedrig". Die 12V-System-Strommessung ist unzuverlässig.','["pm14v_current_sensor_a", "wiring_harness", "dcdc_converter"]','[{"id": "sensor_failed", "p": "high", "en": "Current sensor failed", "de": "Stromsensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A89','P','14 Volt Power Module Current Sensor A Circuit High','14-Volt-Leistungsmodul Stromsensor A Stromkreis hoch','The current sensor A of the 14V DC/DC converter module reports a circuit high fault. 12V system current measurement is unreliable.','Der Stromsensor A des 14V-DC/DC-Wandlermoduls meldet einen Fehler "Stromkreis hoch". Die 12V-System-Strommessung ist unzuverlässig.','["pm14v_current_sensor_a", "wiring_harness", "dcdc_converter"]','[{"id": "sensor_failed", "p": "high", "en": "Current sensor failed", "de": "Stromsensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8A','P','14 Volt Power Module Current Sensor A Circuit Intermittent','14-Volt-Leistungsmodul Stromsensor A Stromkreis sporadisch','The current sensor A of the 14V DC/DC converter module reports a circuit intermittent fault. 12V system current measurement is unreliable.','Der Stromsensor A des 14V-DC/DC-Wandlermoduls meldet einen Fehler "Stromkreis sporadisch". Die 12V-System-Strommessung ist unzuverlässig.','["pm14v_current_sensor_a", "wiring_harness", "dcdc_converter"]','[{"id": "sensor_failed", "p": "high", "en": "Current sensor failed", "de": "Stromsensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8B','P','14 Volt Power Module System Voltage','14-Volt-Leistungsmodul Systemspannung','The 14V DC/DC converter module reports a "system voltage" condition. 12V vehicle electrical supply may be impaired.','Das 14V-DC/DC-Wandlermodul meldet einen Zustand "Systemspannung". Die 12V-Bordnetz-Versorgung kann beeinträchtigt sein.','["pm14v_module", "dcdc_converter"]','[{"id": "module_internal", "p": "high", "en": "Internal module fault", "de": "Interner Modulfehler"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8C','P','14 Volt Power Module System Voltage Unstable','14-Volt-Leistungsmodul Systemspannung instabil','The 14V DC/DC converter module reports a "system voltage unstable" condition. 12V vehicle electrical supply may be impaired.','Das 14V-DC/DC-Wandlermodul meldet einen Zustand "Systemspannung instabil". Die 12V-Bordnetz-Versorgung kann beeinträchtigt sein.','["pm14v_module", "dcdc_converter"]','[{"id": "regulation_unstable", "p": "high", "en": "Voltage regulation unstable", "de": "Spannungsregelung instabil"}, {"id": "load_oscillation", "p": "medium", "en": "Load oscillation", "de": "Last-Oszillation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8D','P','14 Volt Power Module System Voltage Low','14-Volt-Leistungsmodul Systemspannung niedrig','The 14V DC/DC converter module reports a "system voltage low" condition. 12V vehicle electrical supply may be impaired.','Das 14V-DC/DC-Wandlermodul meldet einen Zustand "Systemspannung niedrig". Die 12V-Bordnetz-Versorgung kann beeinträchtigt sein.','["pm14v_module", "dcdc_converter"]','[{"id": "load_too_high", "p": "high", "en": "Load exceeds module capacity", "de": "Last \u00fcbersteigt Modul-Kapazit\u00e4t"}, {"id": "regulator_low", "p": "medium", "en": "Output regulator low", "de": "Ausgangs-Regler zu niedrig"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8E','P','14 Volt Power Module System Voltage High','14-Volt-Leistungsmodul Systemspannung hoch','The 14V DC/DC converter module reports a "system voltage high" condition. 12V vehicle electrical supply may be impaired.','Das 14V-DC/DC-Wandlermodul meldet einen Zustand "Systemspannung hoch". Die 12V-Bordnetz-Versorgung kann beeinträchtigt sein.','["pm14v_module", "dcdc_converter"]','[{"id": "regulator_overshoot", "p": "high", "en": "Output regulator overshoots", "de": "Ausgangs-Regler \u00fcberschwingt"}, {"id": "feedback_lost", "p": "medium", "en": "Voltage feedback lost", "de": "Spannungs-R\u00fcckmeldung verloren"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A8F','P','14 Volt Power Module System Performance','14-Volt-Leistungsmodul System-Verhalten','The 14V DC/DC converter module reports a "system performance" condition. 12V vehicle electrical supply may be impaired.','Das 14V-DC/DC-Wandlermodul meldet einen Zustand "System-Verhalten". Die 12V-Bordnetz-Versorgung kann beeinträchtigt sein.','["pm14v_module", "dcdc_converter"]','[{"id": "module_drift", "p": "high", "en": "Module characteristic drifted", "de": "Modul-Kennlinie driftet"}, {"id": "thermal_drift", "p": "medium", "en": "Thermal drift outside calibration", "de": "Thermische Drift au\u00dferhalb der Kalibrierung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A90','P','Drive Motor A Performance','Antriebsmotor A Verhalten','The drive motor A does not deliver the expected torque or efficiency. Phase imbalance, magnet weakness, or bearing wear.','Der Antriebsmotor A liefert nicht das erwartete Drehmoment oder die erwartete Effizienz. Phasen-Unsymmetrie, Magnet-Schwäche oder Lagerverschleiß.','["drive_motor_a"]','[{"id": "phase_imbalance", "p": "high", "en": "Phase current imbalance", "de": "Phasenstrom-Unsymmetrie"}, {"id": "magnet_aged", "p": "medium", "en": "Magnet flux degraded", "de": "Magnetfluss nachgelassen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [3, 16]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A91','P','Drive Motor B Performance','Antriebsmotor B Verhalten','The drive motor B does not deliver the expected torque or efficiency. Phase imbalance, magnet weakness, or bearing wear.','Der Antriebsmotor B liefert nicht das erwartete Drehmoment oder die erwartete Effizienz. Phasen-Unsymmetrie, Magnet-Schwäche oder Lagerverschleiß.','["drive_motor_b"]','[{"id": "phase_imbalance", "p": "high", "en": "Phase current imbalance", "de": "Phasenstrom-Unsymmetrie"}, {"id": "magnet_aged", "p": "medium", "en": "Magnet flux degraded", "de": "Magnetfluss nachgelassen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [3, 16]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A92','P','Hybrid Generator Performance','Hybrid-Generator Verhalten','The hybrid generator does not deliver the expected torque or efficiency. Phase imbalance, magnet weakness, or bearing wear.','Der Hybrid-Generator liefert nicht das erwartete Drehmoment oder die erwartete Effizienz. Phasen-Unsymmetrie, Magnet-Schwäche oder Lagerverschleiß.','["hybrid_generator"]','[{"id": "phase_imbalance", "p": "high", "en": "Phase current imbalance", "de": "Phasenstrom-Unsymmetrie"}, {"id": "magnet_aged", "p": "medium", "en": "Magnet flux degraded", "de": "Magnetfluss nachgelassen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [3, 16]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A93','P','Inverter A Cooling System Performance','Inverter A Kühlsystem Funktion','The hybrid control module detects insufficient cooling performance for inverter A, where coolant temperature rise per power dissipation exceeds expected value.','Das Hybridsteuergerät erkennt unzureichende Kühlleistung für Inverter A, wenn der Temperaturanstieg pro Verlustleistung über dem Erwartungswert liegt.','["hybrid_inverter", "electric_coolant_pump", "coolant_radiator"]','[{"id": "pump_weak", "p": "high", "en": "Coolant pump weak", "de": "K\u00fchlmittelpumpe schwach"}, {"id": "low_coolant", "p": "medium", "en": "Low coolant level", "de": "Niedriger K\u00fchlmittelstand"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1.5, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A94','P','DC/DC Converter Performance','DC/DC-Wandler Funktion','The DC/DC converter does not deliver commanded 12 V output current within tolerance, indicating internal degradation.','Der DC/DC-Wandler liefert den angeforderten 12-V-Ausgangsstrom nicht innerhalb der Toleranz, Hinweis auf interne Alterung.','["dc_dc_converter"]','[{"id": "converter_aging", "p": "high", "en": "Converter aged", "de": "Wandler gealtert"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [800, 4000], "estimated_hours": [3.0, 10.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A95','P','High Voltage Fuse','Hochvolt-Sicherung','BMS detects open high-voltage fuse, typically tripped by overcurrent event between battery and inverter or charger.','Das BMS erkennt eine offene Hochvolt-Sicherung, meist ausgelöst durch Überstrom zwischen Batterie und Inverter oder Lader.','["hv_fuse", "hv_battery"]','[{"id": "overcurrent_event", "p": "high", "en": "Overcurrent event", "de": "\u00dcberstromereignis"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1.5, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0A96','P','Hybrid/EV Battery Pack Cooling Fan 2 Control Circuit/Open','Hybrid/EV-Batteriepaket-Kühlerlüfter 2 Steuerkreis offen','The HV battery pack cooling fan 2 reports a control circuit/open condition. Battery thermal management is impaired.','Der HV-Batteriepaket-Kühlerlüfter 2 meldet einen Zustand "Steuerkreis offen". Das Thermomanagement der Batterie ist beeinträchtigt.','["hybrid_battery_cooling_fan_2", "wiring_harness", "bms"]','[{"id": "wire_open", "p": "high", "en": "Open in fan control wire", "de": "Unterbrechung in der L\u00fcfter-Steuerleitung"}, {"id": "motor_open", "p": "medium", "en": "Open fan motor", "de": "Offener L\u00fcftermotor"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
