INSERT OR IGNORE INTO dtc_codes VALUES('P0AD6','P','Hybrid/EV Battery Pack Air Flow Valve A Control Circuit Range/Performance','Hybrid/EV-Batteriepaket Luftstrom-Ventil A Steuerkreis Bereich/Leistung','The HV battery pack air flow valve A reports a control circuit range/performance condition. Air routing for thermal management is impaired.','Das HV-Batteriepaket Luftstrom-Ventil A meldet einen Zustand "Steuerkreis Bereich/Leistung". Die Luftführung für das Thermomanagement ist beeinträchtigt.','["hv_battery_air_flow_valve_a", "wiring_harness", "bms"]','[{"id": "actuator_lazy", "p": "high", "en": "Actuator response slower than calibrated", "de": "Aktuator-Reaktion langsamer als kalibriert"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0AD7','P','Hybrid/EV Battery Pack Air Flow Valve A Control Circuit Low','Hybrid/EV-Batteriepaket Luftstrom-Ventil A Steuerkreis niedrig','The HV battery pack air flow valve A reports a control circuit low condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often con','Das HV-Batteriepaket Luftstrom-Ventil A meldet einen Zustand "Steuerkreis niedrig". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei akt','["hv_battery_air_flow_valve_a", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "actuator_short", "p": "medium", "en": "Actuator internal short", "de": "Aktuator intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0AD8','P','Hybrid/EV Battery Pack Air Flow Valve A Control Circuit High','Hybrid/EV-Batteriepaket Luftstrom-Ventil A Steuerkreis hoch','The HV battery pack air flow valve A reports a control circuit high condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often co','Das HV-Batteriepaket Luftstrom-Ventil A meldet einen Zustand "Steuerkreis hoch". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktive','["hv_battery_air_flow_valve_a", "wiring_harness", "bms"]','[{"id": "short_to_battery", "p": "high", "en": "Wire shorted to B+", "de": "Leitung mit B+ kurzgeschlossen"}, {"id": "actuator_open", "p": "medium", "en": "Open actuator", "de": "Offener Aktuator"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
