INSERT OR IGNORE INTO dtc_codes VALUES('P0B07','P','Electric/Auxiliary Transmission Fluid Pump Motor Phase W Current Low','Elektrische/Auxiliäre Getriebeölpumpe Motor Phase W Strom niedrig','The phase W current of the auxiliary transmission fluid pump motor reports a current low fault. Pump phase commutation impaired.','Der Phase-W-Strom des Motors der Auxiliär-Getriebeölpumpe meldet einen Fehler "Strom niedrig". Pumpen-Phasen-Kommutierung beeinträchtigt.','["aux_trans_pump_motor_phase_w", "wiring_harness", "tcm"]','[{"id": "winding_open", "p": "high", "en": "Phase winding partially open", "de": "Phasenwicklung teilweise unterbrochen"}, {"id": "sensor_offset", "p": "medium", "en": "Current sensor offset drifted", "de": "Stromsensor-Versatz driftet"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 2500], "estimated_hours": [2, 8]}',1);
