INSERT OR IGNORE INTO dtc_codes VALUES('P0B09','P','Electric/Auxiliary Transmission Fluid Pump A Motor Supply Voltage Circuit/Open','Elektrische/Auxiliäre Getriebeölpumpe A Motor Versorgungsspannungs-Stromkreis offen','The supply voltage circuit of auxiliary transmission fluid pump A motor reports a open condition.','Der Versorgungsspannungs-Stromkreis des Motors der Auxiliär-Getriebeölpumpe A meldet einen Zustand "offen".','["aux_trans_pump_a_motor", "wiring_harness", "tcm"]','[{"id": "wire_open", "p": "high", "en": "Open in supply wire", "de": "Unterbrechung in der Versorgungsleitung"}, {"id": "fuse_blown", "p": "medium", "en": "Supply fuse blown", "de": "Versorgungssicherung durchgebrannt"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0A','P','Electric/Auxiliary Transmission Fluid Pump A Motor Supply Voltage Circuit Low','Elektrische/Auxiliäre Getriebeölpumpe A Motor Versorgungsspannungs-Stromkreis niedrig','The supply voltage circuit of auxiliary transmission fluid pump A motor reports a low condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code ','Der Versorgungsspannungs-Stromkreis des Motors der Auxiliär-Getriebeölpumpe A meldet einen Zustand "niedrig". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wacke','["aux_trans_pump_a_motor", "wiring_harness", "tcm"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "voltage_collapse", "p": "medium", "en": "Supply rail collapsed", "de": "Versorgungspfad bricht ein"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0B','P','Electric/Auxiliary Transmission Fluid Pump A Motor Supply Voltage Circuit High','Elektrische/Auxiliäre Getriebeölpumpe A Motor Versorgungsspannungs-Stromkreis hoch','The supply voltage circuit of auxiliary transmission fluid pump A motor reports a high condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code','Der Versorgungsspannungs-Stromkreis des Motors der Auxiliär-Getriebeölpumpe A meldet einen Zustand "hoch". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackelte','["aux_trans_pump_a_motor", "wiring_harness", "tcm"]','[{"id": "short_to_battery", "p": "high", "en": "Wire shorted to higher voltage", "de": "Leitung mit h\u00f6herer Spannung kurzgeschlossen"}, {"id": "alt_overvoltage", "p": "medium", "en": "Alternator overvoltage", "de": "Generator-\u00dcberspannung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0C','P','Electric/Auxiliary Transmission Fluid Pump A Hydraulic Leakage','Elektrische/Auxiliäre Getriebeölpumpe A Hydraulische Leckage','The TCM detects hydraulic leakage from auxiliary transmission fluid pump A. Pump output cannot maintain pressure due to internal or external leak.','Das Getriebesteuergerät erkennt eine hydraulische Leckage an der Auxiliär-Getriebeölpumpe A. Die Pumpenleistung kann den Druck aufgrund einer internen oder externen Leckage nicht halten.','["aux_trans_pump_a", "transmission_fluid"]','[{"id": "seal_aged", "p": "high", "en": "Pump seal aged", "de": "Pumpendichtung gealtert"}, {"id": "internal_wear", "p": "medium", "en": "Internal pump wear", "de": "Interner Pumpenverschlei\u00df"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0D','P','Electric/Auxiliary Transmission Fluid Pump Motor Control Module','Elektrische/Auxiliäre Getriebeölpumpe Motor-Steuermodul','The auxiliary transmission fluid pump motor control module reports an internal fault. Pump cannot be commanded reliably.','Das Motor-Steuermodul der Auxiliär-Getriebeölpumpe meldet einen internen Fehler. Die Pumpe kann nicht zuverlässig angesteuert werden.','["aux_trans_pump_control_module"]','[{"id": "module_internal", "p": "high", "en": "Internal module fault", "de": "Interner Modulfehler"}, {"id": "communication_lost", "p": "medium", "en": "Communication lost", "de": "Kommunikation verloren"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0E','P','Hybrid/EV Battery Pack Current Sensor B Circuit','Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis','The ECM detects a circuit fault on the hybrid/ev battery pack current sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["hv_battery_pack_current_sensor_b", "wiring_harness", "bms"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B0F','P','Hybrid/EV Battery Pack Current Sensor B Circuit Range/Performance','Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis Bereich/Leistung','The ECM detects a circuit range/performance fault on the hybrid/ev battery pack current sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis Bereich/Leistung" am Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["hv_battery_pack_current_sensor_b", "wiring_harness", "bms"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced", "de": "Sensorbefestigung versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B10','P','Hybrid/EV Battery Pack Current Sensor B Circuit Low','Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis niedrig','The ECM detects a circuit low fault on the hybrid/ev battery pack current sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis niedrig" am Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["hv_battery_pack_current_sensor_b", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B11','P','Hybrid/EV Battery Pack Current Sensor B Circuit High','Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis hoch','The ECM detects a circuit high fault on the hybrid/ev battery pack current sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis hoch" am Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["hv_battery_pack_current_sensor_b", "wiring_harness", "bms"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open sensor", "de": "Offener Sensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B12','P','Hybrid/EV Battery Pack Current Sensor B Circuit Intermittent/Erratic','Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis sporadisch/unsauber','The ECM detects a circuit intermittent/erratic fault on the hybrid/ev battery pack current sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis sporadisch/unsauber" am Hybrid/EV-Batteriepaket-Stromsensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["hv_battery_pack_current_sensor_b", "wiring_harness", "bms"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B13','P','Hybrid/EV Battery Pack Current Sensor A/B Correlation','Hybrid/EV-Batteriepaket-Stromsensor A/B Korrelation','The signals of HV battery pack current sensors A and B do not correlate within the calibrated tolerance. Sensor drift or harness offset.','Die Signale der HV-Batteriepaket-Stromsensoren A und B korrelieren nicht innerhalb der kalibrierten Toleranz. Sensordrift oder Verkabelungs-Versatz.','["hv_battery_pack_current_sensor_a", "hv_battery_pack_current_sensor_b", "bms"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Ein Sensor driftet"}, {"id": "ground_offset", "p": "medium", "en": "Ground offset between sensors", "de": "Massenversatz zwischen Sensoren"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 7]}',1);
