INSERT OR IGNORE INTO dtc_codes VALUES('P0B25','P','Hybrid/EV Battery A Voltage Low','Hybrid/EV-Batterie A Spannung niedrig','The voltage of HV battery A is below the expected window. Cell-group depleted, deeply aged, or sense fault.','Die Spannung der HV-Batterie A liegt unter dem erwarteten Bereich. Zellgruppe entladen, stark gealtert oder Messfehler.','["hv_battery_a", "bms"]','[{"id": "cell_aged", "p": "high", "en": "Cells in group aged - capacity reduced", "de": "Zellen in der Gruppe gealtert - Kapazit\u00e4t reduziert"}, {"id": "deep_discharge", "p": "medium", "en": "Deep discharge event", "de": "Tiefentladungs-Ereignis"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 5000], "estimated_hours": [3, 16]}',1);
