INSERT OR IGNORE INTO dtc_codes VALUES('P0B2B','P','Hybrid/EV Battery C Voltage','Hybrid/EV-Batterie C Spannung','The BMS detects a generic fault on the voltage measurement of HV battery C. Cell-group voltage monitoring is the foundation of HV battery safety — drift here triggers contactor opening, charge inhibit, and reduced power to protect the pack.','Das BMS erkennt einen allgemeinen Fehler bei der Spannungsmessung der HV-Batterie C. Die Zellgruppen-Spannungsüberwachung ist die Basis der HV-Batterie-Sicherheit — Drift hier löst Schütz-Öffnung, Lade-Sperre und Leistungsreduktion aus, um die Batter','["hv_battery_c", "bms"]','[{"id": "cell_imbalance", "p": "high", "en": "Cell imbalance in this group", "de": "Zell-Ungleichgewicht in dieser Gruppe"}, {"id": "sense_circuit_fault", "p": "medium", "en": "Sense circuit fault", "de": "Mess-Stromkreis-Fehler"}, {"id": "ground_circuit_resistance", "p": "low", "en": "Ground point with elevated resistance", "de": "Massepunkt mit erh\u00f6htem Widerstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 5000], "estimated_hours": [3, 16]}',1);
