INSERT OR IGNORE INTO dtc_codes VALUES('P0B33','P','High Voltage Service Disconnect Circuit','Hochvolt-Service-Trennung Stromkreis','The high-voltage service disconnect circuit reports a circuit condition. Safe HV disconnection state cannot be verified.','Der HV-Service-Trennungs-Stromkreis meldet einen Zustand "Stromkreis". Der sichere HV-Trennzustand kann nicht geprüft werden.','["hv_service_disconnect_switch", "wiring_harness", "bms"]','[{"id": "switch_failed", "p": "high", "en": "Service disconnect switch failed", "de": "Service-Trennschalter defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B34','P','High Voltage Service Disconnect Circuit Performance','Hochvolt-Service-Trennung Stromkreis Verhalten','The high-voltage service disconnect circuit reports a circuit performance condition. Safe HV disconnection state cannot be verified.','Der HV-Service-Trennungs-Stromkreis meldet einen Zustand "Stromkreis Verhalten". Der sichere HV-Trennzustand kann nicht geprüft werden.','["hv_service_disconnect_switch", "wiring_harness", "bms"]','[{"id": "switch_aged", "p": "high", "en": "Switch contacts aged", "de": "Schalterkontakte gealtert"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B35','P','High Voltage Service Disconnect Circuit Low','Hochvolt-Service-Trennung Stromkreis niedrig','The high-voltage service disconnect circuit reports a circuit low condition. Safe HV disconnection state cannot be verified.','Der HV-Service-Trennungs-Stromkreis meldet einen Zustand "Stromkreis niedrig". Der sichere HV-Trennzustand kann nicht geprüft werden.','["hv_service_disconnect_switch", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "switch_short", "p": "medium", "en": "Switch shorted", "de": "Schalter kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
