INSERT OR IGNORE INTO dtc_codes VALUES('P0B37','P','High Voltage Service Disconnect Open','Hochvolt-Service-Trennung offen','The high-voltage service disconnect circuit reports a open condition. Safe HV disconnection state cannot be verified.','Der HV-Service-Trennungs-Stromkreis meldet einen Zustand "offen". Der sichere HV-Trennzustand kann nicht geprüft werden.','["hv_service_disconnect_switch", "wiring_harness", "bms"]','[{"id": "switch_open", "p": "high", "en": "Service disconnect switch in service position", "de": "Service-Trennschalter in Service-Position"}, {"id": "wire_open", "p": "medium", "en": "Open in disconnect wire", "de": "Unterbrechung in der Trennleitung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B38','P','Motor Electronics Coolant Pump B Control Circuit/Open','Motor-Elektronik-Kühlmittelpumpe B Steuerkreis offen','The motor electronics coolant pump B control circuit reports a control circuit/open condition. Power electronics cooling cannot be commanded reliably on branch B.','Der Steuerstromkreis der Motor-Elektronik-Kühlmittelpumpe B meldet einen Zustand "Steuerkreis offen". Die Leistungselektronik-Kühlung auf Zweig B kann nicht zuverlässig angesteuert werden.','["motor_electronics_coolant_pump_b", "wiring_harness", "hybrid_control_module"]','[{"id": "wire_open", "p": "high", "en": "Open in pump control wire", "de": "Unterbrechung in der Pumpen-Steuerleitung"}, {"id": "motor_open", "p": "medium", "en": "Open pump motor", "de": "Offener Pumpenmotor"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
