INSERT OR IGNORE INTO dtc_codes VALUES('P0B3A','P','Motor Electronics Coolant Pump B Control Circuit High','Motor-Elektronik-Kühlmittelpumpe B Steuerkreis hoch','The motor electronics coolant pump B control circuit reports a control circuit high condition. Power electronics cooling cannot be commanded reliably on branch B.','Der Steuerstromkreis der Motor-Elektronik-Kühlmittelpumpe B meldet einen Zustand "Steuerkreis hoch". Die Leistungselektronik-Kühlung auf Zweig B kann nicht zuverlässig angesteuert werden.','["motor_electronics_coolant_pump_b", "wiring_harness", "hybrid_control_module"]','[{"id": "short_to_battery", "p": "high", "en": "Control wire shorted to B+", "de": "Steuerleitung mit B+ kurzgeschlossen"}, {"id": "motor_open", "p": "medium", "en": "Open pump motor", "de": "Offener Pumpenmotor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B3B','P','Hybrid/EV Battery Voltage Sense A Circuit','Hybrid/EV-Batterie-Spannungsmessung A Stromkreis','The BMS detects a circuit fault on voltage sense channel A of the high-voltage battery. Cell-group voltage measurement is unreliable on this channel.','Das BMS erkennt einen Fehler "Stromkreis" am Spannungsmess-Kanal A der Hochvolt-Batterie. Die Zellgruppen-Spannungsmessung auf diesem Kanal ist unzuverlässig.','["hv_battery_voltage_sense_a", "wiring_harness", "bms"]','[{"id": "sense_circuit_failed", "p": "high", "en": "Sense circuit failed", "de": "Mess-Stromkreis defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B3C','P','Hybrid/EV Battery Voltage Sense A Circuit Range/Performance','Hybrid/EV-Batterie-Spannungsmessung A Stromkreis Bereich/Leistung','The BMS detects a circuit range/performance fault on voltage sense channel A of the high-voltage battery. Cell-group voltage measurement is unreliable on this channel.','Das BMS erkennt einen Fehler "Stromkreis Bereich/Leistung" am Spannungsmess-Kanal A der Hochvolt-Batterie. Die Zellgruppen-Spannungsmessung auf diesem Kanal ist unzuverlässig.','["hv_battery_voltage_sense_a", "wiring_harness", "bms"]','[{"id": "sense_drift", "p": "high", "en": "Sense voltage drifted", "de": "Mess-Spannung driftet"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0B3D','P','Hybrid/EV Battery Voltage Sense A Circuit Low','Hybrid/EV-Batterie-Spannungsmessung A Stromkreis niedrig','The BMS detects a circuit low fault on voltage sense channel A of the high-voltage battery. Cell-group voltage measurement is unreliable on this channel.','Das BMS erkennt einen Fehler "Stromkreis niedrig" am Spannungsmess-Kanal A der Hochvolt-Batterie. Die Zellgruppen-Spannungsmessung auf diesem Kanal ist unzuverlässig.','["hv_battery_voltage_sense_a", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Sense wire shorted to ground", "de": "Mess-Leitung mit Masse kurzgeschlossen"}, {"id": "wire_open", "p": "medium", "en": "Open in sense wire", "de": "Unterbrechung in der Mess-Leitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
