INSERT OR IGNORE INTO dtc_codes VALUES('P0C1D','P','Electric/Auxiliary Transmission Fluid Pump Control Module Internal Temperature Sensor Circuit Range/Performance','Elektrische/Auxiliäre Getriebeölpumpe Steuermodul Innentemperatur-Sensor Stromkreis Bereich/Leistung','The internal temperature sensor signal is outside the calibrated range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms ','Das Signal des Innentemperatur-Sensors liegt außerhalb des kalibrierten Bereichs. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktiv','["aux_trans_pump_control_module"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "thermal_lag", "p": "medium", "en": "Thermal lag in module package", "de": "Thermische Verz\u00f6gerung im Modul-Geh\u00e4use"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
