INSERT OR IGNORE INTO dtc_codes VALUES('P0D00','P','Control Pilot Charging Ventilation Switch Circuit/Open','Steuerpilot-Lade-Ventilations-Schalter Stromkreis offen','The control pilot charging ventilation switch reports a circuit/open condition. Charging ventilation requirement signal compromised (used for indoor charging).','Der Steuerpilot-Lade-Ventilations-Schalter meldet einen Zustand "Stromkreis offen". Das Belüftungs-Anforderungs-Signal beim Laden ist beeinträchtigt (verwendet für Innen-Ladung).','["control_pilot_ventilation_switch", "wiring_harness", "bms"]','[{"id": "wire_open", "p": "high", "en": "Open in switch wire", "de": "Unterbrechung in der Schalter-Leitung"}, {"id": "switch_failed", "p": "medium", "en": "Switch failed", "de": "Schalter defekt"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0D01','P','Control Pilot Charging Ventilation Switch Range/Performance','Steuerpilot-Lade-Ventilations-Schalter Bereich/Leistung','The control pilot charging ventilation switch reports a range/performance condition. Charging ventilation requirement signal compromised (used for indoor charging).','Der Steuerpilot-Lade-Ventilations-Schalter meldet einen Zustand "Bereich/Leistung". Das Belüftungs-Anforderungs-Signal beim Laden ist beeinträchtigt (verwendet für Innen-Ladung).','["control_pilot_ventilation_switch", "wiring_harness", "bms"]','[{"id": "switch_aged", "p": "high", "en": "Switch contacts aged", "de": "Schalterkontakte gealtert"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0D02','P','Hybrid/EV Charging System Voltage Out Of Range','Hybrid/EV Ladesystem Spannung außerhalb Bereich','Charging system detects mains voltage outside acceptable range during AC charging, preventing safe charge initiation.','Das Ladesystem erkennt eine Netzspannung außerhalb des zulässigen Bereichs beim AC-Laden und verhindert einen sicheren Ladestart.','["on_board_charger", "charge_port", "external_evse"]','[{"id": "evse_fault", "p": "high", "en": "EVSE delivering wrong voltage", "de": "EVSE liefert falsche Spannung"}, {"id": "mains_supply", "p": "medium", "en": "Mains supply unstable", "de": "Netzversorgung instabil"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 1500], "estimated_hours": [0.5, 5.0]}',1);
