INSERT OR IGNORE INTO dtc_codes VALUES('P0D04','P','Control Pilot Charging Ventilation Switch Intermittent/Erratic','Steuerpilot-Lade-Ventilations-Schalter sporadisch/unsauber','The control pilot charging ventilation switch reports a intermittent/erratic condition. The on-board charger negotiates voltage, current and safety with the EVSE; a fault interrupts charging or limits it to AC slow-charge despite a DC fast charger be','Der Steuerpilot-Lade-Ventilations-Schalter meldet einen Zustand "sporadisch/unsauber". Das Bordladegerät verhandelt Spannung, Strom und Sicherheit mit der EVSE; ein Fehler unterbricht das Laden oder begrenzt es auf AC-Langsamladen trotz angeschlossen','["control_pilot_ventilation_switch", "wiring_harness", "bms"]','[{"id": "connector_loose", "p": "high", "en": "Connector not seated", "de": "Stecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 2]}',1);
