INSERT OR IGNORE INTO dtc_codes VALUES('P0D16','P','Battery Charging System A High Voltage Interlock Circuit Performance','Batterieladesystem A HV-Verriegelungs-Stromkreis Verhalten','The HV interlock circuit of battery charging system A reports a performance condition. Safety interlock chain may be compromised.','Der HV-Verriegelungs-Stromkreis des Batterieladesystems A meldet einen Zustand "Verhalten". Die Sicherheits-Verriegelungskette kann beeinträchtigt sein.','["bcs_a_hv_interlock", "wiring_harness", "bms"]','[{"id": "interlock_drift", "p": "high", "en": "Interlock signal drifted", "de": "Verriegelungs-Signal driftet"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0D17','P','Battery Charging System A High Voltage Interlock CircuitCircuit Low','Batterieladesystem A HV-Verriegelungs-Stromkreis niedrig','The HV interlock circuit of battery charging system A reports a circuit low condition. Safety interlock chain may be compromised.','Der HV-Verriegelungs-Stromkreis des Batterieladesystems A meldet einen Zustand "Stromkreis niedrig". Die Sicherheits-Verriegelungskette kann beeinträchtigt sein.','["bcs_a_hv_interlock", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "interlock_grounded", "p": "medium", "en": "Interlock grounded", "de": "Verriegelung mit Masse verbunden"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0D18','P','Battery Charging System A High Voltage Interlock CircuitCircuit High','Batterieladesystem A HV-Verriegelungs-Stromkreis hoch','The HV interlock circuit of battery charging system A reports a circuit high condition. Safety interlock chain may be compromised.','Der HV-Verriegelungs-Stromkreis des Batterieladesystems A meldet einen Zustand "Stromkreis hoch". Die Sicherheits-Verriegelungskette kann beeinträchtigt sein.','["bcs_a_hv_interlock", "wiring_harness", "bms"]','[{"id": "short_to_battery", "p": "high", "en": "Wire shorted to B+", "de": "Leitung mit B+ kurzgeschlossen"}, {"id": "pull_down_open", "p": "medium", "en": "Pull-down resistor open", "de": "Pull-Down-Widerstand offen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 6]}',1);
