INSERT OR IGNORE INTO dtc_codes VALUES('P0D29','P','Battery Charger Input Current Too Low','Batterielader Eingangsstrom zu niedrig','The battery charger reports input input current too low condition. EVSE/AC mains supply may be out of specification.','Der Batterielader meldet einen Eingangs-Zustand "Eingangsstrom zu niedrig". EVSE/Netzversorgung kann außerhalb der Spezifikation sein.','["battery_charger", "ac_input_circuit"]','[{"id": "load_low", "p": "high", "en": "Load demand low", "de": "Lastbedarf niedrig"}, {"id": "current_sensor_offset", "p": "medium", "en": "Current sensor offset drifted low", "de": "Stromsensor-Versatz driftet niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
