INSERT OR IGNORE INTO dtc_codes VALUES('P0D5C','P','Battery Charger Hybrid/EV Battery Output Power Performance','Batterielader Hybrid/EV-Batterie- Ausgangsleistung Verhalten','The hybrid/ev battery output power does not match the commanded value within tolerance. Charger characteristic drifted or load mismatch.','Die Hybrid/EV-Batterie--Ausgangsleistung passt nicht innerhalb der Toleranz zum Sollwert. Lader-Kennlinie driftet oder Last-Fehlanpassung.','["battery_charger_hv_output", "battery_charger"]','[{"id": "regulator_drift", "p": "high", "en": "Output regulator drifted", "de": "Ausgangs-Regler driftet"}, {"id": "load_mismatch", "p": "medium", "en": "Load mismatch", "de": "Last-Fehlanpassung"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0D5D','P','Battery Charger Hybrid/EV System Discharge Time Too Short','Batterielader Hybrid/EV-System Entladezeit zu kurz','The battery charger system DC-link discharge time is shorter than calibrated. Indicates short circuit in discharge path.','Die Zwischenkreis-Entladezeit des Batterielade-Systems ist kürzer als kalibriert. Deutet auf Kurzschluss im Entladepfad hin.','["battery_charger_discharge_circuit", "dc_link_capacitor"]','[{"id": "short_in_discharge", "p": "high", "en": "Short circuit in discharge path", "de": "Kurzschluss im Entladepfad"}, {"id": "resistor_short", "p": "medium", "en": "Discharge resistor shorted", "de": "Entlade-Widerstand kurzgeschlossen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [2, 10]}',1);
