INSERT OR IGNORE INTO dtc_codes VALUES('P0D61','P','Hybrid/EV Battery Pack Cooling Fan 2 Sense Circuit Low','Hybrid/EV-Batteriepaket-Kühlerlüfter 2 Mess-Stromkreis niedrig','The HV battery pack cooling fan 2 sense circuit reports a sense circuit low fault. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active ofte','Der Mess-Stromkreis des HV-Batteriepaket-Kühlerlüfters 2 meldet einen Fehler "Mess-Stromkreis niedrig". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest ','["hv_battery_cooling_fan_2_sense", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Sense wire shorted to ground", "de": "Mess-Leitung mit Masse kurzgeschlossen"}, {"id": "tachometer_short", "p": "medium", "en": "Tachometer shorted", "de": "Tachometer kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 600], "estimated_hours": [0.5, 3]}',1);
