INSERT OR IGNORE INTO dtc_codes VALUES('P0DFD','P','Battery Charger Coolant Control Valve Control Circuit/Open','Batterielader-Kühlmittel-Steuerventil Steuerkreis offen','The battery charger coolant control valve reports a control circuit/open condition. The on-board charger negotiates voltage, current and safety with the EVSE; a fault interrupts charging or limits it to AC slow-charge despite a DC fast charger being ','Das Batterielader-Kühlmittel-Steuerventil meldet einen Zustand "Steuerkreis offen". Das Bordladegerät verhandelt Spannung, Strom und Sicherheit mit der EVSE; ein Fehler unterbricht das Laden oder begrenzt es auf AC-Langsamladen trotz angeschlossener ','["battery_charger_coolant_valve", "wiring_harness", "bms"]','[{"id": "wire_open", "p": "high", "en": "Open in valve control wire", "de": "Unterbrechung in der Ventil-Steuerleitung"}, {"id": "actuator_open", "p": "medium", "en": "Open valve actuator", "de": "Offener Ventil-Aktuator"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
