INSERT OR IGNORE INTO dtc_codes VALUES('P0ECE','P','A/C Refrigerant Distribution Valve A Control Circuit Low','Klima-Kältemittel-Verteilventil A Steuerkreis niedrig','The A/C refrigerant distribution valve A reports a control circuit low condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often','Das Klima-Kältemittel-Verteilventil A meldet einen Zustand "Steuerkreis niedrig". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktiv','["ac_refrigerant_distribution_valve_a", "wiring_harness"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "coil_short", "p": "medium", "en": "Coil internal short", "de": "Spule intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0ECF','P','A/C Refrigerant Distribution Valve A Control Circuit High','Klima-Kältemittel-Verteilventil A Steuerkreis hoch','The A/C refrigerant distribution valve A reports a control circuit high condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active ofte','Das Klima-Kältemittel-Verteilventil A meldet einen Zustand "Steuerkreis hoch". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem ','["ac_refrigerant_distribution_valve_a", "wiring_harness"]','[{"id": "short_to_battery", "p": "high", "en": "Wire shorted to B+", "de": "Leitung mit B+ kurzgeschlossen"}, {"id": "coil_open", "p": "medium", "en": "Coil open", "de": "Spule offen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0ED0','P','A/C Refrigerant Distribution Valve A Performance','Klima-Kältemittel-Verteilventil A Verhalten','The A/C refrigerant distribution valve A reports a performance condition.','Das Klima-Kältemittel-Verteilventil A meldet einen Zustand "Verhalten".','["ac_refrigerant_distribution_valve_a", "wiring_harness"]','[{"id": "valve_stuck", "p": "high", "en": "Valve mechanically stuck", "de": "Ventil mechanisch klemmt"}, {"id": "refrigerant_low", "p": "medium", "en": "Refrigerant level low", "de": "K\u00e4ltemittel-Niveau niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0ED1','P','Hybrid/EV Battery Multiple Sensor Voltage Correlation','Hybrid/EV-Batterie Mehrfach-Sensor-Spannungskorrelation','The BMS detects that multiple HV battery voltage sensor readings disagree beyond calibration. SOC/SOH calculations unreliable.','Das BMS erkennt, dass mehrere HV-Batterie-Spannungs-Sensorwerte über die Kalibrierung hinaus abweichen. SOC/SOH-Berechnungen unzuverlässig.','["hv_battery_pack_voltage_sensors", "bms"]','[{"id": "sensor_offset_drift", "p": "high", "en": "Sensor offsets drifted", "de": "Sensor-Vers\u00e4tze driften"}, {"id": "wiring_resistance", "p": "medium", "en": "Sense wire resistance high", "de": "Mess-Leitungs-Widerstand hoch"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 3500], "estimated_hours": [3, 12]}',1);
