INSERT OR IGNORE INTO dtc_codes VALUES('P0EE4','P','A/C Refrigerant Distribution Valve B Control Circuit/Open','Klima-Kältemittel-Verteilventil B Steuerkreis offen','The A/C refrigerant distribution valve B reports a control circuit/open condition.','Das Klima-Kältemittel-Verteilventil B meldet einen Zustand "Steuerkreis offen".','["ac_refrigerant_distribution_valve_b", "wiring_harness"]','[{"id": "wire_open", "p": "high", "en": "Open in control wire", "de": "Unterbrechung in der Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Coil open", "de": "Spule offen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EE5','P','A/C Refrigerant Distribution Valve B Control Circuit Low','Klima-Kältemittel-Verteilventil B Steuerkreis niedrig','The A/C refrigerant distribution valve B reports a control circuit low condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often','Das Klima-Kältemittel-Verteilventil B meldet einen Zustand "Steuerkreis niedrig". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktiv','["ac_refrigerant_distribution_valve_b", "wiring_harness"]','[{"id": "short_to_ground", "p": "high", "en": "Wire shorted to ground", "de": "Leitung mit Masse kurzgeschlossen"}, {"id": "coil_short", "p": "medium", "en": "Coil internal short", "de": "Spule intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EE6','P','A/C Refrigerant Distribution Valve B Control Circuit High','Klima-Kältemittel-Verteilventil B Steuerkreis hoch','The A/C refrigerant distribution valve B reports a control circuit high condition. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active ofte','Das Klima-Kältemittel-Verteilventil B meldet einen Zustand "Steuerkreis hoch". Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem ','["ac_refrigerant_distribution_valve_b", "wiring_harness"]','[{"id": "short_to_battery", "p": "high", "en": "Wire shorted to B+", "de": "Leitung mit B+ kurzgeschlossen"}, {"id": "coil_open", "p": "medium", "en": "Coil open", "de": "Spule offen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EE7','P','A/C Refrigerant Distribution Valve B Performance','Klima-Kältemittel-Verteilventil B Verhalten','The A/C refrigerant distribution valve B reports a performance condition.','Das Klima-Kältemittel-Verteilventil B meldet einen Zustand "Verhalten".','["ac_refrigerant_distribution_valve_b", "wiring_harness"]','[{"id": "valve_stuck", "p": "high", "en": "Valve mechanically stuck", "de": "Ventil mechanisch klemmt"}, {"id": "refrigerant_low", "p": "medium", "en": "Refrigerant level low", "de": "K\u00e4ltemittel-Niveau niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EE8','P','Battery Charger Coupler Temperature Sensor B Circuit','Batterielade-Kopplungs-Temperatursensor B Stromkreis','The ECM detects a circuit fault on the battery charger coupler temperature sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Batterielade-Kopplungs-Temperatursensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_coupler_temp_sensor_b", "wiring_harness", "bms"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
