INSERT OR IGNORE INTO dtc_codes VALUES('P0EFA','P','Battery Charger A Input Voltage Sensor B Circuit High','Batterielader A Eingangs-Spannungssensor B Stromkreis hoch','The ECM detects a high fault on the battery charger a input voltage sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "hoch" am Batterielader A Eingangs-Spannungssensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_a_input_voltage_sensor_b", "wiring_harness", "bms"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open sensor", "de": "Offener Sensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EFB','P','Battery Charger A Input Voltage Sensor B Circuit Intermittent/Erratic','Batterielader A Eingangs-Spannungssensor B Stromkreis sporadisch/unsauber','The ECM detects a intermittent/erratic fault on the battery charger a input voltage sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "sporadisch/unsauber" am Batterielader A Eingangs-Spannungssensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_a_input_voltage_sensor_b", "wiring_harness", "bms"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EFC','P','Battery Charger A Input Voltage Sensor C Circuit','Batterielader A Eingangs-Spannungssensor C Stromkreis','The ECM detects a circuit fault on the battery charger a input voltage sensor c circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Batterielader A Eingangs-Spannungssensor C Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_a_input_voltage_sensor_c", "wiring_harness", "bms"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EFD','P','Battery Charger A Input Voltage Sensor C Circuit Range/Performance','Batterielader A Eingangs-Spannungssensor C Stromkreis Bereich/Leistung','The ECM detects a range/performance fault on the battery charger a input voltage sensor c circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Bereich/Leistung" am Batterielader A Eingangs-Spannungssensor C Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_a_input_voltage_sensor_c", "wiring_harness", "bms"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced", "de": "Sensorbefestigung versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0EFE','P','Battery Charger A Input Voltage Sensor C Circuit Low','Batterielader A Eingangs-Spannungssensor C Stromkreis niedrig','The ECM detects a low fault on the battery charger a input voltage sensor c circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "niedrig" am Batterielader A Eingangs-Spannungssensor C Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["battery_charger_a_input_voltage_sensor_c", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P0FFF','P','Reserved Powertrain Fault','Reservierter Antriebsstrang-Fehler','Manufacturer-specific reserved code in the SAE generic range used as catch-all for hybrid system faults that do not map to a more specific defined code. Should be diagnosed using the freeze frame data and any additional manufacturer codes.','Herstellerspezifischer reservierter Code im SAE-Generic-Bereich als Sammelcode für Hybridsystemfehler, die keinem spezifischeren Code zugeordnet sind. Diagnose erfolgt anhand der Freeze-Frame-Daten und ergänzender Herstellercodes.','["hybrid_control_module"]','[{"id": "unspecified_fault", "p": "medium", "en": "Unspecified hybrid system fault", "de": "Nicht n\u00e4her spezifizierter Hybridsystemfehler"}]','{"difficulty": "shop_only", "diy_possible": false, "estimated_cost_eur": [200, 5000], "estimated_hours": [1.0, 16.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2000','P','NOx Adsorber Efficiency Below Threshold (Bank 1)','NOx-Adsorber Wirkungsgrad unter Schwellwert (Bank 1)','The lean NOx trap (LNT) on bank 1 is no longer storing or releasing NOx within the required efficiency window. Detected by the downstream NOx sensor or model-based monitor — typically caused by sulphur poisoning, thermal aging, or a failed regenerati','Der Mager-NOx-Speicherkat (LNT) an Bank 1 speichert oder regeneriert NOx nicht mehr im geforderten Wirkungsgrad. Erkennt der nachgelagerte NOx-Sensor oder das modellbasierte Monitoring — meist durch Sulfatvergiftung, Alterung oder fehlgeschlagene Reg','["nox_adsorber_catalyst", "nox_sensor_downstream", "exhaust_temperature_sensor"]','[{"id": "lnt_sulphur_poisoning", "p": "high", "en": "Sulphur poisoning from high-sulphur fuel \u2014 desulphation regeneration not running", "de": "Sulfatvergiftung durch schwefelhaltigen Kraftstoff \u2014 Desulfatierung l\u00e4uft nicht"}, {"id": "lnt_thermal_aging", "p": "medium", "en": "Thermal aging of washcoat after high-temperature exposure", "de": "Thermische Alterung des Washcoats nach \u00dcbertemperatur"}, {"id": "nox_sensor_drift", "p": "medium", "en": "Downstream NOx sensor reading drifts", "de": "Nachgelagerter NOx-Sensor driftet"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3500], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2001','P','NOx Adsorber Efficiency Below Threshold (Bank 2)','NOx-Adsorber Wirkungsgrad unter Schwellwert (Bank 2)','The lean NOx trap (LNT) on bank 2 is no longer storing or releasing NOx within the required efficiency window. Detected by the downstream NOx sensor or model-based monitor — typically caused by sulphur poisoning, thermal aging, or a failed regenerati','Der Mager-NOx-Speicherkat (LNT) an Bank 2 speichert oder regeneriert NOx nicht mehr im geforderten Wirkungsgrad. Erkennt der nachgelagerte NOx-Sensor oder das modellbasierte Monitoring — meist durch Sulfatvergiftung, Alterung oder fehlgeschlagene Reg','["nox_adsorber_catalyst", "nox_sensor_downstream"]','[{"id": "lnt_sulphur_poisoning", "p": "high", "en": "Sulphur poisoning", "de": "Sulfatvergiftung"}, {"id": "lnt_thermal_aging", "p": "medium", "en": "Thermal aging of washcoat", "de": "Thermische Alterung des Washcoats"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3500], "estimated_hours": [2.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2002','P','Diesel Particulate Filter Efficiency Below Threshold (Bank 1)','Dieselpartikelfilter Wirkungsgrad unter Schwellwert (Bank 1)','Diesel Particulate Filter Efficiency Below Threshold (Bank 1): the control module has detected this fault condition.','Dieselpartikelfilter Wirkungsgrad unter Schwellwert (Bank 1): das Steuergerät hat diesen Fehlerzustand erkannt.','["diesel_particulate_filter", "dpf_differential_pressure_sensor", "dpf_temperature_sensor"]','[{"id": "dpf_loaded_failed_regen", "p": "high", "en": "DPF heavily loaded \u2014 repeated short trips prevent regeneration", "de": "DPF stark beladen \u2014 viele Kurzstrecken verhindern die Regeneration"}, {"id": "dpf_substrate_damaged", "p": "medium", "en": "Filter substrate cracked or melted from runaway regeneration", "de": "Filtermaterial gerissen oder geschmolzen durch unkontrollierte Regeneration"}, {"id": "dpf_pressure_sensor_drift", "p": "medium", "en": "Differential pressure sensor drift", "de": "Differenzdrucksensor driftet"}, {"id": "dpf_housing_leak", "p": "low", "en": "Leak around DPF housing", "de": "Undichtigkeit am DPF-Geh\u00e4use"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 4000], "estimated_hours": [2.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2003','P','Diesel Particulate Filter Efficiency Below Threshold (Bank 2)','Dieselpartikelfilter Wirkungsgrad unter Schwellwert (Bank 2)','Diesel Particulate Filter Efficiency Below Threshold (Bank 2): the control module has detected this fault condition.','Dieselpartikelfilter Wirkungsgrad unter Schwellwert (Bank 2): das Steuergerät hat diesen Fehlerzustand erkannt.','["diesel_particulate_filter", "dpf_differential_pressure_sensor", "dpf_temperature_sensor"]','[{"id": "dpf_loaded_failed_regen", "p": "high", "en": "DPF heavily loaded \u2014 repeated short trips prevent regeneration", "de": "DPF stark beladen \u2014 viele Kurzstrecken verhindern die Regeneration"}, {"id": "dpf_substrate_damaged", "p": "medium", "en": "Filter substrate cracked or melted", "de": "Filtermaterial gerissen oder geschmolzen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 4000], "estimated_hours": [2.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2004','P','Intake Manifold Runner Control Stuck Open (Bank 1)','Saugrohrumschaltung hängt offen (Bank 1)','The intake manifold runner control (IMRC) flap on bank 1 is stuck in the open position. The IMRC swirls or tumbles intake charge at low rpm by closing one runner per cylinder; when stuck open, low-end torque drops and the engine may misfire on cold s','Die Saugrohrumschaltklappe (IMRC) an Bank 1 hängt offen. Die IMRC erzeugt bei niedriger Drehzahl Drall oder Tumble, indem sie pro Zylinder einen Kanal schliesst; offen festhängend bricht das Drehmoment unten ein und der Motor kann beim Kaltstart Auss','["intake_manifold_runner", "imrc_actuator", "intake_manifold"]','[{"id": "imrc_carbon_buildup", "p": "high", "en": "Carbon buildup blocks flap travel", "de": "Verkokung blockiert Klappenweg"}, {"id": "imrc_actuator_failed", "p": "medium", "en": "IMRC actuator or vacuum motor failed", "de": "IMRC-Steller oder Unterdruckdose defekt"}, {"id": "imrc_linkage_broken", "p": "medium", "en": "Linkage rod broken or disconnected", "de": "Gest\u00e4nge gebrochen oder ausgehakt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2005','P','Intake Manifold Runner Control Stuck Open (Bank 2)','Saugrohrumschaltung hängt offen (Bank 2)','The intake manifold runner control (IMRC) flap on bank 2 is stuck in the open position. The IMRC swirls or tumbles intake charge at low rpm by closing one runner per cylinder; when stuck open, low-end torque drops and the engine may misfire on cold s','Die Saugrohrumschaltklappe (IMRC) an Bank 2 hängt offen. Die IMRC erzeugt bei niedriger Drehzahl Drall oder Tumble, indem sie pro Zylinder einen Kanal schliesst; offen festhängend bricht das Drehmoment unten ein und der Motor kann beim Kaltstart Auss','["intake_manifold_runner", "imrc_actuator"]','[{"id": "imrc_carbon_buildup", "p": "high", "en": "Carbon buildup blocks flap travel", "de": "Verkokung blockiert Klappenweg"}, {"id": "imrc_actuator_failed", "p": "medium", "en": "IMRC actuator failed on bank 2", "de": "IMRC-Steller an Bank 2 defekt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2006','P','Intake Manifold Runner Control Stuck Closed (Bank 1)','Saugrohrumschaltung hängt geschlossen (Bank 1)','The IMRC flap on bank 1 is stuck in the closed position and cannot open at higher rpm. Top-end power suffers because the runner is restricted, and the engine may breathe poorly above mid-range.','Die IMRC-Klappe an Bank 1 hängt geschlossen und kann bei höherer Drehzahl nicht öffnen. Die Spitzenleistung leidet, weil der Kanal eingeschnürt bleibt, und der Motor atmet oberhalb des mittleren Drehzahlbereichs schlecht.','["intake_manifold_runner", "imrc_actuator"]','[{"id": "imrc_carbon_seized", "p": "high", "en": "Carbon deposits seize flap closed", "de": "Verkokung verklemmt Klappe geschlossen"}, {"id": "imrc_actuator_stuck", "p": "medium", "en": "Actuator stuck or vacuum line collapsed", "de": "Steller h\u00e4ngt oder Unterdruckleitung kollabiert"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2007','P','Intake Manifold Runner Control Stuck Closed (Bank 2)','Saugrohrumschaltung hängt geschlossen (Bank 2)','Bank 2 counterpart to P2006. The IMRC flap on bank 2 cannot return to the open position and chokes intake flow at higher rpm.','Bank-2-Pendant zu P2006. Die IMRC-Klappe auf Bank 2 kehrt nicht in die offene Stellung zurück und drosselt den Ansaugfluss bei höherer Drehzahl.','["intake_manifold_runner", "imrc_actuator"]','[{"id": "imrc_carbon_seized", "p": "high", "en": "Carbon deposits seize flap closed on bank 2", "de": "Verkokung verklemmt Klappe geschlossen an Bank 2"}, {"id": "imrc_actuator_stuck", "p": "medium", "en": "Bank 2 actuator stuck", "de": "Bank-2-Steller h\u00e4ngt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2008','P','Intake Manifold Runner Control Solenoid Circuit Open (Bank 1)','Saugrohrumschaltung Magnetventil-Stromkreis offen (Bank 1)','The ECU detects an open circuit on the IMRC solenoid for bank 1. No control current flows when the runner is commanded to switch, leaving the flap in its default position.','Die Motorsteuerung erkennt eine Unterbrechung im Stromkreis des IMRC-Magnetventils für Bank 1. Beim Schaltbefehl fliesst kein Steuerstrom, sodass die Klappe in der Grundstellung bleibt.','["imrc_solenoid", "imrc_wiring", "ecm"]','[{"id": "imrc_solenoid_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetventilspule unterbrochen"}, {"id": "imrc_connector_loose", "p": "medium", "en": "Connector unplugged or corroded", "de": "Stecker abgezogen oder korrodiert"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2009','P','Intake Manifold Runner Control Solenoid Circuit Low (Bank 1)','Saugrohrumschaltung Magnetventil-Stromkreis Signal zu niedrig (Bank 1)','The IMRC solenoid drive line for bank 1 reads below the lower threshold — short to ground or a failed driver stage. The runner cannot be switched on demand.','Die Ansteuerleitung des IMRC-Magnetventils an Bank 1 liegt unter dem unteren Schwellwert — Kurzschluss nach Masse oder defekte Endstufe. Die Saugrohrumschaltung lässt sich nicht mehr ansteuern.','["imrc_solenoid", "imrc_wiring"]','[{"id": "signal_short_to_ground", "p": "high", "en": "Drive line shorted to ground", "de": "Ansteuerleitung gegen Masse kurzgeschlossen"}, {"id": "imrc_solenoid_short", "p": "medium", "en": "Solenoid internally shorted", "de": "Magnetventil mit internem Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200A','P','Intake Manifold Runner Performance (Bank 1)','Saugrohrumschaltung Leistung (Bank 1)','The intake manifold runner control (IMRC) on bank 1 reports that flap movement does not match the commanded position within the allowed time window — either too slow, too short a stroke, or position feedback off-target.','Die Saugrohrumschaltung (IMRC) an Bank 1 meldet, dass die Klappenbewegung nicht im erwarteten Zeitfenster auf die Sollposition kommt — zu langsam, zu kurzer Hub oder Positions-Feedback weicht ab.','["intake_manifold_runner", "imrc_actuator", "imrc_position_sensor"]','[{"id": "imrc_carbon_buildup", "p": "high", "en": "Carbon buildup restricts flap travel", "de": "Verkokung schr\u00e4nkt Klappenweg ein"}, {"id": "imrc_actuator_weak", "p": "medium", "en": "Actuator weak or vacuum supply low", "de": "Steller schwach oder Unterdruckversorgung niedrig"}, {"id": "imrc_linkage_play", "p": "low", "en": "Linkage worn \u2014 play between actuator and flap", "de": "Gest\u00e4nge ausgeschlagen \u2014 Spiel zwischen Steller und Klappe"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200B','P','Intake Manifold Runner Performance (Bank 2)','Saugrohrumschaltung Leistung (Bank 2)','The intake manifold runner control (IMRC) on bank 2 reports that flap movement does not match the commanded position within the allowed time window — either too slow, too short a stroke, or position feedback off-target.','Die Saugrohrumschaltung (IMRC) an Bank 2 meldet, dass die Klappenbewegung nicht im erwarteten Zeitfenster auf die Sollposition kommt — zu langsam, zu kurzer Hub oder Positions-Feedback weicht ab.','["intake_manifold_runner", "imrc_actuator"]','[{"id": "imrc_carbon_buildup", "p": "high", "en": "Carbon buildup", "de": "Verkokung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200C','P','Particulate Filter Over Temperature (Bank 1)','Partikelfilter Übertemperatur (Bank 1)','A temperature sensor at the diesel particulate filter (DPF) on bank 1 has exceeded the safe limit — typically during a runaway regeneration. Continued operation can melt or crack the substrate.','Ein Temperatursensor am Dieselpartikelfilter (DPF) an Bank 1 hat den zulässigen Grenzwert überschritten — meist während einer ausser Kontrolle geratenen Regeneration. Weiterbetrieb kann das Filtermaterial schmelzen oder reissen lassen.','["diesel_particulate_filter", "dpf_temperature_sensor", "regeneration_strategy"]','[{"id": "dpf_runaway_regen", "p": "high", "en": "Excessive soot load triggers runaway regeneration", "de": "Zu hohe Russmasse f\u00fchrt zu unkontrollierter Regeneration"}, {"id": "dpf_post_injection_excess", "p": "medium", "en": "Post-injection over-fueling during regeneration", "de": "Nacheinspritzung \u00fcberdosiert bei Regeneration"}, {"id": "dpf_temp_sensor_drift", "p": "low", "en": "DPF temperature sensor reading drifts high", "de": "DPF-Temperatursensor driftet nach oben"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 4000], "estimated_hours": [1.5, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200D','P','Particulate Filter Over Temperature (Bank 2)','Partikelfilter Übertemperatur (Bank 2)','A temperature sensor at the diesel particulate filter (DPF) on bank 2 has exceeded the safe limit — typically during a runaway regeneration. Continued operation can melt or crack the substrate.','Ein Temperatursensor am Dieselpartikelfilter (DPF) an Bank 2 hat den zulässigen Grenzwert überschritten — meist während einer ausser Kontrolle geratenen Regeneration. Weiterbetrieb kann das Filtermaterial schmelzen oder reissen lassen.','["diesel_particulate_filter", "dpf_temperature_sensor"]','[{"id": "dpf_runaway_regen", "p": "high", "en": "Runaway regeneration", "de": "Unkontrollierte Regeneration"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 4000], "estimated_hours": [1.5, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200E','P','Catalyst System Over Temperature (Bank 1)','Katalysatorsystem Übertemperatur (Bank 1)','A temperature sensor in the exhaust catalyst on bank 1 reports a value above the safe operating limit. Sustained over-temperature can sinter the precious-metal washcoat and destroy conversion efficiency.','Ein Temperatursensor im Abgaskatalysator an Bank 1 meldet einen Wert über dem zulässigen Grenzbereich. Anhaltende Übertemperatur sintert den Edelmetall-Washcoat und zerstört die Konvertierungsleistung.','["catalytic_converter", "exhaust_temperature_sensor"]','[{"id": "cat_misfire_unburned_fuel", "p": "high", "en": "Persistent misfire dumps unburned fuel into the cat", "de": "Anhaltende Aussetzer leiten unverbrannten Kraftstoff in den Kat"}, {"id": "cat_rich_mixture", "p": "medium", "en": "Sustained rich mixture from leaking injector or fuel pressure regulator", "de": "Anhaltend fettes Gemisch durch undichten Injektor oder defekten Druckregler"}, {"id": "cat_temp_sensor_high_drift", "p": "low", "en": "Catalyst temperature sensor drifts high", "de": "Katalysator-Temperatursensor driftet nach oben"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 3000], "estimated_hours": [1.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P200F','P','Catalyst System Over Temperature (Bank 2)','Katalysatorsystem Übertemperatur (Bank 2)','A temperature sensor in the exhaust catalyst on bank 2 reports a value above the safe operating limit. Sustained over-temperature can sinter the precious-metal washcoat and destroy conversion efficiency.','Ein Temperatursensor im Abgaskatalysator an Bank 2 meldet einen Wert über dem zulässigen Grenzbereich. Anhaltende Übertemperatur sintert den Edelmetall-Washcoat und zerstört die Konvertierungsleistung.','["catalytic_converter", "exhaust_temperature_sensor"]','[{"id": "cat_misfire_unburned_fuel", "p": "high", "en": "Misfire dumps fuel into cat", "de": "Aussetzer leiten Kraftstoff in den Kat"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 3000], "estimated_hours": [1.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2010','P','Intake Manifold Runner Control Solenoid Circuit High (Bank 1)','Saugrohrumschaltung Magnetventil-Stromkreis Signal zu hoch (Bank 1)','Drive voltage at the IMRC solenoid on bank 1 is above the upper limit — short to supply or an open ground side. The solenoid is energised constantly or the driver protection trips.','Die Ansteuerspannung am IMRC-Magnetventil auf Bank 1 liegt über dem oberen Grenzwert — Kurzschluss nach Plus oder offene Masseseite. Das Ventil bestromt durchgehend oder die Endstufenüberwachung schaltet ab.','["imrc_solenoid", "imrc_wiring"]','[{"id": "signal_short_to_supply", "p": "high", "en": "Drive line shorted to supply", "de": "Ansteuerleitung gegen Plus kurzgeschlossen"}, {"id": "ecu_driver_failed", "p": "low", "en": "ECU driver stage failed", "de": "Endstufe im Steuerger\u00e4t defekt"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2011','P','Intake Manifold Runner Control Circuit/Open (Bank 2)','Saugrohrumschaltung Steuerkreis/offen (Bank 2)','The IMRC actuator drive circuit on bank 2 is open or has lost continuity — control module no longer detects a closing path through the actuator winding.','Der Treiberkreis des IMRC-Stellers an Bank 2 ist offen oder ohne Durchgang — das Steuergerät erkennt keinen geschlossenen Pfad mehr durch die Stellerwicklung.','["imrc_actuator", "intake_manifold_runner_harness"]','[{"id": "imrc_open_wiring", "p": "high", "en": "Open wiring or chafed conductor in IMRC harness", "de": "Unterbrechung oder durchgescheuerte Ader im IMRC-Kabelbaum"}, {"id": "imrc_connector_corroded", "p": "medium", "en": "Connector corroded \u2014 high resistance contact", "de": "Steckverbinder korrodiert \u2014 \u00dcbergangswiderstand"}, {"id": "imrc_actuator_winding_open", "p": "medium", "en": "Actuator solenoid winding open", "de": "Aktuatorwicklung unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2012','P','Intake Manifold Runner Control Circuit Low (Bank 2)','Saugrohrumschaltung Steuerkreis Spannung niedrig (Bank 2)','The IMRC actuator drive line on bank 2 reads below the expected voltage threshold — typically a short to ground or a stuck-low driver inside the control module.','Die IMRC-Treiberleitung an Bank 2 liegt unterhalb der Sollspannung — meist Kurzschluss nach Masse oder fehlerhafter Treiber im Steuergerät.','["imrc_actuator", "intake_manifold_runner_harness"]','[{"id": "imrc_short_to_ground", "p": "high", "en": "Short to ground in driver line", "de": "Kurzschluss nach Masse in der Treiberleitung"}, {"id": "imrc_actuator_internal_short", "p": "medium", "en": "Actuator winding shorted internally", "de": "Aktuatorwicklung intern kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2013','P','Intake Manifold Runner Control Circuit High (Bank 2)','Saugrohrumschaltung Steuerkreis Spannung hoch (Bank 2)','The IMRC actuator drive line on bank 2 reads above the expected voltage threshold — typically a short to battery voltage or an open ground side.','Die IMRC-Treiberleitung an Bank 2 liegt oberhalb der Sollspannung — meist Kurzschluss nach Batterie oder unterbrochene Masse.','["imrc_actuator", "intake_manifold_runner_harness"]','[{"id": "imrc_short_to_b_plus", "p": "high", "en": "Short to B+ in driver line", "de": "Kurzschluss nach Plus in der Treiberleitung"}, {"id": "imrc_open_ground", "p": "medium", "en": "Open ground return on actuator", "de": "Unterbrochener Masse-R\u00fcckleiter am Steller"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2014','P','Intake Manifold Runner Position Sensor/Switch Circuit (Bank 1)','Saugrohrumschaltung Positionssensor-Stromkreis (Bank 1)','The position feedback signal of the IMRC flap on bank 1 is missing or implausible. Without feedback, the ECU cannot verify that the commanded runner position has been reached.','Das Rückmeldesignal der IMRC-Klappenstellung an Bank 1 fehlt oder ist unplausibel. Ohne Rückmeldung kann die Motorsteuerung die kommandierte Stellung nicht überprüfen.','["imrc_position_sensor", "imrc_wiring"]','[{"id": "imrc_pos_sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "imrc_pos_wiring_open", "p": "medium", "en": "Signal wire broken", "de": "Signalleitung unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2015','P','Intake Manifold Runner Position Sensor/Switch Range/Performance (Bank 1)','Saugrohrumschaltung Positionssensor Bereich/Plausibilität (Bank 1)','The IMRC position sensor on bank 1 reports a value, but it does not match the commanded flap state — for example, the flap is commanded closed yet the sensor still reads open. Common on engines where the connector pin clip wears out and the sensor re','Der IMRC-Positionssensor an Bank 1 liefert ein Signal, das aber nicht zur kommandierten Klappenstellung passt — etwa bei kommandierter Schliessstellung meldet er weiter offen. Häufig bei Motoren, deren Steckerklemme verschleisst und der Sensor wechse','["imrc_position_sensor", "imrc_actuator"]','[{"id": "imrc_pos_connector_worn", "p": "high", "en": "Connector clip worn \u2014 intermittent contact", "de": "Steckerklemme verschlissen \u2014 Wackelkontakt"}, {"id": "imrc_flap_sticking", "p": "medium", "en": "Flap sticking due to carbon", "de": "Klappe klemmt durch Verkokung"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2016','P','Intake Manifold Runner Position Sensor/Switch Circuit Low (Bank 1)','Saugrohrumschaltung Positionssensor Signal zu niedrig (Bank 1)','The IMRC position sensor signal on bank 1 reads below the lower limit. Usually a short to ground on the signal wire or a failed sensor.','Das Signal des IMRC-Positionssensors an Bank 1 liegt unter dem unteren Grenzwert. Meist ein Kurzschluss nach Masse auf der Signalleitung oder ein defekter Sensor.','["imrc_position_sensor", "imrc_wiring"]','[{"id": "signal_short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung gegen Masse kurzgeschlossen"}, {"id": "imrc_pos_sensor_failed", "p": "medium", "en": "Position sensor failed low", "de": "Positionssensor liefert dauerhaft Niedrigsignal"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2017','P','Intake Manifold Runner Position Sensor/Switch Circuit High (Bank 1)','Saugrohrumschaltung Positionssensor Signal zu hoch (Bank 1)','The IMRC position sensor signal on bank 1 reads above the upper limit. Typically a short to supply, an open ground reference, or a sensor that failed high.','Das Signal des IMRC-Positionssensors an Bank 1 liegt über dem oberen Grenzwert. Typisch ein Kurzschluss nach Plus, eine offene Masseleitung oder ein defekter Sensor.','["imrc_position_sensor", "imrc_wiring"]','[{"id": "signal_short_to_supply", "p": "high", "en": "Signal wire shorted to supply", "de": "Signalleitung gegen Plus kurzgeschlossen"}, {"id": "imrc_pos_ground_open", "p": "medium", "en": "Sensor ground open", "de": "Sensormasse unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2018','P','Intake Manifold Runner Position Sensor/Switch Circuit Open (Bank 2)','Saugrohrumschaltung Positionssensor/-schalter Stromkreis offen (Bank 2)','The ECU detects an open circuit on the IMRC position sensor on bank 2. Without position feedback the ECU cannot confirm runner switching and falls back to a default mode.','Die Motorsteuerung erkennt eine Unterbrechung im Stromkreis des IMRC-Positionssensors auf Bank 2. Ohne Positionsrückmeldung kann das Steuergerät die Klappenumschaltung nicht bestätigen und schaltet in einen Standardmodus.','["imrc_position_sensor_b2", "imrc_wiring"]','[{"id": "imrc_sensor_open", "p": "high", "en": "Sensor element open", "de": "Sensorelement unterbrochen"}, {"id": "signal_wire_open", "p": "medium", "en": "Signal wire open", "de": "Signalleitung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2019','P','Intake Manifold Runner Position Sensor/Switch Range/Performance (Bank 2)','Saugrohrumschaltung Positionssensor/-schalter Bereich/Plausibilität (Bank 2)','The IMRC position sensor on bank 2 produces an electrically valid signal that does not match the commanded runner state — typically a sensor drift or sticking flap.','Der IMRC-Positionssensor auf Bank 2 liefert ein elektrisch gültiges Signal, das nicht zum kommandierten Klappenzustand passt — typischerweise Sensordrift oder hängende Klappe.','["imrc_position_sensor_b2", "intake_manifold_runner"]','[{"id": "imrc_sensor_drift", "p": "high", "en": "Position sensor drift", "de": "Positionssensor driftet"}, {"id": "imrc_carbon_buildup", "p": "medium", "en": "Carbon buildup blocks flap travel", "de": "Verkokung blockiert Klappenweg"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201A','P','Reductant Injection Valve Circuit Range/Performance (Bank 2 Unit 1)','Reduktionsmittel-Einspritzventil Bereich/Leistung (Bank 2 Einheit 1)','Reductant Injection Valve Circuit Range/Performance (Bank 2 Unit 1): the signal is implausible or outside the valid range. This valve doses reductant (DEF/AdBlue) into the exhaust for SCR NOx reduction.','Reduktionsmittel-Einspritzventil Bereich/Leistung (Bank 2 Einheit 1): das Signal ist unplausibel bzw. außerhalb des gültigen Bereichs. Dieses Ventil dosiert Reduktionsmittel (AdBlue) in den Abgasstrang zur SCR-NOx-Minderung.','["reductant_injection_valve", "reductant_metering_unit", "scr_catalyst"]','[{"id": "def_crystallization", "p": "high", "en": "DEF crystallisation clogs the dosing nozzle", "de": "AdBlue-Kristallisation verstopft die Dosierd\u00fcse"}, {"id": "def_pressure_low", "p": "medium", "en": "DEF supply pressure below target", "de": "AdBlue-Versorgungsdruck unter Sollwert"}, {"id": "def_valve_aging", "p": "medium", "en": "Valve coil ageing \u2014 slow response", "de": "Ventilspule alterungsbedingt \u2014 tr\u00e4ge Reaktion"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201B','P','Intake Manifold Runner Control Actuator Supply Voltage Low (Bank 1)','Saugrohrumschaltung Stellerversorgung Spannung niedrig (Bank 1)','The supply voltage feeding the IMRC actuator on bank 1 is below the lower limit — typically a fuse, relay, or harness fault on the supply rail.','Die Versorgungsspannung des IMRC-Stellers an Bank 1 liegt unter dem unteren Grenzwert — meist Sicherung, Relais oder Kabelbaumfehler auf der Versorgungsleitung.','["imrc_actuator", "imrc_supply_relay", "imrc_supply_fuse"]','[{"id": "imrc_supply_fuse_blown", "p": "high", "en": "Supply fuse blown", "de": "Versorgungssicherung defekt"}, {"id": "imrc_supply_open", "p": "medium", "en": "Open supply wire", "de": "Unterbrochene Versorgungsleitung"}, {"id": "imrc_supply_relay_failed", "p": "medium", "en": "Supply relay contacts pitted", "de": "Versorgungsrelais verschmort"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [20, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201C','P','Intake Manifold Runner Control Actuator Supply Voltage Low (Bank 2)','Saugrohrumschaltung Stellerversorgung Spannung niedrig (Bank 2)','The supply voltage feeding the IMRC actuator on bank 2 is below the lower limit — typically a fuse, relay, or harness fault on the supply rail.','Die Versorgungsspannung des IMRC-Stellers an Bank 2 liegt unter dem unteren Grenzwert — meist Sicherung, Relais oder Kabelbaumfehler auf der Versorgungsleitung.','["imrc_actuator", "imrc_supply_relay"]','[{"id": "imrc_supply_fuse_blown", "p": "high", "en": "Supply fuse blown", "de": "Versorgungssicherung defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [20, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201D','P','Intake Manifold Runner Control Actuator Internal Performance (Bank 1)','Saugrohrumschaltung Steller interne Leistung (Bank 1)','Internal self-diagnostics of the IMRC actuator on bank 1 report an off-spec condition — driver stage, position-feedback or thermal limit no longer matches the calibrated profile.','Die interne Eigendiagnose des IMRC-Stellers an Bank 1 meldet einen Abweichungszustand — Treiberstufe, Positions-Rückmeldung oder Temperaturgrenze passt nicht mehr zur Kalibrierung.','["imrc_actuator", "imrc_position_sensor"]','[{"id": "imrc_actuator_internal_fault", "p": "high", "en": "Actuator internal driver or sensor fault", "de": "Interner Treiber- oder Sensorfehler im Steller"}, {"id": "imrc_overheat", "p": "low", "en": "Actuator overheated and derated", "de": "Steller \u00fcberhitzt und reduziert sich selbst"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201E','P','Intake Manifold Runner Control Actuator Internal Performance (Bank 2)','Saugrohrumschaltung Steller interne Leistung (Bank 2)','Internal self-diagnostics of the IMRC actuator on bank 2 report an off-spec condition — driver stage, position-feedback or thermal limit no longer matches the calibrated profile.','Die interne Eigendiagnose des IMRC-Stellers an Bank 2 meldet einen Abweichungszustand — Treiberstufe, Positions-Rückmeldung oder Temperaturgrenze passt nicht mehr zur Kalibrierung.','["imrc_actuator"]','[{"id": "imrc_actuator_internal_fault", "p": "high", "en": "Internal actuator fault", "de": "Interner Stellerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P201F','P','Reductant Pump A Stuck On','Reduktionsmittelpumpe A bleibt eingeschaltet','Reductant Pump A Stuck On: the actuator is stuck in the on position.','Reduktionsmittelpumpe A bleibt eingeschaltet: das Stellglied hängt in der Ein-Stellung.','["reductant_pump", "reductant_pump_relay"]','[{"id": "pump_relay_welded", "p": "high", "en": "Pump relay contacts welded", "de": "Pumpenrelais-Kontakte verschweisst"}, {"id": "pump_driver_short_to_b_plus", "p": "medium", "en": "Pump driver line shorted to B+", "de": "Pumpentreiberleitung Kurzschluss nach Plus"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2020','P','Intake Manifold Runner Position Sensor/Switch Circuit Low (Bank 2)','Saugrohrumschaltung Positionssensor/-schalter Signal zu niedrig (Bank 2)','The IMRC position sensor on bank 2 reports a voltage below the lower threshold — typically a short to ground or a sensor with very low resistance.','Der IMRC-Positionssensor auf Bank 2 meldet eine Spannung unter dem unteren Schwellwert — typischerweise Massekurzschluss oder Sensor mit sehr niedrigem Widerstand.','["imrc_position_sensor_b2", "imrc_wiring"]','[{"id": "signal_short_to_ground", "p": "high", "en": "Signal shorted to ground", "de": "Signal gegen Masse kurzgeschlossen"}, {"id": "imrc_sensor_short", "p": "medium", "en": "Sensor element shorted", "de": "Sensorelement durchlegiert"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2021','P','Intake Manifold Runner Position Sensor/Switch Circuit High (Bank 2)','Saugrohrumschaltung Positionssensor/-schalter Signal zu hoch (Bank 2)','The IMRC position sensor on bank 2 reports a voltage above the upper threshold — usually a short to positive or an open ground.','Der IMRC-Positionssensor auf Bank 2 meldet eine Spannung über dem oberen Schwellwert — meist Kurzschluss nach Plus oder unterbrochene Masse.','["imrc_position_sensor_b2", "imrc_wiring"]','[{"id": "signal_short_to_power", "p": "high", "en": "Signal shorted to positive", "de": "Signal nach Plus kurzgeschlossen"}, {"id": "ground_open", "p": "medium", "en": "Sensor ground open", "de": "Sensormasse unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2022','P','Intake Manifold Runner Position Sensor/Switch Circuit High (Bank 2)','Saugrohrumschaltung Positionssensor Schaltkreis hoch (Bank 2)','The IMRC position sensor on bank 2 reports a signal above the upper plausibility limit — typically an open signal line, broken sensor, or short to B+.','Der IMRC-Positionssensor an Bank 2 meldet ein Signal oberhalb der oberen Plausibilitätsgrenze — meist offene Signalleitung, defekter Sensor oder Kurzschluss nach Plus.','["imrc_position_sensor", "intake_manifold_runner_harness"]','[{"id": "imrc_pos_sensor_open", "p": "high", "en": "Open signal line at IMRC position sensor", "de": "Unterbrochene Signalleitung am IMRC-Positionssensor"}, {"id": "imrc_pos_sensor_short_b_plus", "p": "medium", "en": "Signal shorted to B+", "de": "Signalleitung Kurzschluss nach Plus"}, {"id": "imrc_pos_sensor_failed", "p": "medium", "en": "Sensor element failed", "de": "Sensorelement defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 350], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2023','P','Intake Manifold Runner Position Sensor/Switch Circuit Intermittent (Bank 2)','Saugrohrumschaltung Positionssensor Schaltkreis sporadisch (Bank 2)','The IMRC position sensor signal on bank 2 jumps or drops out intermittently — usually a loose pin, partially-broken conductor, or moisture in the connector.','Das IMRC-Positionssensorsignal an Bank 2 springt oder fällt sporadisch aus — meist lockerer Pin, angebrochene Ader oder Feuchtigkeit im Stecker.','["imrc_position_sensor", "imrc_connector"]','[{"id": "imrc_pos_intermittent_pin", "p": "high", "en": "Loose terminal in connector", "de": "Loser Kontakt im Stecker"}, {"id": "imrc_pos_water_ingress", "p": "medium", "en": "Water ingress into connector", "de": "Wassereintritt in den Stecker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.5, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2024','P','EVAP Fuel Vapor Temperature Sensor Circuit','EVAP Kraftstoffdampf-Temperatursensor Schaltkreis','A general fault is reported on the EVAP fuel-vapor temperature sensor circuit — open, shorted, or out of plausible range. The sensor is part of the evaporative-emission system used to monitor canister loading.','Allgemeiner Fehler im Schaltkreis des EVAP-Kraftstoffdampf-Temperatursensors — offen, kurzgeschlossen oder ausserhalb des Plausibilitätsbereichs. Der Sensor sitzt im Tankentlüftungssystem zur Überwachung der Aktivkohlefilter-Beladung.','["evap_fuel_vapor_temp_sensor", "evap_canister"]','[{"id": "evap_temp_sensor_failed", "p": "high", "en": "Vapor temperature sensor failed", "de": "Dampf-Temperatursensor defekt"}, {"id": "evap_temp_harness_fault", "p": "medium", "en": "Harness fault between sensor and PCM", "de": "Kabelbaumfehler zwischen Sensor und Steuerger\u00e4t"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2025','P','EVAP Fuel Vapor Temperature Sensor Performance','EVAP Kraftstoffdampf-Temperatursensor Leistung','The EVAP fuel-vapor temperature sensor reading is plausible but does not match expected behaviour over time or temperature — slow response, incorrect offset, or stuck reading.','Der Wert des EVAP-Dampftemperatursensors ist plausibel, weicht aber von der erwarteten Charakteristik über Zeit oder Temperatur ab — träge Reaktion, falscher Offset oder eingefrorener Wert.','["evap_fuel_vapor_temp_sensor"]','[{"id": "evap_temp_sensor_drift", "p": "high", "en": "Sensor drift over service life", "de": "Sensor driftet im Lauf der Betriebszeit"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "contamination", "p": "low", "en": "Sensor element contaminated by oil, soot or coolant", "de": "Sensorelement durch \u00d6l, Ru\u00df oder K\u00fchlmittel verschmutzt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2026','P','EVAP Fuel Vapor Temperature Sensor Circuit Low Voltage','EVAP Kraftstoffdampf-Temperatursensor Schaltkreis niedrige Spannung','The EVAP fuel-vapor temperature sensor signal sits below the lower plausibility limit — short to ground or short between signal and ground inside the sensor.','Das Signal des EVAP-Dampftemperatursensors liegt unterhalb der unteren Plausibilitätsgrenze — Kurzschluss nach Masse oder interner Kurzschluss im Sensor.','["evap_fuel_vapor_temp_sensor"]','[{"id": "evap_temp_short_to_ground", "p": "high", "en": "Short to ground on signal line", "de": "Kurzschluss nach Masse auf der Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 300], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2027','P','EVAP Fuel Vapor Temperature Sensor Circuit High Voltage','EVAP Kraftstoffdampf-Temperatursensor Schaltkreis hohe Spannung','The EVAP fuel-vapor temperature sensor signal sits above the upper plausibility limit — open signal line, broken sensor, or short to B+.','Das Signal des EVAP-Dampftemperatursensors liegt oberhalb der oberen Plausibilitätsgrenze — offene Signalleitung, defekter Sensor oder Kurzschluss nach Plus.','["evap_fuel_vapor_temp_sensor"]','[{"id": "evap_temp_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 300], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2028','P','EVAP Fuel Vapor Temperature Sensor Circuit Intermittent','EVAP Kraftstoffdampf-Temperatursensor Schaltkreis sporadisch','The EVAP fuel-vapor temperature sensor signal jumps or drops out intermittently — usually a connector or chafed wire.','Das Signal des EVAP-Dampftemperatursensors springt oder fällt sporadisch aus — meist Stecker oder durchgescheuerte Leitung.','["evap_fuel_vapor_temp_sensor", "evap_harness"]','[{"id": "evap_temp_intermittent", "p": "high", "en": "Intermittent connector or chafed wire", "de": "Wackliger Stecker oder durchgescheuerte Ader"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [30, 300], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2029','P','Fuel Fired Heater Disabled','Brennstoff-Standheizung deaktiviert','The fuel-fired auxiliary heater (used to warm coolant or DEF on cold start) has been disabled by the control module — typically because of repeated start failures, low-voltage supply, or a self-protection condition.','Die brennstoffbetriebene Zusatzheizung (heizt Kühlmittel oder AdBlue beim Kaltstart) wurde vom Steuergerät abgeschaltet — meist nach mehrfachen Startfehlversuchen, Unterspannung oder Eigenschutzauslösung.','["fuel_fired_heater", "heater_glow_plug", "heater_fuel_pump"]','[{"id": "ffh_glow_plug_failed", "p": "high", "en": "Heater glow plug failed", "de": "Gl\u00fchstift der Heizung defekt"}, {"id": "ffh_low_voltage_lockout", "p": "medium", "en": "Low battery voltage triggered lockout", "de": "Niedrige Batteriespannung hat Sperre ausgel\u00f6st"}, {"id": "ffh_fuel_supply_starved", "p": "medium", "en": "Fuel supply starved \u2014 empty tank or pump weak", "de": "Kraftstoffversorgung mangelhaft \u2014 Tank leer oder Pumpe schwach"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 1200], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('P202A','P','Reductant Tank Heater Control Circuit/Open','Reduktionsmitteltank-Heizung Steuerkreis/offen','The DEF tank heater control circuit is open or has lost continuity — the PCM cannot drive the resistive heater that prevents the DEF (urea) tank from freezing in winter.','Der Steuerkreis der AdBlue-Tankheizung ist offen oder ohne Durchgang — das Steuergerät kann den Widerstandsheizer nicht ansteuern, der das Einfrieren des AdBlue-Tanks im Winter verhindert.','["reductant_tank_heater", "reductant_tank_harness"]','[{"id": "def_heater_open_winding", "p": "high", "en": "Heater element winding open", "de": "Heizelement-Wicklung unterbrochen"}, {"id": "def_heater_open_wire", "p": "medium", "en": "Open wire between PCM and heater", "de": "Unterbrechung zwischen Steuerger\u00e4t und Heizung"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 700], "estimated_hours": [0.7, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P202B','P','Reductant Tank Heater Control Circuit Low','Reduktionsmitteltank-Heizung Steuerkreis Spannung niedrig','The DEF tank heater control line reads below the expected voltage — short to ground or stuck-low driver.','Die Steuerleitung der AdBlue-Tankheizung liegt unter der erwarteten Spannung — Kurzschluss nach Masse oder fehlerhafter Treiber.','["reductant_tank_heater"]','[{"id": "def_heater_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 700], "estimated_hours": [0.7, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P202C','P','Reductant Tank Heater Control Circuit High','Reduktionsmitteltank-Heizung Steuerkreis Spannung hoch','The DEF tank heater control line reads above the expected voltage — short to B+ or open ground. The sensor heater warms the element to operating temperature (~600 °C); without it the lambda sensor stays inactive in closed loop and the ECM cannot trim','Die Steuerleitung der AdBlue-Tankheizung liegt über der erwarteten Spannung — Kurzschluss nach Plus oder offene Masse. Die Sondenheizung bringt das Element auf Betriebstemperatur (~600 °C); ohne sie bleibt die Lambdasonde im geschlossenen Regelkreis ','["reductant_tank_heater"]','[{"id": "def_heater_short_to_b_plus", "p": "high", "en": "Short to B+", "de": "Kurzschluss nach Plus"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 700], "estimated_hours": [0.7, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P202D','P','Reductant Leakage','Reduktionsmittel-Leckage','A leak has been detected in the DEF (urea) supply system — usually by a pressure-decay test after pump shutdown, or by visible crystallisation around fittings.','Eine Leckage im AdBlue-Versorgungssystem wurde erkannt — meist durch einen Druckabfalltest nach Pumpenabschaltung oder durch sichtbare Kristallisation an Verschraubungen.','["reductant_supply_line", "reductant_pump", "reductant_injection_valve"]','[{"id": "def_line_leak", "p": "high", "en": "Cracked DEF line or fitting", "de": "Gerissene AdBlue-Leitung oder Verschraubung"}, {"id": "def_pump_seal_leak", "p": "medium", "en": "Pump seal leaking", "de": "Pumpendichtung undicht"}, {"id": "def_injector_seal", "p": "medium", "en": "Injector mounting seal leaking", "de": "Injektor-Aufnahmedichtung undicht"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P202E','P','Reductant Injection Valve Circuit Range/Performance (Bank 1 Unit 1)','Reduktionsmittel-Einspritzventil Bereich/Leistung (Bank 1 Einheit 1)','Reductant Injection Valve Circuit Range/Performance (Bank 1 Unit 1): the signal is implausible or outside the valid range. This valve doses reductant (DEF/AdBlue) into the exhaust for SCR NOx reduction.','Reduktionsmittel-Einspritzventil Bereich/Leistung (Bank 1 Einheit 1): das Signal ist unplausibel bzw. außerhalb des gültigen Bereichs. Dieses Ventil dosiert Reduktionsmittel (AdBlue) in den Abgasstrang zur SCR-NOx-Minderung.','["reductant_injection_valve", "reductant_metering_unit"]','[{"id": "def_crystallization", "p": "high", "en": "DEF crystallisation in nozzle", "de": "AdBlue-Kristallisation in der D\u00fcse"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P202F','P','Reductant/Regeneration Supply Control Circuit Range/Performance','Reduktionsmittel-/Regenerations-Versorgungssteuerung Bereich/Leistung','The control line that gates the DEF supply pump or the regeneration heating circuit does not respond as commanded — duty cycle, current draw, or response time off-spec.','Die Steuerleitung der AdBlue-Versorgungspumpe oder des Regenerationsheizkreises reagiert nicht wie befohlen — Tastverhältnis, Stromaufnahme oder Reaktionszeit ausserhalb der Toleranz.','["reductant_supply_pump", "reductant_supply_relay"]','[{"id": "def_supply_relay_aged", "p": "high", "en": "Supply relay aged or pitted contacts", "de": "Versorgungsrelais gealtert oder Kontakte verbrannt"}, {"id": "def_supply_pump_aging", "p": "medium", "en": "Supply pump motor brushes worn", "de": "Pumpenmotorb\u00fcrsten verschlissen"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [1.0, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2030','P','Fuel Fired Heater Performance','Brennstoff-Standheizung Leistung','The fuel-fired auxiliary heater is operating but not delivering the expected heat output within the calibrated time — flame sensor reports weak combustion, exhaust temperature does not rise, or coolant heating rate is below threshold.','Die brennstoffbetriebene Zusatzheizung läuft, liefert aber im Kalibrierzeitfenster nicht die erwartete Heizleistung — Flammwächter meldet schwache Verbrennung, Abgastemperatur steigt nicht, oder Kühlmittel-Aufheizrate liegt unter Schwellwert.','["fuel_fired_heater", "heater_flame_sensor", "heater_combustion_chamber"]','[{"id": "ffh_combustion_chamber_sooted", "p": "high", "en": "Combustion chamber sooted from short cycles", "de": "Brennkammer durch Kurzl\u00e4ufe verrusst"}, {"id": "ffh_flame_sensor_weak", "p": "medium", "en": "Flame sensor degraded", "de": "Flammw\u00e4chter altert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 900], "estimated_hours": [1.0, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('P2031','P','Exhaust Gas Temperature Sensor Circuit (Bank 1 Sensor 2)','Abgastemperatursensor Stromkreis (Bank 1 Sensor 2)','The exhaust gas temperature (EGT) sensor at position 2 on bank 1 — typically downstream of the catalyst or before the DPF — reports an implausible signal. EGT sensors protect the turbocharger and DPF from over-temperature and time the regeneration cy','Der Abgastemperatursensor (EGT) an Position 2 auf Bank 1 — meist nach dem Katalysator oder vor dem DPF — liefert ein unplausibles Signal. EGT-Sensoren schützen Turbolader und DPF vor Übertemperatur und steuern den Regenerationszyklus.','["egt_sensor", "egt_wiring"]','[{"id": "egt_sensor_failed", "p": "high", "en": "EGT sensor failed", "de": "EGT-Sensor defekt"}, {"id": "egt_wiring_damaged", "p": "medium", "en": "Wiring damaged by heat", "de": "Verkabelung durch Hitze besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2032','P','Exhaust Gas Temperature Sensor Circuit Low (Bank 1 Sensor 2)','Abgastemperatursensor Signal zu niedrig (Bank 1 Sensor 2)','The EGT sensor at bank 1 position 2 reads below the lower limit. Common when the signal is shorted to ground or the sensor element is open.','Der EGT-Sensor an Bank 1 Position 2 liegt unter dem unteren Grenzwert. Häufig durch Kurzschluss nach Masse oder ein offenes Sensorelement.','["egt_sensor", "egt_wiring"]','[{"id": "signal_short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung gegen Masse kurzgeschlossen"}, {"id": "egt_sensor_open", "p": "medium", "en": "Sensor element open", "de": "Sensorelement unterbrochen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2033','P','Exhaust Gas Temperature Sensor Circuit High (Bank 1 Sensor 2)','Abgastemperatursensor Signal zu hoch (Bank 1 Sensor 2)','The EGT sensor at bank 1 position 2 reads above the upper limit. Usually a short to supply, an open ground or a sensor that drifted high — risk of false DPF over-temperature limp.','Der EGT-Sensor an Bank 1 Position 2 liegt über dem oberen Grenzwert. Meist ein Kurzschluss nach Plus, offene Masseleitung oder driftender Sensor — Risiko eines unberechtigten DPF-Übertemperatur-Notlaufs.','["egt_sensor", "egt_wiring"]','[{"id": "signal_short_to_supply", "p": "high", "en": "Signal wire shorted to supply", "de": "Signalleitung gegen Plus kurzgeschlossen"}, {"id": "egt_sensor_drift_high", "p": "medium", "en": "Sensor drift to high reading", "de": "Sensor driftet ins Hohe"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2034','P','Exhaust Gas Temperature Sensor Circuit (Bank 2 Sensor 2)','Abgastemperatursensor Schaltkreis (Bank 2 Sensor 2)','A general electrical fault is reported on the exhaust gas temperature (EGT) sensor at bank 2 sensor 2 — open, short, or out of plausibility. EGT sensors monitor catalyst, DPF, and turbocharger inlet/outlet temperatures.','Allgemeiner elektrischer Fehler am Abgastemperatur (EGT) Sensor an Bank 2 Sensor 2 — offen, kurzgeschlossen oder unplausibel. EGT-Sensoren überwachen Katalysator-, DPF- und Turbolader-Ein-/Auslasstemperatur.','["exhaust_gas_temperature_sensor", "egt_harness"]','[{"id": "egt_sensor_failed", "p": "high", "en": "EGT sensor element failed", "de": "EGT-Sensorelement defekt"}, {"id": "egt_harness_open", "p": "medium", "en": "Open wire in EGT harness", "de": "Unterbrechung im EGT-Kabelbaum"}, {"id": "egt_connector_corroded", "p": "low", "en": "Connector corroded by exhaust heat", "de": "Stecker durch Abgashitze korrodiert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2035','P','Exhaust Gas Temperature Sensor Circuit Low (Bank 2 Sensor 2)','Abgastemperatursensor Schaltkreis Spannung niedrig (Bank 2 Sensor 2)','The EGT sensor on bank 2 sensor 2 reads below the lower plausibility limit — short to ground or shorted sensor element.','Der EGT-Sensor an Bank 2 Sensor 2 liegt unter der unteren Plausibilitätsgrenze — Kurzschluss nach Masse oder kurzgeschlossenes Sensorelement.','["exhaust_gas_temperature_sensor"]','[{"id": "egt_short_to_ground", "p": "high", "en": "Signal shorted to ground", "de": "Signalleitung Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2036','P','Exhaust Gas Temperature Sensor Circuit High (Bank 2 Sensor 2)','Abgastemperatursensor Schaltkreis Spannung hoch (Bank 2 Sensor 2)','The EGT sensor on bank 2 sensor 2 reads above the upper plausibility limit — open signal or short to B+.','Der EGT-Sensor an Bank 2 Sensor 2 liegt über der oberen Plausibilitätsgrenze — offenes Signal oder Kurzschluss nach Plus.','["exhaust_gas_temperature_sensor"]','[{"id": "egt_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 350], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2037','P','Reductant Injection Air Pressure Sensor A Circuit','Reduktionsmittel-Einspritz-Luftdrucksensor A Schaltkreis','A general electrical fault is reported on reductant injection air-pressure sensor A — used on air-assisted DEF dosing systems to monitor the atomisation air pressure delivered to the injector.','Allgemeiner elektrischer Fehler am Reduktionsmittel-Einspritz-Luftdrucksensor A — wird bei luftunterstützten AdBlue-Dosiersystemen genutzt, um den Zerstäubungsluftdruck am Injektor zu überwachen.','["reductant_air_pressure_sensor", "reductant_air_pump"]','[{"id": "def_air_press_sensor_failed", "p": "high", "en": "Air pressure sensor failed", "de": "Luftdrucksensor defekt"}, {"id": "def_air_press_harness_fault", "p": "medium", "en": "Harness fault between sensor and PCM", "de": "Kabelbaumfehler zwischen Sensor und Steuerger\u00e4t"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2038','P','Reductant Injection Air Pressure Sensor A Circuit Range/Performance','Reduktionsmittel-Einspritz-Luftdrucksensor A Bereich/Leistung','The reductant injection air-pressure sensor A reads inside the electrical range but does not match expected behaviour over time or load — slow response or wrong offset.','Der Reduktionsmittel-Einspritz-Luftdrucksensor A liegt im elektrischen Bereich, weicht aber im Zeitverlauf oder unter Last vom erwarteten Verhalten ab — träge Reaktion oder falscher Offset.','["reductant_air_pressure_sensor"]','[{"id": "def_air_press_drift", "p": "high", "en": "Sensor drift", "de": "Sensor driftet"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2039','P','Reductant Injection Air Pressure Sensor A Circuit Low','Reduktionsmittel-Einspritz-Luftdrucksensor A Schaltkreis niedrig','The reductant injection air-pressure sensor A reads below its lower plausibility limit — short to ground or sensor internal short.','Der Reduktionsmittel-Einspritz-Luftdrucksensor A liegt unter der unteren Plausibilitätsgrenze — Kurzschluss nach Masse oder interner Sensor-Kurzschluss.','["reductant_air_pressure_sensor"]','[{"id": "def_air_press_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203A','P','Reductant Level Sensor A Circuit','Reduktionsmittel-Füllstandsensor A Schaltkreis','A general electrical fault is reported on DEF level sensor A — open, shorted, or out of plausibility. Some tanks use multiple level senders to cover irregular tank shapes; this is the primary one.','Allgemeiner elektrischer Fehler am AdBlue-Füllstandsensor A — offen, kurzgeschlossen oder unplausibel. Manche Tanks nutzen mehrere Füllstandgeber für unregelmässige Tankformen; dieser ist der primäre.','["reductant_level_sensor", "reductant_tank"]','[{"id": "def_level_a_failed", "p": "high", "en": "Sender failed \u2014 float, swing arm, or rheostat", "de": "Geber defekt \u2014 Schwimmer, Schwenkarm oder Widerstand"}, {"id": "def_level_a_harness", "p": "medium", "en": "Harness or connector fault", "de": "Kabelbaum- oder Steckerfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203B','P','Reductant Level Sensor A Circuit Range/Performance','Reduktionsmittel-Füllstandsensor A Bereich/Leistung','DEF level sensor A reading is in electrical range but plausibility check fails — value sticks, jumps, or does not match consumption.','Der AdBlue-Füllstandsensor A liegt im elektrischen Bereich, scheitert aber an der Plausibilität — bleibt hängen, springt oder passt nicht zum Verbrauch.','["reductant_level_sensor"]','[{"id": "def_level_a_stuck", "p": "high", "en": "Float arm sticks", "de": "Schwimmerarm h\u00e4ngt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203C','P','Reductant Level Sensor A Circuit Low','Reduktionsmittel-Füllstandsensor A Schaltkreis niedrig','DEF level sensor A reads below lower plausibility — short to ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the','Der AdBlue-Füllstandsensor A liegt unter der unteren Plausibilität — Kurzschluss nach Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbau','["reductant_level_sensor"]','[{"id": "def_level_a_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203D','P','Reductant Level Sensor A Circuit High','Reduktionsmittel-Füllstandsensor A Schaltkreis hoch','DEF level sensor A reads above upper plausibility — open signal or short to B+. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often c','Der AdBlue-Füllstandsensor A liegt über der oberen Plausibilität — offenes Signal oder Kurzschluss nach Plus. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wacke','["reductant_level_sensor"]','[{"id": "def_level_a_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203E','P','Reductant Level Sensor A Circuit Intermittent/Erratic','Reduktionsmittel-Füllstandsensor A Schaltkreis sporadisch/erratisch','Reductant Level Sensor A Circuit Intermittent/Erratic: the signal is intermittent or erratic. Often a loose connector or chafed wiring; a wiggle test often locates it.','Reduktionsmittel-Füllstandsensor A Schaltkreis sporadisch/erratisch: das Signal ist sporadisch oder unsauber. Oft loser Stecker oder gescheuerte Leitung; ein Wackeltest lokalisiert ihn oft.','["reductant_level_sensor"]','[{"id": "def_level_a_intermittent", "p": "high", "en": "Corroded sender contact", "de": "Korrodierter Geberkontakt"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 600], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P203F','P','Reductant Level Too Low','Reduktionsmittel-Füllstand zu niedrig','The DEF tank level has dropped below the warning threshold — driver action required to refill before the inducement strategy escalates to limp mode or no-restart.','Der AdBlue-Tankfüllstand ist unter die Warnschwelle gefallen — Fahrer muss nachfüllen, bevor die Anreizstrategie auf Notlauf oder Startverhinderung eskaliert.','["reductant_tank", "reductant_level_sensor"]','[{"id": "def_low_no_refill", "p": "high", "en": "DEF tank simply empty \u2014 refill needed", "de": "AdBlue-Tank schlicht leer \u2014 nachf\u00fcllen"}, {"id": "def_level_sensor_underread", "p": "low", "en": "Level sensor under-reading", "de": "F\u00fcllstandsensor liest zu niedrig"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 60], "estimated_hours": [0.1, 0.3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2040','P','Reductant Injection Air Pressure Sensor A Circuit High','Reduktionsmittel-Einspritz-Luftdrucksensor A Schaltkreis hoch','The reductant injection air-pressure sensor A reads above its upper plausibility limit — open signal line or short to B+.','Der Reduktionsmittel-Einspritz-Luftdrucksensor A liegt über der oberen Plausibilitätsgrenze — offene Signalleitung oder Kurzschluss nach Plus.','["reductant_air_pressure_sensor"]','[{"id": "def_air_press_open", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2041','P','Reductant Injection Air Pressure Sensor A Circuit Intermittent','Reduktionsmittel-Einspritz-Luftdrucksensor A Schaltkreis sporadisch','The reductant injection air-pressure sensor A signal jumps or drops out intermittently — connector or harness issue.','Das Signal des Reduktionsmittel-Einspritz-Luftdrucksensors A springt oder fällt sporadisch aus — Stecker- oder Kabelbaumproblem.','["reductant_air_pressure_sensor", "reductant_air_pressure_connector"]','[{"id": "def_air_press_intermittent", "p": "high", "en": "Intermittent connector or chafed wire", "de": "Wackliger Stecker oder durchgescheuerte Ader"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 450], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2042','P','Reductant Temperature Sensor A Circuit','Reduktionsmittel-Temperatursensor A Schaltkreis','A general electrical fault is reported on reductant (DEF) temperature sensor A — used to compensate dosing for fluid viscosity and to enable tank heating in winter.','Allgemeiner elektrischer Fehler am Reduktionsmittel (AdBlue) Temperatursensor A — kompensiert die Dosierung für Viskosität und steuert die Tankheizung im Winter.','["reductant_temperature_sensor", "reductant_tank"]','[{"id": "def_temp_sensor_failed", "p": "high", "en": "Sensor element failed", "de": "Sensorelement defekt"}, {"id": "def_temp_harness_fault", "p": "medium", "en": "Harness fault", "de": "Kabelbaumfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.7, 2.5]}',1);
