INSERT OR IGNORE INTO dtc_codes VALUES('P2047','P','Reductant Injection Valve Circuit/Open (Bank 1 Unit 1)','Reduktionsmittel-Einspritzventil Schaltkreis/offen (Bank 1 Einheit 1)','Reductant Injection Valve Circuit/Open (Bank 1 Unit 1): the circuit is open. This valve doses reductant (DEF/AdBlue) into the exhaust for SCR NOx reduction.','Reduktionsmittel-Einspritzventil Schaltkreis/offen (Bank 1 Einheit 1): der Stromkreis ist unterbrochen. Dieses Ventil dosiert Reduktionsmittel (AdBlue) in den Abgasstrang zur SCR-NOx-Minderung.','["reductant_injection_valve", "reductant_injection_harness"]','[{"id": "def_inj_open_winding", "p": "high", "en": "Solenoid winding open", "de": "Magnetwicklung unterbrochen"}, {"id": "def_inj_open_wiring", "p": "medium", "en": "Open wire between PCM and valve", "de": "Unterbrechung zwischen Steuerger\u00e4t und Ventil"}, {"id": "def_inj_connector_corroded", "p": "medium", "en": "Connector corroded", "de": "Steckverbinder korrodiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 900], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2048','P','Reductant Injection Valve Circuit Low (Bank 1 Unit 1)','Reduktionsmittel-Einspritzventil Schaltkreis niedrig (Bank 1 Einheit 1)','Reductant Injection Valve Circuit Low (Bank 1 Unit 1): the signal voltage is below the expected range. This valve doses reductant (DEF/AdBlue) into the exhaust for SCR NOx reduction.','Reduktionsmittel-Einspritzventil Schaltkreis niedrig (Bank 1 Einheit 1): die Signalspannung liegt unter dem erwarteten Bereich. Dieses Ventil dosiert Reduktionsmittel (AdBlue) in den Abgasstrang zur SCR-NOx-Minderung.','["reductant_injection_valve"]','[{"id": "def_inj_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 900], "estimated_hours": [0.7, 3.0]}',1);
