INSERT OR IGNORE INTO dtc_codes VALUES('P204A','P','Reductant Pressure Sensor Circuit','Reduktionsmittel-Drucksensor Schaltkreis','A general electrical fault is reported on the DEF system pressure sensor — used to verify pump priming, line pressure, and to detect leaks via pressure-decay tests.','Allgemeiner elektrischer Fehler am AdBlue-Systemdrucksensor — überwacht Pumpenfüllung, Leitungsdruck und erkennt Lecks per Druckabfalltest.','["reductant_pressure_sensor", "reductant_supply_line"]','[{"id": "def_press_sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "def_press_harness_fault", "p": "medium", "en": "Harness fault", "de": "Kabelbaumfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 700], "estimated_hours": [0.7, 2.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P204B','P','Reductant Pressure Sensor Circuit Range/Performance','Reduktionsmittel-Drucksensor Bereich/Leistung','DEF pressure sensor reads within electrical range but plausibility fails — does not rise during prime, drift over a drive cycle, or stuck at a constant value.','Der AdBlue-Drucksensor liegt im elektrischen Bereich, scheitert aber an der Plausibilität — steigt beim Vorfüllen nicht, driftet über einen Fahrzyklus oder bleibt konstant.','["reductant_pressure_sensor"]','[{"id": "def_press_drift", "p": "high", "en": "Sensor drift or stuck reading", "de": "Sensor driftet oder bleibt h\u00e4ngen"}, {"id": "def_pump_weak", "p": "medium", "en": "Pump pressure builds slowly", "de": "Pumpe baut Druck zu langsam auf"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P204C','P','Reductant Pressure Sensor Circuit Low','Reduktionsmittel-Drucksensor Schaltkreis niedrig','DEF pressure sensor reads below the lower plausibility limit — short to ground or sensor element shorted.','Der AdBlue-Drucksensor liegt unter der unteren Plausibilitätsgrenze — Kurzschluss nach Masse oder kurzgeschlossenes Sensorelement.','["reductant_pressure_sensor"]','[{"id": "def_press_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 600], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P204D','P','Reductant Pressure Sensor Circuit High','Reduktionsmittel-Drucksensor Schaltkreis hoch','DEF pressure sensor reads above the upper plausibility limit — open signal or short to B+. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is act','Der AdBlue-Drucksensor liegt über der oberen Plausibilitätsgrenze — offenes Signal oder Kurzschluss nach Plus. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wack','["reductant_pressure_sensor"]','[{"id": "def_press_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 600], "estimated_hours": [0.7, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P204E','P','Reductant Pressure Sensor Circuit Intermittent/Erratic','Reduktionsmittel-Drucksensor Schaltkreis sporadisch/erratisch','DEF pressure sensor signal is unstable or jumps — usually a connector or chafed wire. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active o','Das Signal des AdBlue-Drucksensors ist instabil oder springt — meist Stecker oder durchgescheuerte Ader. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest','["reductant_pressure_sensor"]','[{"id": "def_press_intermittent", "p": "high", "en": "Intermittent connector", "de": "Wackliger Stecker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 500], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P204F','P','Reductant System Performance','Reduktionsmittel-System Plausibilität','The SCR (selective catalytic reduction) system using AdBlue/DEF is not delivering the expected NOx conversion. Causes range from poor reductant quality, dosing module faults, heater failure on the AdBlue tank in cold weather, or a degraded SCR cataly','Das SCR-System mit AdBlue/DEF erreicht nicht die erwartete NOx-Umsetzung. Ursachen reichen von schlechter Reduktionsmittelqualität über Fehler im Dosiermodul, Ausfall der AdBlue-Tankheizung bei Kälte bis zu einem degradierten SCR-Katalysator.','["scr_catalyst", "adblue_dosing_module", "adblue_tank_heater", "nox_sensor"]','[{"id": "adblue_quality_low", "p": "high", "en": "Poor reductant quality or contamination", "de": "Schlechte Reduktionsmittelqualit\u00e4t oder Verunreinigung"}, {"id": "dosing_module_clogged", "p": "medium", "en": "Dosing module clogged with urea crystals", "de": "Dosiermodul mit Harnstoffkristallen verstopft"}, {"id": "scr_catalyst_aged", "p": "medium", "en": "SCR catalyst aged or contaminated", "de": "SCR-Katalysator gealtert oder verunreinigt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 3000], "estimated_hours": [1.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2050','P','Reductant Injection Valve Circuit/Open (Bank 2 Unit 1)','Reduktionsmittel-Einspritzventil Schaltkreis/offen (Bank 2 Einheit 1)','Reductant Injection Valve Circuit/Open (Bank 2 Unit 1): the circuit is open. This valve doses reductant (DEF/AdBlue) into the exhaust for SCR NOx reduction.','Reduktionsmittel-Einspritzventil Schaltkreis/offen (Bank 2 Einheit 1): der Stromkreis ist unterbrochen. Dieses Ventil dosiert Reduktionsmittel (AdBlue) in den Abgasstrang zur SCR-NOx-Minderung.','["reductant_injection_valve"]','[{"id": "def_inj_open_winding", "p": "high", "en": "Solenoid winding open", "de": "Magnetwicklung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 900], "estimated_hours": [0.7, 3.0]}',1);
