INSERT OR IGNORE INTO dtc_codes VALUES('P206D','P','Reductant Quality Sensor Circuit High','Reduktionsmittel-Qualitätssensor Schaltkreis hoch','DEF quality sensor reads above upper plausibility — open signal or short to B+. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often c','Der AdBlue-Qualitätssensor liegt über der oberen Plausibilität — offenes Signal oder Kurzschluss nach Plus. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackelt','["reductant_quality_sensor"]','[{"id": "def_quality_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 900], "estimated_hours": [1.0, 3.0]}',1);
