INSERT OR IGNORE INTO dtc_codes VALUES('P20C5','P','Reductant Heater D Control Circuit/Open','Reduktionsmittelheizung D Steuerkreis/offen','Reductant heater D control circuit open.','Steuerkreis der AdBlue-Heizung D offen.','["reductant_line_heater_d"]','[{"id": "line_heater_d_open", "p": "high", "en": "Heater winding open", "de": "Heizwicklung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P20C6','P','Reductant Heater D Control Circuit Performance','Reduktionsmittelheizung D Steuerkreis Leistung','Reductant heater D does not warm in time.','AdBlue-Heizung D erwärmt nicht im Zeitfenster.','["reductant_line_heater_d"]','[{"id": "line_heater_d_partial", "p": "high", "en": "Partial winding fault", "de": "Teilweiser Wicklungsfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.7, 3.0]}',1);
