INSERT OR IGNORE INTO dtc_codes VALUES('P21A8','P','Reductant Level Sensor B Circuit','Reduktionsmittel-Füllstandsensor B Schaltkreis','A general electrical fault is reported on DEF level sensor B — open, shorted, or out of plausibility. Some tanks use multiple level senders to cover irregular tank shapes; this is the primary one.','Allgemeiner elektrischer Fehler am AdBlue-Füllstandsensor B — offen, kurzgeschlossen oder unplausibel. Manche Tanks nutzen mehrere Füllstandgeber für unregelmässige Tankformen; dieser ist der primäre.','["reductant_level_sensor"]','[{"id": "def_level_b_failed", "p": "high", "en": "Sender failed", "de": "Geber defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P21A9','P','Reductant Level Sensor B Circuit Range/Performance','Reduktionsmittel-Füllstandsensor B Bereich/Leistung','DEF level sensor B reading is in electrical range but plausibility check fails — value sticks, jumps, or does not match consumption.','Der AdBlue-Füllstandsensor B liegt im elektrischen Bereich, scheitert aber an der Plausibilität — bleibt hängen, springt oder passt nicht zum Verbrauch.','["reductant_level_sensor"]','[{"id": "def_level_b_stuck", "p": "high", "en": "Float arm sticks", "de": "Schwimmerarm h\u00e4ngt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P21AA','P','Reductant Level Sensor B Circuit Low','Reduktionsmittel-Füllstandsensor B Schaltkreis niedrig','DEF level sensor B reads below lower plausibility — short to ground. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the','Der AdBlue-Füllstandsensor B liegt unter der unteren Plausibilität — Kurzschluss nach Masse. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbau','["reductant_level_sensor"]','[{"id": "def_level_b_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P21AB','P','Reductant Level Sensor B Circuit High','Reduktionsmittel-Füllstandsensor B Schaltkreis hoch','DEF level sensor B reads above upper plausibility — open signal or short to B+. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often c','Der AdBlue-Füllstandsensor B liegt über der oberen Plausibilität — offenes Signal oder Kurzschluss nach Plus. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wacke','["reductant_level_sensor"]','[{"id": "def_level_b_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.7, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P21AC','P','Reductant Level Sensor B Circuit Intermittent/Erratic','Reduktionsmittel-Füllstandsensor B Schaltkreis sporadisch/erratisch','Reductant Level Sensor B Circuit Intermittent/Erratic: the signal is intermittent or erratic. Often a loose connector or chafed wiring; a wiggle test often locates it.','Reduktionsmittel-Füllstandsensor B Schaltkreis sporadisch/erratisch: das Signal ist sporadisch oder unsauber. Oft loser Stecker oder gescheuerte Leitung; ein Wackeltest lokalisiert ihn oft.','["reductant_level_sensor"]','[{"id": "def_level_b_intermittent", "p": "high", "en": "Corroded sender contact", "de": "Korrodierter Geberkontakt"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 600], "estimated_hours": [0.7, 3.0]}',1);
