INSERT OR IGNORE INTO dtc_codes VALUES('P21DB','P','Cylinder 1 Injector B Circuit Low','Zylinder 1 Injektor B Schaltkreis niedrig','Cylinder 1 second-injector (B) drive line stuck low — short to ground. A flow-deviating injector throws off cylinder balance — adjacent cylinders run leaner/richer to compensate, often masking the root cause until the trim limit is hit.','Treiberleitung des Zweitinjektors (B) an Zylinder 1 niedrig — Kurzschluss nach Masse. Ein abweichender Injektor stört die Zylinderbalance — Nachbarzylinder laufen kompensatorisch magerer/fetter, was die Ursache oft maskiert, bis das Trim-Limit erreic','["fuel_injector"]','[{"id": "cyl1_inj_b_short_to_ground", "p": "high", "en": "Short to ground", "de": "Kurzschluss nach Masse"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P21DC','P','Cylinder 1 Injector B Circuit High','Zylinder 1 Injektor B Schaltkreis hoch','Cylinder 1 second-injector (B) drive line stuck high — short to B+. A flow-deviating injector throws off cylinder balance — adjacent cylinders run leaner/richer to compensate, often masking the root cause until the trim limit is hit.','Treiberleitung des Zweitinjektors (B) an Zylinder 1 hoch — Kurzschluss nach Plus. Ein abweichender Injektor stört die Zylinderbalance — Nachbarzylinder laufen kompensatorisch magerer/fetter, was die Ursache oft maskiert, bis das Trim-Limit erreicht i','["fuel_injector"]','[{"id": "cyl1_inj_b_short_to_b_plus", "p": "high", "en": "Short to B+", "de": "Kurzschluss nach Plus"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 4.0]}',1);
