INSERT OR IGNORE INTO dtc_codes VALUES('P22B8','P','O2 Sensor Positive Current Control Circuit/Open (Bank 2 Sensor 2)','Lambdasonden-Pumpstrom positiv Steuerkreis/offen (Bank 2 Sensor 2)','The positive (sourcing) side of the O2 sensor pumping current control circuit on bank 2 sensor 2 is open. Wide-band O2 sensors regulate oxygen concentration in a reference chamber by pumping current; the positive line is open here.','Die positive Seite (Sourcing) des Pumpstrom-Steuerkreises der Lambdasonde an Bank 2 Sensor 2 ist offen. Breitbandsonden regeln die Sauerstoffkonzentration in einer Referenzkammer per Pumpstrom; hier ist die positive Leitung offen.','["oxygen_sensor"]','[{"id": "o2_pos_open_b2s2", "p": "high", "en": "Open positive current line", "de": "Positive Stromleitung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',1);
