INSERT OR IGNORE INTO dtc_codes VALUES('P22CC','P','Turbocharger Compressor Outlet Switching Valve Control Circuit High','Turbolader Verdichter-Auslass-Schaltventil Steuerkreis hoch','Compressor outlet switching valve drive line stuck high — short to B+. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Treiberleitung des Verdichter-Auslass-Schaltventils hoch — Kurzschluss nach Plus. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den gefordert','["boost_switching_valve"]','[{"id": "switch_valve_short_to_b_plus", "p": "high", "en": "Short to B+", "de": "Kurzschluss nach Plus"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.7, 3.0]}',1);
