INSERT OR IGNORE INTO dtc_codes VALUES('P22CF','P','Turbocharger Turbine Inlet Valve Control Circuit/Open','Turbolader Turbinen-Eintrittsventil Steuerkreis/offen','The drive circuit for the turbocharger turbine inlet valve is open. On sequential or two-stage charging the turbine inlet valve directs exhaust gas to the relevant turbine.','Der Treiberkreis des Turbinen-Eintrittsventils ist offen. Bei sequenziellem oder zweistufigem Aufladen lenkt das Ventil das Abgas zur relevanten Turbine.','["turbocharger", "turbine_inlet_valve"]','[{"id": "turbine_inlet_open_winding", "p": "high", "en": "Solenoid winding open", "de": "Magnetwicklung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 4.0]}',1);
