INSERT OR IGNORE INTO dtc_codes VALUES('P22D5','P','Turbocharger Turbine Inlet Valve Position Sensor Circuit Range/Performance','Turbolader Turbinen-Eintrittsventil Positionssensor Bereich/Leistung','Position sensor in range but plausibility fails — does not match commanded position. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Positionssensor liegt im Bereich, scheitert aber an der Plausibilität — passt nicht zur Sollposition. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator','["turbine_inlet_valve"]','[{"id": "turbine_inlet_pos_drift", "p": "high", "en": "Sensor drift", "de": "Sensor driftet"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.7, 3.0]}',1);
