INSERT OR IGNORE INTO dtc_codes VALUES('P22D7','P','Turbocharger Turbine Inlet Valve Position Sensor Circuit High','Turbolader Turbinen-Eintrittsventil Positionssensor Schaltkreis hoch','Position sensor above upper plausibility — open signal or short to B+. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Positionssensor über oberer Plausibilität — offenes Signal oder Kurzschluss nach Plus. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den gefo','["turbine_inlet_valve"]','[{"id": "turbine_inlet_pos_open_signal", "p": "high", "en": "Open signal line", "de": "Unterbrochene Signalleitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.7, 3.0]}',1);
