INSERT OR IGNORE INTO dtc_codes VALUES('P22D9','P','Cylinder 1 Alternative Fuel Injector Control Circuit/Open','Zylinder 1 Alternativ-Kraftstoffinjektor Steuerkreis/offen','The drive circuit for the cylinder 1 alternative-fuel injector is open. Bi-fuel vehicles have a second set of injectors for CNG, LPG, or hydrogen — separate from the petrol/diesel injectors.','Der Treiberkreis des Alternativ-Kraftstoffinjektors an Zylinder 1 ist offen. Zweistoff-Fahrzeuge haben einen zweiten Injektorensatz für CNG, LPG oder Wasserstoff — getrennt von den Benzin-/Dieselinjektoren.','["alternative_fuel_injector"]','[{"id": "alt_inj_cyl1_open_winding", "p": "high", "en": "Injector winding open", "de": "Injektorwicklung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1.0, 4.0]}',1);
