INSERT OR IGNORE INTO dtc_codes VALUES('P22E0','P','Cylinder 2 Alternative Fuel Injector Control Circuit Range/Performance','Zylinder 2 Alternativ-Kraftstoffinjektor Steuerkreis Bereich/Leistung','Cylinder 2 alternative-fuel injector is electrically OK but its response (current ramp, dwell, peak voltage) is off-spec — typically winding ageing.','Alternativ-Kraftstoffinjektor an Zylinder 2 ist elektrisch in Ordnung, der Antwortverlauf passt aber nicht zur Kalibrierung — meist Wicklungsalterung.','["alternative_fuel_injector"]','[{"id": "alt_inj_cyl2_drift", "p": "high", "en": "Winding ageing", "de": "Wicklungsalterung"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1.0, 4.0]}',1);
