INSERT OR IGNORE INTO dtc_codes VALUES('P22F1','P','Particulate Matter Sensor Heater Performance','Partikelsensor-Heizung Funktion','The particulate matter (PM) sensor heater on diesel after-DPF systems does not reach or hold the calibrated operating temperature within the expected time. Without proper heating the PM sensor cannot be regenerated and read correctly.','Die Heizung des Partikelsensors (PM-Sensor) im Dieselsystem nach dem DPF erreicht oder haelt die kalibrierte Betriebstemperatur nicht innerhalb der erwarteten Zeit. Ohne korrekte Heizung kann der PM-Sensor nicht regeneriert und korrekt ausgelesen wer','["pm_sensor", "pm_heater_circuit"]','[{"id": "pm_sensor_aging", "p": "high", "en": "PM sensor aging", "de": "Alterung des PM-Sensors"}, {"id": "pm_heater_resistance", "p": "medium", "en": "Increased heater resistance", "de": "Erhoehter Heizerwiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1, 4]}',1);
