INSERT OR IGNORE INTO dtc_codes VALUES('P2328','P','Ignition Coil J Primary Control Circuit High','Zündspule J Primärsteuerkreis - hoch','The primary control circuit of ignition coil J reads a voltage above the expected level — typically an open primary circuit or a short to battery voltage on the primary control wire. The ECU sees no normal current flow, coil J does not fire, and the ','Der Primär-Steuerkreis der Zündspule J liegt über dem erwarteten Spannungswert — typischerweise eine Unterbrechung im Primärkreis oder ein Kurzschluss gegen Batteriespannung an der Primär-Steuerleitung. Das Steuergerät erkennt keinen normalen Stromfl','["ignition_coil_j", "ignition_coil_wiring_j", "ignition_module"]','[{"id": "open_circuit", "p": "high", "en": "Open circuit in primary winding or harness for coil J", "de": "Unterbrechung in Prim\u00e4rwicklung oder Kabelbaum der Z\u00fcndspule J"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 280], "estimated_hours": [0.4, 1.2]}',1);
