INSERT OR IGNORE INTO dtc_codes VALUES('P232A','P','TCM Request Forced Engine Shutdown','Aufforderung des TCM zum erzwungenen Motorstopp','The transmission control module (TCM) has requested an emergency engine shutdown over the powertrain bus, typically because it has detected a condition that could damage the gearbox or driveline if engine torque were not removed (e.g. severe overheat','Das Getriebesteuergerät (TCM) hat über den Antriebsstrangbus einen Notabstellbefehl an den Motor abgesetzt - meist weil es einen Zustand erkannt hat, der das Getriebe oder den Antriebsstrang ohne sofortige Drehmomentwegnahme schädigen würde (z. B. st','["tcm", "powertrain_bus", "ecm"]','[{"id": "tcm_internal_protection", "p": "high", "en": "TCM internal protection logic triggered by gearbox condition", "de": "Schutzlogik im TCM durch Getriebezustand ausgel\u00f6st"}, {"id": "bus_message_invalid", "p": "low", "en": "Invalid or stuck shutdown message on powertrain bus", "de": "Fehlerhafte oder h\u00e4ngende Notbotschaft auf dem Antriebsstrangbus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 3500], "estimated_hours": [1.0, 8.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P232B','P','Cylinder 11 Fuel Injector A Offset Learning At Min Limit','Zylinder 11 Einspritzventil A - Offset-Lernwert an unterer Grenze','Cylinder 11 Fuel Injector A Offset Learning At Min Limit: the control module has detected this fault condition. This affects fueling of the associated cylinders.','Zylinder 11 Einspritzventil A - Offset-Lernwert an unterer Grenze: das Steuergerät hat diesen Fehlerzustand erkannt. Dies betrifft die Kraftstoffzufuhr der zugehörigen Zylinder.','["fuel_injector_cyl_11", "injector_wiring_cyl_11", "injector_learning_strategy"]','[{"id": "injector_clogged", "p": "high", "en": "Injector partially clogged or coked", "de": "Einspritzventil teilverstopft oder verkokt"}, {"id": "injector_drift_low", "p": "medium", "en": "Injector aged - flow rate has drifted low", "de": "Einspritzventil gealtert - Durchflussmenge zu gering"}, {"id": "harness_resistance", "p": "low", "en": "Increased contact resistance in injector harness", "de": "Erh\u00f6hter \u00dcbergangswiderstand im Einspritz-Kabelbaum"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [180, 700], "estimated_hours": [1.0, 2.5]}',1);
