INSERT OR IGNORE INTO dtc_codes VALUES('P2336','P','Cylinder 1 Above Knock Threshold','Zylinder 1 über Klopfschwelle','The knock sensor channel for cylinder 1 has registered combustion noise above the calibrated knock threshold beyond what the spark retard map can correct. Often associated with low-octane fuel, EGR malfunction or carbon-induced hot spots.','Der Klopfsensorkanal für Zylinder 1 meldet Verbrennungsgeräusche über der kalibrierten Klopfschwelle, die durch Zündzeitpunkt-Spätverstellung nicht mehr ausgeregelt werden können. Häufig durch zu niedrigoktanigen Kraftstoff, AGR-Fehler oder verkokung','["knock_sensor", "spark_plug"]','[{"id": "low_octane_fuel", "p": "high", "en": "Low octane fuel used", "de": "Zu niedrigoktaniger Kraftstoff getankt"}, {"id": "carbon_hot_spots", "p": "medium", "en": "Carbon deposits causing pre-ignition", "de": "Verkokung mit Gl\u00fchz\u00fcndung"}, {"id": "egr_malfunction", "p": "medium", "en": "EGR not lowering combustion temperature", "de": "AGR senkt Verbrennungstemperatur nicht"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 800], "estimated_hours": [0.5, 4.0]}',1);
