INSERT OR IGNORE INTO dtc_codes VALUES('P235C','P','Cylinder 11 Pressure Sensor Circuit','Zylinder 11 Drucksensor Stromkreis','A general electrical fault on the cylinder 11 combustion pressure sensor — used on engines with closed-loop combustion control (e.g. some Volvo and BMW direct-injection diesels) to measure cylinder pressure directly via a sensor at the glow plug or i','Allgemeiner elektrischer Fehler am Brennraumdrucksensor von Zylinder 11 — eingesetzt bei Motoren mit geschlossener Verbrennungsregelung (z. B. einige Volvo- und BMW-Diesel-Direkteinspritzer) zur direkten Brennraumdruckmessung am Glühkerzen- oder Inje','["cylinder_pressure_sensor_11"]','[{"id": "open_circuit", "p": "high", "en": "Open circuit in sensor or wiring", "de": "Unterbrechung in Sensor oder Verkabelung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1800], "estimated_hours": [1.5, 5.0]}',1);
