INSERT OR IGNORE INTO dtc_codes VALUES('P23F2','P','Cylinder 1 Injector B Air-Fuel Ratio Imbalance','Zylinder 1 Einspritzventil B - Luft-Kraftstoff-Ungleichgewicht','On dual-injector systems (typical for some heavy-duty diesels and some petrol/gas bi-fuel applications) the secondary injector B at cylinder 1 cannot keep its mixture in balance with the rest of the bank.','Bei Doppel-Einspritzventil-Systemen (typisch für einige Nutzfahrzeug-Diesel und manche Bi-Fuel-Anwendungen) kann das sekundäre Einspritzventil B an Zylinder 1 sein Gemisch nicht im Gleichgewicht mit der übrigen Bank halten.','["fuel_injector_b_cyl_1"]','[{"id": "injector_drift", "p": "high", "en": "Injector B for cylinder 1 has drifted in flow rate", "de": "Einspritzventil B an Zylinder 1 hat ver\u00e4nderte Durchflussmenge"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1.0, 4.0]}',1);
