INSERT OR IGNORE INTO dtc_codes VALUES('P2480','P','Exhaust Gas Temperature Sensor Circuit Bank 2 Sensor 3','Abgastemperatursensor Stromkreis Bank 2 Sonde 3','General electrical fault on EGT sensor 3 on bank 2. The ECU loses the temperature reference required for DPF regeneration management on bank 2.','Allgemeiner elektrischer Fehler am EGT-Sensor 3 auf Bank 2. Die ECU verliert die fuer die DPF-Regenerationsregelung auf Bank 2 noetige Temperaturreferenz.','["exhaust_gas_temperature_sensor", "egt_wiring"]','[{"id": "sensor_fault", "p": "high", "en": "Defective EGT sensor", "de": "Defekter EGT-Sensor"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [120, 500], "estimated_hours": [0.5, 2]}',1);
