INSERT OR IGNORE INTO dtc_codes VALUES('P2492','P','EGR Cooler Bypass Position Sensor Circuit Bank 1','AGR-Kühler-Bypass Lagesensor Stromkreis Bank 1','A general circuit fault on the position feedback sensor of the EGR cooler bypass valve on bank 1. EGR mixes inert exhaust into intake to lower combustion peak temperature — too little raises NOx, too much causes misfires and rough running.','Allgemeiner Stromkreisfehler am Lagerückmeldesensor des AGR-Kühler-Bypassventils an Bank 1. AGR mischt inertes Abgas in den Ansaugstrang, um die Verbrennungs-Spitzentemperatur zu senken — zu wenig erhöht NOx, zu viel führt zu Aussetzern und unruhigem','["egr_cooler_bypass_position_sensor_b1"]','[{"id": "open_circuit", "p": "high", "en": "Open in sensor or wiring", "de": "Unterbrechung in Sensor oder Verkabelung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [150, 500], "estimated_hours": [0.8, 2.0]}',1);
