INSERT OR IGNORE INTO dtc_codes VALUES('P2727','P','Pressure Control Solenoid E Control Circuit / Open','Druckregel-Solenoid E Steuerkreis / Unterbrechung','The control line to pressure control solenoid E is open. The solenoid cannot be driven.','Die Steuerleitung zum Druckregel-Solenoid E ist offen. Das Solenoid kann nicht angesteuert werden.','["pressure_control_solenoid_e", "wiring_harness"]','[{"id": "solenoid_open", "p": "high", "en": "Open solenoid coil", "de": "Offene Solenoidspule"}, {"id": "harness_open", "p": "medium", "en": "Broken control wire", "de": "Gebrochene Steuerleitung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6.0]}',1);
