INSERT OR IGNORE INTO dtc_codes VALUES('P2750','P','Intermediate Shaft Speed Sensor C Circuit Range/Performance','Vorgelegewellen-Drehzahlsensor C Stromkreis Bereich/Leistung','The third intermediate shaft speed sensor reading is implausible against expected speed from gear ratio and input shaft speed.','Der Wert des dritten Vorgelegewellen-Drehzahlsensors ist gegenüber der erwarteten Drehzahl aus Übersetzung und Eingangsdrehzahl unplausibel.','["intermediate_shaft_speed_sensor_c", "tone_wheel"]','[{"id": "tone_wheel_damaged", "p": "high", "en": "Damaged tone wheel teeth produce missing pulses", "de": "Besch\u00e4digte Geberradz\u00e4hne erzeugen fehlende Impulse"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor air gap drift", "de": "Sensor-Luftspalt-Drift"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [180, 1500], "estimated_hours": [1.0, 5.0]}',1);
