INSERT OR IGNORE INTO dtc_codes VALUES('P278D','P','Kick Down Switch Circuit High','Kickdown-Schalter Stromkreis hoch','Voltage on the kick-down switch line is above the expected window. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the l','Die Spannung am Kickdown-Schalter liegt über dem erwarteten Bereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokal','["kickdown_switch", "wiring_harness"]','[{"id": "switch_open", "p": "high", "en": "Open switch contacts", "de": "Offene Schaltkontakte"}, {"id": "short_to_battery", "p": "medium", "en": "Switch wire shorted to B+", "de": "Schalterleitung mit B+ kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.3, 1.5]}',1);
