INSERT OR IGNORE INTO dtc_codes VALUES('P278F','P','Clutch B Adaptive Learning at Limit','Kupplung B Adaptive Lernung am Limit','The adaptive learning that compensates for clutch B engagement point drift in a DCT has reached its limit.','Die adaptive Lernung zur Kompensation der Eingriffspunkt-Drift von Kupplung B in einem DCT hat ihren Grenzwert erreicht.','["dual_clutch_b", "tcm"]','[{"id": "clutch_worn_out", "p": "high", "en": "Clutch worn beyond compensation range", "de": "Kupplung \u00fcber den Kompensationsbereich hinaus verschlissen"}, {"id": "actuator_drift", "p": "medium", "en": "Actuator position drift", "de": "Aktuator-Positionsdrift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [4.0, 12.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2790','P','Gate Select Direction Circuit','Wählhebel-Richtungskreis','The gate-select direction circuit on an automated manual or sequential transmission cannot detect which direction the selector is being moved.','Der Wählhebel-Richtungskreis eines automatisierten Schaltgetriebes oder Sequentialgetriebes kann die Bewegungsrichtung des Wählhebels nicht erkennen.','["gate_select_sensor", "shifter_assembly", "wiring_harness"]','[{"id": "sensor_open", "p": "high", "en": "Open sensor or broken signal wire", "de": "Offener Sensor oder gebrochene Signalleitung"}, {"id": "connector_corrosion", "p": "medium", "en": "Corroded sensor connector", "de": "Korrodierter Sensorstecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.8, 3.0]}',1);
