INSERT OR IGNORE INTO dtc_codes VALUES('P2793','P','Gear Shift Direction Circuit','Gangwechsel-Richtungskreis','The gear-shift direction circuit cannot detect the commanded shift direction (up or down) on an automated manual or sequential transmission.','Der Gangwechsel-Richtungskreis kann die angeforderte Schaltrichtung (hoch oder runter) bei einem automatisierten Schaltgetriebe oder Sequentialgetriebe nicht erkennen.','["shift_direction_sensor", "shifter_assembly", "wiring_harness"]','[{"id": "sensor_open", "p": "high", "en": "Open sensor or broken signal wire", "de": "Offener Sensor oder gebrochene Signalleitung"}, {"id": "connector_corrosion", "p": "medium", "en": "Corroded sensor connector", "de": "Korrodierter Sensorstecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.8, 3.0]}',1);
