INSERT OR IGNORE INTO dtc_codes VALUES('P279A','P','Transfer Case Gear High Incorrect Ratio','Verteilergetriebe High-Gang falsche Übersetzung','When the transfer case is in High range the measured input/output speed ratio does not match the expected value. Worn chain or planetary set.','Bei eingelegter High-Range im Verteilergetriebe stimmt die gemessene Übersetzung Eingang/Ausgang nicht mit dem Sollwert überein. Verschlissene Kette oder Planetensatz.','["transfer_case", "planetary_gear_set"]','[{"id": "chain_stretched", "p": "high", "en": "Stretched transfer case chain", "de": "Gel\u00e4ngte Verteilergetriebe-Kette"}, {"id": "planetary_wear", "p": "medium", "en": "Worn planetary gear set", "de": "Verschlissener Planetensatz"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [600, 3500], "estimated_hours": [3.0, 8.0]}',1);
