INSERT OR IGNORE INTO dtc_codes VALUES('P279C','P','Transfer Case Gear Neutral Incorrect Ratio','Verteilergetriebe Neutral falsche Übersetzung','When the transfer case is in Neutral the measured output speed is not zero or shows unexpected drag.','Bei Verteilergetriebe in Neutral ist die gemessene Ausgangsdrehzahl nicht null oder zeigt unerwarteten Mitlauf.','["transfer_case", "shift_fork"]','[{"id": "shift_fork_misaligned", "p": "high", "en": "Shift fork not fully in neutral position", "de": "Schaltgabel nicht vollst\u00e4ndig in Neutral-Position"}, {"id": "drag_torque", "p": "medium", "en": "Drag torque from contaminated oil", "de": "Mitschleppmoment durch verunreinigtes \u00d6l"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2.5, 6.0]}',1);
