INSERT OR IGNORE INTO dtc_codes VALUES('P27E1','P','Electric/Auxiliary Transmission Fluid Pump A Pressure Too Low','Elektrische/Auxiliäre Getriebeölpumpe A Druck zu niedrig','The auxiliary transmission fluid pump A produces less pressure than expected for the commanded duty. Pump aging, leakage, or fluid loss.','Die Auxiliär-Getriebeölpumpe A liefert weniger Druck als bei der angeforderten Ansteuerung erwartet. Pumpenverschleiß, Leckage oder Ölverlust.','["aux_transmission_pump_a", "transmission_fluid", "valve_body"]','[{"id": "pump_worn", "p": "high", "en": "Pump worn or leaking internally", "de": "Pumpe verschlissen oder intern undicht"}, {"id": "fluid_low", "p": "medium", "en": "Transmission fluid level low", "de": "Getriebe\u00f6lstand zu niedrig"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2200], "estimated_hours": [2, 7]}',1);
