INSERT OR IGNORE INTO dtc_codes VALUES('P27EC','P','Transmission Range Control A Position Sensor/Switch Circuit Range/Performance','Getriebebereichs-Steuerung A Positionssensor/Schalter Stromkreis Bereich/Leistung','The position sensor or switch of transmission range control channel A reports a circuit range/performance condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals A meldet einen Zustand "Stromkreis Bereich/Leistung". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_a", "wiring_harness", "tcm"]','[{"id": "switch_dirty_contacts", "p": "medium", "en": "Dirty or oxidised switch contacts", "de": "Verschmutzte oder oxidierte Schalterkontakte"}, {"id": "sensor_misadjusted", "p": "medium", "en": "Sensor mounting misadjusted", "de": "Sensorbefestigung dejustiert"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27ED','P','Transmission Range Control A Position Sensor/Switch Circuit Low','Getriebebereichs-Steuerung A Positionssensor/Schalter Stromkreis niedrig','The position sensor or switch of transmission range control channel A reports a circuit low condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals A meldet einen Zustand "Stromkreis niedrig". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_a", "wiring_harness", "tcm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal short in position sensor", "de": "Interner Kurzschluss im Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27EE','P','Transmission Range Control A Position Sensor/Switch Circuit High','Getriebebereichs-Steuerung A Positionssensor/Schalter Stromkreis hoch','The position sensor or switch of transmission range control channel A reports a circuit high condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals A meldet einen Zustand "Stromkreis hoch". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_a", "wiring_harness", "tcm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open position sensor", "de": "Offener Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27EF','P','Transmission Range Control B Position Sensor/Switch Circuit/Open','Getriebebereichs-Steuerung B Positionssensor/Schalter Stromkreis offen','The position sensor or switch of transmission range control channel B reports a circuit/open condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals B meldet einen Zustand "Stromkreis offen". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_b", "wiring_harness", "tcm"]','[{"id": "wire_open", "p": "high", "en": "Open in sensor signal wire", "de": "Unterbrechung in der Sensor-Signalleitung"}, {"id": "switch_failed_open", "p": "medium", "en": "Position switch failed open", "de": "Positions-Schalter offen ausgefallen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F0','P','Transmission Range Control B Position Sensor/Switch Circuit Range/Performance','Getriebebereichs-Steuerung B Positionssensor/Schalter Stromkreis Bereich/Leistung','The position sensor or switch of transmission range control channel B reports a circuit range/performance condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals B meldet einen Zustand "Stromkreis Bereich/Leistung". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_b", "wiring_harness", "tcm"]','[{"id": "switch_dirty_contacts", "p": "medium", "en": "Dirty or oxidised switch contacts", "de": "Verschmutzte oder oxidierte Schalterkontakte"}, {"id": "sensor_misadjusted", "p": "medium", "en": "Sensor mounting misadjusted", "de": "Sensorbefestigung dejustiert"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F1','P','Transmission Range Control B Position Sensor/Switch Circuit Low','Getriebebereichs-Steuerung B Positionssensor/Schalter Stromkreis niedrig','The position sensor or switch of transmission range control channel B reports a circuit low condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals B meldet einen Zustand "Stromkreis niedrig". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_b", "wiring_harness", "tcm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal short in position sensor", "de": "Interner Kurzschluss im Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F2','P','Transmission Range Control B Position Sensor/Switch Circuit High','Getriebebereichs-Steuerung B Positionssensor/Schalter Stromkreis hoch','The position sensor or switch of transmission range control channel B reports a circuit high condition. The TCM cannot verify the actuator position reliably.','Der Positionssensor bzw. Schalter des Getriebebereichs-Steuerkanals B meldet einen Zustand "Stromkreis hoch". Das Getriebesteuergerät kann die Aktuatorposition nicht zuverlässig prüfen.','["range_control_position_sensor_b", "wiring_harness", "tcm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open position sensor", "de": "Offener Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F3','P','Clutch B Temperature Too High','Kupplung B Temperatur zu hoch','The transmission control unit measures clutch B temperature above the safe operating threshold. Repeated slip events or excessive load have heated the clutch pack.','Das Getriebesteuergerät misst eine Temperatur der Kupplung B oberhalb des sicheren Betriebsbereichs. Wiederholte Schlupfereignisse oder hohe Last haben das Kupplungspaket erhitzt.','["clutch_b", "transmission_fluid", "tcm"]','[{"id": "excessive_slip", "p": "high", "en": "Excessive clutch slip during launches", "de": "\u00dcberm\u00e4\u00dfiger Kupplungsschlupf beim Anfahren"}, {"id": "fluid_degraded", "p": "medium", "en": "Degraded transmission fluid lowers heat capacity", "de": "Verschlechtertes Getriebe\u00f6l senkt die W\u00e4rmekapazit\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [600, 3500], "estimated_hours": [3, 12]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F4','P','Gear Shift Lock Solenoid/Actuator A Performance/Stuck On','Wahlhebel-Sperrsolenoid/-Aktuator A Leistung/festsitzend an','The shift lock solenoid for selector lever A stays engaged when release is commanded. Driver cannot move the selector out of Park or away from the locked gate.','Das Wahlhebel-Sperrsolenoid für Schalthebel A bleibt eingerückt, obwohl die Freigabe angefordert wurde. Der Fahrer kann den Wahlhebel nicht aus der Park-Position oder aus der gesperrten Schaltgasse bewegen.','["shift_lock_solenoid_a", "shift_lock_actuator_a", "tcm"]','[{"id": "actuator_stuck", "p": "high", "en": "Lock actuator mechanically stuck", "de": "Sperraktuator mechanisch festsitzend"}, {"id": "driver_stuck_on", "p": "medium", "en": "Control driver stuck on", "de": "Steuer-Endstufe bleibt durchgeschaltet"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P27F5','P','Gear Shift Lock Solenoid/Actuator A Stuck Off','Wahlhebel-Sperrsolenoid/-Aktuator A festsitzend aus','The shift lock solenoid for selector lever A does not engage when commanded. The selector can be moved without the safety interlock active.','Das Wahlhebel-Sperrsolenoid für Schalthebel A rückt bei Anforderung nicht ein. Der Wahlhebel lässt sich ohne aktive Sicherheitsverriegelung bewegen.','["shift_lock_solenoid_a", "shift_lock_actuator_a", "tcm"]','[{"id": "actuator_failed", "p": "high", "en": "Lock actuator failed mechanically", "de": "Sperraktuator mechanisch defekt"}, {"id": "wire_open", "p": "medium", "en": "Open in solenoid control wire", "de": "Unterbrechung in der Solenoid-Steuerleitung"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2800','P','Transmission Range Sensor B Circuit (PRNDL Input)','Getriebebereichs-Sensor B Stromkreis (PRNDL-Eingang)','The TCM detects an invalid PRNDL signal pattern from transmission range sensor B. The selected gear position cannot be determined reliably from the B-channel.','Das Getriebesteuergerät erkennt ein ungültiges PRNDL-Signalmuster vom Getriebebereichs-Sensor B. Die gewählte Wählhebelposition lässt sich aus dem B-Kanal nicht zuverlässig bestimmen.','["transmission_range_sensor_b", "wiring_harness", "tcm"]','[{"id": "switch_failed", "p": "high", "en": "Range switch contact array failed", "de": "Bereichsschalter-Kontaktarray defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Open or short in PRNDL wiring", "de": "Unterbrechung oder Kurzschluss in der PRNDL-Verkabelung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2801','P','Transmission Range Sensor B Circuit Range/Performance','Getriebebereichs-Sensor B Stromkreis Bereich/Leistung','Range sensor B reports a position that does not match other plausibility checks. Mechanical alignment off or sensor contacts intermittent.','Bereichssensor B meldet eine Position, die anderen Plausibilitätsprüfungen widerspricht. Mechanische Justage ausser Toleranz oder Kontakte sporadisch.','["transmission_range_sensor_b", "wiring_harness", "tcm"]','[{"id": "sensor_misadjusted", "p": "high", "en": "Sensor mechanically misadjusted", "de": "Sensor mechanisch dejustiert"}, {"id": "contacts_dirty", "p": "medium", "en": "Contacts dirty or oxidised", "de": "Kontakte verschmutzt oder oxidiert"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2802','P','Transmission Range Sensor B Circuit Low','Getriebebereichs-Sensor B Stromkreis niedrig','Voltage on the range sensor B signal line is below the expected window. Wire shorted to ground or sensor internal short.','Die Spannung auf der Signalleitung des Bereichssensors B liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder interner Sensor-Kurzschluss.','["transmission_range_sensor_b", "wiring_harness", "tcm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2803','P','Transmission Range Sensor B Circuit High','Getriebebereichs-Sensor B Stromkreis hoch','Voltage on the range sensor B signal line is above the expected window. Wire shorted to B+ or sensor open.','Die Spannung auf der Signalleitung des Bereichssensors B liegt über dem erwarteten Bereich. Leitung mit B+ kurzgeschlossen oder offener Sensor.','["transmission_range_sensor_b", "wiring_harness", "tcm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open range sensor B", "de": "Offener Bereichssensor B"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2804','P','Transmission Range Sensor B Circuit Intermittent','Getriebebereichs-Sensor B Stromkreis sporadisch','The range sensor B signal drops out intermittently. Loose connector or vibration-sensitive solder joint.','Das Signal des Bereichssensors B fällt sporadisch aus. Lockerer Stecker oder vibrationsempfindliche Lötstelle.','["transmission_range_sensor_b", "wiring_harness", "tcm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "harness_chafe", "p": "medium", "en": "Harness chafing intermittently grounds the wire", "de": "Scheuernde Leitung schlie\u00dft sporadisch nach Masse"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2805','P','Transmission Range Sensor A/B Correlation','Getriebebereichs-Sensor A/B Korrelation','The two range sensor channels A and B do not agree on the same gear selector position. Plausibility check fails after debounce.','Die beiden Bereichssensor-Kanäle A und B stimmen nicht über die gewählte Wählhebelposition überein. Die Plausibilitätsprüfung schlägt nach Entprellung fehl.','["transmission_range_sensor_a", "transmission_range_sensor_b", "tcm"]','[{"id": "sensor_misalignment", "p": "high", "en": "One sensor mechanically misaligned", "de": "Ein Sensor mechanisch dejustiert"}, {"id": "contacts_aged", "p": "medium", "en": "Aged switch contacts on one channel", "de": "Gealterte Schalterkontakte auf einem Kanal"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2806','P','Transmission Range Sensor Alignment','Getriebebereichs-Sensor Justierung','The TCM detects that the transmission range sensor mechanical alignment is outside the calibration window. Selector positions read with offset across the entire travel.','Das Getriebesteuergerät erkennt, dass die mechanische Justierung des Getriebebereichs-Sensors außerhalb des Kalibrierfensters liegt. Wählpositionen werden über den gesamten Verfahrweg mit Versatz erkannt.','["transmission_range_sensor", "selector_linkage"]','[{"id": "linkage_shifted", "p": "high", "en": "Selector linkage shifted on the sensor shaft", "de": "W\u00e4hlhebelgest\u00e4nge auf der Sensorwelle verrutscht"}, {"id": "mounting_loose", "p": "medium", "en": "Sensor mounting bolts loose", "de": "Sensor-Befestigungsschrauben gelockert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2807','P','Pressure Control Solenoid G','Druckregel-Solenoid G','A general fault in pressure control solenoid G. Detected via electrical resistance, response to commanded duty cycle, or downstream pressure measurement.','Allgemeiner Fehler im Druckregel-Solenoid G. Erkannt über elektrischen Widerstand, Reaktion auf Soll-Tastgrad oder nachgelagerte Druckmessung.','["pressure_control_solenoid_g", "valve_body"]','[{"id": "solenoid_aged", "p": "high", "en": "Aged solenoid coil resistance drift", "de": "Spulenwiderstand des gealterten Solenoids driftet"}, {"id": "valve_body_wear", "p": "medium", "en": "Worn valve body bore around the solenoid", "de": "Verschlissene Ventilk\u00f6rperbohrung am Solenoid"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2808','P','Pressure Control Solenoid G Performance/Stuck Off','Druckregel-Solenoid G Leistung/festsitzend aus','Pressure control solenoid G is commanded on but does not produce the expected pressure. Spool stuck closed or hydraulic feed restricted.','Das Druckregel-Solenoid G wird angesteuert, liefert aber nicht den erwarteten Druck. Schieber geschlossen festsitzend oder Hydraulik-Zulauf eingeengt.','["pressure_control_solenoid_g", "valve_body"]','[{"id": "spool_stuck_closed", "p": "high", "en": "Solenoid spool stuck in closed position", "de": "Solenoid-Schieber in Geschlossen-Position festsitzend"}, {"id": "feed_restricted", "p": "medium", "en": "Hydraulic feed restricted by debris", "de": "Hydraulik-Zulauf durch Schmutz eingeengt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2809','P','Pressure Control Solenoid G Stuck On','Druckregel-Solenoid G dauerhaft an','Pressure control solenoid G stays in the activated state when commanded off. Affected hydraulic circuit stays pressurised.','Das Druckregel-Solenoid G bleibt im aktivierten Zustand, auch wenn die Anforderung zurückgenommen wird. Der zugehörige Hydraulikkreis bleibt unter Druck.','["pressure_control_solenoid_g", "valve_body"]','[{"id": "spool_stuck_open", "p": "high", "en": "Solenoid spool stuck in open position", "de": "Solenoid-Schieber in Offen-Position festsitzend"}, {"id": "driver_stuck_on", "p": "medium", "en": "TCM output driver stuck on", "de": "TCM-Endstufe bleibt durchgeschaltet"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P280A','P','Transmission Range Sensor A Circuit Not Learned','Getriebebereichs-Sensor A Stromkreis nicht angelernt','The TCM has not learned the calibration window for transmission range sensor A. Selector positions cannot be mapped reliably until adaptation completes.','Das Getriebesteuergerät hat das Kalibrierfenster für den Getriebebereichs-Sensor A nicht angelernt. Wählpositionen können erst nach abgeschlossener Adaption zuverlässig zugeordnet werden.','["transmission_range_sensor_a", "tcm"]','[{"id": "adaptation_lost", "p": "high", "en": "Adaptation lost after battery disconnect or TCM reset", "de": "Adaption nach Batterieabklemmung oder TCM-Reset verloren"}, {"id": "sensor_replaced", "p": "medium", "en": "Sensor replaced without learn procedure", "de": "Sensor ohne Anlernprozedur ersetzt"}]','{"difficulty": "easy", "diy_possible": false, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P280B','P','Transmission Range Sensor B Circuit Not Learned','Getriebebereichs-Sensor B Stromkreis nicht angelernt','The TCM has not learned the calibration window for transmission range sensor B. Selector positions cannot be mapped reliably until adaptation completes.','Das Getriebesteuergerät hat das Kalibrierfenster für den Getriebebereichs-Sensor B nicht angelernt. Wählpositionen können erst nach abgeschlossener Adaption zuverlässig zugeordnet werden.','["transmission_range_sensor_b", "tcm"]','[{"id": "adaptation_lost", "p": "high", "en": "Adaptation lost after battery disconnect or TCM reset", "de": "Adaption nach Batterieabklemmung oder TCM-Reset verloren"}, {"id": "sensor_replaced", "p": "medium", "en": "Sensor replaced without learn procedure", "de": "Sensor ohne Anlernprozedur ersetzt"}]','{"difficulty": "easy", "diy_possible": false, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2810','P','Pressure Control Solenoid G Electrical','Druckregel-Solenoid G elektrisch','The TCM detects an electrical fault on transmission pressure control solenoid G. Hydraulic pressure cannot be modulated as expected, causing harsh or slipping shifts.','Das Getriebesteuergerät erkennt einen elektrischen Fehler am Druckregel-Solenoid G des Getriebes. Der Hydraulikdruck kann nicht wie erwartet moduliert werden, was harte oder rutschende Schaltungen verursacht.','["pressure_control_solenoid_g", "tcm", "transmission_wiring"]','[{"id": "solenoid_internal", "p": "high", "en": "Internal solenoid fault", "de": "Interner Magnetventil-Fehler"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2811','P','Pressure Control Solenoid G Intermittent','Druckregel-Solenoid G sporadisch','Pressure control solenoid G shows intermittent electrical or hydraulic faults. Loose connector or marginal coil.','Das Druckregel-Solenoid G zeigt sporadische elektrische oder hydraulische Fehler. Lockerer Stecker oder grenzwertige Spule.','["pressure_control_solenoid_g", "wiring_harness"]','[{"id": "connector_loose", "p": "high", "en": "Solenoid connector not fully seated", "de": "Solenoidstecker nicht vollst\u00e4ndig eingerastet"}, {"id": "coil_marginal", "p": "medium", "en": "Coil resistance drifts with temperature", "de": "Spulenwiderstand driftet mit Temperatur"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2812','P','Pressure Control Solenoid G Control Circuit/Open','Druckregel-Solenoid G Steuerkreis offen','The TCM detects an open circuit in the control wiring of pressure control solenoid G. No current flows when the solenoid is commanded.','Das Getriebesteuergerät erkennt eine Unterbrechung in der Steuerleitung des Druckregel-Solenoids G. Beim Ansteuern fließt kein Strom.','["pressure_control_solenoid_g", "wiring_harness"]','[{"id": "wire_open", "p": "high", "en": "Open in solenoid control wire", "de": "Unterbrechung in der Solenoid-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open solenoid coil", "de": "Offene Solenoidspule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2813','P','Pressure Control Solenoid G Control Circuit Range/Performance','Druckregel-Solenoid G Steuerkreis Bereich/Leistung','The current through pressure control solenoid G does not match the commanded value within tolerance. Coil resistance drift or high-resistance contact.','Der Strom durch das Druckregel-Solenoid G stimmt nicht innerhalb der Toleranz mit dem Sollwert überein. Driftender Spulenwiderstand oder hochohmiger Kontakt.','["pressure_control_solenoid_g", "wiring_harness"]','[{"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance changed by thermal stress", "de": "Spulenwiderstand durch thermische Belastung ver\u00e4ndert"}, {"id": "connector_high_resistance", "p": "medium", "en": "High-resistance contact in solenoid connector", "de": "Hochohmiger Kontakt im Solenoid-Stecker"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2814','P','Pressure Control Solenoid G Control Circuit Low','Druckregel-Solenoid G Steuerkreis niedrig','Voltage on the pressure control solenoid G control line is below the expected window. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active o','Die Spannung auf der Steuerleitung des Druckregel-Solenoids G liegt unter dem erwarteten Bereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kab','["pressure_control_solenoid_g", "wiring_harness"]','[{"id": "short_to_ground", "p": "high", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}, {"id": "coil_short", "p": "medium", "en": "Internal short in solenoid coil", "de": "Interner Kurzschluss in der Solenoidspule"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2815','P','Pressure Control Solenoid G Control Circuit High','Druckregel-Solenoid G Steuerkreis hoch','Voltage on the pressure control solenoid G control line is above the expected window. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active o','Die Spannung auf der Steuerleitung des Druckregel-Solenoids G liegt über dem erwarteten Bereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabe','["pressure_control_solenoid_g", "wiring_harness"]','[{"id": "short_to_battery", "p": "high", "en": "Control wire shorted to B+", "de": "Steuerleitung mit B+ kurzgeschlossen"}, {"id": "coil_open", "p": "medium", "en": "Open solenoid coil", "de": "Offene Solenoidspule"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2816','P','Pressure Control Solenoid H','Druckregel-Solenoid H','A general fault in pressure control solenoid H. Detected via electrical resistance, response to commanded duty cycle, or downstream pressure measurement.','Allgemeiner Fehler im Druckregel-Solenoid H. Erkannt über elektrischen Widerstand, Reaktion auf Soll-Tastgrad oder nachgelagerte Druckmessung.','["pressure_control_solenoid_h", "valve_body"]','[{"id": "solenoid_aged", "p": "high", "en": "Aged solenoid coil resistance drift", "de": "Spulenwiderstand des gealterten Solenoids driftet"}, {"id": "valve_body_wear", "p": "medium", "en": "Worn valve body bore around the solenoid", "de": "Verschlissene Ventilk\u00f6rperbohrung am Solenoid"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2817','P','Pressure Control Solenoid H Performance/Stuck Off','Druckregel-Solenoid H Leistung/festsitzend aus','Pressure control solenoid H is commanded on but does not produce the expected pressure. Spool stuck closed or hydraulic feed restricted.','Das Druckregel-Solenoid H wird angesteuert, liefert aber nicht den erwarteten Druck. Schieber geschlossen festsitzend oder Hydraulik-Zulauf eingeengt.','["pressure_control_solenoid_h", "valve_body"]','[{"id": "spool_stuck_closed", "p": "high", "en": "Solenoid spool stuck in closed position", "de": "Solenoid-Schieber in Geschlossen-Position festsitzend"}, {"id": "feed_restricted", "p": "medium", "en": "Hydraulic feed restricted by debris", "de": "Hydraulik-Zulauf durch Schmutz eingeengt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2818','P','Pressure Control Solenoid H Stuck On','Druckregel-Solenoid H dauerhaft an','Pressure control solenoid H stays in the activated state when commanded off. Affected hydraulic circuit stays pressurised.','Das Druckregel-Solenoid H bleibt im aktivierten Zustand, auch wenn die Anforderung zurückgenommen wird. Der zugehörige Hydraulikkreis bleibt unter Druck.','["pressure_control_solenoid_h", "valve_body"]','[{"id": "spool_stuck_open", "p": "high", "en": "Solenoid spool stuck in open position", "de": "Solenoid-Schieber in Offen-Position festsitzend"}, {"id": "driver_stuck_on", "p": "medium", "en": "TCM output driver stuck on", "de": "TCM-Endstufe bleibt durchgeschaltet"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
