INSERT OR IGNORE INTO dtc_codes VALUES('P2854','P','Clutch B Pressure Discharge Performance','Kupplung B Druckabbau-Verhalten','Clutch B hydraulic pressure does not bleed off as expected when commanded to release. Excessive residual pressure delays disengagement.','Der Hydraulikdruck der Kupplung B baut sich beim Lösen nicht wie erwartet ab. Übermäßiger Restdruck verzögert das Auskuppeln.','["clutch_b", "clutch_actuator_b", "transmission_fluid"]','[{"id": "actuator_seal_leak", "p": "high", "en": "Clutch actuator seal leaks", "de": "Dichtung des Kupplungsaktuators undicht"}, {"id": "fluid_aerated", "p": "medium", "en": "Aerated transmission fluid", "de": "Mit Luft angereichertes Getriebe\u00f6l"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 2800], "estimated_hours": [3, 10]}',1);
