INSERT OR IGNORE INTO dtc_codes VALUES('P2A22','P','Alternative Fuel Tank Shutoff Valve B Control Circuit/Open','Alternativkraftstoff-Tank-Absperrventil B Steuerkreis offen','The control circuit of alternative fuel tank shutoff valve B reports a control circuit/open condition. Tank isolation cannot be commanded as expected on multi-tank CNG/LPG systems.','Der Steuerstromkreis des Alternativkraftstoff-Tank-Absperrventils B meldet einen Zustand "Steuerkreis offen". Die Tank-Absperrung kann auf Mehrtank-CNG/LPG-Systemen nicht wie erwartet angesteuert werden.','["alt_fuel_tank_shutoff_valve_b", "wiring_harness", "afcm"]','[{"id": "wire_open", "p": "high", "en": "Open in valve control wire", "de": "Unterbrechung in der Ventil-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open valve coil", "de": "Offene Ventilspule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
