INSERT OR IGNORE INTO dtc_codes VALUES('P2A4A','P','Alternative Fuel Tank C Pressure Sensor Circuit Intermittent/Erratic','Alternativkraftstoff-Tank C Drucksensor Stromkreis sporadisch/unsauber','The pressure sensor signal of alternative fuel tank C drops out or jumps intermittently. Loose connector or noisy ground.','Das Drucksensor-Signal des Alternativkraftstoff-Tanks C fällt sporadisch aus oder springt. Lockerer Stecker oder verrauschte Masse.','["alt_fuel_tank_c_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A4B','P','Alternative Fuel Temperature Sensor Circuit','Alternativkraftstoff-Temperatursensor Stromkreis','The AFCM detects a generic fault on the alternative fuel temperature sensor. Fuel viscosity and density compensation cannot be applied reliably.','Das AFCM erkennt einen allgemeinen Fehler am Alternativkraftstoff-Temperatursensor. Die Kompensation für Kraftstoff-Viskosität und -Dichte kann nicht zuverlässig angewendet werden.','["alt_fuel_temperature_sensor", "wiring_harness", "afcm"]','[{"id": "sensor_failed", "p": "high", "en": "Temperature sensor failed", "de": "Temperatursensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A4C','P','Alternative Fuel Temperature Sensor Range/Performance','Alternativkraftstoff-Temperatursensor Bereich/Leistung','The alternative fuel temperature signal does not match plausibility checks against ambient and fuel-rail temperatures. Sensor drift.','Das Alternativkraftstoff-Temperatursignal stimmt nicht mit Plausibilitätsprüfungen gegen Umgebungs- und Verteilerleisten-Temperatur überein. Sensordrift.','["alt_fuel_temperature_sensor", "wiring_harness", "afcm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced from fluid path", "de": "Sensorbefestigung vom Medien-Pfad versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A4D','P','Alternative Fuel Temperature Sensor Circuit Low','Alternativkraftstoff-Temperatursensor Stromkreis niedrig','Voltage on the alternative fuel temperature sensor signal line is below the expected window. Wire shorted to ground or sensor short.','Die Spannung auf der Signalleitung des Alternativkraftstoff-Temperatursensors liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Sensor-Kurzschluss.','["alt_fuel_temperature_sensor", "wiring_harness", "afcm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A4E','P','Alternative Fuel Temperature Sensor Circuit High','Alternativkraftstoff-Temperatursensor Stromkreis hoch','Voltage on the alternative fuel temperature sensor signal line is above the expected window. Wire shorted to B+ or sensor open.','Die Spannung auf der Signalleitung des Alternativkraftstoff-Temperatursensors liegt über dem erwarteten Bereich. Leitung mit B+ kurzgeschlossen oder offener Sensor.','["alt_fuel_temperature_sensor", "wiring_harness", "afcm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open temperature sensor", "de": "Offener Temperatursensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
