INSERT OR IGNORE INTO dtc_codes VALUES('P2A7A','P','Alternative Fuel Hydraulic Pressure Sensor Circuit','Alternativkraftstoff-Hydraulik-Drucksensor Stromkreis','The ECM detects a generic fault on the alternative fuel hydraulic system pressure sensor circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen allgemeinen Fehler im Stromkreis des Alternativkraftstoff-Hydraulik- Drucksensors. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["alt_fuel_hyd_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "sensor_failed", "p": "high", "en": "Pressure sensor failed", "de": "Drucksensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A7B','P','Alternative Fuel Hydraulic Pressure Sensor Range/Performance','Alternativkraftstoff-Hydraulik-Drucksensor Bereich/Leistung','The alternative fuel hydraulic system pressure signal does not match plausibility checks. Sensor drift or installation offset.','Das Drucksignal des Alternativkraftstoff-Hydraulik- Sensors stimmt nicht mit Plausibilitätsprüfungen überein. Sensordrift oder Einbauversatz.','["alt_fuel_hyd_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor zero drifted", "de": "Sensor-Nullpunkt driftet"}, {"id": "mounting_loose", "p": "medium", "en": "Sensor mounting loose - bias offset", "de": "Sensorbefestigung lose - Vorspannungs-Versatz"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A7C','P','Alternative Fuel Hydraulic Pressure Sensor Circuit Low','Alternativkraftstoff-Hydraulik-Drucksensor Stromkreis niedrig','Voltage on the alternative fuel hydraulic system pressure sensor signal line is below the expected window. Wire shorted to ground or sensor short.','Die Spannung auf der Signalleitung des Alternativkraftstoff-Hydraulik- Drucksensors liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Sensor-Kurzschluss.','["alt_fuel_hyd_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A7D','P','Alternative Fuel Hydraulic Pressure Sensor Circuit High','Alternativkraftstoff-Hydraulik-Drucksensor Stromkreis hoch','Voltage on the alternative fuel hydraulic system pressure sensor signal line is above the expected window. Wire shorted to B+ or sensor open.','Die Spannung auf der Signalleitung des Alternativkraftstoff-Hydraulik- Drucksensors liegt über dem erwarteten Bereich. Leitung mit B+ kurzgeschlossen oder offener Sensor.','["alt_fuel_hyd_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open pressure sensor", "de": "Offener Drucksensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A7E','P','Alternative Fuel Hydraulic Pressure Sensor Circuit Intermittent/Erratic','Alternativkraftstoff-Hydraulik-Drucksensor Stromkreis sporadisch/unsauber','The alternative fuel hydraulic system pressure sensor signal drops out or jumps intermittently. Loose connector or noisy ground.','Das Signal des Alternativkraftstoff-Hydraulik- Drucksensors fällt sporadisch aus oder springt. Lockerer Stecker oder verrauschte Masse.','["alt_fuel_hyd_pressure_sensor", "wiring_harness", "afcm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A7F','P','Alternative Fuel Pump A Compression Stroke Valve Control Circuit/Open','Alternativkraftstoff-Pumpe A Verdichtungshub-Ventil Steuerkreis offen','The control circuit of the compression stroke valve in alternative fuel pump A reports a control circuit/open condition. Pump compression stroke cannot be commanded as expected.','Der Steuerstromkreis des Verdichtungshub-Ventils der Alternativkraftstoff-Pumpe A meldet einen Zustand "Steuerkreis offen". Der Verdichtungshub der Pumpe kann nicht wie erwartet angesteuert werden.','["alt_fuel_pump_a_compression_stroke_valve", "wiring_harness", "afcm"]','[{"id": "wire_open", "p": "high", "en": "Open in valve control wire", "de": "Unterbrechung in der Ventil-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open valve coil", "de": "Offene Ventilspule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [2, 6]}',1);
