INSERT OR IGNORE INTO dtc_codes VALUES('P2A8B','P','Alternative Fuel Vaporizer A Performance','Alternativkraftstoff-Verdampfer A Verhalten','The AFCM detects that vaporizer A does not heat the alternative fuel from liquid to vapour within the calibrated time and temperature window. Liquid carry-over to the rail is possible.','Das AFCM erkennt, dass der Verdampfer A den Alternativkraftstoff nicht innerhalb des kalibrierten Zeit- und Temperaturfensters von flüssig auf gasförmig erwärmt. Flüssiger Übertrag in die Verteilerleiste möglich.','["alt_fuel_vaporizer_a", "engine_coolant_circuit", "afcm"]','[{"id": "coolant_flow_low", "p": "high", "en": "Coolant flow through vaporizer reduced", "de": "K\u00fchlmittel-Volumenstrom durch Verdampfer reduziert"}, {"id": "heat_exchanger_fouled", "p": "medium", "en": "Heat exchanger surface fouled", "de": "W\u00e4rmetauscher-Oberfl\u00e4che verschmutzt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [2, 6]}',1);
