INSERT OR IGNORE INTO dtc_codes VALUES('P2A8E','P','Alternative Fuel Pump A Performance','Alternativkraftstoff-Pumpe A Verhalten','The AFCM detects that alternative fuel pump A does not produce the expected pressure or flow for the commanded duty. Pump aging, internal leakage, or supply restriction.','Das AFCM erkennt, dass die Alternativkraftstoff-Pumpe A bei der angeforderten Ansteuerung nicht den erwarteten Druck oder Volumenstrom liefert. Pumpenverschleiß, interne Leckage oder Zulaufeinengung.','["alt_fuel_pump_a", "alt_fuel_filter"]','[{"id": "pump_worn", "p": "high", "en": "Pump internal wear reduces output", "de": "Interner Pumpenverschlei\u00df reduziert F\u00f6rderleistung"}, {"id": "filter_clogged", "p": "medium", "en": "Fuel filter clogged", "de": "Kraftstofffilter verstopft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [2, 8]}',1);
