INSERT OR IGNORE INTO dtc_codes VALUES('P2A91','P','Alternative Fuel Tank Select Valve A Control Circuit/Open','Alternativkraftstoff-Tankwahlventil A Steuerkreis offen','The control circuit of alternative fuel tank select valve A reports a control circuit/open condition. Tank selection on multi-tank CNG/LPG systems cannot be commanded reliably.','Der Steuerstromkreis des Alternativkraftstoff-Tankwahlventils A meldet einen Zustand "Steuerkreis offen". Die Tankauswahl auf Mehrtank-CNG/LPG-Systemen kann nicht zuverlässig angesteuert werden.','["alt_fuel_tank_select_valve_a", "wiring_harness", "afcm"]','[{"id": "wire_open", "p": "high", "en": "Open in valve control wire", "de": "Unterbrechung in der Ventil-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open valve coil", "de": "Offene Ventilspule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2A92','P','Alternative Fuel Tank Select Valve A Control Performance','Alternativkraftstoff-Tankwahlventil A Steuerung Verhalten','The control circuit of alternative fuel tank select valve A reports a control performance condition. Tank selection on multi-tank CNG/LPG systems cannot be commanded reliably.','Der Steuerstromkreis des Alternativkraftstoff-Tankwahlventils A meldet einen Zustand "Steuerung Verhalten". Die Tankauswahl auf Mehrtank-CNG/LPG-Systemen kann nicht zuverlässig angesteuert werden.','["alt_fuel_tank_select_valve_a", "wiring_harness", "afcm"]','[{"id": "valve_stuck_position", "p": "high", "en": "Valve stuck in last commanded position", "de": "Ventil in letzter Anforderung festsitzend"}, {"id": "coil_weak", "p": "medium", "en": "Coil force degraded", "de": "Spulenkraft nachgelassen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
