INSERT OR IGNORE INTO dtc_codes VALUES('P2AB9','P','Wastegate Position Sensor A Circuit High','Wastegate-Positionssensor A Stromkreis hoch','Voltage on the wastegate position sensor A signal line is above the expected window. Wire shorted to B+ or sensor open.','Die Spannung auf der Signalleitung des Wastegate-Positionssensors A liegt über dem erwarteten Bereich. Leitung mit B+ kurzgeschlossen oder offener Sensor.','["wastegate_position_sensor_a", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open position sensor", "de": "Offener Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2ABA','P','Wastegate Position Sensor B Circuit','Wastegate-Positionssensor B Stromkreis','The ECM detects a generic fault on the wastegate position sensor B circuit. Boost actuator position cannot be verified reliably.','Das Motorsteuergerät erkennt einen allgemeinen Fehler im Stromkreis des Wastegate-Positionssensors B. Die Position des Ladedruck-Aktuators kann nicht zuverlässig geprüft werden.','["wastegate_position_sensor_b", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2ABB','P','Wastegate Position Sensor B Circuit Low','Wastegate-Positionssensor B Stromkreis niedrig','Voltage on the wastegate position sensor B signal line is below the expected window. Wire shorted to ground or sensor short.','Die Spannung auf der Signalleitung des Wastegate-Positionssensors B liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Sensor-Kurzschluss.','["wastegate_position_sensor_b", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
