INSERT OR IGNORE INTO dtc_codes VALUES('P2ABD','P','Turbocharger/Supercharger Wastegate Actuator A Driver Current/Temperature Too High','Turbolader/Kompressor Wastegate-Aktuator A Endstufe Strom/Temperatur zu hoch','The output driver for the wastegate actuator A reports current or junction temperature above its protection threshold. Stalled actuator or short to ground.','Die Endstufe des Wastegate-Aktuators A meldet Strom oder Sperrschicht-Temperatur oberhalb der Schutzschwelle. Festsitzender Aktuator oder Kurzschluss nach Masse.','["wastegate_actuator_a", "ecm"]','[{"id": "actuator_jammed", "p": "high", "en": "Wastegate actuator mechanically jammed", "de": "Wastegate-Aktuator mechanisch verklemmt"}, {"id": "short_to_ground", "p": "medium", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2200], "estimated_hours": [2, 7]}',1);
