INSERT OR IGNORE INTO dtc_codes VALUES('P2ABF','P','Intake Air O2 Sensor Reference Voltage Circuit/Open Bank 1','Ansaugluft-Lambdasonde Referenzspannungs-Stromkreis offen Bank 1','The reference voltage supplied to the intake air oxygen sensor on bank 1 reports a circuit fault/open condition. Lambda measurement on the intake side is unreliable.','Die Referenzspannung der Ansaugluft-Lambdasonde auf Bank 1 meldet einen Zustand "Referenzspannungs-Stromkreis offen". Die Lambda-Messung auf der Ansaugseite ist unzuverlässig.','["intake_air_o2_sensor_b1", "wiring_harness", "ecm"]','[{"id": "wire_open", "p": "high", "en": "Open in reference voltage wire", "de": "Unterbrechung in der Referenzspannungs-Leitung"}, {"id": "sensor_failed", "p": "medium", "en": "Intake air O2 sensor failed", "de": "Ansaugluft-Lambdasonde defekt"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
