INSERT OR IGNORE INTO dtc_codes VALUES('P2ADF','P','Intake Air System Leak Bank 2','Ansaugluftsystem Leck Bank 2','The ECM detects a leak in the intake air system on bank 2. Air entering downstream of the MAF sensor causes lean fuel trim and unmetered air ingress.','Das Motorsteuergerät erkennt ein Leck im Ansaugluftsystem auf Bank 2. Luft, die nach dem Luftmassenmesser eindringt, führt zu magerem Kraftstofftrimm und unbemessenem Lufteintritt.','["intake_manifold_b2", "intake_hoses_b2", "intake_gaskets_b2"]','[{"id": "intake_hose_split", "p": "high", "en": "Cracked intake hose between MAF and throttle", "de": "Gerissener Ansaugschlauch zwischen Luftmassenmesser und Drosselklappe"}, {"id": "manifold_gasket_leak", "p": "medium", "en": "Intake manifold gasket leaking", "de": "Saugrohrdichtung undicht"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2AE0','P','Intake Air O2 Sensor Pumping Current Trim Circuit Open Bank 1','Ansaugluft-Lambdasonde Pumpstrom-Trim Stromkreis offen Bank 1','The trim adjustment for the pumping current of the intake air oxygen sensor on bank 1 reports a circuit open condition. Wide-band lambda regulation on the intake side is impaired.','Die Trim-Anpassung für den Pumpstrom der Ansaugluft-Lambdasonde auf Bank 1 meldet einen Zustand "Stromkreis offen". Die Breitband-Lambda-Regelung auf der Ansaugseite ist beeinträchtigt.','["intake_air_o2_sensor_b1", "wiring_harness", "ecm"]','[{"id": "wire_open", "p": "high", "en": "Open in pump current wire", "de": "Unterbrechung in der Pumpstrom-Leitung"}, {"id": "sensor_internal_open", "p": "medium", "en": "Internal open in pump cell", "de": "Interne Unterbrechung in der Pumpzelle"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2AE1','P','Intake Air O2 Sensor Pumping Current Trim Circuit Low Bank 1','Ansaugluft-Lambdasonde Pumpstrom-Trim Stromkreis niedrig Bank 1','The trim adjustment for the pumping current of the intake air oxygen sensor on bank 1 reports a circuit low condition. Wide-band lambda regulation on the intake side is impaired.','Die Trim-Anpassung für den Pumpstrom der Ansaugluft-Lambdasonde auf Bank 1 meldet einen Zustand "Stromkreis niedrig". Die Breitband-Lambda-Regelung auf der Ansaugseite ist beeinträchtigt.','["intake_air_o2_sensor_b1", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Pump current wire shorted to ground", "de": "Pumpstrom-Leitung mit Masse kurzgeschlossen"}, {"id": "pump_cell_short", "p": "medium", "en": "Internal short in pump cell", "de": "Interner Kurzschluss in der Pumpzelle"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
