INSERT OR IGNORE INTO dtc_codes VALUES('P2AFB','P','Starter Relay D Stuck Off','Starterrelais D dauerhaft aus','Starter relay D reports a stuck off condition. Engine cranking can be inhibited or commanded unintentionally.','Das Starterrelais D meldet einen Zustand "dauerhaft aus". Der Motorstart kann unterbunden oder unbeabsichtigt angesteuert werden.','["starter_relay_d", "wiring_harness", "ecm"]','[{"id": "contact_oxidised", "p": "high", "en": "Relay contacts oxidised - high resistance", "de": "Relaiskontakte oxidiert - hoher Widerstand"}, {"id": "coil_burned", "p": "medium", "en": "Relay coil burned out", "de": "Relaisspule durchgebrannt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2AFC','P','Engine Coolant Temperature Sensor 4 Circuit','Motorkühlmitteltemperatur-Sensor 4 Stromkreis','The ECM detects a generic fault on the engine coolant temperature 4 sensor circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen allgemeinen Fehler im Stromkreis des Motorkühlmitteltemperatur-4--Sensors. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_4", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2AFD','P','Engine Coolant Temperature Sensor 4 Range/Performance','Motorkühlmitteltemperatur-Sensor 4 Bereich/Leistung','The engine coolant temperature 4 signal does not match plausibility checks against related signals. Sensor drift.','Das Motorkühlmitteltemperatur-4--Signal stimmt nicht mit Plausibilitätsprüfungen gegen verwandte Signale überein. Sensordrift.','["engine_coolant_temperature_sensor_4", "wiring_harness", "ecm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced from reference path", "de": "Sensorbefestigung vom Referenz-Pfad versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2AFE','P','Engine Coolant Temperature Sensor 4 Circuit Low','Motorkühlmitteltemperatur-Sensor 4 Stromkreis niedrig','Voltage on the engine coolant temperature 4 sensor signal line is below the expected window. Wire shorted to ground or sensor short.','Die Spannung auf der Signalleitung des Motorkühlmitteltemperatur-4--Sensors liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Sensor-Kurzschluss.','["engine_coolant_temperature_sensor_4", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
