INSERT OR IGNORE INTO dtc_codes VALUES('P2B57','P','Low Engine Oil Pressure - Camshaft Control Disabled','Niedriger Motoröldruck - Nockenwellen-Steuerung deaktiviert','Engine oil pressure has fallen below the threshold required for hydraulic camshaft phasing. The ECM disables variable cam control to protect the actuator and lifters.','Der Motoröldruck ist unter die Schwelle gefallen, die für die hydraulische Nockenwellen-Phasenverstellung erforderlich ist. Das Steuergerät deaktiviert die variable Nockenwellen-Steuerung, um Aktuator und Hydrostössel zu schützen.','["engine_oil_pressure_sensor", "engine_oil_pump", "vvt_actuator"]','[{"id": "oil_level_low", "p": "high", "en": "Engine oil level low", "de": "Motor\u00f6lstand zu niedrig"}, {"id": "oil_pump_worn", "p": "medium", "en": "Oil pump worn or pressure relief stuck open", "de": "\u00d6lpumpe verschlissen oder Druckbegrenzungsventil offen festsitzend"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 1500], "estimated_hours": [0.5, 6]}',1);
