INSERT OR IGNORE INTO dtc_codes VALUES('P2B7B','P','EVAP System Pressure Sensor/Switch C Circuit Range/Performance','Tankentlüftungs-Drucksensor/Schalter C Stromkreis Bereich/Leistung','The EVAP pressure sensor/switch C reports a circuit range/performance condition. Tank pressure plausibility for leak detection on this branch is impaired.','Der Tankentlüftungs-Drucksensor/Schalter C meldet einen Zustand "Stromkreis Bereich/Leistung". Die Tankdruck-Plausibilität für die Leckerkennung in diesem Zweig ist beeinträchtigt.','["evap_pressure_sensor_c", "wiring_harness", "ecm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor zero drifted", "de": "Sensor-Nullpunkt driftet"}, {"id": "port_blocked", "p": "medium", "en": "Sensor port restricted", "de": "Sensoranschluss eingeengt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B7C','P','EVAP System Pressure Sensor/Switch C Circuit Low','Tankentlüftungs-Drucksensor/Schalter C Stromkreis niedrig','The EVAP pressure sensor/switch C reports a circuit low condition. Tank pressure plausibility for leak detection on this branch is impaired.','Der Tankentlüftungs-Drucksensor/Schalter C meldet einen Zustand "Stromkreis niedrig". Die Tankdruck-Plausibilität für die Leckerkennung in diesem Zweig ist beeinträchtigt.','["evap_pressure_sensor_c", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B7D','P','EVAP System Pressure Sensor/Switch C Circuit High','Tankentlüftungs-Drucksensor/Schalter C Stromkreis hoch','The EVAP pressure sensor/switch C reports a circuit high condition. Tank pressure plausibility for leak detection on this branch is impaired.','Der Tankentlüftungs-Drucksensor/Schalter C meldet einen Zustand "Stromkreis hoch". Die Tankdruck-Plausibilität für die Leckerkennung in diesem Zweig ist beeinträchtigt.','["evap_pressure_sensor_c", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open pressure sensor", "de": "Offener Drucksensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B7E','P','EVAP System Pressure Sensor/Switch C Circuit Intermittent','Tankentlüftungs-Drucksensor/Schalter C Stromkreis sporadisch','The EVAP pressure sensor/switch C reports a circuit intermittent condition. Tank pressure plausibility for leak detection on this branch is impaired.','Der Tankentlüftungs-Drucksensor/Schalter C meldet einen Zustand "Stromkreis sporadisch". Die Tankdruck-Plausibilität für die Leckerkennung in diesem Zweig ist beeinträchtigt.','["evap_pressure_sensor_c", "wiring_harness", "ecm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B7F','P','Turbocharger/Supercharger Boost Control Module A Calibration Not Learned/Programmed','Turbolader/Kompressor Ladedruck-Steuermodul A Kalibrierung nicht angelernt/programmiert','The boost control module A reports that its calibration data is not present or not learned. Boost regulation falls back to default values until programming or adaptation completes.','Das Ladedruck-Steuermodul A meldet, dass seine Kalibrierdaten fehlen oder nicht angelernt sind. Bis zum Abschluss der Programmierung oder Adaption greift die Ladedruckregelung auf Standardwerte zurück.','["boost_control_module_a", "ecm"]','[{"id": "module_replaced", "p": "high", "en": "Module replaced without programming", "de": "Modul ohne Programmierung ersetzt"}, {"id": "memory_corrupted", "p": "medium", "en": "Calibration memory corrupted after voltage drop", "de": "Kalibrierspeicher nach Spannungseinbruch besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B80','P','Turbocharger/Supercharger Boost Control Module B Calibration Not Learned/Programmed','Turbolader/Kompressor Ladedruck-Steuermodul B Kalibrierung nicht angelernt/programmiert','The boost control module B reports that its calibration data is not present or not learned. Boost regulation falls back to default values until programming or adaptation completes.','Das Ladedruck-Steuermodul B meldet, dass seine Kalibrierdaten fehlen oder nicht angelernt sind. Bis zum Abschluss der Programmierung oder Adaption greift die Ladedruckregelung auf Standardwerte zurück.','["boost_control_module_b", "ecm"]','[{"id": "module_replaced", "p": "high", "en": "Module replaced without programming", "de": "Modul ohne Programmierung ersetzt"}, {"id": "memory_corrupted", "p": "medium", "en": "Calibration memory corrupted after voltage drop", "de": "Kalibrierspeicher nach Spannungseinbruch besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B81','P','Wastegate Position Sensor A Circuit Performance','Wastegate-Positionssensor A Stromkreis Verhalten','The wastegate position sensor A signal does not correlate with the commanded actuator position within tolerance. Sensor offset, mechanical wear, or signal integrity degraded.','Das Signal des Wastegate-Positionssensors A korreliert nicht innerhalb der Toleranz mit der angeforderten Aktuatorposition. Sensorversatz, mechanischer Verschleiß oder verschlechterte Signalqualität.','["wastegate_position_sensor_a", "wastegate_actuator", "ecm"]','[{"id": "sensor_offset", "p": "high", "en": "Sensor mechanically offset from actuator", "de": "Sensor mechanisch vom Aktuator versetzt"}, {"id": "linkage_wear", "p": "medium", "en": "Linkage between sensor and wastegate worn", "de": "Gest\u00e4nge zwischen Sensor und Wastegate verschlissen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B82','P','Wastegate Position Sensor B Circuit Performance','Wastegate-Positionssensor B Stromkreis Verhalten','The wastegate position sensor B signal does not correlate with the commanded actuator position within tolerance. Sensor offset, mechanical wear, or signal integrity degraded.','Das Signal des Wastegate-Positionssensors B korreliert nicht innerhalb der Toleranz mit der angeforderten Aktuatorposition. Sensorversatz, mechanischer Verschleiß oder verschlechterte Signalqualität.','["wastegate_position_sensor_b", "wastegate_actuator", "ecm"]','[{"id": "sensor_offset", "p": "high", "en": "Sensor mechanically offset from actuator", "de": "Sensor mechanisch vom Aktuator versetzt"}, {"id": "linkage_wear", "p": "medium", "en": "Linkage between sensor and wastegate worn", "de": "Gest\u00e4nge zwischen Sensor und Wastegate verschlissen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B83','P','Charge Air Cooler Coolant Pump A Overspeed/Air In System','Ladeluftkühler-Kühlmittelpumpe A Überdrehzahl/Luft im System','The charge air cooler coolant pump A runs above the calibrated maximum speed without producing the expected flow. Indicates air pocket in the coolant loop.','Die charge air cooler coolant pump A läuft über der kalibrierten Maximaldrehzahl, ohne den erwarteten Volumenstrom zu liefern. Deutet auf Lufteinschluss im Kühlkreislauf hin.','["cac_coolant_pump_a", "cac_coolant_loop"]','[{"id": "air_pocket", "p": "high", "en": "Air pocket in coolant loop", "de": "Lufteinschluss im K\u00fchlkreislauf"}, {"id": "coolant_low", "p": "medium", "en": "Coolant level low", "de": "K\u00fchlmittelstand zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B84','P','Charge Air Cooler Coolant Pump A Underspeed','Ladeluftkühler-Kühlmittelpumpe A Unterdrehzahl','The charge air cooler coolant pump A runs below the calibrated minimum speed for the commanded duty. Mechanical resistance high or supply voltage low.','Die charge air cooler coolant pump A läuft unter der kalibrierten Mindestdrehzahl bei der angeforderten Ansteuerung. Mechanischer Widerstand zu hoch oder Versorgungsspannung zu niedrig.','["cac_coolant_pump_a", "cac_coolant_loop"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B85','P','Engine Coolant Pump Underspeed','Motorkühlmittelpumpe Unterdrehzahl','The engine coolant pump runs below the calibrated minimum speed for the commanded duty. Mechanical resistance high or supply voltage low.','Die engine coolant pump läuft unter der kalibrierten Mindestdrehzahl bei der angeforderten Ansteuerung. Mechanischer Widerstand zu hoch oder Versorgungsspannung zu niedrig.','["engine_coolant_pump", "ecm"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B86','P','Coolant Pump A Overspeed/Air in System','Kühlmittelpumpe A Überdrehzahl/Luft im System','The coolant pump A runs above the calibrated maximum speed without producing the expected flow. Indicates air pocket in the coolant loop.','Die coolant pump A läuft über der kalibrierten Maximaldrehzahl, ohne den erwarteten Volumenstrom zu liefern. Deutet auf Lufteinschluss im Kühlkreislauf hin.','["coolant_pump_a", "engine_coolant_loop"]','[{"id": "air_pocket", "p": "high", "en": "Air pocket in coolant loop", "de": "Lufteinschluss im K\u00fchlkreislauf"}, {"id": "coolant_low", "p": "medium", "en": "Coolant level low", "de": "K\u00fchlmittelstand zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B87','P','Coolant Pump A Underspeed','Kühlmittelpumpe A Unterdrehzahl','The coolant pump A runs below the calibrated minimum speed for the commanded duty. Mechanical resistance high or supply voltage low.','Die coolant pump A läuft unter der kalibrierten Mindestdrehzahl bei der angeforderten Ansteuerung. Mechanischer Widerstand zu hoch oder Versorgungsspannung zu niedrig.','["coolant_pump_a", "ecm"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B88','P','Intake Air O2 Sensor Circuit Bank 1','Ansaugluft-Lambdasonde Stromkreis Bank 1','The ECM detects a generic fault on the intake air oxygen sensor signal circuit on bank 1. A drifted or sluggish lambda sensor lets the mixture run lean or rich without correction — fuel economy and emissions suffer immediately.','Das Steuergerät erkennt einen allgemeinen Fehler im Signalstromkreis der Ansaugluft-Lambdasonde auf Bank 1. Eine driftende oder träge Lambdasonde lässt das Gemisch unkorrigiert mager oder fett laufen — Verbrauch und Abgaswerte leiden sofort.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Intake air O2 sensor failed", "de": "Ansaugluft-Lambdasonde defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B89','P','Intake Air O2 Sensor Circuit Low Voltage Bank 1','Ansaugluft-Lambdasonde Stromkreis niedrige Spannung Bank 1','Voltage on the intake air oxygen sensor signal line on bank 1 is below the expected window. A drifted or sluggish lambda sensor lets the mixture run lean or rich without correction — fuel economy and emissions suffer immediately.','Die Spannung auf der Signalleitung der Ansaugluft-Lambdasonde auf Bank 1 liegt unter dem erwarteten Bereich. Eine driftende oder träge Lambdasonde lässt das Gemisch unkorrigiert mager oder fett laufen — Verbrauch und Abgaswerte leiden sofort.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8A','P','Intake Air O2 Sensor Circuit High Voltage Bank 1','Ansaugluft-Lambdasonde Stromkreis hohe Spannung Bank 1','Voltage on the intake air oxygen sensor signal line on bank 1 is above the expected window. A drifted or sluggish lambda sensor lets the mixture run lean or rich without correction — fuel economy and emissions suffer immediately.','Die Spannung auf der Signalleitung der Ansaugluft-Lambdasonde auf Bank 1 liegt über dem erwarteten Bereich. Eine driftende oder träge Lambdasonde lässt das Gemisch unkorrigiert mager oder fett laufen — Verbrauch und Abgaswerte leiden sofort.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open intake air O2 sensor", "de": "Offene Ansaugluft-Lambdasonde"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8B','P','Intake Air O2 Sensor Heater Control Circuit/Open Bank 1','Ansaugluft-Lambdasonde Heizungs-Steuerkreis offen Bank 1','The control circuit for the intake air O2 sensor heater on bank 1 is open. Sensor cannot reach operating temperature.','Der Steuerstromkreis der Ansaugluft-Lambdasonden-Heizung auf Bank 1 ist unterbrochen. Die Sonde kann die Betriebstemperatur nicht erreichen.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "wire_open", "p": "high", "en": "Open in heater control wire", "de": "Unterbrechung in der Heizungs-Steuerleitung"}, {"id": "heater_open", "p": "medium", "en": "Open heater element", "de": "Offenes Heizelement"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8C','P','Intake Air O2 Sensor Heater Control Circuit Range/Performance Bank 1','Ansaugluft-Lambdasonde Heizungs-Steuerkreis Bereich/Leistung Bank 1','The heater current of the intake air O2 sensor on bank 1 does not match the commanded value within tolerance.','Der Heizstrom der Ansaugluft-Lambdasonde auf Bank 1 stimmt nicht innerhalb der Toleranz mit dem Sollwert überein.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "heater_aged", "p": "high", "en": "Heater element resistance drifted", "de": "Widerstand des Heizelements driftet"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact in connector", "de": "Hochohmiger Kontakt im Stecker"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8D','P','Intake Air O2 Sensor Heater Control Circuit Low Bank 1','Ansaugluft-Lambdasonde Heizungs-Steuerkreis niedrig Bank 1','Voltage on the intake air O2 sensor heater control line on bank 1 is below the expected window. Wire shorted to ground or heater element shorted.','Die Spannung auf der Heizungs-Steuerleitung der Ansaugluft-Lambdasonde auf Bank 1 liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Heizelement kurzgeschlossen.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Heater wire shorted to ground", "de": "Heizungs-Leitung mit Masse kurzgeschlossen"}, {"id": "heater_element_short", "p": "medium", "en": "Heater element shorted", "de": "Heizelement kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8E','P','Intake Air O2 Sensor Heater Control Circuit High Bank 1','Ansaugluft-Lambdasonde Heizungs-Steuerkreis hoch Bank 1','Voltage on the intake air O2 sensor heater control line on bank 1 is above the expected window. Wire shorted to B+ or heater element open.','Die Spannung auf der Heizungs-Steuerleitung der Ansaugluft-Lambdasonde auf Bank 1 liegt über dem erwarteten Bereich. Leitung mit B+ kurzgeschlossen oder Heizelement offen.','["intake_air_o2_sensor_b1", "intake_air_o2_sensor_heater_b1", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Heater wire shorted to B+", "de": "Heizungs-Leitung mit B+ kurzgeschlossen"}, {"id": "heater_open", "p": "medium", "en": "Open heater element", "de": "Offenes Heizelement"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B8F','P','Turbocharger/Supercharger B Temperature Sensor Circuit','Turbolader/Kompressor B Temperatursensor Stromkreis','The ECM detects a circuit fault on the turbocharger/supercharger b temperature sensor. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Turbolader/Kompressor B Temperatursensor. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["turbocharger_b_temperature_sensor", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B90','P','Turbocharger/Supercharger B Temperature Sensor Circuit Low','Turbolader/Kompressor B Temperatursensor Stromkreis niedrig','The ECM detects a circuit low fault on the turbocharger/supercharger b temperature sensor. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis niedrig" am Turbolader/Kompressor B Temperatursensor. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["turbocharger_b_temperature_sensor", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B91','P','Turbocharger/Supercharger B Temperature Sensor Circuit High','Turbolader/Kompressor B Temperatursensor Stromkreis hoch','The ECM detects a circuit high fault on the turbocharger/supercharger b temperature sensor. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis hoch" am Turbolader/Kompressor B Temperatursensor. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["turbocharger_b_temperature_sensor", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open sensor", "de": "Offener Sensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B92','P','Turbocharger/Supercharger B Temperature Sensor Range/Performance','Turbolader/Kompressor B Temperatursensor Bereich/Leistung','The ECM detects a range/performance fault on the turbocharger/supercharger b temperature sensor. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Bereich/Leistung" am Turbolader/Kompressor B Temperatursensor. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["turbocharger_b_temperature_sensor", "wiring_harness", "ecm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced", "de": "Sensorbefestigung versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B93','P','Wastegate Position Sensor A Exceeded Learning Limit','Wastegate-Positionssensor A Lerngrenze überschritten','The required adaptation offset for the wastegate position sensor A exceeds the calibrated learning window. Sensor or mechanism out of nominal range.','Der für den Wastegate-Positionssensor A erforderliche Adaptionsversatz überschreitet das kalibrierte Lernfenster. Sensor oder Mechanik außerhalb des Nennbereichs.','["wastegate_position_sensor_a", "wastegate_actuator", "ecm"]','[{"id": "mechanical_drift", "p": "high", "en": "Mechanical wear shifted end-stops", "de": "Mechanischer Verschlei\u00df verschoben die Endanschl\u00e4ge"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor reference drifted", "de": "Sensor-Referenz driftet"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B94','P','Wastegate Position Sensor B Exceeded Learning Limit','Wastegate-Positionssensor B Lerngrenze überschritten','The required adaptation offset for the wastegate position sensor B exceeds the calibrated learning window. Sensor or mechanism out of nominal range.','Der für den Wastegate-Positionssensor B erforderliche Adaptionsversatz überschreitet das kalibrierte Lernfenster. Sensor oder Mechanik außerhalb des Nennbereichs.','["wastegate_position_sensor_b", "wastegate_actuator", "ecm"]','[{"id": "mechanical_drift", "p": "high", "en": "Mechanical wear shifted end-stops", "de": "Mechanischer Verschlei\u00df verschoben die Endanschl\u00e4ge"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor reference drifted", "de": "Sensor-Referenz driftet"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B95','P','Cold Start Injection Pulse Performance','Kaltstart Einspritzimpuls Verhalten','During cold start, the ECM detects that the overall injection pulse performance does not match the calibrated cold-start strategy. Combustion stability is reduced during warm-up.','Beim Kaltstart erkennt das Steuergerät, dass das Gesamt-Einspritzimpuls-Verhalten nicht zur kalibrierten Kaltstart-Strategie passt. Die Verbrennungsstabilität ist im Warmlauf reduziert.','["fuel_injectors", "ecm", "fuel_rail"]','[{"id": "injectors_aged", "p": "high", "en": "Injectors aged - flow drift across cylinders", "de": "Injektoren gealtert - Volumenstrom-Drift zwischen Zylindern"}, {"id": "fuel_pressure_drift", "p": "medium", "en": "Fuel rail pressure drifts during pulse", "de": "Verteilerdruck driftet w\u00e4hrend des Einspritzimpulses"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B96','P','Injection Pulse Performance','Einspritzimpuls Verhalten','The ECM detects that the overall injection pulse performance does not match the calibrated values. Combustion result deviates from expected fuelling behaviour.','Das Steuergerät erkennt, dass das Gesamt-Einspritzimpuls-Verhalten nicht zu den kalibrierten Werten passt. Das Verbrennungsergebnis weicht vom erwarteten Einspritzverhalten ab.','["fuel_injectors", "ecm", "fuel_rail"]','[{"id": "injectors_aged", "p": "high", "en": "Injectors aged - flow drift across cylinders", "de": "Injektoren gealtert - Volumenstrom-Drift zwischen Zylindern"}, {"id": "fuel_pressure_drift", "p": "medium", "en": "Fuel rail pressure drifts during pulse", "de": "Verteilerdruck driftet w\u00e4hrend des Einspritzimpulses"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B97','P','Exhaust Pressure Control Valve A Position Exceeded Learning Limit','Abgasdruck-Steuerventil A Position Lerngrenze überschritten','The required adaptation offset for the exhaust pressure control valve A position exceeds the calibrated learning window. Mechanical wear or sensor drift beyond compensation.','Der für die Position des Abgasdruck-Steuerventils A erforderliche Adaptionsversatz überschreitet das kalibrierte Lernfenster. Mechanischer Verschleiß oder Sensordrift jenseits der Kompensation.','["exhaust_pressure_control_valve_a", "exhaust_pressure_valve_position_sensor"]','[{"id": "mechanism_worn", "p": "high", "en": "Valve mechanism worn at end-stops", "de": "Ventilmechanik an den Endanschl\u00e4gen verschlissen"}, {"id": "sensor_drift", "p": "medium", "en": "Position sensor reference drifted", "de": "Positionssensor-Referenz driftet"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B98','P','Exhaust Pressure Control Valve A Supply Low','Abgasdruck-Steuerventil A Versorgung niedrig','The supply voltage to the exhaust pressure control valve A actuator is below the expected window. Fuse blown, supply wire shorted, or upstream regulator fault.','Die Versorgungsspannung zum Aktuator des Abgasdruck-Steuerventils A liegt unter dem erwarteten Bereich. Sicherung durchgebrannt, Versorgungsleitung kurzgeschlossen oder Reglerfehler stromaufwärts.','["exhaust_pressure_control_valve_a", "wiring_harness"]','[{"id": "fuse_blown", "p": "high", "en": "Supply fuse blown", "de": "Versorgungssicherung durchgebrannt"}, {"id": "supply_wire_short", "p": "medium", "en": "Supply wire shorted to ground", "de": "Versorgungsleitung mit Masse kurzgeschlossen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B99','P','Exhaust Pressure Control Valve A Driver Current/Temperature Too High','Abgasdruck-Steuerventil A Endstufe Strom/Temperatur zu hoch','The output driver for the exhaust pressure control valve A reports current or junction temperature above its protection threshold. Stalled actuator or short-circuit fault.','Die Endstufe des Abgasdruck-Steuerventils A meldet Strom oder Sperrschicht-Temperatur oberhalb der Schutzschwelle. Festsitzender Aktuator oder Kurzschluss.','["exhaust_pressure_control_valve_a", "ecm"]','[{"id": "actuator_jammed", "p": "high", "en": "Valve actuator mechanically jammed", "de": "Ventil-Aktuator mechanisch verklemmt"}, {"id": "short_to_ground", "p": "medium", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9A','P','Reductant Quality Sensor Circuit Intermittent/Erratic','Reduktionsmittel-Qualitätssensor Stromkreis sporadisch/unsauber','The reductant (DEF/AdBlue) quality sensor signal drops out or jumps intermittently. Loose connector, dilution noise, or ground reference offset.','Das Signal des Reduktionsmittel-Qualitätssensors (DEF/AdBlue) fällt sporadisch aus oder springt. Lockerer Stecker, Verdünnungsrauschen oder Versatz der Masse-Referenz.','["reductant_quality_sensor", "wiring_harness", "scr_module"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9B','P','Vehicle Conditions Incorrect for Particulate Matter Sensor Regeneration','Fahrzeugbedingungen ungeeignet für Partikelmasse-Sensor-Regeneration','The ECM detects that the vehicle is not operating in conditions suitable for the periodic PM sensor regeneration cycle. The sensor element cannot be cleaned and soot-mass measurement is paused.','Das Steuergerät erkennt, dass das Fahrzeug nicht in Bedingungen betrieben wird, die für den periodischen Regenerationszyklus des PM-Sensors geeignet sind. Das Sensorelement kann nicht gereinigt werden und die Russmasse-Messung pausiert.','["pm_sensor", "exhaust_system"]','[{"id": "short_trips", "p": "high", "en": "Driving cycle too short for regen conditions", "de": "Fahrzyklus zu kurz f\u00fcr Regenerations-Bedingungen"}, {"id": "low_load", "p": "medium", "en": "Sustained low-load operation", "de": "Anhaltender Niedriglast-Betrieb"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9C','P','Coolant Pump A Stuck/Stalled','Kühlmittelpumpe A festsitzend/blockiert','Coolant pump A reports a stuck/stalled condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe A meldet einen Zustand "festsitzend/blockiert". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_a", "wiring_harness", "ecm"]','[{"id": "impeller_jammed", "p": "high", "en": "Pump impeller jammed by debris", "de": "Pumpenrad durch Schmutz verklemmt"}, {"id": "motor_seized", "p": "medium", "en": "Motor seized", "de": "Motor festsitzend"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9D','P','Coolant Pump A Supply Voltage Circuit','Kühlmittelpumpe A Versorgungsspannungs-Stromkreis','Coolant pump A reports a supply voltage circuit condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe A meldet einen Zustand "Versorgungsspannungs-Stromkreis". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_a", "wiring_harness", "ecm"]','[{"id": "fuse_blown", "p": "high", "en": "Supply fuse blown", "de": "Versorgungssicherung durchgebrannt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9E','P','Coolant Pump A Control Module Overtemperature','Kühlmittelpumpe A Steuermodul Übertemperatur','Coolant pump A reports a control module overtemperature condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe A meldet einen Zustand "Steuermodul Übertemperatur". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_a", "wiring_harness", "ecm"]','[{"id": "ambient_high", "p": "high", "en": "Ambient or under-bonnet temperature too high", "de": "Umgebungs- oder Motorraumtemperatur zu hoch"}, {"id": "module_cooling_blocked", "p": "medium", "en": "Module cooling path blocked", "de": "Modul-K\u00fchlpfad blockiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2B9F','P','Coolant Pump B Underspeed','Kühlmittelpumpe B Unterdrehzahl','Coolant pump B reports a underspeed condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe B meldet einen Zustand "Unterdrehzahl". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_b", "wiring_harness", "ecm"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA0','P','Coolant Pump C Underspeed','Kühlmittelpumpe C Unterdrehzahl','Coolant pump C reports a underspeed condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe C meldet einen Zustand "Unterdrehzahl". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_c", "wiring_harness", "ecm"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA1','P','Coolant Pump D Underspeed','Kühlmittelpumpe D Unterdrehzahl','Coolant pump D reports a underspeed condition. Coolant circulation through the affected loop cannot be commanded reliably.','Die Kühlmittelpumpe D meldet einen Zustand "Unterdrehzahl". Die Kühlmittelzirkulation durch den betroffenen Kreislauf kann nicht zuverlässig angesteuert werden.','["coolant_pump_d", "wiring_harness", "ecm"]','[{"id": "load_high", "p": "high", "en": "Mechanical load increased (binding)", "de": "Mechanische Last erh\u00f6ht (klemmend)"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA2','P','Engine Coolant Pump Stuck/Stalled','Motorkühlmittelpumpe festsitzend/blockiert','The engine coolant pump is mechanically stuck or has stalled. Coolant circulation through the engine is severely reduced or absent.','Die Motorkühlmittelpumpe sitzt mechanisch fest oder ist blockiert. Die Kühlmittelzirkulation durch den Motor ist stark reduziert oder fehlt.','["engine_coolant_pump", "engine_coolant_loop"]','[{"id": "impeller_jammed", "p": "high", "en": "Pump impeller jammed by debris", "de": "Pumpenrad durch Schmutz verklemmt"}, {"id": "motor_seized", "p": "medium", "en": "Motor seized", "de": "Motor festsitzend"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA3','P','Starter/Generator Mechanical Performance','Starter/Generator Mechanische Leistung','The hybrid control module detects that the integrated starter/generator does not deliver the expected mechanical torque or speed for the commanded operation. Belt slippage, bearing wear, or coupling fault.','Das Hybrid-Steuergerät erkennt, dass der integrierte Starter/Generator nicht das erwartete mechanische Drehmoment oder die erwartete Drehzahl für die angeforderte Operation liefert. Riemenschlupf, Lagerverschleiß oder Kopplungsfehler.','["starter_generator", "drive_belt", "hybrid_control_module"]','[{"id": "belt_slipping", "p": "high", "en": "Drive belt slipping or worn", "de": "Antriebsriemen rutscht oder verschlissen"}, {"id": "bearing_worn", "p": "medium", "en": "Starter/generator bearing worn", "de": "Starter/Generator-Lager verschlissen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA4','P','Catalyst Feedgas Performance','Katalysator-Eingangsgas-Verhalten','The ECM detects that the exhaust gas composition reaching the catalyst (feedgas) deviates from the calibrated profile. Pre-cat O2 measurement and air-fuel control are inconsistent with engine operation.','Das Steuergerät erkennt, dass die Abgaszusammensetzung am Katalysator-Eingang (Feedgas) vom kalibrierten Profil abweicht. Vor-Kat-O2-Messung und Lambda-Regelung passen nicht zum Motorbetrieb.','["catalytic_converter", "o2_sensor_pre_cat", "ecm"]','[{"id": "fuel_trim_drift", "p": "high", "en": "Long-term fuel trim drifted out of nominal range", "de": "Langzeit-Kraftstofftrimm au\u00dferhalb des Nennbereichs"}, {"id": "exhaust_leak_pre_cat", "p": "medium", "en": "Exhaust leak upstream of catalyst", "de": "Abgasleck vor dem Katalysator"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA5','P','Particulate Filter Feedgas Performance','Partikelfilter-Eingangsgas-Verhalten','The ECM detects that the exhaust gas composition reaching the particulate filter (feedgas) deviates from the calibrated profile. Soot input rate cannot be modelled correctly, affecting regen scheduling.','Das Steuergerät erkennt, dass die Abgaszusammensetzung am Partikelfilter-Eingang (Feedgas) vom kalibrierten Profil abweicht. Die Russeintrags-Rate kann nicht korrekt modelliert werden, was die Regenerations-Planung beeinflusst.','["particulate_filter", "exhaust_gas_temp_sensor_pre_dpf"]','[{"id": "exhaust_leak_pre_dpf", "p": "high", "en": "Exhaust leak upstream of DPF", "de": "Abgasleck vor dem Partikelfilter"}, {"id": "egt_sensor_drift", "p": "medium", "en": "EGT sensor pre-DPF drift", "de": "Vor-DPF-Abgastemperatursensor driftet"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA6','P','NOx Exceedance - SCR NOx Catalyst Performance','NOx-Überschreitung - SCR-NOx-Katalysator Verhalten','NOx emissions are above the legal threshold and the ECU isolates the cause to the SCR NOx catalyst. Conversion efficiency is degraded — aged substrate, sulphur poisoning, or thermal damage.','Die NOx-Emissionen liegen über dem gesetzlichen Schwellenwert und das Steuergerät lokalisiert die Ursache am SCR-NOx-Katalysator. Die Umwandlungs-Effizienz ist verschlechtert - gealtertes Substrat, Schwefelvergiftung oder thermische Schädigung.','["scr_catalyst", "reductant_dosing_unit"]','[{"id": "catalyst_aged", "p": "high", "en": "SCR catalyst substrate aged or contaminated", "de": "SCR-Katalysator-Substrat gealtert oder verunreinigt"}, {"id": "thermal_damage", "p": "medium", "en": "Thermal damage from prior over-temperature event", "de": "Thermische Sch\u00e4digung durch fr\u00fchere \u00dcbertemperatur"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA7','P','NOx Exceedence - Empty Reagent Tank','NOx-Überschreitung - Reagenz-Tank leer','NOx emissions are above the legal threshold and the ECU isolates the cause to an empty reductant tank. SCR cannot dose AdBlue/DEF.','Die NOx-Emissionen liegen über dem gesetzlichen Schwellenwert und das Steuergerät lokalisiert die Ursache an einem leeren Reduktionsmitteltank. SCR kann kein AdBlue/DEF dosieren.','["reductant_tank", "reductant_level_sensor"]','[{"id": "tank_empty", "p": "high", "en": "DEF/AdBlue tank empty - refill required", "de": "DEF/AdBlue-Tank leer - Nachf\u00fcllung erforderlich"}, {"id": "level_sensor_failed", "p": "medium", "en": "Level sensor reads empty incorrectly", "de": "F\u00fcllstandsensor meldet f\u00e4lschlich leer"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA8','P','NOx Exceedence - Interruption of Reagent Dosing Activity','NOx-Überschreitung - Unterbrechung der Reagenz-Dosierung','NOx emissions are above the legal threshold and the ECU isolates the cause to interruption of reductant dosing. The injection valve, pump, or supply line is impaired.','Die NOx-Emissionen liegen über dem gesetzlichen Schwellenwert und das Steuergerät lokalisiert die Ursache in einer Unterbrechung der Reduktionsmittel-Dosierung. Einspritzventil, Pumpe oder Versorgungsleitung sind beeinträchtigt.','["reductant_injection_valve", "reductant_pump", "scr_module"]','[{"id": "injection_valve_clogged", "p": "high", "en": "Reductant injection valve clogged", "de": "Reduktionsmittel-Einspritzventil verstopft"}, {"id": "pump_failure", "p": "medium", "en": "Reductant pump output insufficient", "de": "Reduktionsmittel-Pumpenleistung unzureichend"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BA9','P','NOx Exceedence — Insufficient Reagent','NOx-Überschreitung — zu wenig Reagenz','The SCR system has detected that NOx emissions exceed the legal limit and the cause is traced to insufficient AdBlue/DEF dosing. Modern emission regulations require this fault to be reported separately so that operator-induced misuse (running an empt','Das SCR-System hat festgestellt, dass die NOx-Emissionen über dem gesetzlichen Grenzwert liegen, und führt das auf eine ungenügende AdBlue/DEF-Dosierung zurück. Moderne Abgasvorschriften verlangen die getrennte Meldung dieses Fehlers, damit Manipulat','["reductant_dosing_unit", "reductant_tank", "scr_catalyst"]','[{"id": "def_tank_low_or_empty", "p": "high", "en": "DEF tank repeatedly run empty", "de": "DEF-Tank wiederholt leer gefahren"}, {"id": "def_quality_poor", "p": "medium", "en": "Diluted or contaminated DEF", "de": "DEF verd\u00fcnnt oder verunreinigt"}, {"id": "dosing_pump_underperforming", "p": "medium", "en": "Dosing pump output below spec", "de": "Dosierpumpe f\u00f6rdert zu wenig"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 4.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAA','P','NOx Sensor Range/Performance (Bank 1, Sensor 1)','NOx-Sensor Bereich/Plausibilität (Bank 1, Sonde 1)','The upstream NOx sensor on bank 1 returns values that are not plausible for the current operating point. NOx sensors are slow to warm up, sensitive to soot and water, and are a frequent failure on diesel SCR systems.','Der NOx-Sensor vor dem Katalysator auf Bank 1 liefert für den aktuellen Betriebspunkt unplausible Werte. NOx-Sensoren benötigen lange zur Aufheizung, sind empfindlich gegen Ruß und Wasser und fallen an Diesel-SCR-Systemen häufig aus.','["nox_sensor_upstream", "nox_sensor_wiring"]','[{"id": "nox_sensor_failed", "p": "high", "en": "NOx sensor element failed", "de": "NOx-Sensorelement defekt"}, {"id": "nox_sensor_contaminated", "p": "medium", "en": "Sensor contaminated with soot or condensate", "de": "Sensor mit Ru\u00df oder Kondensat verunreinigt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [200, 800], "estimated_hours": [0.5, 2.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAB','P','NOx Exceedence — Reagent System Performance','NOx-Überschreitung — Reagenzsystem-Leistung','The SCR system has detected that NOx emissions exceed the legal limit and the cause is traced to a performance fault in the reagent dosing system — for example a slow dosing pump, a clogged injector, or a frozen line that is not yet caught by another','Das SCR-System hat festgestellt, dass die NOx-Emissionen über dem gesetzlichen Grenzwert liegen, und führt das auf einen Leistungsfehler im Dosiersystem zurück — etwa eine träge Dosierpumpe, einen verstopften Injektor oder eine vereiste Leitung, die ','["reductant_dosing_unit", "reductant_injector", "reductant_pump"]','[{"id": "dosing_injector_clogged", "p": "high", "en": "Reductant injector clogged with crystals", "de": "Reagenzinjektor mit Kristallen verstopft"}, {"id": "dosing_pump_underperforming", "p": "medium", "en": "Dosing pump output below spec", "de": "Dosierpumpe f\u00f6rdert zu wenig"}, {"id": "reductant_line_blocked", "p": "medium", "en": "Reagent supply line blocked", "de": "Reagenzleitung blockiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.0, 5.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAC','P','NOx Exceedence - Insufficient Reagent Quality','NOx-Ueberschreitung - unzureichende Reagenzqualitaet','The diesel exhaust aftertreatment system detects elevated NOx levels combined with abnormal reagent (AdBlue/DEF) consumption, indicating that the reagent quality is insufficient or contaminated. Many regions trigger driver inducement (limited restart','Das Dieselabgasnachbehandlungssystem erkennt erhoehte NOx-Werte zusammen mit auffaelligem Reagenzverbrauch (AdBlue/DEF). Daraus wird auf unzureichende oder verunreinigte Reagenzqualitaet geschlossen. In vielen Regionen wird ein Fahrer-Inducement (Sta','["scr_catalyst", "def_tank", "nox_sensor", "def_quality_sensor"]','[{"id": "wrong_fluid_in_def_tank", "p": "high", "en": "Non-DEF liquid in tank (water, diesel)", "de": "Falsche Fluessigkeit im Tank (Wasser, Diesel)"}, {"id": "degraded_def", "p": "medium", "en": "Aged or diluted DEF/AdBlue", "de": "Gealtertes oder verduenntes AdBlue"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAD','P','NOx Exceedence - Insufficient Reagent Consumption','NOx-Ueberschreitung - unzureichender Reagenzverbrauch','The aftertreatment system detects elevated NOx emissions while reagent (AdBlue/DEF) consumption is below the expected level. Causes include clogged dosing injector, incorrect dosing rate or tampering.','Das Abgasnachbehandlungssystem erkennt erhoehte NOx-Emissionen, waehrend der Reagenzverbrauch (AdBlue/DEF) unter dem erwarteten Wert liegt. Ursachen sind verstopfte Dosierventile, falsche Dosierraten oder Manipulation.','["def_dosing_valve", "scr_catalyst", "nox_sensor"]','[{"id": "dosing_valve_clogged", "p": "high", "en": "Clogged DEF dosing valve", "de": "Verstopftes AdBlue-Dosierventil"}, {"id": "dosing_calibration", "p": "medium", "en": "Incorrect dosing calibration", "de": "Falsche Dosierkalibrierung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAE','P','NOx Exceedence - EGR System','NOx-Ueberschreitung - AGR-System','NOx emissions are above the legal threshold and the ECU isolates the cause to the EGR system. EGR flow is too low or absent under operating conditions where NOx reduction is required.','Die NOx-Emissionen liegen ueber dem gesetzlichen Schwellenwert und die Motorsteuerung lokalisiert die Ursache im AGR-System. Der AGR-Massenstrom ist zu gering oder fehlt unter Betriebsbedingungen, in denen eine NOx-Reduktion erforderlich ist.','["egr_valve", "egr_cooler", "egr_diff_pressure_sensor"]','[{"id": "egr_valve_stuck_closed", "p": "high", "en": "EGR valve stuck closed", "de": "AGR-Ventil geschlossen festsitzend"}, {"id": "egr_passages_clogged", "p": "high", "en": "Carbon clogged EGR passages", "de": "Verkokte AGR-Kanaele"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [1.5, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BAF','P','NOx Sensor Heater Sense Circuit Range/Performance Bank 1 Sensor 1','NOx-Sensor-Heizung Signal-Stromkreis Bereich/Funktion Bank 1 Sonde 1','The heater sense feedback of NOx sensor 1 on bank 1 reports values that do not match expected operation. The sensor warm-up cycle does not behave as the diagnostic expects.','Die Heizungs-Rueckmeldung des NOx-Sensors 1 auf Bank 1 liefert Werte, die nicht zur erwarteten Funktion passen. Der Aufheizzyklus des Sensors verlaeuft nicht wie von der Diagnose erwartet.','["nox_sensor", "nox_heater_circuit"]','[{"id": "nox_sensor_aging", "p": "high", "en": "NOx sensor aging", "de": "Alterung des NOx-Sensors"}, {"id": "heater_circuit_resistance", "p": "medium", "en": "High resistance in heater circuit", "de": "Erhoehter Widerstand im Heizkreis"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB0','P','Alternative Fuel Consumption Too Low','Alternativkraftstoff-Verbrauch zu niedrig','The AFCM detects that alternative fuel consumption falls below the expected value for the active operating mode. Indicates injector clogging, leaks before injectors, or incorrect tank-fill correction.','Das AFCM erkennt, dass der Alternativkraftstoff-Verbrauch unter dem für den aktiven Betriebsmodus erwarteten Wert liegt. Deutet auf verstopfte Injektoren, Lecks vor den Injektoren oder falsche Tank-Füll-Korrektur hin.','["alt_fuel_injectors", "alt_fuel_tank", "afcm"]','[{"id": "injector_clogged", "p": "high", "en": "Alt fuel injectors partially clogged", "de": "Alternativkraftstoff-Injektoren teilweise verstopft"}, {"id": "tank_calibration_off", "p": "medium", "en": "Tank-fill calibration drifted", "de": "Tank-F\u00fcllkalibrierung driftet"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB1','P','Alternative Fuel Consumption Too High','Alternativkraftstoff-Verbrauch zu hoch','The AFCM detects that alternative fuel consumption exceeds the expected value for the active operating mode. Indicates injector leakage, fuel pressure too high, or unmetered fuel loss.','Das AFCM erkennt, dass der Alternativkraftstoff-Verbrauch über dem für den aktiven Betriebsmodus erwarteten Wert liegt. Deutet auf Injektor-Leckage, zu hohen Kraftstoffdruck oder unbemessenen Kraftstoffverlust hin.','["alt_fuel_injectors", "alt_fuel_rail", "alt_fuel_pressure_regulator"]','[{"id": "injector_leak", "p": "high", "en": "Alt fuel injector leaking", "de": "Alternativkraftstoff-Injektor undicht"}, {"id": "pressure_too_high", "p": "medium", "en": "Fuel rail pressure above target", "de": "Verteilerleisten-Druck \u00fcber Sollwert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB2','P','Alternative Fuel Tank Empty','Alternativkraftstoff-Tank leer','The AFCM detects that the alternative fuel tank is empty. Bi-fuel vehicles may switch to gasoline operation; mono-fuel vehicles cannot continue without refuel.','Das AFCM erkennt, dass der Alternativkraftstoff-Tank leer ist. Bi-Fuel-Fahrzeuge schalten ggf. auf Benzinbetrieb um; Mono-Fuel-Fahrzeuge können ohne Nachtanken nicht weiterfahren.','["alt_fuel_tank", "alt_fuel_level_sensor"]','[{"id": "tank_empty", "p": "high", "en": "Tank actually empty - refuel required", "de": "Tank tats\u00e4chlich leer - Nachtanken erforderlich"}, {"id": "level_sensor_failed", "p": "medium", "en": "Level sensor reads empty incorrectly", "de": "F\u00fcllstandsensor meldet f\u00e4lschlich leer"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 200], "estimated_hours": [0, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB3','P','Fuel Pump Secondary Circuit Performance','Kraftstoffpumpe Sekundär-Stromkreis Verhalten','The ECM detects that the secondary fuel pump control circuit (typically used for high-load enrichment) does not respond as expected. Pump output, relay, or driver fault.','Das Steuergerät erkennt, dass der sekundäre Steuerstromkreis der Kraftstoffpumpe (typischerweise für Hochlast-Anreicherung) nicht wie erwartet reagiert. Pumpenleistung, Relais- oder Endstufen-Fehler.','["fuel_pump", "fuel_pump_relay_secondary", "ecm"]','[{"id": "relay_aged", "p": "high", "en": "Secondary fuel pump relay aged", "de": "Sekund\u00e4r-Kraftstoffpumpen-Relais gealtert"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB4','P','Engine Coolant Temperature Sensor 4 Circuit Intermittent/Erratic','Motorkühlmitteltemperatur-Sensor 4 Stromkreis sporadisch/unsauber','The signal of engine coolant temperature sensor 4 drops out or jumps intermittently. Loose connector or noisy ground reference.','Das Signal des Motorkühlmitteltemperatur-Sensors 4 fällt sporadisch aus oder springt. Lockerer Stecker oder verrauschte Masse-Referenz.','["engine_coolant_temperature_sensor_4", "wiring_harness", "ecm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB5','P','Engine Coolant Temperature Sensor 5 Circuit Intermittent/Erratic','Motorkühlmitteltemperatur-Sensor 5 Stromkreis sporadisch/unsauber','The signal of engine coolant temperature sensor 5 drops out or jumps intermittently. Loose connector or noisy ground reference.','Das Signal des Motorkühlmitteltemperatur-Sensors 5 fällt sporadisch aus oder springt. Lockerer Stecker oder verrauschte Masse-Referenz.','["engine_coolant_temperature_sensor_5", "wiring_harness", "ecm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB6','P','Engine Coolant Temperature Sensor 6 Circuit','Motorkühlmitteltemperatur-Sensor 6 Stromkreis','The ECM detects a circuit fault on the engine coolant temperature sensor 6. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Motorkühlmitteltemperatur-Sensor 6. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_6", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB7','P','Engine Coolant Temperature Sensor 6 Range/Performance','Motorkühlmitteltemperatur-Sensor 6 Bereich/Leistung','The ECM detects a range/performance fault on the engine coolant temperature sensor 6. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Bereich/Leistung" am Motorkühlmitteltemperatur-Sensor 6. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_6", "wiring_harness", "ecm"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced", "de": "Sensorbefestigung versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB8','P','Engine Coolant Temperature Sensor 6 Circuit Low','Motorkühlmitteltemperatur-Sensor 6 Stromkreis niedrig','The ECM detects a circuit low fault on the engine coolant temperature sensor 6. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis niedrig" am Motorkühlmitteltemperatur-Sensor 6. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_6", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BB9','P','Engine Coolant Temperature Sensor 6 Circuit High','Motorkühlmitteltemperatur-Sensor 6 Stromkreis hoch','The ECM detects a circuit high fault on the engine coolant temperature sensor 6. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis hoch" am Motorkühlmitteltemperatur-Sensor 6. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_6", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open sensor", "de": "Offener Sensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BBA','P','Engine Coolant Temperature Sensor 6 Circuit Intermittent/Erratic','Motorkühlmitteltemperatur-Sensor 6 Stromkreis sporadisch/unsauber','The ECM detects a circuit intermittent/erratic fault on the engine coolant temperature sensor 6. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis sporadisch/unsauber" am Motorkühlmitteltemperatur-Sensor 6. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["engine_coolant_temperature_sensor_6", "wiring_harness", "ecm"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BBB','P','Turbocharger/Supercharger Bypass Valve A Position Sensor Circuit','Turbolader/Kompressor Bypass-Ventil A Positionssensor Stromkreis','The turbocharger/supercharger bypass valve A reports a position sensor circuit condition. Boost recirculation cannot be commanded reliably.','Das Turbolader/Kompressor-Bypass-Ventil A meldet einen Zustand "Positionssensor Stromkreis". Die Ladeluft-Rezirkulation kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_a", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BBC','P','Turbocharger/Supercharger Bypass Valve A Position Sensor Circuit Low','Turbolader/Kompressor Bypass-Ventil A Positionssensor Stromkreis niedrig','The turbocharger/supercharger bypass valve A reports a position sensor circuit low condition. Boost recirculation cannot be commanded reliably.','Das Turbolader/Kompressor-Bypass-Ventil A meldet einen Zustand "Positionssensor Stromkreis niedrig". Die Ladeluft-Rezirkulation kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_a", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BBD','P','Turbocharger/Supercharger Bypass Valve A Position Sensor Circuit High','Turbolader/Kompressor Bypass-Ventil A Positionssensor Stromkreis hoch','The turbocharger/supercharger bypass valve A reports a position sensor circuit high condition. Boost recirculation cannot be commanded reliably.','Das Turbolader/Kompressor-Bypass-Ventil A meldet einen Zustand "Positionssensor Stromkreis hoch". Die Ladeluft-Rezirkulation kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_a", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open position sensor", "de": "Offener Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BBE','P','Turbocharger/Supercharger Bypass Valve A Position Exceeded Learning Limit','Turbolader/Kompressor Bypass-Ventil A Position Lerngrenze überschritten','The turbocharger/supercharger bypass valve A reports a position exceeded learning limit condition. Boost recirculation cannot be commanded reliably.','Das Turbolader/Kompressor-Bypass-Ventil A meldet einen Zustand "Position Lerngrenze überschritten". Die Ladeluft-Rezirkulation kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_a", "wiring_harness", "ecm"]','[{"id": "mechanism_worn", "p": "high", "en": "Mechanism worn at end-stops", "de": "Mechanik an den Endanschl\u00e4gen verschlissen"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor reference drifted", "de": "Sensor-Referenz driftet"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
