INSERT OR IGNORE INTO dtc_codes VALUES('P2BD5','P','Motor Electronics Coolant Pump C Control Circuit Low','Motor-Elektronik-Kühlmittelpumpe C Steuerkreis niedrig','The motor electronics coolant pump C (cooling the drive inverter or motor) reports a control circuit low condition. Power electronics cooling may be impaired.','Die Motor-Elektronik-Kühlmittelpumpe C (kühlt Wechselrichter oder Antriebsmotor) meldet einen Zustand "Steuerkreis niedrig". Die Leistungselektronik-Kühlung kann beeinträchtigt sein.','["motor_electronics_coolant_pump_c", "wiring_harness", "hybrid_control_module"]','[{"id": "short_to_ground", "p": "high", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}, {"id": "motor_short", "p": "medium", "en": "Internal short in pump motor", "de": "Interner Kurzschluss im Pumpenmotor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BD6','P','Motor Electronics Coolant Pump C Control Circuit High','Motor-Elektronik-Kühlmittelpumpe C Steuerkreis hoch','The motor electronics coolant pump C (cooling the drive inverter or motor) reports a control circuit high condition. Power electronics cooling may be impaired.','Die Motor-Elektronik-Kühlmittelpumpe C (kühlt Wechselrichter oder Antriebsmotor) meldet einen Zustand "Steuerkreis hoch". Die Leistungselektronik-Kühlung kann beeinträchtigt sein.','["motor_electronics_coolant_pump_c", "wiring_harness", "hybrid_control_module"]','[{"id": "short_to_battery", "p": "high", "en": "Control wire shorted to B+", "de": "Steuerleitung mit B+ kurzgeschlossen"}, {"id": "motor_open", "p": "medium", "en": "Open pump motor", "de": "Offener Pumpenmotor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2BD7','P','Motor Electronics Coolant Pump C Control Performance','Motor-Elektronik-Kühlmittelpumpe C Steuerung Verhalten','The motor electronics coolant pump C (cooling the drive inverter or motor) reports a control performance condition. Power electronics cooling may be impaired.','Die Motor-Elektronik-Kühlmittelpumpe C (kühlt Wechselrichter oder Antriebsmotor) meldet einen Zustand "Steuerung Verhalten". Die Leistungselektronik-Kühlung kann beeinträchtigt sein.','["motor_electronics_coolant_pump_c", "wiring_harness", "hybrid_control_module"]','[{"id": "pump_aged", "p": "high", "en": "Pump output degraded with age", "de": "Pumpenf\u00f6rderleistung mit Alter nachgelassen"}, {"id": "air_pocket", "p": "medium", "en": "Air pocket in coolant loop", "de": "Lufteinschluss im K\u00fchlkreislauf"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
