INSERT OR IGNORE INTO dtc_codes VALUES('P2BE8','P','Hybrid/EV Battery Precharge Contactor Control Circuit B Open','Hybrid/EV-Batterie Vorlade-Schütz Steuerkreis B offen','The control circuit B for the hybrid battery precharge contactor reports a open condition. Pre-charging the DC link before main contactor closure cannot be commanded reliably.','Der Steuerstromkreis B für das Vorlade-Schütz der Hybrid-Batterie meldet einen Zustand "offen". Das Vorladen des Zwischenkreises vor dem Schließen des Hauptschützes kann nicht zuverlässig angesteuert werden.','["hybrid_precharge_contactor_b", "wiring_harness", "bms"]','[{"id": "wire_open", "p": "high", "en": "Open in coil control wire", "de": "Unterbrechung in der Spulen-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open contactor coil", "de": "Offene Sch\u00fctzspule"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2200], "estimated_hours": [2, 7]}',1);
