INSERT OR IGNORE INTO dtc_codes VALUES('P2BEA','P','Hybrid/EV Battery Precharge Contactor Control Circuit B Low','Hybrid/EV-Batterie Vorlade-Schütz Steuerkreis B niedrig','The control circuit B for the hybrid battery precharge contactor reports a low condition. Pre-charging the DC link before main contactor closure cannot be commanded reliably.','Der Steuerstromkreis B für das Vorlade-Schütz der Hybrid-Batterie meldet einen Zustand "niedrig". Das Vorladen des Zwischenkreises vor dem Schließen des Hauptschützes kann nicht zuverlässig angesteuert werden.','["hybrid_precharge_contactor_b", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}, {"id": "coil_short", "p": "medium", "en": "Internal short in contactor coil", "de": "Interner Kurzschluss in der Sch\u00fctzspule"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2200], "estimated_hours": [2, 7]}',1);
