INSERT OR IGNORE INTO dtc_codes VALUES('P2C00','P','Fuel Pressure Regulator C Performance','Kraftstoffdruckregler C Verhalten','Fuel pressure regulator C does not maintain rail pressure within the calibrated tolerance. Aged regulator or contamination affecting flow.','Der Kraftstoffdruckregler C hält den Verteilerleistendruck nicht innerhalb der kalibrierten Toleranz. Gealterter Regler oder Verschmutzung beeinflusst den Volumenstrom.','["fuel_pressure_regulator_c", "wiring_harness", "fuel_rail"]','[{"id": "regulator_aged", "p": "high", "en": "Regulator aged", "de": "Regler gealtert"}, {"id": "contamination", "p": "medium", "en": "Contamination affecting regulator seat", "de": "Verschmutzung beeinflusst Reglersitz"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
