INSERT OR IGNORE INTO dtc_codes VALUES('P2C02','P','Fuel Pressure Regulator D Control Circuit/Open','Kraftstoffdruckregler D Steuerkreis offen','The control circuit of fuel pressure regulator D is open. Solenoid cannot be energised on command.','Der Steuerstromkreis des Kraftstoffdruckreglers D ist unterbrochen. Das Solenoid kann auf Anforderung nicht erregt werden.','["fuel_pressure_regulator_d", "wiring_harness", "fuel_rail"]','[{"id": "wire_open", "p": "high", "en": "Open in regulator control wire", "de": "Unterbrechung in der Regler-Steuerleitung"}, {"id": "coil_open", "p": "medium", "en": "Open regulator coil", "de": "Offene Reglerspule"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C03','P','Fuel Pressure Regulator D Control Circuit Low','Kraftstoffdruckregler D Steuerkreis niedrig','Voltage on the fuel pressure regulator D control line is below the expected window. Wire shorted to ground or coil short.','Die Spannung auf der Steuerleitung des Kraftstoffdruckreglers D liegt unter dem erwarteten Bereich. Leitung mit Masse kurzgeschlossen oder Spulen-Kurzschluss.','["fuel_pressure_regulator_d", "wiring_harness", "fuel_rail"]','[{"id": "short_to_ground", "p": "high", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}, {"id": "coil_short", "p": "medium", "en": "Internal short in regulator coil", "de": "Interner Kurzschluss in der Reglerspule"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
