INSERT OR IGNORE INTO dtc_codes VALUES('P2C26','P','Fuel Injector Group B Supply Sense Circuit','Kraftstoffinjektor-Gruppe B Versorgungs-Mess-Stromkreis','The ECM detects a generic fault on the supply sense circuit of fuel injector group B. Group supply voltage cannot be measured reliably.','Das Steuergerät erkennt einen allgemeinen Fehler im Mess-Stromkreis der Versorgung der Kraftstoffinjektor-Gruppe B. Die Versorgungsspannung der Gruppe kann nicht zuverlässig gemessen werden.','["fuel_injector_group_b", "wiring_harness", "ecm"]','[{"id": "wiring_fault", "p": "high", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "fuse_aged", "p": "medium", "en": "Group supply fuse aged with high resistance", "de": "Gruppen-Versorgungssicherung gealtert mit hohem Widerstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C27','P','Fuel Injector Group B Supply Sense Circuit Low','Kraftstoffinjektor-Gruppe B Versorgungs-Mess-Stromkreis niedrig','Voltage on the supply sense circuit of fuel injector group B is below the expected window. Indicates collapsed supply or short to ground.','Die Spannung auf dem Mess-Stromkreis der Versorgung der Kraftstoffinjektor-Gruppe B liegt unter dem erwarteten Bereich. Deutet auf zusammengebrochene Versorgung oder Masseschluss hin.','["fuel_injector_group_b", "wiring_harness", "ecm"]','[{"id": "supply_collapsed", "p": "high", "en": "Supply rail collapsed under load", "de": "Versorgungspfad bricht unter Last zusammen"}, {"id": "short_to_ground", "p": "medium", "en": "Sense wire shorted to ground", "de": "Mess-Leitung mit Masse kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C28','P','Fuel Injector Group B Supply Sense Circuit High','Kraftstoffinjektor-Gruppe B Versorgungs-Mess-Stromkreis hoch','Voltage on the supply sense circuit of fuel injector group B is above the expected window. Indicates overvoltage or wire shorted to B+.','Die Spannung auf dem Mess-Stromkreis der Versorgung der Kraftstoffinjektor-Gruppe B liegt über dem erwarteten Bereich. Deutet auf Überspannung oder Kurzschluss nach B+ hin.','["fuel_injector_group_b", "wiring_harness", "ecm"]','[{"id": "alternator_overvoltage", "p": "high", "en": "Alternator regulator drift - overvoltage", "de": "Generator-Regler driftet - \u00dcberspannung"}, {"id": "short_to_battery", "p": "medium", "en": "Sense wire shorted to B+", "de": "Mess-Leitung mit B+ kurzgeschlossen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C29','P','Turbocharger/Supercharger Bypass Valve B Stuck','Turbolader/Kompressor Bypass-Ventil B festsitzend','The turbocharger/supercharger bypass valve B reports a stuck condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "festsitzend". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "valve_seized", "p": "high", "en": "Bypass valve mechanically seized", "de": "Bypass-Ventil mechanisch festsitzend"}, {"id": "carbon_deposits", "p": "medium", "en": "Carbon deposits jam the valve", "de": "Kohlenstoffablagerungen blockieren das Ventil"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2A','P','Turbocharger/Supercharger Bypass Valve B Position Sensor Circuit/Open','Turbolader/Kompressor Bypass-Ventil B Positionssensor Stromkreis offen','The turbocharger/supercharger bypass valve B reports a position sensor circuit/open condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Positionssensor Stromkreis offen". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "wire_open", "p": "high", "en": "Open in sensor signal wire", "de": "Unterbrechung in der Sensor-Signalleitung"}, {"id": "sensor_failed", "p": "medium", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2B','P','Turbocharger/Supercharger Bypass Valve B Position Sensor Circuit Low','Turbolader/Kompressor Bypass-Ventil B Positionssensor Stromkreis niedrig','The turbocharger/supercharger bypass valve B reports a position sensor circuit low condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Positionssensor Stromkreis niedrig". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2C','P','Turbocharger/Supercharger Bypass Valve B Position Sensor Circuit High','Turbolader/Kompressor Bypass-Ventil B Positionssensor Stromkreis hoch','The turbocharger/supercharger bypass valve B reports a position sensor circuit high condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Positionssensor Stromkreis hoch". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open position sensor", "de": "Offener Positionssensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2D','P','Turbocharger/Supercharger Bypass Valve B Position Exceeded Learning Limit','Turbolader/Kompressor Bypass-Ventil B Position Lerngrenze überschritten','The turbocharger/supercharger bypass valve B reports a position exceeded learning limit condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Position Lerngrenze überschritten". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "mechanism_worn", "p": "high", "en": "Mechanism worn at end-stops", "de": "Mechanik an den Endanschl\u00e4gen verschlissen"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor reference drifted", "de": "Sensor-Referenz driftet"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2E','P','Turbocharger/Supercharger Bypass Valve B Supply Voltage Low','Turbolader/Kompressor Bypass-Ventil B Versorgungsspannung niedrig','The turbocharger/supercharger bypass valve B reports a supply voltage low condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Versorgungsspannung niedrig". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "fuse_blown", "p": "high", "en": "Supply fuse blown", "de": "Versorgungssicherung durchgebrannt"}, {"id": "supply_wire_short", "p": "medium", "en": "Supply wire shorted to ground", "de": "Versorgungsleitung mit Masse kurzgeschlossen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C2F','P','Turbocharger/Supercharger Bypass Valve B Driver Current/Temperature Too High','Turbolader/Kompressor Bypass-Ventil B Endstufe Strom/Temperatur zu hoch','The turbocharger/supercharger bypass valve B reports a driver current/temperature too high condition. Boost recirculation cannot be commanded reliably on this branch.','Das Turbolader/Kompressor-Bypass-Ventil B meldet einen Zustand "Endstufe Strom/Temperatur zu hoch". Die Ladeluft-Rezirkulation auf diesem Zweig kann nicht zuverlässig angesteuert werden.','["turbo_bypass_valve_b", "wiring_harness", "ecm"]','[{"id": "actuator_jammed", "p": "high", "en": "Bypass valve actuator jammed", "de": "Bypass-Ventil-Aktuator verklemmt"}, {"id": "short_to_ground", "p": "medium", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C30','P','Ignition Coil Primary Circuit Fuse A','Zündspulen-Primär-Stromkreis Sicherung A','The ECM detects an open or blown fuse on the ignition coil primary supply circuit A. Affected coils receive no operating voltage.','Das Steuergerät erkennt eine durchgebrannte oder offene Sicherung im Primär-Versorgungsstromkreis der Zündspulen A. Betroffene Spulen erhalten keine Betriebsspannung.','["ignition_coil_fuse_a", "ignition_coils", "wiring_harness"]','[{"id": "fuse_blown", "p": "high", "en": "Primary supply fuse blown by short circuit", "de": "Prim\u00e4r-Versorgungssicherung durch Kurzschluss durchgebrannt"}, {"id": "coil_short", "p": "medium", "en": "Shorted ignition coil drawing excess current", "de": "Kurzgeschlossene Z\u00fcndspule zieht \u00dcberstrom"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 300], "estimated_hours": [0.2, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C31','P','Ignition Coil Primary Circuit Fuse B','Zündspulen-Primär-Stromkreis Sicherung B','The ECM detects an open or blown fuse on the ignition coil primary supply circuit B. Affected coils receive no operating voltage.','Das Steuergerät erkennt eine durchgebrannte oder offene Sicherung im Primär-Versorgungsstromkreis der Zündspulen B. Betroffene Spulen erhalten keine Betriebsspannung.','["ignition_coil_fuse_b", "ignition_coils", "wiring_harness"]','[{"id": "fuse_blown", "p": "high", "en": "Primary supply fuse blown by short circuit", "de": "Prim\u00e4r-Versorgungssicherung durch Kurzschluss durchgebrannt"}, {"id": "coil_short", "p": "medium", "en": "Shorted ignition coil drawing excess current", "de": "Kurzgeschlossene Z\u00fcndspule zieht \u00dcberstrom"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 300], "estimated_hours": [0.2, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2C32','P','Crankcase Pressure Sensor B Circuit','Kurbelgehäuse-Drucksensor B Stromkreis','The ECM detects a circuit fault on the crankcase pressure sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Kurbelgehäuse-Drucksensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["crankcase_pressure_sensor_b", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
