INSERT OR IGNORE INTO dtc_codes VALUES('P2C34','P','Crankcase Pressure Sensor B Circuit Low','Kurbelgehäuse-Drucksensor B Stromkreis niedrig','The ECM detects a circuit low fault on the crankcase pressure sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis niedrig" am Kurbelgehäuse-Drucksensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["crankcase_pressure_sensor_b", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
