INSERT OR IGNORE INTO dtc_codes VALUES('P2C37','P','Cold Start Engine Coolant Pump Performance','Kaltstart Motorkühlmittelpumpe Verhalten','During cold start, the engine coolant pump does not produce the expected flow. Pump aging combined with high cold viscosity, or pump-disable strategy malfunction.','Beim Kaltstart liefert die Motorkühlmittelpumpe nicht den erwarteten Volumenstrom. Pumpenverschleiß kombiniert mit hoher Kaltviskosität oder Fehler in der Pumpenabschalt-Strategie.','["engine_coolant_pump", "engine_coolant_loop"]','[{"id": "pump_aged", "p": "high", "en": "Pump output degraded with age", "de": "Pumpenf\u00f6rderleistung mit Alter nachgelassen"}, {"id": "cold_viscosity", "p": "medium", "en": "Cold coolant viscosity too high", "de": "Kaltes K\u00fchlmittel mit zu hoher Viskosit\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
