INSERT OR IGNORE INTO dtc_codes VALUES('P2C43','P','Battery Isolation/Voltage Stabilization Control Circuit','Batterie-Isolation/Spannungsstabilisierung Steuerkreis','The battery isolation/voltage stabilization module reports a control circuit condition. Power supply quality during start/stop or load shedding is impaired.','Das Batterie-Isolations-/Spannungsstabilisierungsmodul meldet einen Zustand "Steuerkreis". Die Stromversorgungsqualität bei Start/Stopp oder Lastabwurf ist beeinträchtigt.','["battery_isolation_module", "wiring_harness", "ecm"]','[{"id": "module_failed", "p": "high", "en": "Isolation/stabilization module failed", "de": "Isolations-/Stabilisierungsmodul defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
