INSERT OR IGNORE INTO dtc_codes VALUES('P2C51','P','Fuel Level Sensor A/B Correlation','Kraftstoff-Füllstandsensor A/B Korrelation','The signals of fuel level sensors A and B do not correlate within the calibrated tolerance. Common in saddle tanks where two sensors monitor each tank half.','Die Signale der Kraftstoff-Füllstandsensoren A und B korrelieren nicht innerhalb der kalibrierten Toleranz. Bei Satteltanks häufig - zwei Sensoren überwachen die Tankhälften.','["fuel_level_sensor_a", "fuel_level_sensor_b", "ecm"]','[{"id": "float_stuck", "p": "high", "en": "One float stuck on guide rod", "de": "Ein Schwimmer am F\u00fchrungsrohr festsitzend"}, {"id": "transfer_pump_failed", "p": "medium", "en": "Saddle tank transfer pump failed", "de": "Satteltank-F\u00f6rderpumpe defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
