INSERT OR IGNORE INTO dtc_codes VALUES('P2C94','P','Hybrid/EV Battery Contactor Control Supply Circuit/Low','Hybrid/EV-Batterie Schütz-Steuerung Versorgungsstromkreis niedrig','The supply circuit for the hybrid battery contactor control reports a low condition. Contactor coils may not energise as expected.','Der Versorgungsstromkreis der Hybrid-Batterie-Schütz-Steuerung meldet einen Zustand "niedrig". Die Schützspulen werden möglicherweise nicht wie erwartet erregt.','["hybrid_battery_contactor_control_supply", "wiring_harness", "bms"]','[{"id": "short_to_ground", "p": "high", "en": "Supply wire shorted to ground", "de": "Versorgungsleitung mit Masse kurzgeschlossen"}, {"id": "voltage_collapse", "p": "medium", "en": "Supply rail collapses under load", "de": "Versorgungspfad bricht unter Last zusammen"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
