INSERT OR IGNORE INTO dtc_codes VALUES('P2C96','P','Hybrid/EV Battery Disable Circuit/Open','Hybrid/EV-Batterie Abschaltung Stromkreis offen','The hybrid battery disable circuit reports a circuit/open condition. Service disconnect signal cannot be read reliably.','Der Hybrid-Batterie-Abschaltstromkreis meldet einen Zustand "Stromkreis offen". Das Service-Trennsignal kann nicht zuverlässig gelesen werden.','["hybrid_battery_disable_switch", "wiring_harness", "bms"]','[{"id": "wire_open", "p": "high", "en": "Open in disable signal wire", "de": "Unterbrechung in der Abschaltsignal-Leitung"}, {"id": "switch_failed", "p": "medium", "en": "Service disconnect switch failed open", "de": "Service-Trennschalter offen ausgefallen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
