INSERT OR IGNORE INTO dtc_codes VALUES('P2C98','P','Hybrid/EV Battery Disable Circuit High','Hybrid/EV-Batterie Abschaltung Stromkreis hoch','The hybrid battery disable circuit reports a circuit high condition. Service disconnect signal cannot be read reliably.','Der Hybrid-Batterie-Abschaltstromkreis meldet einen Zustand "Stromkreis hoch". Das Service-Trennsignal kann nicht zuverlässig gelesen werden.','["hybrid_battery_disable_switch", "wiring_harness", "bms"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "pull_down_open", "p": "medium", "en": "Pull-down resistor open", "de": "Pull-Down-Widerstand offen"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
