INSERT OR IGNORE INTO dtc_codes VALUES('P2CA1','P','Charge Air Cooler Coolant Pump Sense Circuit High','Ladeluftkühler-Kühlmittelpumpe Mess-Stromkreis hoch','The sense feedback circuit for the charge air cooler coolant pump reports a high condition. Pump output verification is impaired.','Der Mess-Rückmeldekreis der Ladeluftkühler-Kühlmittelpumpe meldet einen Zustand "hoch". Die Verifikation der Pumpenleistung ist beeinträchtigt.','["cac_coolant_pump", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Sense wire shorted to B+", "de": "Mess-Leitung mit B+ kurzgeschlossen"}, {"id": "regulator_overvoltage", "p": "medium", "en": "Pump driver feedback drifted high", "de": "Pumpentreiber-R\u00fcckmeldung driftet hoch"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CA2','P','Charge Air Cooler Coolant Pump Sense Circuit Low','Ladeluftkühler-Kühlmittelpumpe Mess-Stromkreis niedrig','The sense feedback circuit for the charge air cooler coolant pump reports a low condition. Pump output verification is impaired.','Der Mess-Rückmeldekreis der Ladeluftkühler-Kühlmittelpumpe meldet einen Zustand "niedrig". Die Verifikation der Pumpenleistung ist beeinträchtigt.','["cac_coolant_pump", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Sense wire shorted to ground", "de": "Mess-Leitung mit Masse kurzgeschlossen"}, {"id": "wire_open", "p": "medium", "en": "Open in sense wire", "de": "Unterbrechung in der Mess-Leitung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CA3','P','Charge Air Cooler Coolant Pump Sense Circuit Performance','Ladeluftkühler-Kühlmittelpumpe Mess-Stromkreis Verhalten','The sense feedback circuit for the charge air cooler coolant pump reports a performance condition. Pump output verification is impaired.','Der Mess-Rückmeldekreis der Ladeluftkühler-Kühlmittelpumpe meldet einen Zustand "Verhalten". Die Verifikation der Pumpenleistung ist beeinträchtigt.','["cac_coolant_pump", "wiring_harness", "ecm"]','[{"id": "sense_drift", "p": "high", "en": "Sense feedback drifted from expected", "de": "Mess-R\u00fcckmeldung weicht vom Erwarteten ab"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact in connector", "de": "Hochohmiger Kontakt im Stecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CA4','P','Particulate Filter Pressure Sensor Signals Swapped A/B','Partikelfilter-Drucksensor Signale A/B vertauscht','The ECM detects that the particulate filter pressure sensor signals A and B are reversed - low-pressure side reads as high-pressure side and vice versa. Most likely a wiring swap during service.','Das Steuergerät erkennt, dass die Partikelfilter-Drucksensorsignale A und B vertauscht sind - die Niederdruckseite wird als Hochdruckseite gelesen und umgekehrt. Wahrscheinlich Verkabelungs-Vertauschung bei Service.','["pf_pressure_sensor_a", "pf_pressure_sensor_b", "wiring_harness"]','[{"id": "harness_swap", "p": "high", "en": "Sensor connectors A and B swapped during service", "de": "Sensorstecker A und B bei Service vertauscht"}, {"id": "sensor_install_wrong", "p": "medium", "en": "Sensors installed in wrong positions", "de": "Sensoren in falschen Positionen verbaut"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.2, 1]}',1);
