INSERT OR IGNORE INTO dtc_codes VALUES('P2CBC','P','Fan 3 Overspeed','Lüfter 3 Überdrehzahl','Cooling fan 3 exceeds the calibrated maximum speed. Indicates load lost (broken fan blade) or supply voltage above nominal.','Der Kühlerlüfter 3 überschreitet die kalibrierte Maximaldrehzahl. Deutet auf verlorene Last (gebrochenes Lüfterrad) oder zu hohe Versorgungsspannung hin.','["cooling_fan_3"]','[{"id": "blade_broken", "p": "high", "en": "Fan blade broken or detached", "de": "L\u00fcfterrad gebrochen oder abgel\u00f6st"}, {"id": "alternator_overvoltage", "p": "medium", "en": "Alternator overvoltage", "de": "Generator-\u00dcberspannung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 700], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CBD','P','PCV Heater "B" Control Circuit /Open','PCV-Heizer "B" Steuerkreis offen','The control circuit of PCV (positive crankcase ventilation) heater B reports a control circuit /open condition. PCV line heater prevents oil mist freezing in cold weather.','Der Steuerstromkreis des PCV-Heizers B (positive Kurbelgehäuse-Entlüftung) meldet einen Zustand "Steuerkreis offen". Der PCV-Leitungsheizer verhindert Vereisung der Ölnebel-Leitung bei Kälte.','["pcv_heater_b", "wiring_harness", "ecm"]','[{"id": "wire_open", "p": "high", "en": "Open in heater control wire", "de": "Unterbrechung in der Heizungs-Steuerleitung"}, {"id": "element_open", "p": "medium", "en": "Open heater element", "de": "Offenes Heizelement"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CBE','P','PCV Heater "B" Control Circuit High','PCV-Heizer "B" Steuerkreis hoch','The control circuit of PCV (positive crankcase ventilation) heater B reports a control circuit high condition. PCV line heater prevents oil mist freezing in cold weather.','Der Steuerstromkreis des PCV-Heizers B (positive Kurbelgehäuse-Entlüftung) meldet einen Zustand "Steuerkreis hoch". Der PCV-Leitungsheizer verhindert Vereisung der Ölnebel-Leitung bei Kälte.','["pcv_heater_b", "wiring_harness", "ecm"]','[{"id": "short_to_battery", "p": "high", "en": "Control wire shorted to B+", "de": "Steuerleitung mit B+ kurzgeschlossen"}, {"id": "element_open", "p": "medium", "en": "Open heater element", "de": "Offenes Heizelement"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
