INSERT OR IGNORE INTO dtc_codes VALUES('P2CC0','P','PCV Heater "B" Performance','PCV-Heizer "B" Verhalten','The control circuit of PCV (positive crankcase ventilation) heater B reports a performance condition. PCV line heater prevents oil mist freezing in cold weather.','Der Steuerstromkreis des PCV-Heizers B (positive Kurbelgehäuse-Entlüftung) meldet einen Zustand "Verhalten". Der PCV-Leitungsheizer verhindert Vereisung der Ölnebel-Leitung bei Kälte.','["pcv_heater_b", "wiring_harness", "ecm"]','[{"id": "element_aged", "p": "high", "en": "Heater element aged - low output", "de": "Heizelement gealtert - geringe Leistung"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low under load", "de": "Versorgungsspannung unter Last zu niedrig"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',1);
