INSERT OR IGNORE INTO dtc_codes VALUES('P2CD4','P','A/C Refrigerant Pressure Sensor A/B Correlation','Klimakältemittel-Drucksensor A/B Korrelation','The signals of A/C refrigerant pressure sensors A and B do not correlate within the calibrated tolerance. One sensor drifts or installation offset between the two channels.','Die Signale der Klimakältemittel-Drucksensoren A und B korrelieren nicht innerhalb der kalibrierten Toleranz. Ein Sensor driftet oder es liegt ein Einbauversatz zwischen den beiden Kanälen vor.','["ac_refrigerant_pressure_sensor_a", "ac_refrigerant_pressure_sensor_b", "ecm"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor characteristic drifted", "de": "Eine Sensorkennlinie driftet"}, {"id": "harness_swap", "p": "medium", "en": "Harness incorrectly swapped between channels", "de": "Verkabelung zwischen Kan\u00e4len vertauscht"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.3, 2]}',1);
