INSERT OR IGNORE INTO dtc_codes VALUES('P2CDA','P','Alternative Fuel Tank A Vacuum Insulation Deteriorated','Alternativkraftstoff-Tank A Vakuumisolierung verschlechtert','The AFCM detects that the vacuum insulation of alternative fuel tank A has lost effectiveness. Common in cryogenic LNG tanks where loss of vacuum increases boil-off rate.','Das AFCM erkennt, dass die Vakuumisolierung des Alternativkraftstoff-Tanks A an Wirksamkeit verloren hat. Bei kryogenen LNG-Tanks verbreitet - Vakuumverlust erhöht die Verdampfungs-Rate.','["alt_fuel_tank_a", "alt_fuel_tank_a_insulation"]','[{"id": "vacuum_loss", "p": "high", "en": "Vacuum loss in tank double-wall", "de": "Vakuumverlust in der doppelwandigen Tankh\u00fclle"}, {"id": "insulation_aged", "p": "medium", "en": "Insulation material aged", "de": "Isoliermaterial gealtert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [4, 16]}',1);
