INSERT OR IGNORE INTO dtc_codes VALUES('P2CF6','P','Hybrid/EV Battery Pack Coolant Pump B Overspeed /Air in System','Hybrid/EV-Batteriepaket-Kühlmittelpumpe B Überdrehzahl /Luft im System','The HV battery pack coolant pump B reports a overspeed /air in system condition. Battery thermal management may be impaired.','Die HV-Batteriepaket-Kühlmittelpumpe B meldet einen Zustand "Überdrehzahl /Luft im System". Das Thermomanagement der Batterie kann beeinträchtigt sein.','["hybrid_battery_coolant_pump_b", "battery_pack_coolant_loop"]','[{"id": "air_pocket", "p": "high", "en": "Air pocket in coolant loop", "de": "Lufteinschluss im K\u00fchlkreislauf"}, {"id": "coolant_low", "p": "medium", "en": "Coolant level low", "de": "K\u00fchlmittelstand zu niedrig"}, {"id": "cell_imbalance", "p": "low", "en": "Pack cell imbalance approaching service threshold", "de": "Pack-Zell-Ungleichgewicht nahe Wartungsschwelle"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 6]}',1);
