INSERT OR IGNORE INTO dtc_codes VALUES('P2CF8','P','Engine Coolant Bypass Valve D Control Circuit Driver Current/Temperature Too High','Motorkühlmittel-Bypass-Ventil D Steuerendstufe Strom/Temperatur zu hoch','The output driver for the engine coolant bypass valve D actuator reports current or junction temperature above its protection threshold. Stalled actuator or short to ground.','Die Endstufe des Aktuators des Motorkühlmittel-Bypass-Ventils D meldet Strom oder Sperrschicht-Temperatur oberhalb der Schutzschwelle. Festsitzender Aktuator oder Kurzschluss nach Masse.','["engine_coolant_bypass_valve_d", "ecm"]','[{"id": "actuator_jammed", "p": "high", "en": "Bypass actuator mechanically jammed", "de": "Bypass-Aktuator mechanisch verklemmt"}, {"id": "short_to_ground", "p": "medium", "en": "Control wire shorted to ground", "de": "Steuerleitung mit Masse kurzgeschlossen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1800], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2CF9','P','Belt Integrated Starter Generator Belt Tensioner Control Circuit/Open','Riemenintegrierter Starter-Generator Riemenspanner Steuerkreis offen','The control circuit of the belt-integrated starter/generator (BISG) belt tensioner reports a control circuit/open condition. Belt tension cannot be modulated for assist/regen modes.','Der Steuerstromkreis des Riemenspanners des riemenintegrierten Starter/Generators (BISG) meldet einen Zustand "Steuerkreis offen". Die Riemenspannung kann nicht für Boost-/Regen-Modi moduliert werden.','["bisg_belt_tensioner", "wiring_harness", "hybrid_control_module"]','[{"id": "wire_open", "p": "high", "en": "Open in tensioner control wire", "de": "Unterbrechung in der Spanner-Steuerleitung"}, {"id": "actuator_open", "p": "medium", "en": "Open tensioner actuator", "de": "Offener Spanner-Aktuator"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
