INSERT OR IGNORE INTO dtc_codes VALUES('P2DC7','P','Starter/Generator Excitation Current','Starter/Generator Erregerstrom','The starter/generator excitation current control reports a generic fault.','Die Erregerstrom-Steuerung des Starter/Generators meldet einen allgemeinen Fehler.','["starter_generator_excitation_circuit", "starter_generator", "hybrid_control_module"]','[{"id": "excitation_circuit_fault", "p": "high", "en": "Excitation circuit fault", "de": "Erregerkreis-Fehler"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DC8','P','Starter/Generator Excitation Current Low','Starter/Generator Erregerstrom niedrig','The starter/generator excitation current is below the expected window.','Der Erregerstrom des Starter/Generators liegt unter dem erwarteten Bereich.','["starter_generator_excitation_circuit", "starter_generator", "hybrid_control_module"]','[{"id": "winding_partial_open", "p": "high", "en": "Excitation winding partially open", "de": "Erregerwicklung teilweise unterbrochen"}, {"id": "supply_voltage_low", "p": "medium", "en": "Supply voltage low", "de": "Versorgungsspannung niedrig"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DC9','P','Starter/Generator Excitation Current High','Starter/Generator Erregerstrom hoch','The starter/generator excitation current is above the expected window. Indicates winding short or driver fault.','Der Erregerstrom des Starter/Generators liegt über dem erwarteten Bereich. Deutet auf Wicklungs-Kurzschluss oder Endstufen-Fehler hin.','["starter_generator_excitation_circuit", "starter_generator"]','[{"id": "winding_short", "p": "high", "en": "Excitation winding short", "de": "Erregerwicklung-Kurzschluss"}, {"id": "driver_high", "p": "medium", "en": "Output driver fault high", "de": "Endstufen-Fehler hoch"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DCA','P','Starter/Generator Excitation Current Intermittent','Starter/Generator Erregerstrom sporadisch','The starter/generator excitation current drops out or jumps intermittently. Loose connector or unstable driver.','Der Erregerstrom des Starter/Generators fällt sporadisch aus oder springt. Lockerer Stecker oder instabile Endstufe.','["starter_generator_excitation_circuit", "wiring_harness"]','[{"id": "connector_loose", "p": "high", "en": "Connector not seated", "de": "Stecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DCB','P','Starter/Generator Phase X-Y-Z Current Sensor Correlation','Starter/Generator Phase X-Y-Z Stromsensor Korrelation','The phase X, Y, and Z current sensors of the starter/generator do not correlate within the calibrated tolerance. Sum of phase currents should be near zero.','Die Phasen-X-, Y- und Z-Stromsensoren des Starter/Generators korrelieren nicht innerhalb der kalibrierten Toleranz. Die Summe der Phasenströme sollte nahe Null sein.','["starter_generator_phase_x_current_sensor", "starter_generator_phase_y_current_sensor", "starter_generator_phase_z_current_sensor"]','[{"id": "sensor_offset", "p": "high", "en": "One sensor offset drifted", "de": "Ein Sensor-Versatz driftet"}, {"id": "ground_offset", "p": "medium", "en": "Ground offset between sensors", "de": "Massenversatz zwischen Sensoren"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
