INSERT OR IGNORE INTO dtc_codes VALUES('P2DCD','P','Particulate Filter B Incorrect','Partikelfilter B falsch','The ECM detects that the installed particulate filter B does not match the expected type or specification. Wrong replacement part or substrate damage.','Das Steuergerät erkennt, dass der eingebaute Partikelfilter B nicht zum erwarteten Typ oder zur Spezifikation passt. Falsches Ersatzteil oder Substrat-Schaden.','["particulate_filter_b"]','[{"id": "wrong_part", "p": "high", "en": "Wrong DPF type installed", "de": "Falscher DPF-Typ verbaut"}, {"id": "substrate_damage", "p": "medium", "en": "Substrate damaged or missing", "de": "Substrat besch\u00e4digt oder fehlt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [800, 5000], "estimated_hours": [2, 8]}',1);
