INSERT OR IGNORE INTO dtc_codes VALUES('P2DD9','P','EVAP System Leak Detection Pump Control Circuit Performance','EVAP-Leck-Erkennungs-Pumpe Steuerkreis Verhalten','The EVAP leak detection pump control circuit reports a performance condition. Pump response or current draw outside calibration.','Der Steuerstromkreis der EVAP-Leck-Erkennungs-Pumpe meldet einen Verhaltens-Zustand. Pumpen-Reaktion oder Stromaufnahme außerhalb der Kalibrierung.','["evap_leak_detection_pump", "wiring_harness", "ecm"]','[{"id": "pump_aged", "p": "high", "en": "Pump output degraded", "de": "Pumpenleistung nachgelassen"}, {"id": "high_resistance", "p": "medium", "en": "High-resistance contact", "de": "Hochohmiger Kontakt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DDA','P','EVAP System Leak Detection Pump Performance/Stuck Off','EVAP-Leck-Erkennungs-Pumpe Verhalten/festsitzend aus','The EVAP leak detection pump does not start when commanded. Motor seized, relay failure, or driver fault.','Die EVAP-Leck-Erkennungs-Pumpe startet bei Anforderung nicht. Motor festsitzend, Relaisausfall oder Endstufen-Fehler.','["evap_leak_detection_pump", "wiring_harness", "ecm"]','[{"id": "motor_seized", "p": "high", "en": "Pump motor seized", "de": "Pumpenmotor festsitzend"}, {"id": "relay_failed", "p": "medium", "en": "Pump relay failed", "de": "Pumpenrelais defekt"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2DDB','P','EVAP System Leak Detection Pump Stuck On','EVAP-Leck-Erkennungs-Pumpe dauerhaft an','The EVAP leak detection pump stays running when commanded off. Relay welded or driver stuck on. The evaporative system captures fuel vapor from the tank and purges it into intake; leaks or stuck purge valves leak hydrocarbons and cause emissions fail','Die EVAP-Leck-Erkennungs-Pumpe läuft weiter, obwohl Abschalten angefordert. Verschweißtes Relais oder Endstufe bleibt durchgeschaltet. Das EVAP-System fängt Kraftstoffdämpfe aus dem Tank und spült sie in den Ansaugtrakt; Leckagen oder klemmende Tanke','["evap_leak_detection_pump", "wiring_harness", "ecm"]','[{"id": "relay_welded", "p": "high", "en": "Relay contacts welded", "de": "Relaiskontakte verschwei\u00dft"}, {"id": "driver_stuck_on", "p": "medium", "en": "Output driver stuck on", "de": "Endstufe bleibt durchgeschaltet"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
