INSERT OR IGNORE INTO dtc_codes VALUES('P2E7B','P','Drive Motor A Excitation Current Sensor Circuit','Antriebsmotor A Erregerstrom-Sensor Stromkreis','The drive motor A excitation current sensor circuit reports a generic fault. Field excitation current measurement is unreliable.','Der Stromkreis des Erregerstrom-Sensors des Antriebsmotors A meldet einen allgemeinen Fehler. Die Felderregerstrom-Messung ist unzuverlässig.','["drive_motor_a_excitation_current_sensor", "wiring_harness", "hybrid_control_module"]','[{"id": "sensor_failed", "p": "high", "en": "Excitation current sensor failed", "de": "Erregerstrom-Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring fault", "de": "Verkabelungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E7C','P','A/C Compressor Control Module Internal Temperature Sensor B Circuit','Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis','The ECM detects a circuit fault on the a/c compressor control module internal temperature sensor b. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Klimakompressor-Steuermodul Interner Temperatursensor B. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["ac_compressor_cm_internal_temp_sensor_b", "wiring_harness", "ac_compressor_module"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E7D','P','A/C Compressor Control Module Internal Temperature Sensor B Range/Performance','Klimakompressor-Steuermodul Interner Temperatursensor B Bereich/Leistung','The ECM detects a range/performance fault on the a/c compressor control module internal temperature sensor b. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Bereich/Leistung" am Klimakompressor-Steuermodul Interner Temperatursensor B. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["ac_compressor_cm_internal_temp_sensor_b", "wiring_harness", "ac_compressor_module"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor characteristic drifted", "de": "Sensorkennlinie driftet"}, {"id": "mounting_displaced", "p": "medium", "en": "Sensor mounting displaced", "de": "Sensorbefestigung versetzt"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E7E','P','A/C Compressor Control Module Internal Temperature Sensor B Circuit High','Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis hoch','The ECM detects a circuit high fault on the a/c compressor control module internal temperature sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis hoch" am Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["ac_compressor_cm_internal_temp_sensor_b", "wiring_harness", "ac_compressor_module"]','[{"id": "short_to_battery", "p": "high", "en": "Signal wire shorted to B+", "de": "Signalleitung mit B+ kurzgeschlossen"}, {"id": "sensor_open", "p": "medium", "en": "Open sensor", "de": "Offener Sensor"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E7F','P','A/C Compressor Control Module Internal Temperature Sensor B Circuit Low','Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis niedrig','The ECM detects a circuit low fault on the a/c compressor control module internal temperature sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis niedrig" am Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["ac_compressor_cm_internal_temp_sensor_b", "wiring_harness", "ac_compressor_module"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E80','P','A/C Compressor Control Module Internal Temperature Sensor B Circuit Intermittent/Erratic','Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis sporadisch/unsauber','The ECM detects a circuit intermittent/erratic fault on the a/c compressor control module internal temperature sensor b circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis sporadisch/unsauber" am Klimakompressor-Steuermodul Interner Temperatursensor B Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["ac_compressor_cm_internal_temp_sensor_b", "wiring_harness", "ac_compressor_module"]','[{"id": "connector_loose", "p": "high", "en": "Sensor connector not seated", "de": "Sensorstecker nicht eingerastet"}, {"id": "ground_noisy", "p": "medium", "en": "Noisy ground reference", "de": "Verrauschte Masse-Referenz"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E81','P','Cold Start Engine Coolant Bypass Valve D Stuck Closed','Kaltstart Motorkühlmittel-Bypass-Ventil D geschlossen festsitzend','During cold start, engine coolant bypass valve D is stuck closed. Coolant cannot flow through the affected branch.','Beim Kaltstart sitzt das Motorkühlmittel-Bypass-Ventil D geschlossen festsitzend. Kühlmittel kann nicht durch den betroffenen Zweig fließen.','["engine_coolant_bypass_valve_d"]','[{"id": "valve_stuck_closed", "p": "high", "en": "Valve stuck closed at cold", "de": "Ventil bei K\u00e4lte geschlossen festsitzend"}, {"id": "actuator_lazy_cold", "p": "medium", "en": "Actuator response sluggish at cold", "de": "Aktuator-Reaktion bei K\u00e4lte tr\u00e4ge"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E82','P','Cold Start Engine Coolant Pump Overspeed','Kaltstart Motorkühlmittelpumpe Überdrehzahl','During cold start, the engine coolant pump exceeds the calibrated maximum speed. Indicates load lost or supply voltage too high.','Beim Kaltstart überschreitet die Motorkühlmittelpumpe die kalibrierte Maximaldrehzahl. Deutet auf verlorene Last oder zu hohe Versorgungsspannung hin.','["engine_coolant_pump"]','[{"id": "load_lost", "p": "high", "en": "Pump impeller damaged", "de": "Pumpenrad besch\u00e4digt"}, {"id": "supply_voltage_high", "p": "medium", "en": "Supply voltage above nominal", "de": "Versorgungsspannung \u00fcber Nennwert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [2, 7]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2E83','P','Fuel Rail Pressure Performance - Engine Off','Kraftstoff-Verteilerleistendruck Verhalten - Motor aus','After engine shutdown, the fuel rail pressure does not maintain the calibrated decay profile. Indicates injector leakage or check valve fault.','Nach Motor-Abschaltung hält der Verteilerleistendruck nicht das kalibrierte Abbau-Profil. Deutet auf Injektor-Leckage oder Rückschlagventil-Fehler hin.','["fuel_injectors", "fuel_rail", "fuel_pressure_check_valve"]','[{"id": "injector_leak", "p": "high", "en": "Injector leaks after shutdown", "de": "Injektor undicht nach Abschaltung"}, {"id": "check_valve_failed", "p": "medium", "en": "Check valve failed", "de": "R\u00fcckschlagventil defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 6]}',1);
