INSERT OR IGNORE INTO dtc_codes VALUES('P2EAE','P','Reductant Injection Valve Circuit Range/Performance Bank 1 Unit 2','Reduktionsmittel-Einspritzventil Stromkreis Bereich/Leistung Bank 1 Einheit 2','The reductant injection valve on bank 1 unit 2 reports a range/performance fault. Dosing accuracy on this unit is impaired.','Das Reduktionsmittel-Einspritzventil auf Bank 1 Einheit 2 meldet einen Bereich/Leistungs-Fehler. Die Dosier-Genauigkeit dieser Einheit ist beeinträchtigt.','["reductant_injection_valve_b1_u2"]','[{"id": "valve_clogged", "p": "high", "en": "Injection valve partially clogged", "de": "Einspritzventil teilweise verstopft"}, {"id": "coil_drift", "p": "medium", "en": "Coil resistance drifted", "de": "Spulenwiderstand driftet"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2EAF','P','Reductant Injection Valve Stuck Closed Bank 1 Unit 2','Reduktionsmittel-Einspritzventil geschlossen festsitzend Bank 1 Einheit 2','The reductant injection valve on bank 1 unit 2 is stuck closed. No DEF/AdBlue can be dosed on this unit.','Das Reduktionsmittel-Einspritzventil auf Bank 1 Einheit 2 sitzt geschlossen festsitzend. An dieser Einheit kann kein DEF/AdBlue dosiert werden.','["reductant_injection_valve_b1_u2"]','[{"id": "valve_seized", "p": "high", "en": "Valve mechanically seized closed", "de": "Ventil mechanisch geschlossen festsitzend"}, {"id": "crystallization", "p": "medium", "en": "DEF crystallization blocks valve", "de": "DEF-Kristallisation blockiert Ventil"}, {"id": "stuck_carbon_buildup", "p": "low", "en": "Carbon or debris buildup preventing free movement", "de": "Verkokung oder Ablagerungen verhindern freies Bewegen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2EB0','P','Throttle Valve Intake Air Pressure Sensor Circuit','Drosselklappen-Ansaugluftdruck-Sensor Stromkreis','The ECM detects a circuit fault on the throttle valve intake air pressure sensor circuit. Reading cannot be used reliably for control.','Das Steuergerät erkennt einen Fehler "Stromkreis" am Drosselklappen-Ansaugluftdruck-Sensor Stromkreis. Der Messwert kann nicht zuverlässig zur Regelung herangezogen werden.','["throttle_valve_intake_air_pressure_sensor", "wiring_harness", "ecm"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 2]}',1);
