INSERT OR IGNORE INTO dtc_codes VALUES('P2EB4','P','Hybrid/EV Battery Inductive Charger High Voltage Interlock Circuit/Open','Hybrid/EV-Batterie-Induktivlader HV-Verriegelungs-Stromkreis offen','The inductive charger reports a high voltage interlock circuit/open condition. Inductive charging cannot proceed reliably.','Der Induktivlader meldet einen Zustand "HV-Verriegelungs-Stromkreis offen". Das induktive Laden kann nicht zuverlässig erfolgen.','["hv_inductive_charger"]','[{"id": "interlock_open", "p": "high", "en": "Interlock chain interrupted", "de": "Verriegelungskette unterbrochen"}, {"id": "connector_loose", "p": "medium", "en": "Connector not seated", "de": "Stecker nicht eingerastet"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 8]}',1);
