INSERT OR IGNORE INTO dtc_codes VALUES('P2EB7','P','Replace 12V Battery','12V-Batterie ersetzen','The vehicle electrical system reports that the 12V auxiliary battery has reached end-of-life and should be replaced. State-of-health below threshold.','Das Bordnetz meldet, dass die 12V-Hilfsbatterie das Lebensdauer-Ende erreicht hat und ersetzt werden sollte. Gesundheitszustand unter Schwelle.','["aux_12v_battery"]','[{"id": "battery_aged", "p": "high", "en": "12V battery aged", "de": "12V-Batterie gealtert"}, {"id": "deep_discharge", "p": "medium", "en": "Repeated deep discharge events", "de": "Wiederholte Tiefentladungs-Ereignisse"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.3, 1.5]}',1);
