INSERT OR IGNORE INTO dtc_codes VALUES('P2EBF','P','Battery Charging Mode Switch Stuck','Batterielade-Modus-Schalter festsitzend','The battery charging mode switch is mechanically stuck in one position. Driver cannot change between charging modes.','Der Batterielade-Modus-Schalter sitzt mechanisch in einer Position fest. Der Fahrer kann nicht zwischen Lademodi wechseln.','["battery_charging_mode_switch"]','[{"id": "switch_failed", "p": "high", "en": "Switch mechanically stuck", "de": "Schalter mechanisch festsitzend"}, {"id": "contacts_oxidised", "p": "medium", "en": "Contacts oxidised", "de": "Kontakte oxidiert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('P2EC0','P','Turbocharger Compressor Outlet Temperature Sensor Circuit Low','Turbolader-Verdichter-Auslass-Temperatursensor Stromkreis niedrig','The turbocharger compressor outlet temperature sensor reports a circuit low fault. Charge air temperature post-compressor is unreliable.','Der Verdichter-Auslass-Temperatursensor des Turboladers meldet einen Fehler "Stromkreis niedrig". Die Ladelufttemperatur nach dem Verdichter ist unzuverlässig.','["turbo_compressor_outlet_temp_sensor", "wiring_harness", "ecm"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masse kurzgeschlossen"}, {"id": "sensor_internal_short", "p": "medium", "en": "Internal sensor short", "de": "Interner Sensor-Kurzschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 2]}',1);
