INSERT OR IGNORE INTO dtc_codes VALUES('U0045','N','Vehicle Communication Bus B (-) shorted to Bus B (+)','Fahrzeug-Kommunikationsbus B (-) mit Bus B (+) kurzgeschlossen','The two lines of differential bus B are shorted together. A communication loss with this module breaks any function relying on its data — diagnostic tools may show ''no response'' and dependent modules can fall into limp mode.','Die beiden Leitungen des Differential-Bus B sind miteinander kurzgeschlossen. Ein Kommunikationsausfall mit diesem Modul bricht jede Funktion, die seine Daten benötigt — Diagnosegeräte zeigen ''keine Antwort'' und abhängige Steuergeräte können in den','["bus_b_wiring"]','[{"id": "short_between_lines", "p": "high", "en": "Bus lines shorted together", "de": "Bus-Leitungen untereinander kurzgeschlossen"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [100, 1500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0046','N','Vehicle Communication Bus C','Fahrzeug-Kommunikationsbus C','Generic fault on bus C (third bus, often chassis CAN or diagnostic CAN). A communication loss with this module breaks any function relying on its data — diagnostic tools may show ''no response'' and dependent modules can fall into limp mode.','Allgemeiner Fehler am Bus C (dritter Bus, oft Chassis-CAN oder Diagnose-CAN). Ein Kommunikationsausfall mit diesem Modul bricht jede Funktion, die seine Daten benötigt — Diagnosegeräte zeigen ''keine Antwort'' und abhängige Steuergeräte können in den','["bus_c_wiring", "bus_c_nodes"]','[{"id": "bus_fault", "p": "high", "en": "Wiring or node fault on bus C", "de": "Verkabelungs- oder Knotenfehler auf Bus C"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [100, 1500], "estimated_hours": [1, 6]}',1);
