INSERT OR IGNORE INTO dtc_codes VALUES('U0060','N','Vehicle Communication Bus F (+) Open','Fahrzeug-Kommunikationsbus F (+) unterbrochen','The plus line of vehicle bus F is open. Used by some vehicles for body or infotainment subnets; loss disables those features.','Die Plus-Leitung des Fahrzeugbus F ist unterbrochen. Wird in einigen Fahrzeugen für Karosserie- oder Infotainment-Subnetze verwendet, beim Ausfall fallen diese Funktionen aus.','["can_high_wire"]','[{"id": "canh_open", "p": "high", "en": "Bus-F high wire broken", "de": "Bus-F-High-Leitung unterbrochen"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 700], "estimated_hours": [1.0, 5.0]}',1);
