INSERT OR IGNORE INTO dtc_codes VALUES('U0091','N','CAN Communication Bus "C" Off','CAN-Kommunikationsbus "C" abgeschaltet','Bus C (third CAN bus, often used for chassis or infotainment) has entered the bus-off state. All modules on Bus C lose communication.','Bus C (dritter CAN-Bus, oft für Fahrwerk oder Infotainment) ist in den Bus-Off-Zustand gegangen. Alle Steuergeräte an Bus C verlieren die Kommunikation.','["can_bus_wiring", "can_terminating_resistor"]','[{"id": "bus_c_short", "p": "high", "en": "Bus C shorted to supply or ground", "de": "Bus C gegen Versorgung oder Masse kurzgeschlossen"}, {"id": "bus_c_terminator", "p": "medium", "en": "Bus C terminating resistor failed", "de": "Abschlusswiderstand von Bus C defekt"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 1500], "estimated_hours": [1.0, 6.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0092','N','CAN Communication Bus "C" Performance','CAN-Kommunikationsbus "C" Leistungsfehler','Bus C shows degraded performance with elevated error counters but has not yet gone bus-off. Sporadic message losses on modules attached to Bus C.','Bus C zeigt verschlechterte Leistung mit erhöhten Fehlerzählern, ist aber noch nicht im Bus-Off-Zustand. Sporadische Nachrichtenverluste an Steuergeräten an Bus C.','["can_bus_wiring"]','[{"id": "marginal_bus_c", "p": "high", "en": "Marginal Bus C wiring or connector", "de": "Grenzwertige Bus-C-Verkabelung oder Stecker"}, {"id": "bus_c_module_marginal", "p": "medium", "en": "One module on Bus C transmitting marginal frames", "de": "Ein Steuerger\u00e4t an Bus C sendet grenzwertige Frames"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 1200], "estimated_hours": [1.0, 5.0]}',1);
