INSERT OR IGNORE INTO dtc_codes VALUES('U015D','N','Lost Communication With Automated Driving System Control Module B','Kommunikationsverlust mit Automatisiertes-Fahren-Steuermodul B','Lost Communication With Automated Driving System Control Module B: the control module has detected this fault condition.','Kommunikationsverlust mit Automatisiertes-Fahren-Steuermodul B: das Steuergerät hat diesen Fehlerzustand erkannt.','["ads_module_b", "can_bus"]','[{"id": "module_unpowered", "p": "high", "en": "Module unpowered", "de": "Modul ohne Spannung"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 3000], "estimated_hours": [1, 8]}',1);
