INSERT OR IGNORE INTO dtc_codes VALUES('U0175','N','Lost Communication With Restraints System Sensor F','Kommunikationsverlust mit Rückhaltesystem-Sensor F','ECU lost CAN/dedicated-bus communication with restraints system sensor F (airbag/seatbelt sensor). A communication loss with this module breaks any function relying on its data — diagnostic tools may show ''no response'' and dependent modules can fal','Steuergerät hat die Kommunikation zum Rückhaltesystem-Sensor F (Airbag/Gurtsensor) verloren. Ein Kommunikationsausfall mit diesem Modul bricht jede Funktion, die seine Daten benötigt — Diagnosegeräte zeigen ''keine Antwort'' und abhängige Steuergerät','["restraints_sensor_f", "can_bus"]','[{"id": "sensor_unpowered", "p": "high", "en": "Sensor unpowered or wiring broken", "de": "Sensor ohne Spannung oder Verkabelung unterbrochen"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1, 4]}',1);
