INSERT OR IGNORE INTO dtc_codes VALUES('U0177','N','Lost Communication with Mirror Memory Module','Kommunikation mit Spiegel-Memory-Modul verloren','The Mirror Memory Module has stopped transmitting on the vehicle data bus, so other control units no longer receive its messages. Memory mirror positioning stops working. Typical causes are loss of power or ground at the module, an open or shorted CA','Spiegel-Memory-Modul — diese Komponente sendet keine Botschaften mehr auf dem Datenbus, sodass andere Steuergeräte die benötigten Informationen nicht mehr erhalten. Die Spiegel-Memory-Verstellung funktioniert nicht mehr. Typische Ursachen sind fehlen','["mirror_memory_module", "can_bus_wiring"]','[{"id": "mirror_module_unpowered", "p": "high", "en": "Mirror module unpowered", "de": "Spiegel-Modul ohne Spannung"}, {"id": "mirror_wiring", "p": "medium", "en": "CAN wiring to mirror module broken", "de": "CAN-Leitung zum Spiegel-Modul unterbrochen"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 700], "estimated_hours": [0.5, 2.5]}',0);
