INSERT OR IGNORE INTO dtc_codes VALUES('U0197','N','Lost Communication with Hands-Free Phone Control Module','Kommunikation mit Freisprecheinrichtungs-Steuergerät verloren','The infotainment system cannot reach the hands-free phone controller. Bluetooth telephony, address book sync and emergency call features may be unavailable.','Das Infotainment kann das Steuergerät der Freisprecheinrichtung nicht erreichen. Bluetooth-Telefonie, Adressbuch-Synchronisation und Notruffunktionen können ausfallen.','["hands_free_module", "infotainment_bus"]','[{"id": "hf_module_unpowered", "p": "high", "en": "Hands-free module unpowered", "de": "Freisprech-Modul ohne Spannung"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 500], "estimated_hours": [0.3, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0198','N','Lost Communication with Telematic Control Module','Kommunikation mit Telematik-Steuergerät verloren','The vehicle has lost the telematics module (eCall / Connected Services / TCU). Emergency call, remote services and over-the-air features are unavailable until the module is back online.','Das Fahrzeug hat das Telematik-Steuergerät (eCall / Connected Services / TCU) verloren. Notruf, Remote-Dienste und Over-the-Air-Funktionen sind nicht verfügbar, bis das Modul wieder online ist.','["telematics_module", "can_bus_wiring"]','[{"id": "tcu_unpowered", "p": "high", "en": "TCU unpowered or backup battery dead", "de": "TCU ohne Spannung oder Backup-Batterie leer"}, {"id": "antenna_open", "p": "low", "en": "Mobile antenna disconnected", "de": "Mobilfunkantenne getrennt"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [100, 1200], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0199','N','Lost Communication with Door Control Module','Kommunikation mit Tür-Steuergerät verloren','The Door Control Module has stopped transmitting on the vehicle data bus, so other control units no longer receive its messages. A door control module is silent; its window, lock, and mirror controls fail. Typical causes are loss of power or ground a','Tür-Steuergerät — diese Komponente sendet keine Botschaften mehr auf dem Datenbus, sodass andere Steuergeräte die benötigten Informationen nicht mehr erhalten. Ein Türsteuergerät meldet sich nicht; Fensterheber, Verriegelung und Spiegel fallen aus. T','["door_control_module", "can_bus_wiring"]','[{"id": "door_module_unpowered", "p": "high", "en": "Door module unpowered (often broken wires in door hinge)", "de": "T\u00fcr-Modul ohne Spannung (oft gebrochene Dr\u00e4hte im T\u00fcrscharnier)"}, {"id": "water_in_door_module", "p": "medium", "en": "Water ingress into door module", "de": "Wassereinbruch ins T\u00fcr-Modul"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [1.0, 3.0]}',0);
