INSERT OR IGNORE INTO dtc_codes VALUES('U0229','N','Lost Communication With Heated Steering Wheel Module','Kommunikationsverlust mit Lenkradheizungs-Modul','ECU lost communication with the heated steering wheel module. A communication loss with this module breaks any function relying on its data — diagnostic tools may show ''no response'' and dependent modules can fall into limp mode.','Steuergerät hat die Kommunikation zum Lenkradheizungs-Modul verloren. Ein Kommunikationsausfall mit diesem Modul bricht jede Funktion, die seine Daten benötigt — Diagnosegeräte zeigen ''keine Antwort'' und abhängige Steuergeräte können in den Notlauf','["heated_steering_module", "can_bus"]','[{"id": "module_unpowered", "p": "high", "en": "Module unpowered", "de": "Modul ohne Spannung"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
