INSERT OR IGNORE INTO dtc_codes VALUES('U0235','N','Lost Communication with Cruise Control Front Distance Range Sensor','Kommunikation mit Abstandssensor (ACC) verloren','Adaptive cruise control has lost the front radar / distance sensor. ACC is deactivated, fixed-speed cruise may stay available, and forward collision warning is disabled.','Der Abstandsregeltempomat hat den Frontradar-/Abstandssensor verloren. ACC wird deaktiviert, der konventionelle Tempomat bleibt eventuell verfügbar, der Frontkollisionswarner ist abgeschaltet.','["acc_radar", "can_bus_wiring"]','[{"id": "radar_obstructed", "p": "high", "en": "Radar obstructed or misaligned", "de": "Radar verschmutzt oder dejustiert"}, {"id": "radar_unpowered", "p": "medium", "en": "Radar unpowered", "de": "Radar ohne Spannung"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 1500], "estimated_hours": [0.5, 3.0]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0236','N','Lost Communication with Steering Angle Sensor Module','Kommunikation mit Lenkwinkelsensor-Modul verloren','The ESP / power steering controller has lost the steering angle sensor. ESP is deactivated and lane-keeping assistance is disabled.','Das ESP-/Lenkungs-Steuergerät hat den Lenkwinkelsensor verloren. ESP wird deaktiviert, Spurhalteassistent ist abgeschaltet.','["steering_angle_sensor", "clockspring", "can_bus_wiring"]','[{"id": "sensor_uncalibrated", "p": "medium", "en": "Sensor lost calibration after repair", "de": "Sensor nach Reparatur ohne Kalibrierung"}, {"id": "clockspring_failed", "p": "medium", "en": "Clockspring failed", "de": "Wickelfeder defekt"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.5, 3.0]}',1);
