INSERT OR IGNORE INTO dtc_codes VALUES('U025D','N','Lost Communication With Front Controls Interface Module B','Kommunikationsverlust zum Front-Bedien-Interface-Modul B','The vehicle bus reports loss of communication with the front controls interface module B. Hard-keys, rotary knob and steering-wheel switches that route through this module stop being recognised.','Der Fahrzeugbus meldet Kommunikationsverlust zum Front-Bedien-Interface-Modul B. Tasten, Dreh-Drück-Steller und Lenkradtasten, die über dieses Modul laufen, werden nicht mehr erkannt.','["front_controls_interface_module_b", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U025E','N','Lost Communication With Electronic Brake Booster Control Module A','Kommunikationsverlust zum elektronischen Bremskraftverstärker-Steuergerät A','The vehicle bus reports loss of communication with electronic brake booster module A. Boost assist, brake-by-wire pedal feedback and regenerative-brake blending coordinated by this node may revert to a degraded mode.','Der Fahrzeugbus meldet Kommunikationsverlust zum elektronischen Bremskraftverstärker-Steuergerät A. Verstärker-Assistenz, Brake-by-Wire-Pedalrückmeldung und Mischung mit Rekuperation aus diesem Knoten können in den Notlauf wechseln.','["electronic_brake_booster_module_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1, 5]}',1);
