INSERT OR IGNORE INTO dtc_codes VALUES('U028A','N','Lost Communication With Transmission Fluid Pump Module B','Kommunikationsverlust zum Getriebeöl-Pumpe-Steuergerät B','The vehicle bus reports loss of communication with transmission fluid pump module B. Auxiliary ATF pumping during start/stop or hybrid coast cannot be commanded, which may delay shifts or impair cooling.','Der Fahrzeugbus meldet Kommunikationsverlust zum Getriebeöl-Pumpe-Steuergerät B. Zusätzliches ATF-Pumpen im Start/Stop oder Hybrid-Coasting kann nicht angefordert werden, was Schaltungen verzögern oder die Kühlung beeinträchtigen kann.','["transmission_fluid_pump_module_b", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
