INSERT OR IGNORE INTO dtc_codes VALUES('U028C','N','Lost Communication With Active Grille Air Shutter Module D','Kommunikationsverlust zur aktiven Kühlergrill-Luftklappe-Steuerung D','The vehicle bus reports loss of communication with active grille shutter module D. The aerodynamic flaps in front of the radiator stay in their default position, increasing drag and possibly affecting cooling.','Der Fahrzeugbus meldet Kommunikationsverlust zur aktiven Kühlergrill-Luftklappe-Steuerung D. Die aerodynamischen Klappen vor dem Kühler bleiben in der Default-Stellung, was Luftwiderstand erhöht und Kühlung beeinflussen kann.','["active_grille_shutter_module_d", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 900], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U028D','N','Lost Communication With Active Aerodynamic Feature Control Module A','Kommunikationsverlust zur Aktiv-Aerodynamik-Steuerung A','The vehicle bus reports loss of communication with active aerodynamic feature module A. Powered spoilers, air-dams or wheel-arch closures controlled by this node default to a fixed position.','Der Fahrzeugbus meldet Kommunikationsverlust zur Aktiv-Aerodynamik-Steuerung A. Elektrisch verstellbare Spoiler, Luftleitwände oder Radkasten-Verschlüsse dieses Knotens fallen in eine feste Position zurück.','["active_aero_module_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [0.5, 3]}',0);
