INSERT OR IGNORE INTO dtc_codes VALUES('U041A','N','Invalid Data Received From Battery Isolation/Voltage Stabilization Control Module','Ungültige Daten vom Batterietrenn-/Spannungsstabilisierungs-Steuergerät','A receiving module detected implausible data from the battery isolation / voltage stabilization module (typical in start/stop systems). Switching state or stabilizer voltage values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Batterietrenn-/Spannungsstabilisierungs-Steuergerät (typisch in Start/Stop-Systemen). Schaltzustand oder Stabilisator-Spannung bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["battery_isolation_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U041B','N','Invalid Data Received From Exhaust Gas Sensor Module A','Ungültige Daten vom Abgassensor-Modul A','A receiving module detected implausible data from exhaust gas sensor module A (smart wide-range O2 / lambda module). Lambda or pumping current values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Abgassensor-Modul A (smarter Breitband-O2-/Lambda-Sensor). Lambda- oder Pumpstromwerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["exhaust_gas_sensor_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U041C','N','Invalid Data Received From Rocker Arm Control Module A','Ungültige Daten vom Kipphebel-Steuergerät A','A receiving module detected implausible data from rocker arm actuator module A (variable valve lift / cylinder deactivation). Position or pressure feedback fails plausibility checks and is rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Kipphebel-Aktor-Modul A (variabler Ventilhub / Zylinderabschaltung). Position oder Druckrückmeldung bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["rocker_arm_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U041D','N','Invalid Data Received From Rocker Arm Control Module B','Ungültige Daten vom Kipphebel-Steuergerät B','A receiving module detected implausible data from rocker arm actuator module B (variable valve lift / cylinder deactivation). Position or pressure feedback fails plausibility checks and is rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Kipphebel-Aktor-Modul B (variabler Ventilhub / Zylinderabschaltung). Position oder Druckrückmeldung bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["rocker_arm_module_b"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U041E','N','Invalid Data Received From All Wheel Drive Control Module','Ungültige Daten vom Allrad-Steuergerät','A receiving module detected implausible data from the AWD control module. Torque distribution or clutch position values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Allrad-Steuergerät. Drehmoment-Verteilung oder Kupplungsposition bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["awd_control_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [0.5, 3]}',1);
