INSERT OR IGNORE INTO dtc_codes VALUES('U0421','N','Invalid Data Received from Throttle/Pedal Position Sensor','Ungültige Daten vom Drosselklappen-/Pedalwertgeber empfangen','The ECU receives implausible accelerator pedal or throttle data over the bus. The engine drops to limp-mode with reduced power.','Die Motorsteuerung empfängt unplausible Werte des Gas-/Drosselklappenpotis über den Bus. Der Motor geht in den Notlauf mit reduzierter Leistung.','["accelerator_pedal_sensor", "throttle_actuator"]','[{"id": "pedal_sensor_failed", "p": "medium", "en": "Pedal sensor partially failed", "de": "Pedalsensor teilweise defekt"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}, {"id": "terminator_resistor_drift", "p": "low", "en": "CAN terminating resistor (120 \u03a9) drifted out of spec", "de": "CAN-Abschlusswiderstand (120 \u03a9) au\u00dferhalb der Spezifikation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.3, 2.0]}',1);
