INSERT OR IGNORE INTO dtc_codes VALUES('U0473','N','Invalid Data Received From Restraints System Sensor C','Ungültige Daten vom Rückhaltesystem-Sensor C','A receiving module detected implausible data from restraints system sensor C (satellite crash sensor). Acceleration profile values fail plausibility checks against other crash sensors and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Rückhaltesystem-Sensor C (Satelliten-Crashsensor). Beschleunigungsprofile bestehen Plausibilitätsprüfungen gegen andere Crashsensoren nicht und werden verworfen.','["restraints_system_sensor_c"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
