INSERT OR IGNORE INTO dtc_codes VALUES('U0476','N','Invalid Data Received from Driver Assistance System','Ungültige Daten vom Fahrerassistenzsystem empfangen','The Driver Assistance System is present on the data bus but the values it reports are implausible — out of range, frozen, or failing the checksum or rolling-count check. The receiving modules reject the data. Driver-assist features such as lane keepi','Fahrerassistenzsystem — diese Komponente ist zwar am Datenbus aktiv, liefert aber unplausible Werte (außerhalb des Bereichs, eingefroren oder mit fehlerhafter Prüfsumme bzw. Zählung). Die empfangenden Steuergeräte verwerfen die Daten. Fahrerassistenz','["driver_assistance_module", "can_bus_wiring"]','[{"id": "adas_calibration_lost", "p": "high", "en": "ADAS calibration lost (after windshield/bumper repair)", "de": "ADAS-Kalibrierung verloren (nach Windschutzscheiben-/Sto\u00dfstangen-Reparatur)"}, {"id": "adas_sensor_obstructed", "p": "medium", "en": "Sensor obstructed (dirt, snow, sticker)", "de": "Sensor verdeckt (Schmutz, Schnee, Aufkleber)"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 1500], "estimated_hours": [1.0, 4.0]}',1);
