INSERT OR IGNORE INTO dtc_codes VALUES('U0481','N','Invalid Data Received From Automatic Lighting Control Module','Ungültige Daten vom Automatik-Licht-Steuergerät','A receiving module detected implausible data from the automatic lighting (ambient light/rain sensor) control module. Lux or wiper-trigger values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Automatik-Licht-Steuergerät (Umgebungslicht-/Regensensor). Lux oder Wischer-Trigger bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["automatic_lighting_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 1.5]}',0);
