INSERT OR IGNORE INTO dtc_codes VALUES('U0492','N','Invalid Data Received From Television','Ungültige Daten vom TV-Modul','A receiving module detected implausible data from the rear-seat TV/DVB tuner module. Channel, source or fault status values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Fond-TV-/DVB-Tuner-Modul. Kanal, Quelle oder Fehler-Status bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["tv_tuner_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0493','N','Invalid Data Received From Personal Computer','Ungültige Daten vom Bord-Personal-Computer','A receiving module detected implausible data from the on-board personal computer (commercial fleet/police laptop dock with vehicle interface). Status values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Bord-Personal-Computer (Flotten-/Polizei-Laptop-Dock mit Fahrzeug-Interface). Statuswerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["on_board_pc"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [0.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0494','N','Invalid Data Received From Digital Audio Control Module A','Ungültige Daten vom Digital-Audio-Steuergerät A','A receiving module detected implausible data from digital audio control module A (DSP / source matrix). Channel routing, EQ or volume values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Digital-Audio-Steuergerät A (DSP/Quell-Matrix). Kanal-Routing, EQ oder Lautstärke bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["digital_audio_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',0);
