INSERT OR IGNORE INTO dtc_codes VALUES('U0496','N','Invalid Data Received From Subscription Entertainment Receiver Module','Ungültige Daten vom Abo-Entertainment-Empfänger-Modul','A receiving module detected implausible data from the subscription entertainment receiver (satellite radio/TV with subscription). Stream or authentication state values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Abo-Entertainment-Empfänger (Satellitenradio/-TV mit Abo). Stream- oder Auth-Status bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["subscription_entertainment_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',0);
