INSERT OR IGNORE INTO dtc_codes VALUES('U0498','N','Invalid Data Received From Telephone Control Module','Ungültige Daten vom Telefon-Steuergerät','A receiving module detected implausible data from the telephone control module (Bluetooth/handsfree). Pairing, call state or audio routing values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Telefon-Steuergerät (Bluetooth-/Freisprecheinrichtung). Pairing, Anruf-Status oder Audio-Routing bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["telephone_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 2]}',0);
