INSERT OR IGNORE INTO dtc_codes VALUES('U049A','N','Invalid Data Received From Door Control Module A','Ungültige Daten vom Türsteuergerät A','A receiving module detected implausible data from door control module A. Door status, lock state, window or mirror values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Türsteuergerät A. Tür-, Verriegelungs-, Fenster- oder Spiegel-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["door_control_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1000], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U049B','N','Invalid Data Received From Tachograph Module','Ungültige Daten vom Tachograph-Modul','A receiving module detected implausible data from the digital tachograph module (commercial vehicle driving-time recorder). Speed, distance or driver-card values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom digitalen Tachographen-Modul (Lenkzeit-Schreiber für Nutzfahrzeuge). Geschwindigkeit, Wegstrecke oder Fahrerkarten-Daten bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["tachograph_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U049C','N','Invalid Data Received From Battery Charger Control Module A','Ungültige Daten vom Batterielade-Steuergerät A','A receiving module detected implausible data from battery charger control module A (on-board AC charger). Charge current, voltage or grid sync values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Batterielade-Steuergerät A (On-Board-AC-Lader). Ladestrom, Spannung oder Netz-Sync bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["battery_charger_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U049D','N','Invalid Data Received From Glow Plug Control Module 2','Ungültige Daten vom Glühkerzen-Steuergerät 2','A receiving module detected implausible data from glow plug control module 2. Plug current/voltage or temperature values fail plausibility checks and are rejected; cold-start strategy reverts to fail-safe.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Glühkerzen-Steuergerät 2. Glühkerzen-Strom/-Spannung oder Temperatur bestehen Plausibilitätsprüfungen nicht und werden verworfen; Kaltstart-Strategie wechselt in Notlauf.','["glow_plug_module_2"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',1);
