INSERT OR IGNORE INTO dtc_codes VALUES('U04B1','N','Invalid Data Received From Battery Monitor Module','Ungültige Daten vom Batterie-Überwachungs-Modul','A receiving module detected implausible data from the 12-V battery monitor (intelligent battery sensor). Voltage, current or temperature values fail plausibility checks and are rejected; SoC estimation reverts to a default model.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom 12-V-Batterie-Überwachungs-Modul (intelligenter Batteriesensor). Spannung, Strom oder Temperatur bestehen Plausibilitätsprüfungen nicht und werden verworfen; SoC-Schätzung wechselt auf Default','["battery_monitor_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 1.5]}',1);
