INSERT OR IGNORE INTO dtc_codes VALUES('U04B3','N','Invalid Data Received From Planetary Gear Set Control Module','Ungültige Daten vom Planetenrad-Getriebe-Steuergerät','A receiving module detected implausible data from the planetary gear set control module (typical in power-split hybrid eCVT). Speed/torque distribution values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Planetenrad-Getriebe-Steuergerät (typisch in Power-Split-Hybrid-eCVT). Drehzahl-/Moment-Verteilung bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["planetary_gear_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 4000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U04B4','N','Invalid Data Received From Brake Blending Actuator','Ungültige Daten vom Brake-Blending-Aktor','A receiving module detected implausible data from the brake blending actuator (manages mix of regen + friction braking on hybrids/EVs). Pressure command vs. actual fails plausibility checks and is rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Brake-Blending-Aktor (Mischung aus Rekuperation + Reibungsbremse bei Hybriden/EVs). Druck-Sollwert vs. Ist besteht Plausibilitätsprüfungen nicht und wird verworfen.','["brake_blending_actuator"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
