INSERT OR IGNORE INTO dtc_codes VALUES('U04BD','N','Invalid Data Received From Park Lock/Pawl Control Module','Ungültige Daten vom Parksperren-Steuergerät','A receiving module detected implausible data from the park lock/pawl control module (electric park-pawl actuator on shift-by-wire transmissions). Engaged/released state values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Parksperren-Steuergerät (elektrischer Pawl-Aktor an Shift-by-Wire-Getrieben). Eingerastet/gelöst-Status bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["park_lock_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U04BE','N','Invalid Data Received From Battery Charger Control Module B','Ungültige Daten vom Batterielade-Steuergerät B','A receiving module detected implausible data from battery charger control module B (on-board AC charger). Charge current, voltage or grid sync values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Batterielade-Steuergerät B (On-Board-AC-Lader). Ladestrom, Spannung oder Netz-Sync bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["battery_charger_module_b"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U04BF','N','Invalid Data Received From Drive Motor A Clutch Actuator','Ungültige Daten vom Antriebsmotor-A-Kupplungsaktor','A receiving module detected implausible data from the drive motor A clutch actuator (engagement clutch on hybrid drivetrains). Position or pressure values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Antriebsmotor-A-Kupplungsaktor (Eingriffskupplung an Hybrid-Antrieben). Position oder Druck bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["drive_motor_a_clutch_actuator"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U04C0','N','Invalid Data Received From Battery Management Control Module','Ungültige Daten vom Batterie-Management-Steuergerät','A receiving module detected implausible data from the battery management control module (BMS master). SoC, SoH, current or voltage values fail plausibility checks against other inputs and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Batterie-Management-Steuergerät (BMS-Master). SoC, SoH, Strom oder Spannung bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["bms"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0500','N','Invalid Data Received from Communication Module','Ungültige Daten vom Kommunikationsmodul empfangen','A control module receives data from the telematics/communication module that is implausible, has the wrong format or fails checksum. Connected services and emergency-call functions may stop working.','Ein Steuergerät empfängt Daten vom Telematik-/Kommunikationsmodul, die unplausibel sind, falsches Format haben oder die Checksumme verfehlen. Connected Services und Notruffunktion können ausfallen.','["communication_module", "can_bus_wiring"]','[{"id": "comm_module_firmware", "p": "high", "en": "Communication module firmware out of date", "de": "Kommunikationsmodul-Firmware veraltet"}, {"id": "comm_module_internal_fault", "p": "medium", "en": "Communication module internal fault", "de": "Interner Fehler im Kommunikationsmodul"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [80, 1500], "estimated_hours": [0.5, 4.0]}',1);
