INSERT OR IGNORE INTO dtc_codes VALUES('U0513','N','Invalid Data Received From Yaw Rate Sensor Module','Ungültige Daten vom Gier-Raten-Sensor-Modul','A receiving module detected implausible data from the yaw rate sensor module (typically combined with lateral/longitudinal accelerometer). Rotational rate values fail plausibility checks against steering and wheel speed and are rejected; ESC may be i','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Gier-Raten-Sensor-Modul (meist mit Quer-/Längsbeschleunigung kombiniert). Drehraten bestehen Plausibilitätsprüfungen gegen Lenkwinkel und Raddrehzahl nicht und werden verworfen; ESC kann deakt','["yaw_rate_sensor_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
