INSERT OR IGNORE INTO dtc_codes VALUES('U0531','N','Invalid Data Received From Rear Gate Module','Ungültige Daten vom Heckklappen-Modul','A receiving module detected implausible data from the rear gate (powered tailgate/liftgate) module. Position, motor current or anti-pinch values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Heckklappen-Modul (elektrische Heckklappe). Position, Motorstrom oder Einklemmschutz-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["rear_gate_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0532','N','Invalid Data Received From Rain Sensing Module','Ungültige Daten vom Regensensor-Modul','A receiving module detected implausible data from the rain sensing module. Wetness/intensity values fail plausibility checks and are rejected; auto-wipers may revert to fixed intermittent or off.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Regensensor-Modul. Nässe-/Intensitäts-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen; Auto-Wischer wechseln auf festen Intervall oder Aus.','["rain_sensor_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0533','N','Invalid Data Received From Side Obstacle Detection Control Module A','Ungültige Daten vom Seitenhindernis-Erkennungs-Steuergerät A','A receiving module detected implausible data from side obstacle detection module A (corner radar). Distance/closing-speed values fail plausibility checks and are rejected; blind-spot warning may be inhibited.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Seitenhindernis-Erkennungs-Steuergerät A (Eck-Radar). Abstands-/Geschwindigkeits-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen; Toter-Winkel-Warnung kann deaktiviert werden','["side_obstacle_detection_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',0);
