INSERT OR IGNORE INTO dtc_codes VALUES('U0535','N','Invalid Data Received From Convenience Recall Module','Ungültige Daten vom Komfort-Memory-Modul','A receiving module detected implausible data from the convenience recall module (per-driver presets for seat, mirror, climate, audio). Profile data fails plausibility checks and is rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Komfort-Memory-Modul (fahrer-spezifische Voreinstellungen für Sitz, Spiegel, Klima, Audio). Profil-Daten bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["convenience_recall_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0536','N','Invalid Data Received From Lateral Acceleration Sensor Module','Ungültige Daten vom Quer-Beschleunigungssensor-Modul','A receiving module detected implausible data from the lateral acceleration sensor module. Lateral g values fail plausibility checks against steering and yaw rate and are rejected; ESC may be inhibited.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Quer-Beschleunigungssensor-Modul. Quer-g-Werte bestehen Plausibilitätsprüfungen gegen Lenkwinkel und Gierrate nicht und werden verworfen; ESC kann deaktiviert werden.','["lateral_acceleration_sensor_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0537','N','Invalid Data Received From Column Lock Module','Ungültige Daten vom Lenksäulen-Verriegelungs-Modul','A receiving module detected implausible data from the steering column lock (ELV) module. Lock/unlock state values fail plausibility checks and are rejected; the engine may refuse to start.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom elektronischen Lenkschloss-Modul (ELV). Verriegelungs-Status bestehen Plausibilitätsprüfungen nicht und werden verworfen; der Motor kann den Start verweigern.','["column_lock_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0538','N','Invalid Data Received From Digital Audio Control Module C','Ungültige Daten vom Digital-Audio-Steuergerät C','A receiving module detected implausible data from digital audio control module C (DSP / source matrix). Channel routing, EQ or volume values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Digital-Audio-Steuergerät C (DSP/Quell-Matrix). Kanal-Routing, EQ oder Lautstärke bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["digital_audio_module_c"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U0539','N','Invalid Data Received From Digital Audio Control Module D','Ungültige Daten vom Digital-Audio-Steuergerät D','A receiving module detected implausible data from digital audio control module D (DSP / source matrix). Channel routing, EQ or volume values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Digital-Audio-Steuergerät D (DSP/Quell-Matrix). Kanal-Routing, EQ oder Lautstärke bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["digital_audio_module_d"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1200], "estimated_hours": [0.5, 3]}',0);
