INSERT OR IGNORE INTO dtc_codes VALUES('U0594','N','Invalid Data Received From Hybrid/EV Powertrain Control Module','Ungültige Daten vom Hybrid-/EV-Antriebsstrang-Steuergerät','A receiving module detected implausible data from the hybrid/EV powertrain control module (master coordinator for engine + motor + battery). Torque request or mode-state values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Hybrid-/EV-Antriebsstrang-Steuergerät (Master-Koordinator für Motor + E-Maschine + Batterie). Momentanforderung oder Modus-Status bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["hev_ev_powertrain_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0595','N','Invalid Data Received From Powertrain Control Monitor Module','Ungültige Daten vom Antriebsstrang-Überwachungs-Modul','A receiving module detected implausible data from the powertrain control monitor (independent watchdog comparing ECM/PCM commands against sensor inputs). Status flags fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Antriebsstrang-Überwachungs-Modul (unabhängiger Watchdog, der ECM-/PCM-Befehle gegen Sensoreingänge prüft). Status-Flags bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["powertrain_monitor_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1, 5]}',1);
