INSERT OR IGNORE INTO dtc_codes VALUES('U05A1','N','NOx Sensor A Received Invalid Data From ECM/PCM','NOx-Sensor A erhielt ungültige Daten vom ECM/PCM','NOx sensor A (smart sensor with own ECU) received implausible data from the ECM/PCM. Engine load, fuel rate or temperature data needed for the sensor''s internal compensation fails plausibility checks; the sensor reports degraded readings.','NOx-Sensor A (smarter Sensor mit eigenem Steuergerät) erhielt unstimmige Daten vom ECM/PCM. Motorlast, Kraftstoffrate oder Temperaturdaten, die der Sensor für die interne Kompensation benötigt, bestehen Plausibilitätsprüfungen nicht; der Sensor melde','["nox_sensor_a", "ecm"]','[{"id": "module_internal_fault", "p": "high", "en": "ECM/PCM internal fault or sensor input drift", "de": "Interner ECM-/PCM-Fehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1, 5]}',1);
