INSERT OR IGNORE INTO dtc_codes VALUES('U05A3','N','Invalid Data Received From Reductant Quality Module','Ungültige Daten vom AdBlue-Qualitäts-Modul','A receiving module detected implausible data from the reductant (DEF/AdBlue) quality sensor module. Concentration values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom AdBlue-Qualitätssensor-Modul. Konzentrationswerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["reductant_quality_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A4','N','Particulate Matter Sensor Received Invalid Data From ECM/PCM','Partikelsensor erhielt ungültige Daten vom ECM/PCM','The particulate matter (PM) sensor (smart sensor with own ECU) received implausible data from the ECM/PCM. Engine load, exhaust temperature or DPF state data needed for compensation fails plausibility checks; PM readings are degraded.','Der Partikelsensor (smarter Sensor mit eigenem Steuergerät) erhielt unstimmige Daten vom ECM/PCM. Motorlast, Abgastemperatur oder DPF-Status-Daten, die zur Kompensation benötigt werden, bestehen Plausibilitätsprüfungen nicht; PM-Messwerte sind beeint','["pm_sensor", "ecm"]','[{"id": "module_internal_fault", "p": "high", "en": "ECM/PCM internal fault or sensor input drift", "de": "Interner ECM-/PCM-Fehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A5','N','Invalid Data Received From NH3 Sensor','Ungültige Daten vom NH3-Sensor','A receiving module detected implausible data from the ammonia (NH3) slip sensor downstream of the SCR. Concentration values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom NH3-Schlupfsensor hinter dem SCR. Konzentrationswerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["nh3_sensor"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A6','N','Invalid Data Received From Reductant Heater Control Module','Ungültige Daten vom AdBlue-Heizungs-Steuergerät','A receiving module detected implausible data from the reductant heater module. Heater current/voltage or temperature values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom AdBlue-Heizungs-Steuergerät. Heizstrom/-spannung oder Temperatur bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["reductant_heater_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A7','N','Invalid Data Received From Safety Integration Control Module','Ungültige Daten vom Safety-Integration-Steuergerät','A receiving module detected implausible data from the safety integration module that arbitrates between ADAS, restraint, brake and steering systems. Cross-system safety status values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Safety-Integration-Steuergerät, das zwischen ADAS, Rückhaltesystem, Bremse und Lenkung koordiniert. Übergreifende Sicherheits-Status-Werte bestehen Plausibilitätsprüfungen nicht und werden ver','["safety_integration_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A8','N','Invalid Data Received From NOx Sensor C','Ungültige Daten vom NOx-Sensor C','A receiving module detected implausible data from NOx sensor C (smart sensor with own ECU). NOx concentration or pumping current values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom NOx-Sensor C (smarter Sensor mit eigenem Steuergerät). NOx-Konzentration oder Pumpstrom bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["nox_sensor_c"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [350, 1800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05A9','N','NOx Sensor C Received Invalid Data From ECM/PCM','NOx-Sensor C erhielt ungültige Daten vom ECM/PCM','NOx sensor C (smart sensor with own ECU) received implausible data from the ECM/PCM. Engine load, fuel rate or temperature data needed for the sensor''s internal compensation fails plausibility checks; the sensor reports degraded readings.','NOx-Sensor C (smarter Sensor mit eigenem Steuergerät) erhielt unstimmige Daten vom ECM/PCM. Motorlast, Kraftstoffrate oder Temperaturdaten, die der Sensor für die interne Kompensation benötigt, bestehen Plausibilitätsprüfungen nicht; der Sensor melde','["nox_sensor_c", "ecm"]','[{"id": "module_internal_fault", "p": "high", "en": "ECM/PCM internal fault or sensor input drift", "de": "Interner ECM-/PCM-Fehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05AA','N','Invalid Data Received From Charge Air Cooler Coolant Pump','Ungültige Daten von der Ladeluftkühler-Kühlmittelpumpe','A receiving module detected implausible data from the charge air cooler (intercooler) coolant pump. Pump speed or flow values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten von der Ladeluftkühler-Kühlmittelpumpe. Pumpendrehzahl oder Volumenstrom bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["cac_coolant_pump"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05AB','N','Invalid Data Received From Engine Disconnect Clutch','Ungültige Daten von der Motor-Trennkupplung','A receiving module detected implausible data from the hybrid engine disconnect clutch actuator. Position or pressure values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten von der Hybrid-Trennkupplungs-Steuerung. Position oder Druck bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["engine_disconnect_clutch_actuator"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3500], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05AC','N','Invalid Data Received From Vehicle Thermal Management Control Module','Ungültige Daten vom Fahrzeug-Thermomanagement-Steuergerät','A receiving module detected implausible data from the vehicle thermal management module. Coolant loop coordination values fail plausibility checks and are rejected; sub-modules may revert to local control.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Fahrzeug-Thermomanagement-Steuergerät. Kühlkreis-Koordinations-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen; Untergeräte können auf lokale Regelung zurückfallen.','["thermal_management_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B2','N','Invalid Data Received From Comfort and Convenience Display A','Ungültige Daten von der Komfort-/Convenience-Anzeige A','A receiving module detected implausible data from comfort and convenience display A. Display state or input values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten von der Komfort-/Convenience-Anzeige A. Display-Status oder Eingabewerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["comfort_display_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B3','N','Invalid Data Received From Comfort and Convenience Display B','Ungültige Daten von der Komfort-/Convenience-Anzeige B','A receiving module detected implausible data from comfort and convenience display B. Display state or input values fail plausibility checks and are rejected.','Ein empfangendes Steuergerät erkennt unstimmige Daten von der Komfort-/Convenience-Anzeige B. Display-Status oder Eingabewerte bestehen Plausibilitätsprüfungen nicht und werden verworfen.','["comfort_display_b"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B4','N','Invalid Data Received From Driver Monitoring System Module','Ungültige Daten vom Fahrer-Beobachtungs-Modul','A receiving module detected implausible data from the driver monitoring system (DMS) module. Eye/head-pose tracking values fail plausibility checks and are rejected; ADAS handover features may be inhibited.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom Fahrer-Beobachtungs-Modul (DMS). Augen-/Kopfposen-Erfassung bestehen Plausibilitätsprüfungen nicht und werden verworfen; ADAS-Übergabe-Funktionen können deaktiviert sein.','["driver_monitoring_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1800], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B5','N','Invalid Data Received From Front Radar Module A','Ungültige Daten vom vorderen Radar-Modul A','A receiving module detected implausible data from front radar module A. Distance/closing-speed values fail plausibility checks against camera/lidar and are rejected; ACC, AEB and FCW degrade.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom vorderen Radar-Modul A. Abstand-/Geschwindigkeits-Werte bestehen Plausibilitätsprüfungen gegen Kamera/Lidar nicht und werden verworfen; ACC, AEB und FCW werden eingeschränkt.','["front_radar_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B6','N','Invalid Data Received From Front Radar Module B','Ungültige Daten vom vorderen Radar-Modul B','A receiving module detected implausible data from front radar module B. Distance/closing-speed values fail plausibility checks against camera/lidar and are rejected; ACC, AEB and FCW degrade.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom vorderen Radar-Modul B. Abstand-/Geschwindigkeits-Werte bestehen Plausibilitätsprüfungen gegen Kamera/Lidar nicht und werden verworfen; ACC, AEB und FCW werden eingeschränkt.','["front_radar_module_b"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U05B7','N','Invalid Data Received From Rear Radar Module A','Ungültige Daten vom hinteren Radar-Modul A','A receiving module detected implausible data from rear radar module A. Distance/azimuth values fail plausibility checks and are rejected; blind-spot warning and rear cross-traffic alert are inhibited.','Ein empfangendes Steuergerät erkennt unstimmige Daten vom hinteren Radar-Modul A. Abstand-/Azimut-Werte bestehen Plausibilitätsprüfungen nicht und werden verworfen; Toter-Winkel-Warnung und Querverkehrswarnung hinten werden deaktiviert.','["rear_radar_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault or sensor input drift", "de": "Interner Modulfehler oder Driften des Sensoreingangs"}, {"id": "software_mismatch", "p": "medium", "en": "Software version mismatch after replacement", "de": "Software-Versionskonflikt nach Tausch"}, {"id": "gateway_module_fault", "p": "low", "en": "Gateway module routing CAN messages incorrectly", "de": "Gateway-Modul leitet CAN-Botschaften fehlerhaft"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [0.5, 3]}',0);
