INSERT OR IGNORE INTO dtc_codes VALUES('U063D','N','Lost Communication With Hybrid/EV Electronics Coolant Pump A','Kommunikationsverlust zur HV-Elektronik-Kühlmittelpumpe A','The vehicle bus reports loss of communication with smart HV power-electronics coolant pump A. Inverter and DC/DC cooling cannot be commanded; derating may follow.','Der Fahrzeugbus meldet Kommunikationsverlust zur smarten Kühlmittelpumpe A der HV-Leistungselektronik. Wechselrichter- und DC/DC-Kühlung können nicht angefordert werden; Leistungs-Reduktion möglich.','["hv_electronics_coolant_pump_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U063E','N','Lost Communication With Exhaust Heat Exchanger Bypass Valve Actuator A','Kommunikationsverlust zum Abgaswärmetauscher-Bypassventil-Aktor A','The vehicle bus reports loss of communication with smart exhaust heat exchanger bypass valve actuator A. Exhaust-heat recovery cannot be commanded; cabin/coolant warm-up may slow down.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Abgaswärmetauscher-Bypassventil-Aktor A. Abgaswärme-Rückgewinnung kann nicht angefordert werden; Innenraum-/Kühlmittel-Erwärmung kann verzögert sein.','["exhaust_heat_exchanger_bypass_actuator_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U063F','N','Lost Communication With Engine Coolant Flow Control Valve Position Sensor','Kommunikationsverlust zum Positionssensor des Kühlmittel-Stromregelventils','The vehicle bus reports loss of communication with smart engine coolant flow control valve position sensor. Closed-loop control of the flow valve loses its actual feedback.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Positionssensor des Kühlmittel-Stromregelventils. Die Regelschleife des Stromventils verliert die Ist-Rückmeldung.','["coolant_flow_valve_position_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1000], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0640','N','Lost Communication With EVAP Fuel Vapor Temperature Sensor Circuit','Kommunikationsverlust zum EVAP-Kraftstoffdampf-Temperatursensor-Kreis','The vehicle bus reports loss of communication with smart EVAP fuel vapor temperature sensor. Tank-vapor temperature compensation for the EVAP system is unavailable.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten EVAP-Kraftstoffdampf-Temperatursensor. Die Temperatur-Kompensation des EVAP-Systems ist nicht verfügbar.','["evap_vapor_temp_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0641','N','Lost Communication With EVAP System Pressure Sensor/Switch Circuit A','Kommunikationsverlust zum EVAP-Druck-Sensor/Schalter A','The vehicle bus reports loss of communication with smart EVAP system pressure sensor / switch A. Tank-pressure-based leak detection cannot run on this channel.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten EVAP-Druck-Sensor/Schalter A. Tankdruck-basierte Leckdiagnose kann auf diesem Kanal nicht laufen.','["evap_pressure_sensor_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2]}',1);
