INSERT OR IGNORE INTO dtc_codes VALUES('U0643','N','Lost Communication With Turbocharger/Supercharger A Temperature Sensor','Kommunikationsverlust zum Turbolader-A-Temperatursensor','The vehicle bus reports loss of communication with smart turbocharger A temperature sensor. Turbo overheat protection switches to a model-based estimate.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Turbolader-A-Temperatursensor. Der Turbo-Überhitzungsschutz wechselt auf eine modellbasierte Schätzung.','["turbo_a_temp_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0644','N','Lost Communication With Wastegate Position Sensor A','Kommunikationsverlust zum Wastegate-Positionssensor A','The vehicle bus reports loss of communication with smart wastegate position sensor A. Closed-loop wastegate control loses its actual feedback; boost falls back to an open-loop fail-safe.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Wastegate-Positionssensor A. Die Wastegate-Regelung verliert die Ist-Rückmeldung; Ladedruck fällt in einen offenen Notlauf.','["wastegate_position_sensor_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1000], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0645','N','Lost Communication With Active Air Dam Module','Kommunikationsverlust zum aktiven Luftleitwand-Modul','The vehicle bus reports loss of communication with smart active air dam module. The lower-front aero spoiler stays in its default position; aerodynamic drag and front-end cooling can change.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Aktiv-Luftleitwand-Modul. Der ausfahrbare Frontspoiler bleibt in der Default-Position; Luftwiderstand und Frontkühlung können sich ändern.','["active_air_dam_module", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1500], "estimated_hours": [0.5, 3]}',0);
