INSERT OR IGNORE INTO dtc_codes VALUES('U064D','N','Lost Communication With Trailer Brake Control Switch','Kommunikationsverlust zum Anhänger-Brems-Steuerschalter','The vehicle bus reports loss of communication with smart trailer brake control switch. The driver-adjustable trailer brake gain input is unavailable; trailer braking falls back to default behaviour.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Anhänger-Brems-Steuerschalter. Die fahrer-einstellbare Anhängerbrems-Verstärkung fehlt; Anhängerbremsung wechselt in Default-Verhalten.','["trailer_brake_control_switch", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.5, 1.5]}',1);
