INSERT OR IGNORE INTO dtc_codes VALUES('U0658','N','Lost Communication With Windshield Temperature Sensor','Kommunikationsverlust zum Windschutzscheiben-Temperatursensor','The vehicle bus reports loss of communication with smart windshield temperature sensor (used for defog/defrost strategy and rain/light combo modules). Auto-climate strategy loses one of its inputs.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Windschutzscheiben-Temperatursensor (für Beschlag-/Enteisungsstrategie und Regen-/Licht-Kombimodule). Die Automatik-Klima-Strategie verliert einen ihrer Eingänge.','["windshield_temp_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 1.5]}',0);
