INSERT OR IGNORE INTO dtc_codes VALUES('U0667','N','Lost Communication With Engine Oil Temperature Sensor A','Kommunikationsverlust zum Motoröltemperatursensor A','The vehicle bus reports loss of communication with smart engine oil temperature sensor A. Oil-life model and oil-protection logic switch to a substitute value.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Motoröltemperatursensor A. Öl-Lebensdauer-Modell und Öl-Schutz-Logik wechseln auf einen Ersatzwert.','["engine_oil_temp_sensor_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0668','N','Lost Communication With Engine Oil Level Sensor Circuit','Kommunikationsverlust zum Motorölstand-Sensor-Kreis','The vehicle bus reports loss of communication with smart engine oil level sensor. Oil-level warnings cannot be issued reliably; refill alerts may be missing.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Motorölstand-Sensor. Ölstand-Warnungen können nicht zuverlässig ausgegeben werden; Nachfüll-Hinweise können ausbleiben.','["engine_oil_level_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('U0669','N','Lost Communication With EGR Sensor D','Kommunikationsverlust zum AGR-Sensor D','The vehicle bus reports loss of communication with smart EGR sensor D (position or flow). EGR closed-loop control loses its actual feedback.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten AGR-Sensor D (Position oder Massenstrom). Die AGR-Regelung verliert die Ist-Rückmeldung.','["egr_sensor_d", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 1000], "estimated_hours": [0.5, 3]}',1);
