INSERT OR IGNORE INTO dtc_codes VALUES('U066F','N','Lost Communication With Low Pressure Fuel System Sensor','Kommunikationsverlust zum Niederdruck-Kraftstoffsystem-Sensor','The vehicle bus reports loss of communication with smart low-pressure fuel system sensor. Lift-pump pressure feedback is unavailable; high-pressure pump and injection switch to a fail-safe map.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Niederdruck-Kraftstoffsystem-Sensor. Förderpumpen-Druckrückmeldung fehlt; Hochdruckpumpe und Einspritzung wechseln in ein Notlauf-Kennfeld.','["low_pressure_fuel_sensor", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 800], "estimated_hours": [0.5, 2]}',1);
