INSERT OR IGNORE INTO dtc_codes VALUES('U0672','N','Lost Communication With Engine Coolant Pump','Kommunikationsverlust zur Motor-Kühlmittelpumpe','The vehicle bus reports loss of communication with smart engine coolant pump (electric water pump). Pump speed cannot be commanded; coolant flow falls back to a default duty.','Der Fahrzeugbus meldet Kommunikationsverlust zur smarten Motor-Kühlmittelpumpe (elektrische Wasserpumpe). Pumpendrehzahl kann nicht angefordert werden; Kühlmittelstrom fällt auf eine Default-PWM zurück.','["engine_coolant_pump", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
