INSERT OR IGNORE INTO dtc_codes VALUES('U0675','N','Lost Communication With Turbocharger/Supercharger Speed Sensor A','Kommunikationsverlust zum Turbolader-Drehzahlsensor A','The vehicle bus reports loss of communication with smart turbocharger speed sensor A. Overspeed protection switches to model-based estimation; boost may be limited.','Der Fahrzeugbus meldet Kommunikationsverlust zum smarten Turbolader-Drehzahlsensor A. Drehzahl-Begrenzungsschutz wechselt auf modellbasierte Schätzung; Ladedruck kann begrenzt werden.','["turbo_speed_sensor_a", "vehicle_bus_wiring"]','[{"id": "bus_wiring_fault", "p": "high", "en": "Bus wiring open or shorted", "de": "Bus-Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "module_unpowered", "p": "medium", "en": "Module without power or ground", "de": "Modul ohne Spannung oder Masse"}, {"id": "module_failed", "p": "medium", "en": "Module failed", "de": "Modul defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',1);
