INSERT OR IGNORE INTO dtc_codes VALUES('B009E','B','Right Side Restraints Sensor 5','Rechte Seitenrückhaltesensor 5','Fault on right-side restraints sensor 5.','Fehler am rechten Seitenrückhaltesensor 5.','["right_side_restraints_sensor_5", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Side impact sensor failed", "de": "Seitenaufprallsensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1, 4]}',1);
