INSERT OR IGNORE INTO dtc_codes VALUES('B00A0','B','Occupant Classification System','Insassen-Klassifizierungssystem','Fault on the occupant classification system (OCS) — typically detects whether the front passenger seat is empty, holds a child seat, or has an adult, to enable/suppress passenger airbag.','Fehler am Insassen-Klassifizierungssystem (OCS) — erkennt, ob der Beifahrersitz leer ist, einen Kindersitz hält oder von einem Erwachsenen besetzt ist, um den Beifahrerairbag freizugeben oder zu sperren.','["ocs_module", "seat_sensors"]','[{"id": "module_internal_fault", "p": "high", "en": "OCS module internal fault", "de": "OCS-Modul-interner Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00A1','B','Occupant Position System','Insassen-Positionssystem','Fault on the occupant position system that detects forward/rearward position of occupants, used by the airbag controller to scale deployment force.','Fehler am Insassen-Positionssystem, das die Vor-/Rückposition der Insassen erkennt; das Airbag-Steuergerät skaliert damit die Auslösekraft.','["occupant_position_module", "seat_sensors"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00B0','B','Driver Seat Occupant Classification Sensor A','Fahrersitz Insassen-Klassifizierungssensor A','Fault on driver seat occupant classification sensor A — typically a force/weight sensing pad in the seat cushion that determines passenger weight class.','Fehler am Klassifizierungssensor A des Fahrersitzes — typisch eine Kraft-/Gewichtsmatte im Sitzpolster, die das Gewichtsklasse erkennt.','["driver_classification_sensor_a", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Classification sensor failed", "de": "Klassifizierungssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00B1','B','Driver Seat Occupant Classification Sensor B','Fahrersitz Insassen-Klassifizierungssensor B','Fault on driver seat occupant classification sensor B.','Fehler am Klassifizierungssensor B des Fahrersitzes.','["driver_classification_sensor_b", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Classification sensor failed", "de": "Klassifizierungssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
