INSERT OR IGNORE INTO dtc_codes VALUES('B00B3','B','Driver Seat Occupant Classification Sensor D','Fahrersitz Insassen-Klassifizierungssensor D','Fault on driver seat occupant classification sensor D.','Fehler am Klassifizierungssensor D des Fahrersitzes.','["driver_classification_sensor_d", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Classification sensor failed", "de": "Klassifizierungssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
