INSERT OR IGNORE INTO dtc_codes VALUES('B00B5','B','Driver Seat Track Position Restraints Sensor','Fahrersitz-Schienen-Positionssensor (Rückhaltesystem)','Fault on the driver seat track position sensor — detects fore/aft seat position, used by the airbag controller to adapt deployment to seat distance from steering wheel.','Fehler am Schienen-Positionssensor des Fahrersitzes — erkennt die Vor-/Rückposition; das Airbag-Steuergerät passt die Auslösung an den Abstand zum Lenkrad an.','["driver_seat_track_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Track position sensor failed", "de": "Schienen-Positionssensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00B6','B','Driver Seat Recline Position Restraints Sensor','Fahrersitz Lehnen-Positionssensor (Rückhaltesystem)','Fault on the driver seat recline position sensor — detects backrest angle, used by the airbag controller for deployment scaling.','Fehler am Lehnen-Positionssensor des Fahrersitzes — erkennt den Lehnenwinkel zur Skalierung der Airbag-Auslösung.','["driver_recline_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Recline sensor failed", "de": "Lehnen-Sensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00B7','B','Driver Seat Occupant Position Sensor A','Fahrersitz Insassen-Positionssensor A','Fault on driver seat occupant position sensor A — detects occupant proximity to airbag (typically capacitive or ultrasonic).','Fehler am Insassen-Positionssensor A des Fahrersitzes — erkennt die Annäherung des Insassen an den Airbag (meist kapazitiv oder Ultraschall).','["driver_occupant_position_sensor_a", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B00B8','B','Driver Seat Occupant Position Sensor B','Fahrersitz Insassen-Positionssensor B','Fault on driver seat occupant position sensor B.','Fehler am Insassen-Positionssensor B des Fahrersitzes.','["driver_occupant_position_sensor_b", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
