INSERT OR IGNORE INTO dtc_codes VALUES('B00C0','B','Passenger Seat Occupant Classification Sensor A','Beifahrersitz Insassen-Klassifizierungssensor A','Fault on passenger seat occupant classification sensor A — used to determine if the seat holds a child, adult or is empty (gates the passenger airbag).','Fehler am Klassifizierungssensor A des Beifahrersitzes — erkennt Kind/Erwachsener/leer (steuert den Beifahrerairbag).','["passenger_classification_sensor_a", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Classification sensor failed", "de": "Klassifizierungssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1, 4]}',1);
