INSERT OR IGNORE INTO dtc_codes VALUES('B00D5','B','Restraint System Passenger Disable Indicator','Beifahrer-Airbag-Deaktivierungsanzeige','Fault on the indicator that shows the passenger airbag is disabled (typically a "PASSENGER AIRBAG OFF" lamp).','Fehler an der Anzeige für deaktivierten Beifahrerairbag (typisch "PASSENGER AIRBAG OFF"-Leuchte).','["passenger_disable_indicator"]','[{"id": "indicator_failed", "p": "high", "en": "Indicator lamp or driver failed", "de": "Warnleuchte oder Endstufe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 400], "estimated_hours": [0.3, 2]}',1);
