INSERT OR IGNORE INTO dtc_codes VALUES('B00F0','B','Driver Inflatable Seat Belt Deployment Control','Fahrer aufblasbarer Sicherheitsgurt Auslösekreis','Fault on the deployment circuit of the driver inflatable seat belt. Inflatable belts (e.g. Ford rear-seat system) widen the belt webbing on impact to spread crash loads over a larger area.','Fehler am Auslösekreis des aufblasbaren Fahrer-Sicherheitsgurts. Aufblasbare Gurte (z. B. Ford-Rücksitzsystem) verbreitern das Gurtband bei Aufprall, um Crashlasten über größere Fläche zu verteilen.','["driver_inflatable_belt", "squib_circuit"]','[{"id": "squib_open", "p": "high", "en": "Inflator squib open", "de": "Aufblasvorrichtung-Z\u00fcndkreis unterbrochen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2000], "estimated_hours": [1.5, 5]}',1);
