INSERT OR IGNORE INTO dtc_codes VALUES('B0121','B','Fluid Reservoir Level Sensor F','Flüssigkeits-Vorratsbehälter Füllstandsensor F','Fault on fluid reservoir level sensor F.','Fehler am Füllstandsensor F des Flüssigkeitsvorratsbehälters.','["fluid_reservoir_level_sensor_f", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Float or sensor failed", "de": "Schwimmer oder Sensor defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0122','B','Pedestrian Alert Speaker A','Fußgängerwarnsignal-Lautsprecher A','Fault on pedestrian alert speaker A — emits an artificial driving sound at low speed on EVs/hybrids (legally required, e.g. UNECE R138, FMVSS 141).','Fehler am Lautsprecher A des Fußgängerwarnsignals — gibt bei EVs/Hybriden im Niedriggeschwindigkeitsbereich ein künstliches Fahrgeräusch ab (gesetzlich vorgeschrieben, z. B. UNECE R138, FMVSS 141).','["pedestrian_alert_speaker_a", "speaker_wiring"]','[{"id": "speaker_failed", "p": "high", "en": "Speaker coil open", "de": "Lautsprecher-Spule unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0123','B','Pedestrian Alert Speaker B','Fußgängerwarnsignal-Lautsprecher B','Fault on pedestrian alert speaker B (second/redundant speaker).','Fehler am Lautsprecher B des Fußgängerwarnsignals (zweiter/redundanter Lautsprecher).','["pedestrian_alert_speaker_b", "speaker_wiring"]','[{"id": "speaker_failed", "p": "high", "en": "Speaker coil open", "de": "Lautsprecher-Spule unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0124','B','Night Vision Camera','Nachtsicht-Kamera','Fault on the night vision camera (typically a thermal/far-infrared camera that detects pedestrians and animals beyond headlight range).','Fehler an der Nachtsicht-Kamera (meist eine Thermal-/Ferninfrarot-Kamera, die Fußgänger und Tiere außerhalb der Scheinwerferreichweite erkennt).','["night_vision_camera", "camera_wiring"]','[{"id": "camera_failed", "p": "high", "en": "Camera module failed", "de": "Kameramodul defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [500, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0125','B','Driver Side Mirror Position Sensor','Fahrer-Außenspiegel Positionssensor','The body control module has detected a fault in the driver-side mirror position sensor. Memory mirror positions cannot be saved or restored reliably.','Das Karosserie-Steuergerät hat einen Fehler im Positionssensor des Fahrer-Außenspiegels erkannt. Memory-Spiegelpositionen können nicht zuverlässig gespeichert oder abgerufen werden.','["mirror_position_sensor", "mirror_motor_assembly"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor or potentiometer failed", "de": "Positionssensor oder Potentiometer defekt"}, {"id": "mirror_assembly_water_ingress", "p": "medium", "en": "Water ingress into mirror assembly", "de": "Wassereintritt in das Spiegelgeh\u00e4use"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0126','B','Passenger Side Mirror Position Sensor','Beifahrer-Außenspiegel Positionssensor','The body control module has detected a fault in the passenger-side mirror position sensor. Same fault profile as B0125 but for the passenger mirror.','Das Karosserie-Steuergerät hat einen Fehler im Positionssensor des Beifahrer-Außenspiegels erkannt. Gleiches Fehlerbild wie B0125, jedoch für den Beifahrerspiegel.','["mirror_position_sensor", "mirror_motor_assembly"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "mirror_assembly_water_ingress", "p": "medium", "en": "Water ingress into mirror assembly", "de": "Wassereintritt in das Spiegelgeh\u00e4use"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0127','B','DC/AC Converter A High Voltage Power Outlet "A" Circuit/Open','DC/AC-Wandler A Hochvolt-Steckdose "A" Schaltkreis unterbrochen','Open circuit on the high-voltage power outlet "A" of DC/AC converter A. The outlet supplies 110/230 V AC from the HV battery on EVs/hybrids (vehicle-to-load).','Unterbrochener Schaltkreis an der Hochvolt-Steckdose "A" des DC/AC-Wandlers A. Die Steckdose liefert 110/230 V AC aus der HV-Batterie bei EVs/Hybriden (Vehicle-to-Load).','["dc_ac_converter_a", "hv_outlet_a"]','[{"id": "open_wiring", "p": "high", "en": "Outlet wiring open", "de": "Steckdosen-Verkabelung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0128','B','Passenger Occupant Detection System Malfunction','Beifahrer-Sitzbelegungserkennung Fehlfunktion','The passenger occupant detection system (ODS), used to enable/disable the passenger airbag based on weight, has reported a malfunction.','Die Beifahrer-Sitzbelegungserkennung (ODS), die den Beifahrerairbag gewichtsabhängig aktiviert oder deaktiviert, meldet eine Fehlfunktion.','["occupant_detection_sensor", "passenger_seat", "srs_control_module"]','[{"id": "ods_sensor_mat_failure", "p": "high", "en": "Seat sensor mat failure", "de": "Defekte Sitzsensormatte"}, {"id": "ods_calibration_lost", "p": "medium", "en": "ODS calibration lost after seat work", "de": "ODS-Kalibrierung nach Sitzarbeiten verloren"}, {"id": "connector_loose", "p": "medium", "en": "Loose ODS connector", "de": "Loser ODS-Stecker"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0129','B','DC/AC Converter A High Voltage Power Outlet "C" Circuit/Open','DC/AC-Wandler A Hochvolt-Steckdose "C" Schaltkreis unterbrochen','Open circuit on the high-voltage power outlet "C" of DC/AC converter A.','Unterbrochener Schaltkreis an der Hochvolt-Steckdose "C" des DC/AC-Wandlers A.','["dc_ac_converter_a", "hv_outlet_c"]','[{"id": "open_wiring", "p": "high", "en": "Outlet wiring open", "de": "Steckdosen-Verkabelung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012A','B','DC/AC Converter A High Voltage Power Outlet "D" Circuit/Open','DC/AC-Wandler A Hochvolt-Steckdose "D" Schaltkreis unterbrochen','Open circuit on the high-voltage power outlet "D" of DC/AC converter A.','Unterbrochener Schaltkreis an der Hochvolt-Steckdose "D" des DC/AC-Wandlers A.','["dc_ac_converter_a", "hv_outlet_d"]','[{"id": "open_wiring", "p": "high", "en": "Outlet wiring open", "de": "Steckdosen-Verkabelung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012B','B','DC/AC Converter A High Voltage Power Outlet "E" Circuit/Open','DC/AC-Wandler A Hochvolt-Steckdose "E" Schaltkreis unterbrochen','Open circuit on the high-voltage power outlet "E" of DC/AC converter A.','Unterbrochener Schaltkreis an der Hochvolt-Steckdose "E" des DC/AC-Wandlers A.','["dc_ac_converter_a", "hv_outlet_e"]','[{"id": "open_wiring", "p": "high", "en": "Outlet wiring open", "de": "Steckdosen-Verkabelung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012C','B','DC/AC Converter A High Voltage Power Outlet Control Module "A"','DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul "A"','Fault reported by control module "A" of the high-voltage power outlet on DC/AC converter A.','Fehler im Steuermodul "A" der Hochvolt-Steckdose des DC/AC-Wandlers A.','["hv_outlet_module_a"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012D','B','DC/AC Converter A High Voltage Power Outlet Control Module "B"','DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul "B"','Fault reported by control module "B".','Fehler im Steuermodul "B".','["hv_outlet_module_b"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012E','B','DC/AC Converter A High Voltage Power Outlet Control Module "C"','DC/AC-Wandler A Hochvolt-Steckdosen-Steuermodul "C"','Fault reported by control module "C".','Fehler im Steuermodul "C".','["hv_outlet_module_c"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B012F','B','A/V Sensor Washer Fluid A Control Circuit','A/V-Sensor-Reinigungsfluid A Steuerschaltkreis','Fault on the control circuit of the audio/video sensor washer fluid pump A. Sprays cleaning fluid on ADAS audio/video sensor lenses.','Fehler am Steuerschaltkreis der Audio/Video-Sensor-Reinigungsfluidpumpe A. Sprüht Reinigungsfluid auf die Linsen der Fahrerassistenz-Audio/Video-Sensoren.','["av_washer_fluid_pump_a", "pump_wiring"]','[{"id": "pump_failed", "p": "high", "en": "Washer fluid pump failed", "de": "Reinigungspumpe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0130','B','Driver Seatbelt Tension Sensor Circuit','Fahrer-Gurtspannungssensor Stromkreis','The driver seatbelt tension sensor circuit is faulty. This sensor is used by the SRS to adjust deployment based on belt usage.','Der Stromkreis des Fahrer-Gurtspannungssensors ist defekt. Dieser Sensor wird vom SRS zur belastungsabhängigen Auslösung verwendet.','["driver_seatbelt_tension_sensor", "srs_control_module"]','[{"id": "sensor_fault", "p": "high", "en": "Tension sensor fault", "de": "Defekter Spannungssensor"}, {"id": "connector_corrosion", "p": "medium", "en": "Corroded sensor connector", "de": "Korrodierter Sensorstecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 500], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0131','B','A/V Sensor Washer Fluid C Control Circuit','A/V-Sensor-Reinigungsfluid C Steuerschaltkreis','Fault on the audio/video sensor washer fluid pump C control circuit.','Fehler am Steuerschaltkreis der A/V-Sensor-Reinigungsfluidpumpe C.','["av_washer_fluid_pump_c", "pump_wiring"]','[{"id": "pump_failed", "p": "high", "en": "Washer fluid pump failed", "de": "Reinigungspumpe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0132','B','A/V Sensor Washer Fluid D Control Circuit','A/V-Sensor-Reinigungsfluid D Steuerschaltkreis','Fault on the A/V sensor washer fluid pump D control circuit.','Fehler am Steuerschaltkreis der A/V-Sensor-Reinigungsfluidpumpe D.','["av_washer_fluid_pump_d", "pump_wiring"]','[{"id": "pump_failed", "p": "high", "en": "Washer fluid pump failed", "de": "Reinigungspumpe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0133','B','A/V Sensor Washer Fluid E Control Circuit','A/V-Sensor-Reinigungsfluid E Steuerschaltkreis','Fault on the A/V sensor washer fluid pump E control circuit.','Fehler am Steuerschaltkreis der A/V-Sensor-Reinigungsfluidpumpe E.','["av_washer_fluid_pump_e", "pump_wiring"]','[{"id": "pump_failed", "p": "high", "en": "Washer fluid pump failed", "de": "Reinigungspumpe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0134','B','A/V Sensor Washer Fluid F Control Circuit','A/V-Sensor-Reinigungsfluid F Steuerschaltkreis','Fault on the A/V sensor washer fluid pump F control circuit.','Fehler am Steuerschaltkreis der A/V-Sensor-Reinigungsfluidpumpe F.','["av_washer_fluid_pump_f", "pump_wiring"]','[{"id": "pump_failed", "p": "high", "en": "Washer fluid pump failed", "de": "Reinigungspumpe defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('B0140','B','Passenger Seatbelt Tension Sensor Circuit','Beifahrer-Gurtspannungssensor Stromkreis','The passenger seatbelt tension sensor circuit is faulty.','Der Stromkreis des Beifahrer-Gurtspannungssensors ist defekt.','["passenger_seatbelt_tension_sensor", "srs_control_module"]','[{"id": "sensor_fault", "p": "high", "en": "Tension sensor fault", "de": "Defekter Spannungssensor"}, {"id": "connector_loose", "p": "medium", "en": "Loose sensor connector", "de": "Loser Sensorstecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 500], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0150','B','HVAC Mode Door Range/Performance','HVAC-Klappensteller Funktionsbereich/Leistung','The HVAC control module has detected that the air distribution mode door (e.g. floor/face/defrost) does not reach the commanded position within the expected time. The actuator may be stuck, the door binding, or the position feedback inaccurate.','Das Klima-Steuergerät hat erkannt, dass die Luftverteilungsklappe (z. B. Fuß/Gesicht/Defrost) die angesteuerte Position nicht in der erwarteten Zeit erreicht. Der Stellmotor klemmt, die Klappe blockiert oder die Positionsrückmeldung ist ungenau.','["mode_door_actuator", "hvac_control_module", "mode_door_linkage"]','[{"id": "mode_door_actuator_failed", "p": "high", "en": "Mode door actuator motor failed", "de": "Klappensteller-Motor defekt"}, {"id": "mode_door_binding", "p": "medium", "en": "Mode door mechanically binding", "de": "Klappe mechanisch schwerg\u00e4ngig"}, {"id": "actuator_wiring", "p": "low", "en": "Wiring or connector fault to actuator", "de": "Verkabelungs- oder Steckerfehler am Steller"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0152','B','Driver Buckle Switch Circuit Malfunction','Gurtschloss Fahrer Schalter Stromkreis Fehlfunktion','The driver seatbelt buckle switch circuit, used to detect whether the belt is fastened, is malfunctioning. The seatbelt warning may be permanently on or off.','Der Stromkreis des Fahrer-Gurtschlossschalters, der erkennt, ob der Gurt angelegt ist, ist defekt. Die Gurtwarnung kann dauerhaft an oder aus sein.','["driver_buckle_switch", "body_control_module"]','[{"id": "switch_failure", "p": "high", "en": "Buckle switch worn or stuck", "de": "Gurtschloss-Schalter verschlissen oder klemmt"}, {"id": "wiring_break", "p": "medium", "en": "Wire break under seat", "de": "Kabelbruch unter dem Sitz"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0154','B','Passenger Buckle Switch Circuit Malfunction','Gurtschloss Beifahrer Schalter Stromkreis Fehlfunktion','The passenger seatbelt buckle switch circuit is malfunctioning.','Der Stromkreis des Beifahrer-Gurtschlossschalters ist defekt.','["passenger_buckle_switch", "body_control_module"]','[{"id": "switch_failure", "p": "high", "en": "Buckle switch failure", "de": "Defekter Gurtschloss-Schalter"}, {"id": "connector_corrosion", "p": "medium", "en": "Corroded buckle connector", "de": "Korrodierter Gurtschloss-Stecker"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0156','B','Sun Load Sensor Circuit','Sonneneinstrahlungssensor Schaltung','The HVAC control module has detected an implausible signal from the sun load (solar) sensor, typically located on the dashboard. Automatic climate control uses this signal to bias cooling on the side facing the sun.','Das Klima-Steuergerät hat ein unplausibles Signal vom Sonneneinstrahlungssensor erkannt — meist im Armaturenbrett verbaut. Die Klimaautomatik nutzt das Signal, um die Kühlung zur sonnenzugewandten Seite zu verstärken.','["sun_load_sensor", "hvac_control_module"]','[{"id": "sun_load_sensor_failed", "p": "high", "en": "Sun load sensor failed", "de": "Sonneneinstrahlungssensor defekt"}, {"id": "sun_load_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0158','B','Ambient Air Temperature Sensor Circuit','Umgebungslufttemperatursensor Schaltung','The HVAC control module has detected an implausible signal from the ambient air temperature sensor used by the climate control system. Symptoms include incorrect outside temperature display and erratic automatic climate behavior.','Das Klima-Steuergerät hat ein unplausibles Signal vom Umgebungslufttemperatursensor erkannt. Symptome sind eine falsche Außentemperaturanzeige und unstetiges Verhalten der Klimaautomatik.','["ambient_air_temperature_sensor", "hvac_control_module"]','[{"id": "ambient_sensor_failed", "p": "high", "en": "Ambient air temperature sensor failed", "de": "Umgebungslufttemperatursensor defekt"}, {"id": "ambient_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 150], "estimated_hours": [0.3, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0159','B','Outside Temperature Sensor Range/Performance','Außentemperatursensor Bereich/Funktion','The HVAC control module reports an out-of-range or implausible reading from the outside air temperature sensor. The displayed value may be stuck or impossibly high/low.','Das Klima-Steuergerät meldet einen Wert außerhalb des Bereichs oder unplausibel vom Außentemperatursensor. Die Anzeige kann eingefroren oder unrealistisch hoch/niedrig sein.','["outside_temperature_sensor", "hvac_control_module"]','[{"id": "ambient_sensor_failed", "p": "high", "en": "Outside temperature sensor failed", "de": "Au\u00dfentemperatursensor defekt"}, {"id": "ambient_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 150], "estimated_hours": [0.3, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0160','B','In-Vehicle Temperature Sensor Circuit','Innenraumtemperatursensor Schaltung','The HVAC control module has detected an implausible signal from the in-vehicle temperature sensor — typically an aspirated sensor in the dashboard. Automatic climate control regulates cabin temperature using this signal.','Das Klima-Steuergerät hat ein unplausibles Signal vom Innenraumtemperatursensor erkannt — meist ein angesaugter Sensor im Armaturenbrett. Die Klimaautomatik regelt die Innenraumtemperatur anhand dieses Signals.','["in_vehicle_temperature_sensor", "hvac_control_module"]','[{"id": "cabin_sensor_failed", "p": "high", "en": "In-vehicle temperature sensor failed", "de": "Innenraumtemperatursensor defekt"}, {"id": "aspirator_fan_blocked", "p": "medium", "en": "Aspirator fan or duct blocked", "de": "Ansaugventilator oder Kanal blockiert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 300], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0162','B','Sun Load Sensor 2 Circuit','Sonneneinstrahlungssensor 2 Schaltung','The HVAC control module has detected an implausible signal from the second sun load sensor. Dual-zone systems use two solar sensors to detect side-asymmetric sunlight and adjust left/right airflow temperature.','Das Klima-Steuergerät hat ein unplausibles Signal vom zweiten Sonneneinstrahlungssensor erkannt. Zwei-Zonen-Systeme nutzen zwei Sonnensensoren, um seitenabhängige Sonneneinstrahlung zu erkennen und die linke/rechte Luftauslasstemperatur anzupassen.','["sun_load_sensor_2", "hvac_control_module"]','[{"id": "sun_load_sensor_failed", "p": "high", "en": "Sun load sensor 2 failed", "de": "Sonneneinstrahlungssensor 2 defekt"}, {"id": "sun_load_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0164','B','Air Bag In-Vehicle Temperature Sensor Circuit','Innenraum-Temperatursensor (SRS) Stromkreis','A fault is detected in the in-vehicle temperature sensor circuit used by the SRS module for deployment compensation.','Ein Fehler wurde im Innenraum-Temperatursensor-Stromkreis erkannt, der vom SRS-Steuergerät zur Auslösekompensation verwendet wird.','["in_vehicle_temperature_sensor", "srs_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Temperature sensor failure", "de": "Temperatursensor defekt"}, {"id": "wiring_short", "p": "medium", "en": "Wiring short or open", "de": "Kabel kurzgeschlossen oder unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 300], "estimated_hours": [0.4, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0166','B','HVAC Discharge Air Temperature Sensor','HVAC-Auslasslufttemperatursensor','The HVAC control module reports an implausible signal from the discharge (vent outlet) air temperature sensor. This sensor verifies that the actual outlet air temperature matches the commanded value.','Das Klima-Steuergerät meldet ein unplausibles Signal vom Auslasslufttemperatursensor. Dieser Sensor prüft, ob die tatsächliche Ausströmtemperatur dem Sollwert entspricht.','["discharge_air_temp_sensor", "hvac_control_module"]','[{"id": "discharge_sensor_failed", "p": "high", "en": "Discharge air temp sensor failed", "de": "Auslasslufttemperatursensor defekt"}, {"id": "discharge_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 300], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0168','B','HVAC Air Mix Door Performance','HVAC-Mischklappe Funktionsbereich','The HVAC control module has detected that the air mix (blend) door does not reach the commanded position within the expected time. The blend door regulates the ratio of air through the heater core versus around it.','Das Klima-Steuergerät hat erkannt, dass die Mischklappe (Blend Door) die angesteuerte Position nicht in der erwarteten Zeit erreicht. Die Klappe regelt den Anteil der Luft durch den Heizungswärmetauscher.','["air_mix_door_actuator", "hvac_control_module", "blend_door_linkage"]','[{"id": "blend_door_actuator_failed", "p": "high", "en": "Blend door actuator motor failed", "de": "Mischklappen-Stellmotor defekt"}, {"id": "blend_door_binding", "p": "medium", "en": "Blend door mechanically binding or broken", "de": "Mischklappe schwerg\u00e4ngig oder gebrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 6.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0170','B','HVAC Mode Door Position Sensor','HVAC-Modusklappen Positionssensor','The HVAC control module reports an implausible position signal from the mode (air distribution) door feedback sensor. Without valid feedback the actuator cannot be regulated to the correct position.','Das Klima-Steuergerät meldet ein unplausibles Positionssignal vom Rückmeldesensor der Modusklappe. Ohne gültige Rückmeldung kann der Stellmotor nicht korrekt geregelt werden.','["mode_door_position_sensor", "mode_door_actuator", "hvac_control_module"]','[{"id": "mode_door_position_sensor_failed", "p": "high", "en": "Mode door position sensor failed", "de": "Positionssensor der Modusklappe defekt"}, {"id": "actuator_wiring", "p": "medium", "en": "Wiring or connector fault to actuator", "de": "Verkabelungs- oder Steckerfehler am Steller"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0173','B','HVAC Air Inlet Door','HVAC-Ansaugklappe','The HVAC control module has detected a fault on the fresh-air/recirculation inlet door — typically a stuck actuator or position feedback out of range.','Das Klima-Steuergerät hat einen Fehler an der Frischluft/Umluft-Ansaugklappe erkannt — meist ein klemmender Stellmotor oder eine Rückmeldung außerhalb des Bereichs.','["air_inlet_door_actuator", "hvac_control_module"]','[{"id": "inlet_actuator_failed", "p": "high", "en": "Inlet door actuator failed", "de": "Ansaugklappen-Stellmotor defekt"}, {"id": "inlet_door_binding", "p": "medium", "en": "Inlet door mechanically binding", "de": "Ansaugklappe schwerg\u00e4ngig"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0175','B','HVAC Recirculation Door Performance','HVAC-Umluftklappe Funktionsbereich','The HVAC control module has detected that the recirculation door does not reach the commanded position within the expected time. The recirc door switches between fresh air and recirculated cabin air.','Das Klima-Steuergerät hat erkannt, dass die Umluftklappe die angesteuerte Position nicht in der erwarteten Zeit erreicht. Die Klappe schaltet zwischen Frischluft und umgewälzter Innenraumluft.','["recirculation_door_actuator", "hvac_control_module"]','[{"id": "recirc_actuator_failed", "p": "high", "en": "Recirculation door actuator failed", "de": "Umluftklappen-Stellmotor defekt"}, {"id": "recirc_door_binding", "p": "medium", "en": "Recirculation door mechanically binding", "de": "Umluftklappe schwerg\u00e4ngig"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0181','B','Front Blower Motor Circuit Low','Vorderer Gebläsemotor Schaltung niedrig','The HVAC control module has detected low voltage or a short to ground in the front blower motor circuit. The blower may run too slow or not at all.','Das Klima-Steuergerät hat eine zu niedrige Spannung oder einen Masseschluss im Stromkreis des vorderen Gebläsemotors erkannt. Das Gebläse läuft zu langsam oder gar nicht.','["front_blower_motor", "blower_resistor_or_module", "hvac_control_module"]','[{"id": "blower_motor_worn", "p": "high", "en": "Blower motor worn or seized", "de": "Gebl\u00e4semotor verschlissen oder fest"}, {"id": "blower_resistor_failed", "p": "medium", "en": "Blower resistor or power module failed", "de": "Gebl\u00e4sewiderstand oder Leistungsmodul defekt"}, {"id": "blower_wiring_short", "p": "low", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0182','B','Right Front/Passenger Side Buckle Tension Sensor Circuit','Beifahrer-Gurtspannungssensor Stromkreis','The right front buckle tension sensor circuit is reporting a malfunction.','Der Stromkreis des Beifahrer-Gurtspannungssensors meldet eine Fehlfunktion.','["passenger_buckle_tension_sensor", "srs_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Sensor failure", "de": "Sensorausfall"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 500], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0184','B','Rear Blower Motor Circuit','Hinterer Gebläsemotor Schaltung','The HVAC control module has detected a fault in the rear blower motor circuit, used in vehicles with separate rear climate zones. Symptoms include no rear airflow or rear blower stuck on.','Das Klima-Steuergerät hat einen Fehler im Stromkreis des hinteren Gebläsemotors erkannt — in Fahrzeugen mit separater Heckklima-Zone. Symptome sind fehlender Heckluftstrom oder dauerhaft laufendes Heckgebläse.','["rear_blower_motor", "rear_blower_resistor", "hvac_control_module"]','[{"id": "rear_blower_motor_failed", "p": "high", "en": "Rear blower motor failed", "de": "Hinterer Gebl\u00e4semotor defekt"}, {"id": "rear_blower_resistor_failed", "p": "medium", "en": "Rear blower resistor failed", "de": "Hinterer Gebl\u00e4sewiderstand defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 600], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0186','B','Front Blower Motor Speed Performance','Frontgebläsemotor Drehzahl Funktionsbereich','The HVAC control module has detected that the front blower motor does not run at the commanded speed. Possible causes include a worn motor, blocked airway, or driver module fault.','Das Klima-Steuergerät hat erkannt, dass der Frontgebläsemotor nicht mit der angeforderten Drehzahl läuft. Mögliche Ursachen sind ein verschlissener Motor, ein verstopfter Luftpfad oder ein Fehler im Endstufenmodul.','["blower_motor", "blower_resistor", "cabin_air_filter"]','[{"id": "blower_motor_worn", "p": "high", "en": "Blower motor worn or seized", "de": "Gebl\u00e4semotor verschlissen oder fest"}, {"id": "cabin_filter_blocked", "p": "medium", "en": "Cabin filter heavily blocked", "de": "Innenraumfilter stark verstopft"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0188','B','Rear Wiper Motor Circuit','Heckwischermotor Schaltung','The body control module has detected a fault in the rear wiper motor circuit. Possible faults include an open or shorted motor winding, a stuck mechanism, or wiring damage in the tailgate harness.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Heckwischermotors erkannt. Möglich sind eine Unterbrechung oder ein Kurzschluss in der Motorwicklung, ein blockierter Mechanismus oder ein Verkabelungsschaden im Heckklappenkabelbaum.','["rear_wiper_motor", "body_control_module", "tailgate_harness"]','[{"id": "rear_wiper_motor_failed", "p": "high", "en": "Rear wiper motor failed", "de": "Heckwischermotor defekt"}, {"id": "tailgate_harness_break", "p": "medium", "en": "Tailgate harness broken at hinge", "de": "Heckklappenkabelbaum am Scharnier gebrochen"}, {"id": "rear_wiper_fuse", "p": "low", "en": "Rear wiper fuse blown", "de": "Sicherung Heckwischer durchgebrannt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 350], "estimated_hours": [0.3, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0190','B','Front Wiper Park Switch Circuit','Frontwischer Parkschalter Stromkreis','The body control module has detected a fault in the front wiper park switch circuit. The wipers may not return to the park position when switched off.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Frontwischer-Parkschalters erkannt. Die Wischer kehren beim Ausschalten möglicherweise nicht in die Parkposition zurück.','["wiper_motor", "wiper_park_switch", "body_control_module"]','[{"id": "park_switch_failed", "p": "high", "en": "Park switch in wiper motor failed", "de": "Parkschalter im Wischermotor defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or corroded", "de": "Verkabelung unterbrochen oder korrodiert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0192','B','Front Wiper Speed Performance','Frontwischer Geschwindigkeit Funktionsbereich','The body control module has detected that the front wiper does not run at the commanded speed. Possible causes include a worn motor, binding linkage, or excessive load.','Das Karosserie-Steuergerät hat erkannt, dass der Frontwischer nicht mit der angeforderten Geschwindigkeit läuft. Mögliche Ursachen sind ein verschlissener Motor, schwergängiges Gestänge oder zu hohe Last.','["wiper_motor", "wiper_linkage"]','[{"id": "wiper_motor_worn", "p": "high", "en": "Wiper motor worn", "de": "Wischermotor verschlissen"}, {"id": "linkage_binding", "p": "medium", "en": "Wiper linkage binding or seized", "de": "Wischergest\u00e4nge schwerg\u00e4ngig oder fest"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0200','B','Air Bag System Voltage Out of Range','Airbagsystem Versorgungsspannung außerhalb Bereich','The SRS module has detected that its supply voltage is outside the operating range, preventing reliable deployment readiness.','Das SRS-Steuergerät hat erkannt, dass seine Versorgungsspannung außerhalb des Betriebsbereichs liegt, was eine zuverlässige Auslösebereitschaft verhindert.','["srs_control_module", "vehicle_battery", "srs_power_circuit"]','[{"id": "weak_battery", "p": "high", "en": "Weak or failing vehicle battery", "de": "Schwache oder defekte Fahrzeugbatterie"}, {"id": "alternator_fault", "p": "medium", "en": "Alternator output low or unstable", "de": "Lichtmaschinenleistung niedrig oder instabil"}, {"id": "srs_power_wiring", "p": "medium", "en": "Damaged SRS power wiring", "de": "Besch\u00e4digte SRS-Versorgungsverkabelung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 500], "estimated_hours": [0.3, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0205','B','HVAC Defroster Door Position','HVAC Defroster-Klappe Position','The HVAC control module has detected that the defroster door (windshield air outlet flap) does not reach the commanded position. Defrosting performance may be reduced.','Das Klima-Steuergerät hat erkannt, dass die Defroster-Klappe (Windschutzscheiben-Luftauslass) die angeforderte Position nicht erreicht. Die Entfrostungsleistung kann eingeschränkt sein.','["blend_door_actuator", "hvac_control_module"]','[{"id": "actuator_failed", "p": "high", "en": "Door actuator motor failed or stripped", "de": "Klappenmotor defekt oder ausgeschlagen"}, {"id": "linkage_broken", "p": "medium", "en": "Door linkage broken", "de": "Klappengest\u00e4nge gebrochen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1.5, 8.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0210','B','Rain Sensor Module','Regensensor-Modul','The body control module has detected a fault in the rain sensor module on the windshield. Automatic wiper activation based on moisture detection is no longer available.','Das Karosserie-Steuergerät hat einen Fehler im Regensensor-Modul an der Windschutzscheibe erkannt. Die automatische Wischeraktivierung anhand der Feuchtigkeitserkennung ist nicht mehr verfügbar.','["rain_sensor", "body_control_module", "windshield"]','[{"id": "rain_sensor_failed", "p": "high", "en": "Rain sensor failed or detached", "de": "Regensensor defekt oder gel\u00f6st"}, {"id": "windshield_replaced_uncoded", "p": "medium", "en": "Windshield replaced without sensor recoding", "de": "Windschutzscheibe ohne Sensor-Codierung getauscht"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 400], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0220','B','Front Wiper Motor Speed Circuit','Vorderer Wischermotor Drehzahl Schaltung','The body control module has detected that the front wiper motor speed feedback does not match the commanded speed. The motor may run only on one speed or not at all.','Das Karosserie-Steuergerät hat erkannt, dass die Drehzahlrückmeldung des vorderen Wischermotors nicht dem Sollwert entspricht. Der Motor läuft nur auf einer Stufe oder gar nicht.','["front_wiper_motor", "body_control_module", "wiper_relay"]','[{"id": "wiper_motor_failed", "p": "high", "en": "Wiper motor brushes worn", "de": "Wischermotor-Kohlen verschlissen"}, {"id": "wiper_relay_failed", "p": "medium", "en": "Wiper relay failed", "de": "Wischerrelais defekt"}, {"id": "wiper_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 450], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0223','B','SRS Indicator Lamp Circuit Malfunction','Airbag-Warnleuchte Stromkreis Fehlfunktion','The SRS module has detected a fault in the airbag warning lamp circuit. The lamp may be inoperative, which prevents driver notification of stored faults.','Das SRS-Steuergerät hat einen Fehler im Stromkreis der Airbag-Warnleuchte erkannt. Die Leuchte kann ausfallen, sodass gespeicherte Fehler dem Fahrer nicht angezeigt werden.','["srs_warning_lamp", "instrument_cluster", "body_control_module"]','[{"id": "bulb_failure", "p": "high", "en": "Burnt-out warning bulb (older clusters)", "de": "Durchgebrannte Gl\u00fchbirne (\u00e4ltere Kombiinstrumente)"}, {"id": "cluster_fault", "p": "medium", "en": "Instrument cluster fault", "de": "Defekt im Kombiinstrument"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 600], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0226','B','Headlamp Auto-Leveling Front Sensor','Scheinwerfer-Leuchtweitenregulierung Sensor vorn','The body control module reports an implausible signal from the front ride-height sensor used by the automatic headlamp leveling system. Without valid input, the headlamp pitch cannot be corrected for vehicle load.','Das Karosserie-Steuergerät meldet ein unplausibles Signal vom vorderen Niveausensor der automatischen Leuchtweitenregulierung. Ohne gültige Eingabe kann die Scheinwerferneigung nicht beladungsabhängig korrigiert werden.','["front_ride_height_sensor", "headlamp_leveling_module", "body_control_module"]','[{"id": "ride_height_sensor_failed", "p": "high", "en": "Front ride height sensor failed", "de": "Vorderer Niveausensor defekt"}, {"id": "ride_height_linkage", "p": "medium", "en": "Sensor linkage broken or detached", "de": "Sensorhebel gebrochen oder abgefallen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0228','B','Front Fog Lamp Circuit','Nebelscheinwerfer Schaltung','The body control module has detected a fault in the front fog lamp circuit — typically an open bulb, blown fuse, or wiring fault. One or both fog lamps may not work.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Nebelscheinwerfer erkannt — meist eine durchgebrannte Lampe, eine defekte Sicherung oder ein Verkabelungsfehler. Ein oder beide Nebelscheinwerfer arbeiten nicht.','["front_fog_lamp", "fog_lamp_relay", "body_control_module"]','[{"id": "fog_lamp_bulb_blown", "p": "high", "en": "Fog lamp bulb blown", "de": "Nebelscheinwerferlampe durchgebrannt"}, {"id": "fog_lamp_fuse", "p": "medium", "en": "Fog lamp fuse blown", "de": "Sicherung Nebelscheinwerfer durchgebrannt"}, {"id": "fog_lamp_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 200], "estimated_hours": [0.2, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0231','B','Front Marker Lamp Circuit','Vordere Begrenzungsleuchte Stromkreis','The body control module has detected a fault in the front side marker lamp circuit. The lamp does not match the commanded state — the bulb may be burned out or the wiring is open.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der vorderen Begrenzungsleuchte erkannt. Die Leuchte entspricht nicht dem Sollzustand — die Lampe kann durchgebrannt oder die Verkabelung unterbrochen sein.','["marker_lamp", "body_wiring_harness"]','[{"id": "bulb_burned", "p": "high", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or socket corroded", "de": "Verkabelung unterbrochen oder Sockel korrodiert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0233','B','Rear Tail Lamp Circuit','Rückleuchte Stromkreis','The body control module has detected a fault in the rear tail lamp circuit. The lamp does not match the commanded state.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Rückleuchte erkannt. Die Leuchte entspricht nicht dem Sollzustand.','["tail_lamp", "body_wiring_harness"]','[{"id": "bulb_burned", "p": "high", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or socket corroded", "de": "Verkabelung unterbrochen oder Sockel korrodiert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0235','B','Brake Lamp Circuit','Bremsleuchte Stromkreis','The body control module has detected a fault in the brake lamp circuit. One or more brake lamps do not match the commanded state — a safety-relevant fault.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Bremsleuchte erkannt. Eine oder mehrere Bremsleuchten entsprechen nicht dem Sollzustand — ein sicherheitsrelevanter Fehler.','["brake_lamp", "brake_light_switch", "body_wiring_harness"]','[{"id": "bulb_burned", "p": "high", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}, {"id": "brake_switch_failed", "p": "medium", "en": "Brake light switch failed", "de": "Bremslichtschalter defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0237','B','Backup Lamp Circuit','Rückfahrleuchte Stromkreis','The body control module has detected a fault in the backup (reverse) lamp circuit. The lamp does not match the commanded state when reverse gear is engaged.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Rückfahrleuchte erkannt. Die Leuchte entspricht beim Einlegen des Rückwärtsgangs nicht dem Sollzustand.','["backup_lamp", "reverse_switch", "body_wiring_harness"]','[{"id": "bulb_burned", "p": "high", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}, {"id": "reverse_switch_failed", "p": "medium", "en": "Reverse switch failed", "de": "R\u00fcckfahrschalter defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0239','B','License Plate Lamp Circuit','Kennzeichenleuchte Stromkreis','The body control module has detected a fault in the license plate lamp circuit. The lamp does not match the commanded state.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Kennzeichenleuchte erkannt. Die Leuchte entspricht nicht dem Sollzustand.','["license_plate_lamp", "body_wiring_harness"]','[{"id": "bulb_burned", "p": "high", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or socket corroded", "de": "Verkabelung unterbrochen oder Sockel korrodiert"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 100], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0240','B','Headlamp Switch Circuit','Lichtschalter Schaltung','The body control module has detected an implausible state at the headlamp switch — for example simultaneous low and high beam request, or no signal at all. Lighting functions may be erratic.','Das Karosserie-Steuergerät hat einen unplausiblen Zustand am Lichtschalter erkannt — z. B. gleichzeitiges Abblend- und Fernlichtsignal oder kein Signal. Die Lichtfunktionen können unstetig sein.','["headlamp_switch", "body_control_module"]','[{"id": "headlamp_switch_failed", "p": "high", "en": "Headlamp switch worn or failed", "de": "Lichtschalter verschlissen oder defekt"}, {"id": "switch_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0245','B','Driver Window Switch Circuit','Fahrer-Fensterheberschalter Stromkreis','The body control module has detected a fault in the driver window switch circuit. The window may not respond to the switch in the driver door.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Fahrer-Fensterheberschalters erkannt. Das Fenster reagiert möglicherweise nicht auf den Schalter in der Fahrertür.','["window_switch", "door_wiring_harness", "body_control_module"]','[{"id": "switch_failed", "p": "high", "en": "Window switch failed", "de": "Fensterheberschalter defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or shorted", "de": "Verkabelung unterbrochen oder kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0247','B','Passenger Window Switch Circuit','Beifahrer-Fensterheberschalter Stromkreis','The body control module has detected a fault in the passenger window switch circuit. Same fault profile as B0245 but for the passenger window.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Beifahrer-Fensterheberschalters erkannt. Gleiches Fehlerbild wie B0245, jedoch für das Beifahrerfenster.','["window_switch", "door_wiring_harness"]','[{"id": "switch_failed", "p": "high", "en": "Window switch failed", "de": "Fensterheberschalter defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or shorted", "de": "Verkabelung unterbrochen oder kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 250], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0250','B','HVAC Air Temperature Internal Sensor Circuit','Innenraum-Lufttemperatursensor (HVAC) Stromkreis','The HVAC controller has detected a fault in the internal cabin air temperature sensor circuit, used to regulate climate control output.','Das HVAC-Steuergerät hat einen Fehler im Stromkreis des Innenraum-Lufttemperatursensors erkannt, der zur Regelung der Klimaanlage dient.','["cabin_air_temperature_sensor", "hvac_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Sensor element failure", "de": "Defektes Sensorelement"}, {"id": "blower_motor_dirty", "p": "medium", "en": "Aspirator/blower fan dirty", "de": "Aspirator-/L\u00fcftermotor verschmutzt"}, {"id": "wiring_open", "p": "medium", "en": "Open wiring to sensor", "de": "Unterbrochene Verkabelung zum Sensor"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0252','B','Driver Window Motor Down Circuit','Fahrer-Fensterhebermotor Ab-Kreis','The body control module has detected a fault in the driver window motor down-direction control circuit. The window may not lower correctly.','Das Karosserie-Steuergerät hat einen Fehler im Steuerkreis des Fahrer-Fensterhebermotors für die Ab-Richtung erkannt. Das Fenster lässt sich möglicherweise nicht korrekt absenken.','["window_motor", "door_wiring_harness"]','[{"id": "motor_failed", "p": "high", "en": "Window motor failed or seized", "de": "Fensterhebermotor defekt oder fest"}, {"id": "wiring_short", "p": "medium", "en": "Wiring shorted or open", "de": "Verkabelung kurzgeschlossen oder unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0255','B','HVAC Air Temperature External Sensor Circuit','Außentemperatursensor (HVAC) Stromkreis','A fault has been detected in the external (ambient) temperature sensor circuit used by the HVAC and instrument cluster.','Ein Fehler wurde im Stromkreis des Außentemperatursensors erkannt, der von HVAC und Kombiinstrument verwendet wird.','["ambient_temperature_sensor", "hvac_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Ambient sensor failure (often behind front grille)", "de": "Au\u00dfentemperatursensor defekt (meist hinter K\u00fchlergrill)"}, {"id": "connector_water", "p": "medium", "en": "Water in connector", "de": "Wasser im Stecker"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 150], "estimated_hours": [0.2, 1.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0258','B','HVAC Air Mix Door 1 Circuit','HVAC Mischklappe 1 Stromkreis','The HVAC controller reports a fault in the actuator circuit for air mix door 1, which controls the proportion of warm and cool air in the airflow.','Das HVAC-Steuergerät meldet einen Fehler im Aktuatorstromkreis der Mischklappe 1, die das Verhältnis von Warm- und Kaltluft regelt.','["hvac_air_mix_actuator", "hvac_control_module"]','[{"id": "actuator_motor_fault", "p": "high", "en": "Air mix door actuator motor failed", "de": "Stellmotor der Mischklappe defekt"}, {"id": "door_jammed", "p": "medium", "en": "Mix door jammed by debris", "de": "Mischklappe durch Schmutz blockiert"}, {"id": "wiring_open", "p": "medium", "en": "Open wiring to actuator", "de": "Unterbrochene Verkabelung zum Stellmotor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0260','B','Interior Light Circuit','Innenraumbeleuchtung Stromkreis','The body control module has detected a fault in the interior light circuit. The lamp does not match the commanded state — common cause is a stuck door switch causing battery drain.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Innenraumbeleuchtung erkannt. Die Leuchte entspricht nicht dem Sollzustand — häufige Ursache ist ein klemmender Türkontaktschalter mit Batterieentladung.','["interior_lamp", "door_jamb_switch", "body_wiring_harness"]','[{"id": "door_switch_stuck", "p": "high", "en": "Door jamb switch stuck", "de": "T\u00fcrkontaktschalter klemmt"}, {"id": "bulb_burned", "p": "medium", "en": "Bulb burned out", "de": "Leuchtmittel durchgebrannt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.2, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0263','B','HVAC Air Mix Door 2 Circuit','HVAC Mischklappe 2 Stromkreis','A fault has been detected in the air mix door 2 actuator circuit, used in dual-zone HVAC systems for the passenger side.','Ein Fehler wurde im Stellkreis der Mischklappe 2 erkannt, die in 2-Zonen-Klimaanlagen für die Beifahrerseite zuständig ist.','["hvac_air_mix_actuator_2", "hvac_control_module"]','[{"id": "actuator_motor_fault", "p": "high", "en": "Actuator motor failure", "de": "Stellmotor defekt"}, {"id": "door_jammed", "p": "medium", "en": "Mix door jammed", "de": "Mischklappe blockiert"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0265','B','Driver Door Lock/Unlock Switch Circuit','Fahrertür Verriegelungs-/Entriegelungsschalter Schaltung','Driver Door Lock/Unlock Switch Circuit: an electrical fault is present in the circuit. This affects central locking operated from this switch.','Fahrertür Verriegelungs-/Entriegelungsschalter Schaltung: im Stromkreis liegt ein elektrischer Fehler vor. Dies betrifft die von diesem Schalter ausgelöste Zentralverriegelung.','["door_lock_switch", "body_control_module", "door_harness"]','[{"id": "lock_switch_failed", "p": "high", "en": "Lock/unlock switch failed", "de": "Verriegelungsschalter defekt"}, {"id": "door_harness_break", "p": "medium", "en": "Door harness broken in hinge area", "de": "T\u00fcrkabelbaum im Scharnierbereich gebrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 350], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0268','B','HVAC Mode Door 1 Circuit','HVAC Modusklappe 1 Stromkreis','The HVAC mode door 1 actuator circuit, which routes airflow between defrost, vents, and floor, has reported a fault.','Der Stellkreis der Modusklappe 1, die den Luftstrom zwischen Defrost, Lüftungsdüsen und Fußraum verteilt, meldet einen Fehler.','["hvac_mode_actuator", "hvac_control_module"]','[{"id": "actuator_motor_fault", "p": "high", "en": "Mode actuator motor failure", "de": "Stellmotor der Modusklappe defekt"}, {"id": "actuator_calibration", "p": "medium", "en": "Actuator out of calibration", "de": "Stellmotor au\u00dferhalb der Kalibrierung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0270','B','Passenger Door Lock Switch Circuit','Beifahrertür Verriegelungsschalter Schaltung','Passenger Door Lock Switch Circuit: an electrical fault is present in the circuit. This affects central locking operated from this switch.','Beifahrertür Verriegelungsschalter Schaltung: im Stromkreis liegt ein elektrischer Fehler vor. Dies betrifft die von diesem Schalter ausgelöste Zentralverriegelung.','["door_lock_switch", "body_control_module", "door_harness"]','[{"id": "lock_switch_failed", "p": "high", "en": "Lock switch failed", "de": "Verriegelungsschalter defekt"}, {"id": "door_harness_break", "p": "medium", "en": "Door harness broken in hinge area", "de": "T\u00fcrkabelbaum im Scharnierbereich gebrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 350], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0272','B','Power Door Lock Switch Circuit','Zentralverriegelungs-Schalter Stromkreis','The body control module has detected a fault in the power door lock switch circuit. Central locking may not respond to the door switch.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Zentralverriegelungs-Schalters erkannt. Die Zentralverriegelung reagiert möglicherweise nicht auf den Türschalter.','["door_lock_switch", "door_wiring_harness", "body_control_module"]','[{"id": "switch_failed", "p": "high", "en": "Lock switch failed", "de": "Verriegelungsschalter defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or shorted", "de": "Verkabelung unterbrochen oder kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0273','B','HVAC Recirculation Door Circuit','HVAC Umluftklappe Stromkreis','The HVAC recirculation door actuator circuit has reported a fault. Fresh/recirculated air switching may not work.','Der Stellkreis der Umluftklappe meldet einen Fehler. Die Umschaltung zwischen Frisch- und Umluft kann ausfallen.','["hvac_recirculation_actuator", "hvac_control_module"]','[{"id": "actuator_motor_fault", "p": "high", "en": "Recirculation actuator failed", "de": "Umluftklappen-Stellmotor defekt"}, {"id": "door_stuck", "p": "medium", "en": "Recirculation door stuck", "de": "Umluftklappe verklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.8, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0274','B','Trunk Lid Release Switch Circuit','Kofferraumdeckel-Entriegelungsschalter Stromkreis','The body control module has detected a fault in the trunk lid release switch circuit. The trunk may not open via the interior or remote release.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Kofferraumdeckel-Entriegelungsschalters erkannt. Der Kofferraum lässt sich möglicherweise nicht über den Innen- oder Fernentriegelungstaster öffnen.','["trunk_release_switch", "body_wiring_harness"]','[{"id": "switch_failed", "p": "high", "en": "Release switch failed", "de": "Entriegelungsschalter defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open", "de": "Verkabelung unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0278','B','HVAC Defrost Door Circuit','HVAC Defrost-Klappe Stromkreis','A fault is detected in the HVAC defrost door actuator circuit; defrost airflow may not engage.','Im Stellkreis der Defrost-Klappe der Klimaanlage wurde ein Fehler erkannt; der Defrost-Luftstrom kann ausfallen.','["hvac_defrost_actuator", "hvac_control_module"]','[{"id": "actuator_motor_fault", "p": "high", "en": "Defrost actuator failed", "de": "Defrost-Stellmotor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.8, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0283','B','HVAC Blower Motor Circuit','HVAC Gebläsemotor Stromkreis','The HVAC controller reports a fault in the blower motor control circuit. Blower may run at incorrect speed or not at all.','Das HVAC-Steuergerät meldet einen Fehler im Stellkreis des Gebläsemotors. Das Gebläse läuft mit falscher Drehzahl oder gar nicht.','["hvac_blower_motor", "blower_resistor", "hvac_control_module"]','[{"id": "blower_resistor_fault", "p": "high", "en": "Blower resistor or final stage failed", "de": "Gebl\u00e4sewiderstand oder Endstufe defekt"}, {"id": "blower_motor_worn", "p": "medium", "en": "Worn blower motor brushes", "de": "Verschlissene Gebl\u00e4semotor-B\u00fcrsten"}, {"id": "wiring_short", "p": "low", "en": "Short in blower wiring", "de": "Kurzschluss in der Gebl\u00e4severkabelung"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [50, 350], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0288','B','HVAC A/C Pressure Sensor Circuit','Klimadruck-Sensor Stromkreis','A fault has been detected in the A/C refrigerant pressure sensor circuit. The compressor may be disabled to protect the system.','Ein Fehler wurde im Stromkreis des Klimadrucksensors erkannt. Der Kompressor wird zum Schutz des Systems möglicherweise deaktiviert.','["ac_pressure_sensor", "ac_compressor_relay", "hvac_control_module"]','[{"id": "pressure_sensor_failure", "p": "high", "en": "Pressure sensor failure", "de": "Drucksensor defekt"}, {"id": "refrigerant_low", "p": "medium", "en": "Low refrigerant charge", "de": "Zu wenig K\u00e4ltemittel"}, {"id": "connector_fault", "p": "medium", "en": "Faulty sensor connector", "de": "Defekter Sensorstecker"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 250], "estimated_hours": [0.4, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0290','B','Rear Defrost Switch Circuit','Heckscheibenheizungsschalter Schaltung','The body control module has detected a fault in the rear window defroster switch circuit. The switch may be stuck or its signal does not reach the module — the rear defroster cannot be activated.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Heckscheibenheizungsschalters erkannt. Der Schalter klemmt oder das Signal erreicht das Steuergerät nicht — die Heckscheibenheizung kann nicht aktiviert werden.','["rear_defrost_switch", "body_control_module"]','[{"id": "defrost_switch_failed", "p": "high", "en": "Defrost switch failed", "de": "Heckscheibenheizungsschalter defekt"}, {"id": "switch_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0292','B','HVAC A/C Compressor Clutch Circuit','Klimakompressor-Kupplung Stromkreis','The HVAC controller has detected a fault in the A/C compressor clutch control circuit. The compressor may not engage.','Das HVAC-Steuergerät hat einen Fehler im Stellkreis der Klimakompressor-Kupplung erkannt. Der Kompressor schaltet möglicherweise nicht zu.','["ac_compressor_clutch", "ac_compressor_relay", "hvac_control_module"]','[{"id": "clutch_coil_open", "p": "high", "en": "Compressor clutch coil open", "de": "Kupplungsspule des Kompressors unterbrochen"}, {"id": "relay_failure", "p": "medium", "en": "A/C relay failed", "de": "Klimarelais defekt"}, {"id": "wiring_corrosion", "p": "medium", "en": "Corroded compressor connector", "de": "Korrodierter Kompressorstecker"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0300','B','HVAC Evaporator Temperature Sensor Circuit','Verdampfertemperatur-Sensor Stromkreis','The HVAC controller reports a fault in the evaporator temperature sensor circuit, used to prevent evaporator icing.','Das HVAC-Steuergerät meldet einen Fehler im Stromkreis des Verdampfertemperatursensors, der ein Vereisen verhindert.','["evaporator_temperature_sensor", "hvac_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Evaporator sensor failure", "de": "Verdampfersensor defekt"}, {"id": "connector_fault", "p": "medium", "en": "Faulty sensor connector", "de": "Defekter Sensorstecker"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.8, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0305','B','HVAC Sun Load Sensor Circuit','Sonnenlichtsensor (HVAC) Stromkreis','A fault has been detected in the sun load sensor circuit used by automatic climate control to compensate for solar gain.','Im Stromkreis des Sonnenlichtsensors, der von der Klimaautomatik zur Kompensation der Sonneneinstrahlung verwendet wird, wurde ein Fehler erkannt.','["sun_load_sensor", "hvac_control_module"]','[{"id": "sensor_failure", "p": "high", "en": "Sun load sensor failure", "de": "Sonnenlichtsensor defekt"}, {"id": "wiring_open", "p": "medium", "en": "Open wire in dashboard", "de": "Unterbrochener Draht im Armaturenbrett"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 250], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0310','B','Driver Seat Position Sensor Circuit','Fahrersitz Positionssensor Schaltung','Driver Seat Position Sensor Circuit: an electrical fault is present in the circuit. The sensor reports seat position for the memory function and SRS occupant logic.','Fahrersitz Positionssensor Schaltung: im Stromkreis liegt ein elektrischer Fehler vor. Der Sensor meldet die Sitzposition für die Memory-Funktion und die SRS-Insassenlogik.','["seat_position_sensor", "seat_control_module", "seat_harness"]','[{"id": "seat_position_sensor_failed", "p": "high", "en": "Seat position sensor failed", "de": "Sitzpositionssensor defekt"}, {"id": "seat_harness_connector_fault", "p": "medium", "en": "Seat harness connector damaged", "de": "Sitzkabelbaum-Stecker besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0312','B','Driver Seat Forward/Back Switch Circuit','Fahrersitz Vor-/Rück-Schalter Schaltung','The seat module has detected a fault in the fore/aft adjustment switch on the driver seat. Manual adjustment of the seat position may be limited or not work at all.','Das Sitzsteuergerät hat einen Fehler am Vor-/Rück-Verstellschalter des Fahrersitzes erkannt. Die manuelle Verstellung der Sitzposition kann eingeschränkt sein oder gar nicht funktionieren.','["seat_adjust_switch", "seat_control_module"]','[{"id": "seat_switch_failed", "p": "high", "en": "Seat adjustment switch failed", "de": "Sitzverstellschalter defekt"}, {"id": "switch_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 400], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0320','B','Passenger Seat Position Sensor Circuit','Beifahrersitz Positionssensor Schaltung','Passenger Seat Position Sensor Circuit: an electrical fault is present in the circuit. The sensor reports seat position for the memory function and SRS occupant logic.','Beifahrersitz Positionssensor Schaltung: im Stromkreis liegt ein elektrischer Fehler vor. Der Sensor meldet die Sitzposition für die Memory-Funktion und die SRS-Insassenlogik.','["seat_position_sensor", "seat_control_module", "seat_harness"]','[{"id": "seat_position_sensor_failed", "p": "high", "en": "Seat position sensor failed", "de": "Sitzpositionssensor defekt"}, {"id": "seat_harness_connector_fault", "p": "medium", "en": "Seat harness connector damaged", "de": "Sitzkabelbaum-Stecker besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0322','B','Driver Seat Tilt Position Sensor','Fahrersitz Neigungs-Positionssensor','The body control module has detected a fault in the driver seat tilt position sensor. Memory positions for seat back tilt cannot be reliably stored.','Das Karosserie-Steuergerät hat einen Fehler im Neigungs-Positionssensor des Fahrersitzes erkannt. Memory-Positionen für die Sitzlehnenneigung können nicht zuverlässig gespeichert werden.','["seat_position_sensor", "seat_module"]','[{"id": "sensor_failed", "p": "high", "en": "Tilt position sensor failed", "de": "Neigungs-Positionssensor defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open under seat", "de": "Verkabelung unter dem Sitz unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0325','B','Driver Seat Memory Set Switch','Fahrersitz Memory-Speichertaste','The body control module has detected a fault in the driver seat memory set switch circuit. Seat positions cannot be saved to memory presets.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Memory-Speichertaste des Fahrersitzes erkannt. Sitzpositionen können nicht in den Memory-Speicher abgelegt werden.','["memory_switch", "seat_module"]','[{"id": "switch_failed", "p": "high", "en": "Memory set switch failed", "de": "Memory-Speichertaste defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or shorted", "de": "Verkabelung unterbrochen oder kurzgeschlossen"}, {"id": "needs_reflash", "p": "low", "en": "Module software outdated, reflash may resolve", "de": "Modul-Software veraltet, Reflash kann helfen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0327','B','Passenger Seat Position Memory','Beifahrersitz Positions-Memory','The body control module has detected a fault in the passenger seat position memory function. Saved positions cannot be reliably restored.','Das Karosserie-Steuergerät hat einen Fehler in der Positions-Memory-Funktion des Beifahrersitzes erkannt. Gespeicherte Positionen können nicht zuverlässig wiederhergestellt werden.','["seat_module", "seat_position_sensor"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}, {"id": "seat_module_fault", "p": "medium", "en": "Seat module internal fault", "de": "Sitzmodul interner Fehler"}, {"id": "needs_reflash", "p": "low", "en": "Module software outdated, reflash may resolve", "de": "Modul-Software veraltet, Reflash kann helfen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0330','B','HVAC Rear Blower Motor Circuit','Hintere Gebläsemotor (HVAC) Stromkreis','The HVAC controller reports a fault in the rear blower motor circuit, used in vehicles with rear climate zone.','Das HVAC-Steuergerät meldet einen Fehler im Stromkreis des hinteren Gebläsemotors, der in Fahrzeugen mit Klimazone hinten verbaut ist.','["rear_blower_motor", "rear_blower_resistor", "hvac_control_module"]','[{"id": "rear_blower_resistor_fault", "p": "high", "en": "Rear blower resistor failed", "de": "Hinterer Gebl\u00e4sewiderstand defekt"}, {"id": "blower_motor_worn", "p": "medium", "en": "Rear blower motor worn", "de": "Hinterer Gebl\u00e4semotor verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.8, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0335','B','Driver Seat Heater Circuit','Fahrersitzheizung Stromkreis','The body control module has detected a fault in the driver seat heater circuit. The heating element or wiring is open or shorted — the seat does not heat.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Fahrersitzheizung erkannt. Das Heizelement oder die Verkabelung ist unterbrochen oder kurzgeschlossen — der Sitz heizt nicht.','["seat_heater_element", "seat_wiring_harness"]','[{"id": "heater_element_open", "p": "high", "en": "Heater element broken", "de": "Heizmatte gebrochen"}, {"id": "connector_corroded", "p": "medium", "en": "Seat connector corroded", "de": "Sitzstecker korrodiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0337','B','Passenger Seat Heater Circuit','Beifahrersitzheizung Stromkreis','The body control module has detected a fault in the passenger seat heater circuit. Same fault profile as B0335 but for the passenger seat.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Beifahrersitzheizung erkannt. Gleiches Fehlerbild wie B0335, jedoch für den Beifahrersitz.','["seat_heater_element", "seat_wiring_harness"]','[{"id": "heater_element_open", "p": "high", "en": "Heater element broken", "de": "Heizmatte gebrochen"}, {"id": "connector_corroded", "p": "medium", "en": "Seat connector corroded", "de": "Sitzstecker korrodiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0339','B','Rear Seat Heater Circuit','Rücksitzheizung Stromkreis','The body control module has detected a fault in the rear seat heater circuit. The rear heating elements are open or shorted.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis der Rücksitzheizung erkannt. Die hinteren Heizelemente sind unterbrochen oder kurzgeschlossen.','["seat_heater_element", "rear_seat_wiring"]','[{"id": "heater_element_open", "p": "high", "en": "Heater element broken", "de": "Heizmatte gebrochen"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open under seat", "de": "Verkabelung unter dem Sitz unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0341','B','HVAC Heated Seat Driver Circuit','Sitzheizung Fahrer Stromkreis','A fault has been detected in the driver heated seat circuit. Seat heating may be disabled.','Im Stromkreis der Fahrer-Sitzheizung wurde ein Fehler erkannt. Die Sitzheizung kann deaktiviert sein.','["driver_seat_heater", "heated_seat_module"]','[{"id": "heating_element_open", "p": "high", "en": "Heating element broken", "de": "Heizelement gebrochen"}, {"id": "seat_temperature_sensor", "p": "medium", "en": "Seat temperature sensor fault", "de": "Sitztemperatursensor defekt"}, {"id": "connector_loose", "p": "medium", "en": "Loose seat connector", "de": "Loser Sitzstecker"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0342','B','HVAC Heated Seat Passenger Circuit','Sitzheizung Beifahrer Stromkreis','A fault has been detected in the passenger heated seat circuit.','Im Stromkreis der Beifahrer-Sitzheizung wurde ein Fehler erkannt.','["passenger_seat_heater", "heated_seat_module"]','[{"id": "heating_element_open", "p": "high", "en": "Heating element broken", "de": "Heizelement gebrochen"}, {"id": "connector_loose", "p": "medium", "en": "Loose seat connector", "de": "Loser Sitzstecker"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [1.0, 4.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0420','B','Audio System Internal Failure','Audiosystem interner Fehler','The audio head unit reports an internal self-test failure. Symptoms include silent output, frozen display, or repeated reboots of the infotainment system.','Das Audio-Hauptgerät meldet einen Fehler im internen Selbsttest. Symptome sind stummer Ausgang, eingefrorenes Display oder wiederholte Neustarts des Infotainmentsystems.','["audio_head_unit", "infotainment_module"]','[{"id": "head_unit_internal", "p": "high", "en": "Head unit internal fault", "de": "Hauptger\u00e4t interner Fehler"}, {"id": "software_update_required", "p": "medium", "en": "Software update required", "de": "Software-Update erforderlich"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0425','B','Audio Amplifier Internal Failure','Audio-Verstärker interner Fehler','The audio amplifier reports an internal self-test failure. Sound output may be distorted, missing on some channels, or the amplifier enters a protection mode.','Der Audio-Verstärker meldet einen Fehler im internen Selbsttest. Der Klang kann verzerrt sein, einzelne Kanäle ausfallen oder der Verstärker geht in den Schutzmodus.','["audio_amplifier", "infotainment_module"]','[{"id": "amplifier_internal", "p": "high", "en": "Amplifier internal fault", "de": "Verst\u00e4rker interner Fehler"}, {"id": "power_ground_fault", "p": "medium", "en": "Power supply or ground fault", "de": "Versorgungs- oder Massefehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0440','B','Bluetooth Module Fault','Bluetooth-Modul Fehler','The infotainment system has detected a fault in the Bluetooth module. Pairing with phones may fail or audio streaming drops out.','Das Infotainment-System hat einen Fehler im Bluetooth-Modul erkannt. Die Kopplung mit Telefonen kann fehlschlagen oder Audio-Streaming bricht ab.','["bluetooth_module", "infotainment_module", "bluetooth_antenna"]','[{"id": "module_internal", "p": "high", "en": "Bluetooth module internal fault", "de": "Bluetooth-Modul interner Fehler"}, {"id": "antenna_disconnected", "p": "medium", "en": "Antenna cable loose or disconnected", "de": "Antennenkabel lose oder nicht verbunden"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0445','B','USB Hub Fault','USB-Hub Fehler','The infotainment system has detected a fault in the internal USB hub. USB ports may not detect connected devices reliably.','Das Infotainment-System hat einen Fehler im internen USB-Hub erkannt. USB-Anschlüsse erkennen angeschlossene Geräte möglicherweise nicht zuverlässig.','["usb_hub", "infotainment_module"]','[{"id": "hub_internal", "p": "high", "en": "USB hub internal fault", "de": "USB-Hub interner Fehler"}, {"id": "usb_port_damaged", "p": "medium", "en": "USB port physically damaged", "de": "USB-Anschluss mechanisch besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0450','B','Microphone Circuit','Mikrofon Stromkreis','The infotainment system has detected a fault in the hands-free microphone circuit. Voice commands and phone calls may have poor audio quality.','Das Infotainment-System hat einen Fehler im Stromkreis des Freisprech-Mikrofons erkannt. Sprachbefehle und Telefongespräche können schlechte Audioqualität haben.','["microphone", "infotainment_module"]','[{"id": "microphone_failed", "p": "high", "en": "Microphone failed", "de": "Mikrofon defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open or shorted", "de": "Verkabelung unterbrochen oder kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0455','B','Display Module Internal Failure','Anzeigemodul interner Fehler','The instrument cluster or central display module reports an internal self-test failure. Pixels may be missing, the screen may stay dark, or warning indicators may not display correctly.','Das Kombiinstrument oder zentrale Anzeigemodul meldet einen Fehler im internen Selbsttest. Pixel können fehlen, der Bildschirm bleibt dunkel oder Warnsymbole werden nicht korrekt angezeigt.','["display_module", "instrument_cluster"]','[{"id": "display_internal", "p": "high", "en": "Display module internal fault", "de": "Anzeigemodul interner Fehler"}, {"id": "power_ground_fault", "p": "medium", "en": "Power supply or ground fault", "de": "Versorgungs- oder Massefehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0460','B','Bluetooth Antenna Circuit','Bluetooth-Antenne Stromkreis','The infotainment system has detected a fault in the Bluetooth antenna circuit. Range and connection stability may be reduced.','Das Infotainment-System hat einen Fehler im Stromkreis der Bluetooth-Antenne erkannt. Reichweite und Verbindungsstabilität können eingeschränkt sein.','["bluetooth_antenna", "infotainment_module"]','[{"id": "antenna_disconnected", "p": "high", "en": "Antenna cable disconnected", "de": "Antennenkabel nicht verbunden"}, {"id": "antenna_damaged", "p": "medium", "en": "Antenna damaged", "de": "Antenne besch\u00e4digt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0490','B','Display Backlight Circuit','Display-Hintergrundbeleuchtung Stromkreis','The infotainment or instrument cluster module has detected a fault in the display backlight circuit. The display may stay dark or be unreadable in low light.','Das Infotainment- oder Kombiinstrumentmodul hat einen Fehler im Stromkreis der Display-Hintergrundbeleuchtung erkannt. Das Display kann dunkel bleiben oder bei wenig Licht unlesbar sein.','["display_module", "backlight_circuit"]','[{"id": "backlight_failed", "p": "high", "en": "Backlight LEDs or inverter failed", "de": "Hintergrundbeleuchtung-LEDs oder Inverter defekt"}, {"id": "display_internal", "p": "medium", "en": "Display module internal fault", "de": "Anzeigemodul interner Fehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [0.5, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0500','B','Driver Power Window Circuit Malfunction','Fensterheber Fahrer Stromkreis Fehlfunktion','The driver power window motor or switch circuit has reported a fault. The window may not operate.','Der Stromkreis des Fahrer-Fensterhebermotors oder -schalters meldet einen Fehler. Das Fenster funktioniert möglicherweise nicht.','["driver_window_motor", "driver_window_switch", "door_module"]','[{"id": "window_motor_failure", "p": "high", "en": "Window motor worn or seized", "de": "Fensterhebermotor verschlissen oder fest"}, {"id": "switch_failure", "p": "medium", "en": "Master window switch failure", "de": "Defekter Hauptfensterheber-Schalter"}, {"id": "regulator_broken", "p": "medium", "en": "Window regulator broken", "de": "Fensterheber-Mechanik gebrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0501','B','Passenger Power Window Circuit Malfunction','Fensterheber Beifahrer Stromkreis Fehlfunktion','A fault has been detected in the passenger power window circuit.','Im Stromkreis des Beifahrer-Fensterhebers wurde ein Fehler erkannt.','["passenger_window_motor", "passenger_window_switch", "door_module"]','[{"id": "window_motor_failure", "p": "high", "en": "Window motor failed", "de": "Fensterhebermotor defekt"}, {"id": "switch_contacts_dirty", "p": "medium", "en": "Dirty switch contacts", "de": "Verschmutzte Schalterkontakte"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0502','B','Left Rear Power Window Circuit Malfunction','Fensterheber hinten links Stromkreis Fehlfunktion','A fault has been detected in the left rear power window circuit.','Im Stromkreis des Fensterhebers hinten links wurde ein Fehler erkannt.','["left_rear_window_motor", "rear_door_module"]','[{"id": "window_motor_failure", "p": "high", "en": "Rear window motor failed", "de": "Hinterer Fensterhebermotor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0503','B','Right Rear Power Window Circuit Malfunction','Fensterheber hinten rechts Stromkreis Fehlfunktion','A fault has been detected in the right rear power window circuit.','Im Stromkreis des Fensterhebers hinten rechts wurde ein Fehler erkannt.','["right_rear_window_motor", "rear_door_module"]','[{"id": "window_motor_failure", "p": "high", "en": "Rear window motor failed", "de": "Hinterer Fensterhebermotor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [1.0, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0510','B','Driver Door Open Switch','Fahrertür-Kontaktschalter','The body control module has detected a fault in the driver door open (jamb) switch. The door open state cannot be reliably read — affects interior light, seat belt warning, and remote start interlocks.','Das Karosserie-Steuergerät hat einen Fehler im Fahrertür-Kontaktschalter erkannt. Der Türöffnungs-Zustand kann nicht zuverlässig gelesen werden — betrifft Innenraumbeleuchtung, Gurtwarnung und Fernstart-Sperren.','["door_jamb_switch", "door_wiring_harness", "body_control_module"]','[{"id": "switch_stuck", "p": "high", "en": "Door jamb switch stuck or corroded", "de": "T\u00fcrkontaktschalter klemmt oder korrodiert"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open in door hinge", "de": "Verkabelung im T\u00fcrscharnier unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0520','B','Passenger Door Open Switch','Beifahrertür-Kontaktschalter','The body control module has detected a fault in the passenger door open (jamb) switch. Same fault profile as B0510 but for the passenger door.','Das Karosserie-Steuergerät hat einen Fehler im Beifahrertür-Kontaktschalter erkannt. Gleiches Fehlerbild wie B0510, jedoch für die Beifahrertür.','["door_jamb_switch", "door_wiring_harness", "body_control_module"]','[{"id": "switch_stuck", "p": "high", "en": "Door jamb switch stuck or corroded", "de": "T\u00fcrkontaktschalter klemmt oder korrodiert"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open in door hinge", "de": "Verkabelung im T\u00fcrscharnier unterbrochen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0530','B','Driver Door Lock Actuator Circuit','Türschloss-Aktuator Fahrer Stromkreis','The body control module has detected a fault in the driver door lock actuator circuit. Central locking may not work for the driver door.','Das Karosserie-Steuergerät hat einen Fehler im Stromkreis des Fahrer-Türschlossmotors erkannt. Die Zentralverriegelung der Fahrertür funktioniert möglicherweise nicht.','["driver_door_lock_actuator", "body_control_module", "driver_door_module"]','[{"id": "actuator_motor_failure", "p": "high", "en": "Lock actuator motor failed", "de": "T\u00fcrschloss-Stellmotor defekt"}, {"id": "door_harness_break", "p": "medium", "en": "Wire break in door harness", "de": "Kabelbruch im T\u00fcrstrang"}, {"id": "connector_corrosion", "p": "medium", "en": "Corroded door connector", "de": "Korrodierter T\u00fcrstecker"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [1.0, 3.0]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('B0531','B','Passenger Door Lock Actuator Circuit','Türschloss-Aktuator Beifahrer Stromkreis','A fault has been detected in the passenger door lock actuator circuit.','Im Stromkreis des Beifahrer-Türschlossmotors wurde ein Fehler erkannt.','["passenger_door_lock_actuator", "body_control_module"]','[{"id": "actuator_motor_failure", "p": "high", "en": "Lock actuator failed", "de": "T\u00fcrschlossmotor defekt"}, {"id": "door_harness_break", "p": "medium", "en": "Wire break in door harness", "de": "Kabelbruch im T\u00fcrstrang"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [1.0, 3.0]}',0);
