INSERT OR IGNORE INTO dtc_codes VALUES('C0069','C','Yaw Rate/Longitude Sensors','Gier-/Längsbeschleunigungssensoren','Generic fault on yaw rate/longitudinal acceleration sensor cluster.','Allgemeiner Fehler am Sensorcluster Gierrate/Längsbeschleunigung.','["yaw_long_sensor_cluster"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor cluster failed", "de": "Sensorcluster defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
