INSERT OR IGNORE INTO dtc_codes VALUES('C006B','C','Stability System Active Too Long','Stabilitätssystem zu lange aktiv','Electronic stability control intervened for an excessive duration.','Elektronische Stabilitätskontrolle griff über zu lange Dauer ein.','["esc_module"]','[{"id": "extended_intervention", "p": "high", "en": "Extended intervention from low traction or driver behavior", "de": "Lange Eingriffe durch geringe Traktion oder Fahrweise"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 500], "estimated_hours": [0.3, 2]}',1);
