INSERT OR IGNORE INTO dtc_codes VALUES('C0070','C','Vehicle Speed Sensor Circuit','Fahrzeuggeschwindigkeitssensor Stromkreis','The chassis controller detects a fault in the dedicated vehicle speed sensor circuit (when present in addition to wheel speed sensors).','Das Fahrwerksteuergeraet erkennt einen Fehler im separaten Stromkreis des Fahrzeuggeschwindigkeitssensors (sofern zusaetzlich zu den Raddrehzahlsensoren vorhanden).','["vehicle_speed_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open", "de": "Leitung unterbrochen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0071','C','2/4 Wheel Drive Status Input','2WD/4WD-Statussignal','Fault on 2WD/4WD status signal input.','Fehler am Eingangssignal 2WD/4WD-Status.','["drive_mode_switch"]','[{"id": "switch_fault", "p": "high", "en": "Switch or wiring fault", "de": "Schalter oder Verkabelung defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
