INSERT OR IGNORE INTO dtc_codes VALUES('C0073','C','Delivered Driving Torque','Geliefertes Antriebsmoment','Engine-delivered driving torque does not match TCS request.','Vom Motor geliefertes Antriebsmoment passt nicht zur Anforderung der Traktionskontrolle.','["ecm", "tcs_module"]','[{"id": "ecm_communication_fault", "p": "high", "en": "ECM/TCS communication issue", "de": "Kommunikationsfehler ECM/TCS"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0074','C','Requested Driving Torque','Angefordertes Antriebsmoment','Driving torque request from TCS rejected or out of range.','Drehmoment-Anforderung der Traktionskontrolle abgewiesen oder außerhalb des Bereichs.','["tcs_module", "ecm"]','[{"id": "ecm_communication_fault", "p": "high", "en": "ECM/TCS communication issue", "de": "Kommunikationsfehler ECM/TCS"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
