INSERT OR IGNORE INTO dtc_codes VALUES('C0077','C','Low Tire Pressure','Reifendruck niedrig','Tire pressure monitoring system detected low tire pressure.','Reifendruckkontrollsystem erkennt zu niedrigen Reifendruck.','["tires"]','[{"id": "low_tire_pressure", "p": "high", "en": "Tire(s) under-inflated", "de": "Reifen mit zu wenig Luftdruck"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [0, 30], "estimated_hours": [0.1, 0.3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0078','C','Tire Diameter','Reifendurchmesser','Detected wheel speed implies tire diameter outside expected range — typically wrong tire size or mismatched tires.','Geschwindigkeitssignale legen einen Reifendurchmesser außerhalb des Sollbereichs nahe — meist falsche Reifengröße oder unterschiedliche Reifen.','["tires"]','[{"id": "wrong_tire", "p": "high", "en": "Wrong tire size or mismatch", "de": "Falsche Reifengr\u00f6\u00dfe oder ungleiche Reifen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [0, 800], "estimated_hours": [0.5, 2]}',1);
