INSERT OR IGNORE INTO dtc_codes VALUES('C0080','C','Wheel Speed Mismatch (Front Axle)','Raddrehzahl-Abweichung Vorderachse','Front axle wheel speeds differ beyond the plausibility threshold over time. Often caused by mismatched tyre rolling circumference or a partially failing sensor.','Die Raddrehzahlen der Vorderachse weichen ueber laengere Zeit ueber dem Plausibilitaetsschwellwert voneinander ab. Haeufig durch unterschiedliche Reifenabrollumfaenge oder einen teilweise defekten Sensor verursacht.','["wheel_speed_sensor_fl", "wheel_speed_sensor_fr", "tyres"]','[{"id": "tyre_size_mismatch", "p": "high", "en": "Mixed tyre sizes or worn tyre on one side", "de": "Gemischte Reifengroessen oder einseitig abgefahrener Reifen"}, {"id": "sensor_drift", "p": "medium", "en": "One sensor drifting", "de": "Ein Sensor mit Drift"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [0, 400], "estimated_hours": [0.3, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0081','C','Wheel Speed Mismatch (Rear Axle)','Raddrehzahl-Abweichung Hinterachse','Rear axle wheel speeds differ beyond the plausibility threshold. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Die Raddrehzahlen der Hinterachse weichen ueber dem Plausibilitaetsschwellwert ab. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis z','["wheel_speed_sensor_rl", "wheel_speed_sensor_rr", "tyres"]','[{"id": "tyre_size_mismatch", "p": "high", "en": "Tyre size mismatch", "de": "Reifengroessen-Abweichung"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor drift", "de": "Sensor-Drift"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [0, 400], "estimated_hours": [0.3, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0082','C','Brake System Malfunction Indicator','Bremssystem-Warnleuchte','Brake system malfunction indicator circuit fault.','Fehler am Schaltkreis der Bremssystem-Warnleuchte.','["brake_warning_lamp"]','[{"id": "lamp_circuit_fault", "p": "high", "en": "Lamp circuit or bulb fault", "de": "Lampenstromkreis oder Birne defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.1, 0.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0083','C','Tire Pressure Monitor Malfunction Indicator','Reifendruckkontrolle-Warnleuchte','TPMS malfunction indicator circuit fault.','Fehler am Schaltkreis der TPMS-Warnleuchte.','["tpms_lamp"]','[{"id": "lamp_circuit_fault", "p": "high", "en": "Lamp circuit or bulb fault", "de": "Lampenstromkreis oder Birne defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.1, 0.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0084','C','Traction Active Indicator','Traktionskontrolle Aktiv-Anzeige','Traction control active indicator lamp circuit fault.','Fehler am Schaltkreis der Aktiv-Anzeige der Traktionskontrolle.','["tcs_active_lamp"]','[{"id": "lamp_circuit_fault", "p": "high", "en": "Lamp circuit or bulb fault", "de": "Lampenstromkreis oder Birne defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.1, 0.5]}',1);
