INSERT OR IGNORE INTO dtc_codes VALUES('C0086','C','Vehicle Dynamics Indicator','Fahrdynamik-Anzeige','Vehicle dynamics control indicator lamp circuit fault.','Fehler am Schaltkreis der Fahrdynamik-Anzeige.','["vdc_lamp"]','[{"id": "lamp_circuit_fault", "p": "high", "en": "Lamp circuit or bulb fault", "de": "Lampenstromkreis oder Birne defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 150], "estimated_hours": [0.1, 0.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0089','C','TCS Disable Switch','Traktionskontrolle Deaktivierungsschalter','Fault on TCS disable switch.','Fehler am Deaktivierungsschalter der Traktionskontrolle.','["tcs_disable_switch"]','[{"id": "switch_fault", "p": "high", "en": "Switch failed or wiring fault", "de": "Schalter defekt oder Verkabelung"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C008A','C','TCS Mode Control','Traktionskontrolle Modussteuerung','Fault on TCS mode control input (offroad/sport mode etc.).','Fehler am Eingang der Modussteuerung der Traktionskontrolle (Gelände-/Sport-Modus).','["tcs_mode_switch"]','[{"id": "switch_fault", "p": "high", "en": "Mode switch fault", "de": "Modusschalter defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0090','C','Hydraulic Brake Pressure Sensor Circuit','Bremsdrucksensor Stromkreis','The brake pressure sensor in the master cylinder or hydraulic block reports an implausible signal or no signal. The fault disables ABS, stability control and brake assist.','Der Bremsdrucksensor im Hauptbremszylinder oder Hydraulikblock meldet ein unplausibles oder fehlendes Signal. Der Fehler deaktiviert ABS, Stabilitaetsregelung und Bremsassistent.','["brake_pressure_sensor", "abs_control_module", "sensor_wiring"]','[{"id": "pressure_sensor_failed", "p": "high", "en": "Pressure sensor element failed", "de": "Drucksensorelement defekt"}, {"id": "sensor_wiring_fault", "p": "medium", "en": "Sensor wiring fault", "de": "Sensorleitungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 3.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0091','C','Hydraulic Brake Pressure Sensor Circuit Range/Performance','Bremsdrucksensor Bereich/Leistung','The brake pressure sensor signal is outside the plausibility band relative to pedal application. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code ','Das Signal des Bremsdrucksensors liegt im Verhaeltnis zur Pedalbetaetigung ausserhalb des Plausibilitaetsbandes. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wa','["brake_pressure_sensor", "abs_control_module"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor drift with age", "de": "Sensor-Drift mit Alter"}, {"id": "hydraulic_block_leak", "p": "low", "en": "Internal hydraulic block leak", "de": "Interner Leckage im Hydraulikblock"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1100], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0092','C','4WD/AWD Power Transfer Unit Position Sensor B','4WD/AWD Verteilergetriebe Positionssensor B','Fault on 4WD/AWD power transfer unit (PTU) position sensor B.','Fehler am Positionssensor B des Verteilergetriebes (PTU).','["ptu_pos_sensor_b"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
