INSERT OR IGNORE INTO dtc_codes VALUES('C0094','C','4WD/AWD Rear Differential Unit Temperature Sensor','4WD/AWD Hinterachsdifferential Temperatursensor','Fault on rear differential unit temperature sensor.','Fehler am Temperatursensor des Hinterachsdifferentials.','["rear_diff_temp_sensor"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1000], "estimated_hours": [1, 3]}',1);
