INSERT OR IGNORE INTO dtc_codes VALUES('C0099','C','ABS Control Module Internal Fault','ABS-Steuergeraet interner Fehler','The ABS control module fails its internal self-test (RAM, ROM or processor watchdog). ABS and stability control are disabled.','Das ABS-Steuergeraet besteht den internen Selbsttest nicht (RAM, ROM oder Prozessor-Watchdog). ABS und Stabilitaetsregelung werden deaktiviert.','["abs_control_module"]','[{"id": "module_internal_failure", "p": "high", "en": "Module internally failed", "de": "Steuergeraet intern defekt"}, {"id": "power_supply_undervoltage", "p": "medium", "en": "Power supply undervoltage during operation", "de": "Spannungsversorgung im Betrieb zu niedrig"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [1, 4]}',0);
