INSERT OR IGNORE INTO dtc_codes VALUES('C00A2','C','Driveline Control Module Power Transfer Unit Control Circuit Driver','Antriebsstrang-Modul Verteilergetriebe-Treiber','Fault on driveline control module driver for PTU control circuit.','Fehler am Treiber für den Verteilergetriebe-Steuerschaltkreis im Antriebsstrang-Modul.','["driveline_module", "ptu"]','[{"id": "driver_fault", "p": "high", "en": "Internal driver fault", "de": "Interner Treiber defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A3','C','Driveline Control Module Rear Differential Unit A Control Circuit Driver','Antriebsstrang-Modul Hinterachsdifferential A-Treiber','Fault on driveline control module driver for rear differential unit A.','Fehler am Treiber für den Steuerschaltkreis des Hinterachsdifferentials A.','["driveline_module", "rear_diff_actuator_a"]','[{"id": "driver_fault", "p": "high", "en": "Internal driver fault", "de": "Interner Treiber defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A4','C','Driveline Control Module Rear Differential Unit B Control Circuit Driver','Antriebsstrang-Modul Hinterachsdifferential B-Treiber','Fault on driveline control module driver for rear differential unit B.','Fehler am Treiber für den Steuerschaltkreis des Hinterachsdifferentials B.','["driveline_module", "rear_diff_actuator_b"]','[{"id": "driver_fault", "p": "high", "en": "Internal driver fault", "de": "Interner Treiber defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A5','C','Driveline Control Module Transfer Case Unit Control Circuit Driver','Antriebsstrang-Modul Verteilergetriebe-Treiber (Transfer Case)','Fault on driveline control module driver for transfer case unit.','Fehler am Treiber für den Steuerschaltkreis des Verteilergetriebes (Transfer Case).','["driveline_module", "transfer_case"]','[{"id": "driver_fault", "p": "high", "en": "Internal driver fault", "de": "Interner Treiber defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A6','C','4WD/AWD Transfer Case Unit Actuator','4WD/AWD Verteilergetriebe Aktuator','Fault on transfer case unit actuator.','Fehler am Aktuator des Verteilergetriebes.','["transfer_case_actuator"]','[{"id": "actuator_failed", "p": "high", "en": "Actuator failed", "de": "Aktuator defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A7','C','4WD/AWD Transfer Case Unit Actuator Position Sensor A','4WD/AWD Verteilergetriebe Aktuator Positionssensor A','Fault on transfer case actuator position sensor A.','Fehler am Positionssensor A des Verteilergetriebe-Aktuators.','["transfer_case_actuator_pos_a"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C00A8','C','4WD/AWD Transfer Case Unit Actuator Position Sensor B','4WD/AWD Verteilergetriebe Aktuator Positionssensor B','Fault on transfer case actuator position sensor B.','Fehler am Positionssensor B des Verteilergetriebe-Aktuators.','["transfer_case_actuator_pos_b"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0110','C','ABS Pump Motor Circuit Malfunction','ABS-Pumpenmotor Stromkreis-Fehlfunktion','The ABS control module has detected a fault in the hydraulic pump motor circuit. The pump rebuilds brake pressure during ABS regulation — without it, ABS and stability control are disabled.','Das ABS-Steuergerät hat einen Fehler im Stromkreis des hydraulischen Pumpenmotors erkannt. Die Pumpe baut bei ABS-Regelung den Bremsdruck wieder auf — ohne sie werden ABS und Stabilitätsregelung deaktiviert.','["abs_pump_motor", "abs_control_module", "abs_relay", "power_supply_wiring"]','[{"id": "abs_pump_motor_failed", "p": "high", "en": "ABS pump motor failed (worn brushes, seized)", "de": "ABS-Pumpenmotor defekt (B\u00fcrstenverschlei\u00df, festgefressen)"}, {"id": "abs_relay_failed", "p": "medium", "en": "ABS pump relay failed", "de": "ABS-Pumpenrelais defekt"}, {"id": "abs_power_wiring", "p": "low", "en": "Power supply wiring or fuse fault", "de": "Versorgungsleitungs- oder Sicherungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0111','C','ABS Activation Excessively Long','ABS-Eingriff zu lang','ABS regulation has been active longer than the allowed duration during a single brake event, suggesting a sensor or hydraulic problem.','Die ABS-Regelung war waehrend eines einzelnen Bremsvorgangs laenger aktiv als zulaessig; dies deutet auf ein Sensor- oder Hydraulikproblem hin.','["abs_control_module", "abs_hydraulic_block", "wheel_speed_sensors"]','[{"id": "low_friction_road", "p": "medium", "en": "Extreme low-friction road condition", "de": "Extrem rutschige Fahrbahn"}, {"id": "hydraulic_leak", "p": "medium", "en": "Hydraulic block internal leak", "de": "Interner Leck im Hydraulikblock"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1400], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0112','C','ABS Activation Frequency Too High','ABS-Aktivierungshaeufigkeit zu hoch','ABS regulation cycles activate more frequently than the plausibility model allows.','ABS-Regelzyklen werden haeufiger aktiv als das Plausibilitaetsmodell zulaesst.','["abs_control_module", "wheel_speed_sensors"]','[{"id": "sensor_signal_noise", "p": "high", "en": "Wheel speed sensor signal noise", "de": "Stoersignal eines Raddrehzahlsensors"}, {"id": "tone_ring_damaged", "p": "medium", "en": "Tone ring damaged", "de": "Polrad beschaedigt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0121','C','Valve Relay Circuit Malfunction','Ventilrelais Stromkreis-Fehlfunktion','The ABS control module has detected a fault in the valve relay circuit, which supplies power to the ABS solenoid valves. With this fault, the module cannot energize the valves and ABS is disabled.','Das ABS-Steuergerät hat einen Fehler im Stromkreis des Ventilrelais erkannt, das die ABS-Magnetventile mit Spannung versorgt. Bei aktivem Fehler kann das Steuergerät die Ventile nicht ansteuern und ABS wird deaktiviert.','["abs_valve_relay", "abs_control_module", "abs_hydraulic_unit"]','[{"id": "valve_relay_failed", "p": "high", "en": "Valve relay failed", "de": "Ventilrelais defekt"}, {"id": "abs_module_internal", "p": "medium", "en": "Internal ABS module fault (relay integrated)", "de": "Interner Fehler im ABS-Steuerger\u00e4t (Relais integriert)"}, {"id": "abs_power_wiring", "p": "low", "en": "Power supply wiring or fuse fault", "de": "Versorgungsleitungs- oder Sicherungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0128','C','Low Brake Fluid Indicated','Bremsfluessigkeitsstand niedrig','The brake fluid level switch in the master cylinder reservoir reports a low level. ABS and stability control may be deactivated as a precaution.','Der Bremsfluessigkeitsstand-Schalter im Ausgleichsbehaelter meldet einen zu niedrigen Pegel. ABS und Stabilitaetsregelung koennen vorsichtshalber deaktiviert werden.','["brake_fluid_level_switch", "master_cylinder_reservoir"]','[{"id": "pad_wear", "p": "high", "en": "Worn brake pads (fluid drops as pistons extend)", "de": "Verschlissene Bremsbelaege (Fluessigkeit sinkt mit Kolbenausschub)"}, {"id": "hydraulic_leak", "p": "medium", "en": "Hydraulic system leak", "de": "Leck im Hydrauliksystem"}, {"id": "switch_failed", "p": "low", "en": "Level switch failed", "de": "Pegelschalter defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [10, 400], "estimated_hours": [0.2, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0131','C','Master Cylinder Pressure Sensor Range/Performance','Hauptbremszylinder-Drucksensor Funktionsbereich','The ABS or stability control module has detected an implausible signal from the master cylinder brake pressure sensor. This sensor reports driver brake input and is used by ABS and ESP for control decisions.','Das ABS- oder ESP-Steuergerät hat ein unplausibles Signal vom Drucksensor des Hauptbremszylinders erkannt. Der Sensor meldet die Bremsanforderung des Fahrers und wird von ABS und ESP für Regelentscheidungen genutzt.','["master_cylinder_pressure_sensor", "abs_control_module", "esp_control_module"]','[{"id": "pressure_sensor_failed", "p": "high", "en": "Pressure sensor failed", "de": "Drucksensor defekt"}, {"id": "pressure_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "brake_fluid_air", "p": "low", "en": "Air in brake system causing erratic pressure", "de": "Luft im Bremssystem verursacht unstetigen Druck"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0136','C','Stop Lamp Switch Circuit','Bremslichtschalter Stromkreis','The ABS or stability control module sees an implausible brake light switch signal. Stability and brake assist functions can be limited until the fault is cleared.','Das ABS- oder ESP-Steuergeraet erkennt ein unplausibles Bremslichtschalter-Signal. Stabilitaets- und Bremsassistent-Funktionen koennen bis zur Behebung eingeschraenkt sein.','["brake_light_switch", "abs_control_module", "wiring"]','[{"id": "switch_failed", "p": "high", "en": "Brake light switch failed", "de": "Bremslichtschalter defekt"}, {"id": "switch_misadjusted", "p": "medium", "en": "Switch misadjusted on pedal bracket", "de": "Schalter am Pedalbock falsch eingestellt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [20, 150], "estimated_hours": [0.2, 1]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0141','C','Left Front ABS Inlet Solenoid Circuit','ABS-Einlassventil vorne links Schaltung','Left Front ABS Inlet Solenoid Circuit: an electrical fault is present in the circuit.','ABS-Einlassventil vorne links Schaltung: im Stromkreis liegt ein elektrischer Fehler vor.','["abs_inlet_solenoid", "abs_hydraulic_unit", "abs_control_module"]','[{"id": "abs_solenoid_failed", "p": "high", "en": "Inlet solenoid coil open or shorted", "de": "Spule des Einlassventils unterbrochen oder kurzgeschlossen"}, {"id": "abs_module_internal", "p": "medium", "en": "Internal ABS module fault", "de": "Interner Fehler im ABS-Steuerger\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0146','C','Left Front ABS Outlet Solenoid Circuit','ABS-Auslassventil vorne links Schaltung','Left Front ABS Outlet Solenoid Circuit: an electrical fault is present in the circuit.','ABS-Auslassventil vorne links Schaltung: im Stromkreis liegt ein elektrischer Fehler vor.','["abs_outlet_solenoid", "abs_hydraulic_unit", "abs_control_module"]','[{"id": "abs_solenoid_failed", "p": "high", "en": "Outlet solenoid coil open or shorted", "de": "Spule des Auslassventils unterbrochen oder kurzgeschlossen"}, {"id": "abs_module_internal", "p": "medium", "en": "Internal ABS module fault", "de": "Interner Fehler im ABS-Steuerger\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0148','C','Right Front ABS Outlet Solenoid B Circuit Malfunction','ABS-Auslassventil B vorne rechts Stromkreis-Fehlfunktion','The ABS module has detected an electrical fault in the secondary outlet solenoid for the right front wheel. ABS and stability control are disabled while the fault is active.','Das ABS-Steuergerät hat einen elektrischen Fehler im zweiten Auslassventil für das rechte Vorderrad erkannt. ABS und Stabilitätsregelung sind bei aktivem Fehler deaktiviert.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Outlet solenoid valve failed (open or shorted)", "de": "Auslassventil defekt (Unterbrechung oder Kurzschluss)"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal fault in ABS hydraulic unit", "de": "Interner Fehler im ABS-Hydraulikaggregat"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0151','C','Right Front ABS Inlet Solenoid Circuit','ABS-Einlassventil vorne rechts Schaltung','Right Front ABS Inlet Solenoid Circuit: an electrical fault is present in the circuit.','ABS-Einlassventil vorne rechts Schaltung: im Stromkreis liegt ein elektrischer Fehler vor.','["abs_inlet_solenoid", "abs_hydraulic_unit", "abs_control_module"]','[{"id": "abs_solenoid_failed", "p": "high", "en": "Inlet solenoid coil open or shorted", "de": "Spule des Einlassventils unterbrochen oder kurzgeschlossen"}, {"id": "abs_module_internal", "p": "medium", "en": "Internal ABS module fault", "de": "Interner Fehler im ABS-Steuerger\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0153','C','Right Front ABS Inlet Solenoid B Circuit Malfunction','ABS-Einlassventil B vorne rechts Stromkreis-Fehlfunktion','Electrical fault in the secondary inlet solenoid for the right front wheel. Pressure modulation for that wheel is no longer possible and ABS is disabled.','Elektrischer Fehler im zweiten Einlassventil für das rechte Vorderrad. Eine Druckmodulation an diesem Rad ist nicht mehr möglich und ABS ist deaktiviert.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Inlet solenoid valve failed", "de": "Einlassventil defekt"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal hydraulic unit fault", "de": "Interner Hydraulikaggregat-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0156','C','Right Front ABS Outlet Solenoid Circuit','ABS-Auslassventil vorne rechts Schaltung','Right Front ABS Outlet Solenoid Circuit: an electrical fault is present in the circuit.','ABS-Auslassventil vorne rechts Schaltung: im Stromkreis liegt ein elektrischer Fehler vor.','["abs_outlet_solenoid", "abs_hydraulic_unit", "abs_control_module"]','[{"id": "abs_solenoid_failed", "p": "high", "en": "Outlet solenoid coil open or shorted", "de": "Spule des Auslassventils unterbrochen oder kurzgeschlossen"}, {"id": "abs_module_internal", "p": "medium", "en": "Internal ABS module fault", "de": "Interner Fehler im ABS-Steuerger\u00e4t"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0158','C','Left Rear ABS Inlet Solenoid Circuit Malfunction','ABS-Einlassventil hinten links Stromkreis-Fehlfunktion','Electrical fault in the inlet solenoid for the left rear wheel. ABS is disabled and the warning lamp is illuminated.','Elektrischer Fehler im Einlassventil für das hintere linke Rad. ABS ist deaktiviert und die Warnleuchte leuchtet.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Inlet solenoid valve failed", "de": "Einlassventil defekt"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal hydraulic unit fault", "de": "Interner Hydraulikaggregat-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0161','C','ABS/TCS Brake Switch Circuit','ABS/ASR-Bremslichtschalter Schaltung','The ABS or traction control module has detected an implausible signal from the brake light switch. The switch tells the module whether the driver is braking and is used to inhibit traction control during braking.','Das ABS- oder ASR-Steuergerät hat ein unplausibles Signal vom Bremslichtschalter erkannt. Der Schalter meldet dem Steuergerät die Betätigung der Bremse und wird zur Sperre der Antriebsschlupfregelung beim Bremsen genutzt.','["brake_light_switch", "abs_control_module", "tcs_control_module"]','[{"id": "brake_switch_failed", "p": "high", "en": "Brake light switch failed or misadjusted", "de": "Bremslichtschalter defekt oder falsch justiert"}, {"id": "brake_switch_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0163','C','Left Rear ABS Outlet Solenoid Circuit Malfunction','ABS-Auslassventil hinten links Stromkreis-Fehlfunktion','Electrical fault in the outlet solenoid for the left rear wheel. ABS pressure release for this wheel is no longer possible.','Elektrischer Fehler im Auslassventil für das hintere linke Rad. Ein Druckabbau am Rad ist nicht mehr möglich.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Outlet solenoid valve failed", "de": "Auslassventil defekt"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal hydraulic unit fault", "de": "Interner Hydraulikaggregat-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0168','C','Right Rear ABS Inlet Solenoid Circuit Malfunction','ABS-Einlassventil hinten rechts Stromkreis-Fehlfunktion','Electrical fault in the inlet solenoid for the right rear wheel. ABS is disabled while the fault is active.','Elektrischer Fehler im Einlassventil für das hintere rechte Rad. ABS ist bei aktivem Fehler deaktiviert.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Inlet solenoid valve failed", "de": "Einlassventil defekt"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal hydraulic unit fault", "de": "Interner Hydraulikaggregat-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0173','C','Right Rear ABS Outlet Solenoid Circuit Malfunction','ABS-Auslassventil hinten rechts Stromkreis-Fehlfunktion','Electrical fault in the outlet solenoid for the right rear wheel. ABS pressure release for this wheel is no longer possible.','Elektrischer Fehler im Auslassventil für das hintere rechte Rad. Ein Druckabbau am Rad ist nicht mehr möglich.','["abs_hydraulic_unit", "abs_control_module", "solenoid_valve"]','[{"id": "solenoid_valve_failed", "p": "high", "en": "Outlet solenoid valve failed", "de": "Auslassventil defekt"}, {"id": "hydraulic_unit_internal_fault", "p": "medium", "en": "Internal hydraulic unit fault", "de": "Interner Hydraulikaggregat-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1500], "estimated_hours": [1.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0185','C','Lateral Acceleration Sensor Range/Performance','Querbeschleunigungssensor Bereich/Leistung','The stability control module has detected that the lateral acceleration sensor signal is out of the expected range or does not match other inertial sensors. ESP and roll-stability functions may be disabled.','Das ESP-Steuergerät hat festgestellt, dass das Signal des Querbeschleunigungssensors außerhalb des erwarteten Bereichs liegt oder nicht zu anderen Inertialsensoren passt. ESP und Wankstabilität können deaktiviert sein.','["lateral_acceleration_sensor", "esp_control_module", "sensor_cluster"]','[{"id": "sensor_failed", "p": "high", "en": "Lateral acceleration sensor failed or drifted", "de": "Querbeschleunigungssensor defekt oder driftet"}, {"id": "sensor_misaligned", "p": "medium", "en": "Sensor mounting loose or misaligned after body repair", "de": "Sensorbefestigung lose oder nach Karosseriereparatur falsch ausgerichtet"}, {"id": "calibration_required", "p": "medium", "en": "Calibration after replacement not performed", "de": "Kalibrierung nach Austausch nicht durchgef\u00fchrt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0186','C','Lateral Acceleration Sensor Circuit','Querbeschleunigungssensor Schaltung','The stability control module has detected an implausible signal from the lateral acceleration sensor. ESP uses lateral g-force together with yaw rate and steering angle to detect skid conditions — without it, ESP is disabled.','Das ESP-Steuergerät hat ein unplausibles Signal vom Querbeschleunigungssensor erkannt. ESP nutzt die Querbeschleunigung zusammen mit Gierrate und Lenkwinkel zur Erkennung von Schleudersituationen — ohne dieses Signal wird ESP deaktiviert.','["lateral_acceleration_sensor", "esp_control_module", "sensor_cluster"]','[{"id": "lateral_sensor_failed", "p": "high", "en": "Lateral acceleration sensor failed", "de": "Querbeschleunigungssensor defekt"}, {"id": "sensor_cluster_mounting", "p": "medium", "en": "Sensor cluster loose or mounted incorrectly", "de": "Sensorblock lose oder falsch montiert"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0196','C','Yaw Rate Sensor Circuit','Gierratensensor Schaltung','The stability control module has detected an implausible signal from the yaw rate sensor. The yaw sensor measures rotation around the vertical axis and is essential for ESP — a fault disables stability control.','Das ESP-Steuergerät hat ein unplausibles Signal vom Gierratensensor erkannt. Der Sensor misst die Drehung um die Hochachse und ist für ESP essenziell — bei einem Fehler wird die Stabilitätsregelung deaktiviert.','["yaw_rate_sensor", "esp_control_module", "sensor_cluster"]','[{"id": "yaw_sensor_failed", "p": "high", "en": "Yaw rate sensor failed", "de": "Gierratensensor defekt"}, {"id": "yaw_sensor_calibration", "p": "medium", "en": "Sensor not calibrated after replacement or alignment", "de": "Sensor nach Tausch oder Achsvermessung nicht kalibriert"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0200','C','ABS Solenoid Valve Front Left Circuit','ABS-Magnetventil vorne links Stromkreis','The ABS control module detects a fault in the inlet/outlet solenoid for the front left brake circuit. The valve is integrated in the hydraulic block; replacement is generally a workshop task.','Das ABS-Steuergeraet erkennt einen Fehler am Einlass-/Auslass-Magnetventil des linken Vorderrad-Bremskreises. Das Ventil ist in den Hydraulikblock integriert; ein Tausch ist in der Regel Werkstattaufgabe.','["abs_solenoid_valve_fl", "abs_hydraulic_block", "abs_control_module"]','[{"id": "solenoid_coil_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "hydraulic_block_internal_short", "p": "medium", "en": "Internal short to ground in valve block", "de": "Interner Massekurzschluss im Ventilblock"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0201','C','Brake Fluid Level Switch Circuit','Bremsflüssigkeitsstand-Schalter Schaltung','The ABS or brake control module has detected a fault in the brake fluid level switch circuit. A low fluid level indicates a potential leak in the hydraulic system and disables ABS while a separate brake warning lamp is illuminated.','Das ABS- oder Brems-Steuergerät hat einen Fehler im Stromkreis des Bremsflüssigkeitsstand-Schalters erkannt. Ein niedriger Flüssigkeitsstand weist auf ein mögliches Leck im Hydrauliksystem hin und deaktiviert ABS bei gleichzeitigem Aufleuchten der Br','["brake_fluid_level_switch", "brake_fluid_reservoir", "abs_control_module"]','[{"id": "brake_fluid_low", "p": "high", "en": "Brake fluid level low (worn pads or hydraulic leak)", "de": "Bremsfl\u00fcssigkeitsstand niedrig (verschlissene Bel\u00e4ge oder Leck)"}, {"id": "level_switch_failed", "p": "medium", "en": "Float switch in reservoir failed", "de": "Schwimmerschalter im Beh\u00e4lter defekt"}, {"id": "switch_wiring_fault", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [40, 300], "estimated_hours": [0.3, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0202','C','Brake Pedal Position Sensor','Bremspedalstellungssensor','The chassis or brake control module has detected an implausible signal from the brake pedal position sensor. Modern brake systems use this sensor for brake assist, regenerative braking and adaptive cruise control functions.','Das Fahrwerks- oder Brems-Steuergerät hat ein unplausibles Signal vom Bremspedalstellungssensor erkannt. Moderne Bremssysteme nutzen diesen Sensor für Bremsassistent, Rekuperation und adaptive Geschwindigkeitsregelung.','["brake_pedal_position_sensor", "brake_control_module", "brake_pedal_assembly"]','[{"id": "pedal_sensor_failed", "p": "high", "en": "Pedal position sensor failed", "de": "Pedalstellungssensor defekt"}, {"id": "pedal_sensor_calibration", "p": "medium", "en": "Sensor not calibrated after replacement", "de": "Sensor nach Tausch nicht kalibriert"}, {"id": "pedal_sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 600], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0203','C','ABS Solenoid Valve Front Right Circuit','ABS-Magnetventil vorne rechts Stromkreis','Fault in the front right ABS solenoid (mirror of C0200).','Fehler am ABS-Magnetventil vorne rechts (analog zu C0200).','["abs_solenoid_valve_fr", "abs_hydraulic_block", "abs_control_module"]','[{"id": "solenoid_coil_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "hydraulic_block_internal_short", "p": "medium", "en": "Internal short to ground", "de": "Interner Massekurzschluss"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0205','C','Stop Lamp Switch Circuit','Bremslichtschalter Schaltung','The ABS or stability control module has detected a fault in the stop lamp switch circuit. The brake light switch tells the module whether the driver is braking and is used to coordinate ABS, traction control and cruise control.','Das ABS- oder ESP-Steuergerät hat einen Fehler im Stromkreis des Bremslichtschalters erkannt. Der Schalter meldet die Bremsbetätigung des Fahrers und dient der Koordination von ABS, ASR und Geschwindigkeitsregelung.','["stop_lamp_switch", "abs_control_module", "cruise_control_module"]','[{"id": "stop_lamp_switch_failed", "p": "high", "en": "Stop lamp switch failed or misadjusted", "de": "Bremslichtschalter defekt oder falsch justiert"}, {"id": "stop_lamp_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "stop_lamp_fuse", "p": "low", "en": "Blown stop lamp fuse", "de": "Bremslicht-Sicherung defekt"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0206','C','ABS Solenoid Valve Rear Left Circuit','ABS-Magnetventil hinten links Stromkreis','Fault in the rear left ABS solenoid valve.','Fehler am ABS-Magnetventil hinten links.','["abs_solenoid_valve_rl", "abs_hydraulic_block", "abs_control_module"]','[{"id": "solenoid_coil_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "hydraulic_block_internal_short", "p": "medium", "en": "Internal short to ground", "de": "Interner Massekurzschluss"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0209','C','ABS Solenoid Valve Rear Right Circuit','ABS-Magnetventil hinten rechts Stromkreis','Fault in the rear right ABS solenoid valve.','Fehler am ABS-Magnetventil hinten rechts.','["abs_solenoid_valve_rr", "abs_hydraulic_block", "abs_control_module"]','[{"id": "solenoid_coil_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "hydraulic_block_internal_short", "p": "medium", "en": "Internal short to ground", "de": "Interner Massekurzschluss"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0220','C','ABS Valve Block Supply Voltage','ABS-Ventilblock Versorgungsspannung','Supply voltage to the ABS valve block is out of range, disabling all valve control.','Die Versorgungsspannung des ABS-Ventilblocks liegt ausserhalb des Bereichs; saemtliche Ventilansteuerung wird deaktiviert.','["abs_hydraulic_block", "abs_control_module", "power_supply_wiring"]','[{"id": "supply_undervoltage", "p": "high", "en": "Battery undervoltage", "de": "Batterieunterspannung"}, {"id": "ground_corrosion", "p": "medium", "en": "Ground point corroded", "de": "Massepunkt korrodiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0225','C','ABS Valve Relay Circuit','ABS-Ventilrelais Stromkreis','The valve relay supplying the ABS solenoids does not respond as commanded.','Das Ventilrelais zur Versorgung der ABS-Magnetventile reagiert nicht wie angesteuert.','["abs_valve_relay", "abs_control_module", "relay_wiring"]','[{"id": "relay_failed", "p": "high", "en": "Valve relay failed", "de": "Ventilrelais defekt"}, {"id": "control_circuit_open", "p": "medium", "en": "Relay control circuit open", "de": "Relais-Steuerleitung unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0230','C','Brake Pedal Position Sensor Circuit','Bremspedalpositionssensor Stromkreis','The brake pedal position sensor reports an implausible signal. Required for brake-by-wire and stability control.','Der Bremspedalpositionssensor meldet ein unplausibles Signal. Erforderlich fuer Brake-by-Wire und Stabilitaetsregelung.','["brake_pedal_position_sensor", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "pedal_linkage_loose", "p": "medium", "en": "Pedal linkage loose, biasing sensor", "de": "Pedalanlenkung lose, beeinflusst Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 350], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0234','C','Wheel Speed Sensor Frequency Error','Raddrehzahlsensor Frequenzfehler','The ABS control module has detected that one of the wheel speed sensor signals has a frequency outside the plausible range, e.g. unrealistically high pulses or signal dropouts at speed. Stability control may be limited.','Das ABS-Steuergerät hat erkannt, dass ein Raddrehzahlsignal eine Frequenz außerhalb des plausiblen Bereichs aufweist — etwa unrealistisch hohe Impulse oder Signalaussetzer bei Geschwindigkeit. Die Stabilitätsregelung kann eingeschränkt sein.','["wheel_speed_sensor", "tone_ring", "abs_control_module"]','[{"id": "tone_ring_damaged", "p": "high", "en": "Tone ring damaged, missing teeth, or contaminated", "de": "Polrad besch\u00e4digt, fehlende Z\u00e4hne oder verschmutzt"}, {"id": "sensor_air_gap", "p": "medium", "en": "Sensor air gap incorrect (loose mounting)", "de": "Sensor-Luftspalt falsch (lose Befestigung)"}, {"id": "wheel_speed_sensor_failed", "p": "low", "en": "Wheel speed sensor degraded", "de": "Raddrehzahlsensor verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0235','C','Wheel Speed Sensor Signal Erratic','Raddrehzahlsensor Signal unstetig','The ABS control module has detected an erratic wheel speed sensor signal — sudden jumps or dropouts compared to the other wheels. Typical causes are a damaged tone ring or a loose sensor.','Das ABS-Steuergerät hat ein unstetiges Raddrehzahlsignal erkannt — plötzliche Sprünge oder Aussetzer im Vergleich zu den übrigen Rädern. Typische Ursachen sind ein beschädigtes Polrad oder ein loser Sensor.','["wheel_speed_sensor", "tone_ring", "abs_control_module"]','[{"id": "tone_ring_damaged", "p": "high", "en": "Tone ring damaged or contaminated with metal debris", "de": "Polrad besch\u00e4digt oder mit Metallsp\u00e4nen verschmutzt"}, {"id": "sensor_loose", "p": "medium", "en": "Wheel speed sensor loose in housing", "de": "Raddrehzahlsensor lose im Sitz"}, {"id": "hub_bearing_play", "p": "low", "en": "Excessive hub bearing play", "de": "\u00dcberm\u00e4\u00dfiges Radlagerspiel"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0237','C','Loss of Speed Sensor Signal Front Left','Verlust des Drehzahlsignals vorne links','The ABS control module has lost the wheel speed signal from the front left wheel during driving. ABS and stability control are disabled because wheel-individual speed information is required for slip detection.','Das ABS-Steuergerät hat während der Fahrt das Raddrehzahlsignal des vorderen linken Rades verloren. ABS und Stabilitätsregelung werden deaktiviert, da radindividuelle Drehzahlinformationen für die Schlupferkennung erforderlich sind.','["wheel_speed_sensor", "tone_ring", "abs_control_module", "sensor_wiring"]','[{"id": "wheel_speed_sensor_failed", "p": "high", "en": "Wheel speed sensor failed", "de": "Raddrehzahlsensor defekt"}, {"id": "sensor_wiring_break", "p": "medium", "en": "Wiring break at wheel arch", "de": "Kabelbruch im Radkasten"}, {"id": "tone_ring_damaged", "p": "low", "en": "Tone ring damaged", "de": "Polrad besch\u00e4digt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0238','C','Speed Wheel-to-Wheel Mismatch','Raddrehzahl Rad-zu-Rad Abweichung','The ABS control module has detected an implausible speed difference between wheels that cannot be explained by cornering. This typically points to one suspect sensor, mismatched tyre sizes or a damaged tone ring.','Das ABS-Steuergerät hat eine unplausible Drehzahldifferenz zwischen Rädern erkannt, die sich nicht durch Kurvenfahrt erklären lässt. Üblicherweise weist dies auf einen verdächtigen Sensor, ungleiche Reifengrößen oder ein beschädigtes Polrad hin.','["wheel_speed_sensor", "tone_ring", "tires", "abs_control_module"]','[{"id": "tire_size_mismatch", "p": "high", "en": "Tyre sizes or wear levels do not match across axles", "de": "Reifengr\u00f6\u00dfen oder Verschlei\u00dfgrade an den Achsen unterschiedlich"}, {"id": "tone_ring_damaged", "p": "medium", "en": "Tone ring missing teeth on one wheel", "de": "Polrad an einem Rad mit fehlenden Z\u00e4hnen"}, {"id": "wheel_speed_sensor_failed", "p": "low", "en": "Wheel speed sensor degraded", "de": "Raddrehzahlsensor verschlissen"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0240','C','Brake Pressure Sensor','Bremsdrucksensor','The ABS or stability control module has detected a fault in a brake pressure sensor. Pressure information is used by ESP and brake assist to determine driver intent and modulation pressure during regulation.','Das ABS- oder ESP-Steuergerät hat einen Fehler eines Bremsdrucksensors erkannt. Die Druckinformation wird von ESP und Bremsassistent genutzt, um die Fahrerabsicht und den Modulationsdruck während der Regelung zu bestimmen.','["brake_pressure_sensor", "abs_hydraulic_unit", "abs_control_module"]','[{"id": "pressure_sensor_failed", "p": "high", "en": "Brake pressure sensor failed", "de": "Bremsdrucksensor defekt"}, {"id": "pressure_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "brake_fluid_air", "p": "low", "en": "Air in brake system", "de": "Luft im Bremssystem"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0241','C','ABS Warning Lamp Control Circuit','ABS-Warnleuchte Ansteuerung','The ABS warning lamp control circuit is shorted or open. The driver may see a permanently lit or non-functional ABS warning lamp.','Die Ansteuerung der ABS-Warnleuchte ist kurzgeschlossen oder unterbrochen. Die Warnleuchte kann dauerhaft leuchten oder nicht ansprechen.','["abs_warning_lamp", "instrument_cluster", "abs_control_module"]','[{"id": "bulb_or_led_failed", "p": "medium", "en": "Lamp bulb/LED failed", "de": "Lampe/LED defekt"}, {"id": "wiring_short", "p": "medium", "en": "Control wiring shorted", "de": "Steuerleitung kurzgeschlossen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [40, 350], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0242','C','PCM Indicated ABS Malfunction','PCM meldet ABS-Fehlfunktion','The powertrain control module reports a fault that the ABS module must consider (e.g. traction control engine torque request fault).','Das Antriebssteuergeraet meldet einen Fehler, den das ABS-Modul beruecksichtigen muss (z. B. Anforderung der Motormoment-Reduktion durch ASR).','["powertrain_control_module", "abs_control_module", "communication_bus"]','[{"id": "tcs_torque_request_fault", "p": "high", "en": "Traction control torque request fault", "de": "ASR-Drehmomentanforderungsfehler"}, {"id": "bus_communication_loss", "p": "medium", "en": "Bus communication loss", "de": "Buskommunikation unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0244','C','PWM Brake Pressure Modulation Circuit','PWM-Bremsdruckmodulation Stromkreis','The PWM control of the brake pressure modulation valves is faulty.','Die PWM-Ansteuerung der Bremsdruck-Modulationsventile ist fehlerhaft.','["abs_hydraulic_block", "abs_control_module"]','[{"id": "module_output_fault", "p": "high", "en": "Module PWM output stage fault", "de": "Endstufenfehler im Steuergeraet"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [1.5, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0245','C','Wheel Speed Sensor Frequency Mismatch','Raddrehzahlsensor Frequenzabweichung','The ABS control module has detected that the frequency of one wheel speed sensor signal does not match the others under stable driving conditions. This often indicates a tone ring with extra or missing teeth or a sensor with degraded signal quality.','Das ABS-Steuergerät hat erkannt, dass die Frequenz eines Raddrehzahlsignals bei stabiler Fahrt von den anderen abweicht. Häufig deutet dies auf ein Polrad mit zusätzlichen oder fehlenden Zähnen oder einen Sensor mit eingeschränkter Signalqualität hin','["wheel_speed_sensor", "tone_ring", "abs_control_module"]','[{"id": "tone_ring_damaged", "p": "high", "en": "Tone ring damaged or contaminated", "de": "Polrad besch\u00e4digt oder verschmutzt"}, {"id": "wheel_speed_sensor_failed", "p": "medium", "en": "Wheel speed sensor degraded", "de": "Raddrehzahlsensor verschlissen"}, {"id": "tire_size_mismatch", "p": "low", "en": "Tyre size mismatch", "de": "Reifengr\u00f6\u00dfen-Abweichung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0246','C','ABS/TCS Control Module Internal Performance','ABS/ASR-Steuergeraet interne Leistung','Internal plausibility check of the combined ABS/TCS control module fails.','Die interne Plausibilitaetspruefung des kombinierten ABS-/ASR-Steuergeraets schlaegt fehl.','["abs_control_module"]','[{"id": "module_internal_failure", "p": "high", "en": "Module internal fault", "de": "Steuergeraet intern defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0250','C','Power Steering Pump Pressure','Servolenkungspumpe Druck','The power steering control module has detected an implausible pressure or load signal from the steering pump. On hydraulic systems this may indicate low fluid or a worn pump; on electric systems it may indicate excessive motor load.','Das Lenkungs-Steuergerät hat ein unplausibles Druck- oder Lastsignal der Lenkpumpe erkannt. Bei hydraulischen Systemen kann dies auf niedrigen Flüssigkeitsstand oder eine verschlissene Pumpe hinweisen; bei elektrischen Systemen auf eine zu hohe Motor','["power_steering_pump", "power_steering_module", "power_steering_pressure_sensor"]','[{"id": "ps_fluid_low", "p": "high", "en": "Power steering fluid low or contaminated", "de": "Servo\u00f6l niedrig oder verschmutzt"}, {"id": "ps_pump_worn", "p": "medium", "en": "Power steering pump worn", "de": "Servolenkungspumpe verschlissen"}, {"id": "ps_pressure_sensor_failed", "p": "low", "en": "Pressure sensor failed", "de": "Drucksensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 1200], "estimated_hours": [0.5, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0252','C','Pump Motor Ground Circuit Open','Pumpenmotor Massekreis offen','The pump motor ground return is open. The motor cannot run, and the system disables ABS and stability control.','Die Masseleitung des Pumpenmotors ist unterbrochen. Der Motor laeuft nicht; ABS und Stabilitaetsregelung werden deaktiviert.','["abs_pump_motor", "ground_strap"]','[{"id": "ground_strap_corroded", "p": "high", "en": "Ground strap corroded", "de": "Masseband korrodiert"}, {"id": "ground_wire_broken", "p": "medium", "en": "Ground wire broken", "de": "Masseleitung gebrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 250], "estimated_hours": [0.5, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0258','C','Brake Booster Vacuum Sensor Circuit','Bremskraftverstaerker-Vakuumsensor Stromkreis','The brake booster vacuum sensor reports an implausible signal; brake assist functions are reduced. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the reque','Der Vakuumsensor des Bremskraftverstaerkers meldet ein unplausibles Signal; Bremsassistent-Funktionen werden reduziert. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schl','["brake_booster_vacuum_sensor", "vacuum_hose"]','[{"id": "vacuum_leak", "p": "high", "en": "Vacuum hose leak", "de": "Vakuumschlauch undicht"}, {"id": "sensor_failed", "p": "medium", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0265','C','EBCM Relay Circuit','EBCM-Relais Schaltung','The Electronic Brake Control Module has detected a fault in its main supply relay circuit. Without proper relay supply the EBCM cannot operate the hydraulic unit and ABS as well as stability control are disabled.','Das elektronische Brems-Steuergerät (EBCM) hat einen Fehler im Stromkreis des Hauptversorgungs-Relais erkannt. Ohne Relaisversorgung kann das EBCM die Hydraulikeinheit nicht ansteuern, ABS und Stabilitätsregelung werden deaktiviert.','["ebcm_relay", "ebcm_module", "power_supply_wiring"]','[{"id": "ebcm_relay_failed", "p": "high", "en": "EBCM relay failed", "de": "EBCM-Relais defekt"}, {"id": "ebcm_module_internal", "p": "medium", "en": "Internal EBCM fault (relay integrated)", "de": "Interner EBCM-Fehler (Relais integriert)"}, {"id": "ebcm_power_wiring", "p": "low", "en": "Power supply wiring or fuse fault", "de": "Versorgungsleitungs- oder Sicherungsfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0266','C','Active Brake Booster','Aktiver Bremskraftverstärker','The brake control module has detected a fault in the active (electric or vacuum-controlled) brake booster. Active boosters are used by emergency brake assist and adaptive cruise control to autonomously build brake pressure.','Das Brems-Steuergerät hat einen Fehler am aktiven (elektrischen oder vakuumgesteuerten) Bremskraftverstärker erkannt. Aktive Verstärker werden von Notbremsassistent und adaptiver Geschwindigkeitsregelung zum eigenständigen Aufbau von Bremsdruck genut','["active_brake_booster", "brake_control_module", "vacuum_pump"]','[{"id": "active_booster_failed", "p": "high", "en": "Active booster motor or solenoid failed", "de": "Motor oder Magnetventil des aktiven Verst\u00e4rkers defekt"}, {"id": "vacuum_pump_weak", "p": "medium", "en": "Vacuum supply weak (vacuum pump or hose fault)", "de": "Vakuumversorgung schwach (Vakuumpumpe oder Schlauchfehler)"}, {"id": "booster_wiring_fault", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0267','C','Brake Pump Motor Circuit','Bremspumpenmotor Schaltung','The ABS or brake control module has detected an electrical fault in the brake pump motor circuit. The pump is used to build brake pressure during ABS, ESP and brake-by-wire operations and a fault disables these functions.','Das ABS- oder Brems-Steuergerät hat einen elektrischen Fehler im Stromkreis des Bremspumpenmotors erkannt. Die Pumpe baut bei ABS-, ESP- und Brake-by-Wire-Funktionen Bremsdruck auf; ein Fehler deaktiviert diese Funktionen.','["brake_pump_motor", "abs_control_module", "power_supply_wiring"]','[{"id": "brake_pump_motor_failed", "p": "high", "en": "Brake pump motor failed", "de": "Bremspumpenmotor defekt"}, {"id": "abs_relay_failed", "p": "medium", "en": "Pump motor relay failed", "de": "Pumpenrelais defekt"}, {"id": "abs_power_wiring", "p": "low", "en": "Power supply wiring fault", "de": "Versorgungsleitungs-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0268','C','Brake Pump Run Time Exceeded','Bremspumpe Laufzeit überschritten','The brake control module has detected that the brake pump has run longer than the allowed maximum time. This typically indicates the pump cannot reach target pressure due to a hydraulic leak, air in the system or a worn pump.','Das Brems-Steuergerät hat erkannt, dass die Bremspumpe länger als die zulässige Maximalzeit gelaufen ist. Üblicherweise erreicht die Pumpe den Solldruck nicht — Ursache sind hydraulische Lecks, Luft im System oder eine verschlissene Pumpe.','["brake_pump_motor", "abs_hydraulic_unit", "brake_lines"]','[{"id": "hydraulic_leak", "p": "high", "en": "Hydraulic leak in brake system", "de": "Hydraulisches Leck im Bremssystem"}, {"id": "brake_fluid_air", "p": "medium", "en": "Air in brake system", "de": "Luft im Bremssystem"}, {"id": "brake_pump_motor_failed", "p": "low", "en": "Brake pump worn or weak", "de": "Bremspumpe verschlissen oder schwach"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0269','C','Brake Vacuum Sensor','Bremsvakuumsensor','The brake control module has detected an implausible signal from the vacuum sensor on the brake booster. Modern systems monitor booster vacuum to ensure brake assist is available, especially with stop-start engines and electric vacuum pumps.','Das Brems-Steuergerät hat ein unplausibles Signal vom Vakuumsensor des Bremskraftverstärkers erkannt. Moderne Systeme überwachen das Vakuum, um die Bremsunterstützung sicherzustellen, besonders bei Start-Stopp-Motoren und elektrischen Vakuumpumpen.','["brake_vacuum_sensor", "brake_booster", "vacuum_pump"]','[{"id": "vacuum_sensor_failed", "p": "high", "en": "Vacuum sensor failed", "de": "Vakuumsensor defekt"}, {"id": "vacuum_leak", "p": "medium", "en": "Leak in vacuum supply line", "de": "Leck in der Vakuumleitung"}, {"id": "vacuum_pump_weak", "p": "low", "en": "Vacuum pump weak", "de": "Vakuumpumpe schwach"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0273','C','Brake Booster Pressure Sensor Circuit Malfunction','Bremskraftverstärker-Drucksensor Stromkreis-Fehlfunktion','The brake control module has detected an out-of-range or implausible signal from the brake booster pressure sensor. Brake assist and electronic boost functions may be limited.','Das Bremssteuergerät hat ein außerhalb des Bereichs liegendes oder unplausibles Signal vom Bremskraftverstärker-Drucksensor erkannt. Bremsassistent und elektronische Verstärkung können eingeschränkt sein.','["brake_booster", "booster_pressure_sensor", "brake_control_module"]','[{"id": "pressure_sensor_failed", "p": "high", "en": "Booster pressure sensor failed", "de": "Drucksensor des Bremskraftverst\u00e4rkers defekt"}, {"id": "sensor_wiring_fault", "p": "medium", "en": "Wiring or connector fault to sensor", "de": "Kabel- oder Steckerfehler zum Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0277','C','Brake Booster Vacuum Sensor Circuit Malfunction','Bremskraftverstärker-Vakuumsensor Stromkreis-Fehlfunktion','The brake control module has detected an implausible signal from the booster vacuum sensor. Loss of vacuum signal can cause hard pedal and reduced power assist.','Das Bremssteuergerät hat ein unplausibles Signal vom Vakuumsensor des Bremskraftverstärkers erkannt. Ein fehlendes Vakuumsignal kann zu hartem Pedal und reduzierter Verstärkung führen.','["brake_booster", "vacuum_sensor", "brake_control_module"]','[{"id": "vacuum_sensor_failed", "p": "high", "en": "Vacuum sensor failed", "de": "Vakuumsensor defekt"}, {"id": "vacuum_leak", "p": "medium", "en": "Vacuum leak in booster or hose", "de": "Vakuumleck am Verst\u00e4rker oder Schlauch"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0279','C','Brake Booster Boost Sensor Circuit Malfunction','Bremskraftverstärker-Boost-Sensor Stromkreis-Fehlfunktion','The brake control module has detected an electrical fault in the booster boost (assist pressure) sensor circuit. Power-assist regulation may default to a backup strategy.','Das Bremssteuergerät hat einen elektrischen Fehler im Stromkreis des Boost- bzw. Unterstützungsdrucksensors erkannt. Die Verstärkungsregelung läuft ggf. im Notbetrieb.','["brake_booster", "boost_sensor", "brake_control_module"]','[{"id": "boost_sensor_failed", "p": "high", "en": "Boost sensor failed", "de": "Boost-Sensor defekt"}, {"id": "sensor_wiring_fault", "p": "medium", "en": "Sensor wiring or connector fault", "de": "Sensorkabel- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 700], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0287','C','ESP Performance','ESP Funktionsbereich','The stability control module has detected that overall ESP performance is degraded — typically a plausibility check between yaw rate, lateral acceleration, steering angle and wheel speeds has failed. ESP is deactivated until the root cause is resolve','Das ESP-Steuergerät hat eine eingeschränkte ESP-Funktion erkannt — meist hat eine Plausibilitätsprüfung zwischen Gierrate, Querbeschleunigung, Lenkwinkel und Raddrehzahlen versagt. ESP wird bis zur Behebung der Ursache deaktiviert.','["esp_control_module", "sensor_cluster", "yaw_rate_sensor", "lateral_acceleration_sensor"]','[{"id": "sensor_calibration_required", "p": "high", "en": "Sensor calibration required after repair", "de": "Sensorkalibrierung nach Reparatur erforderlich"}, {"id": "sensor_cluster_mounting", "p": "medium", "en": "Sensor cluster loose or mounted incorrectly", "de": "Sensorblock lose oder falsch montiert"}, {"id": "secondary_fault_present", "p": "low", "en": "Secondary fault on individual sensor", "de": "Folgefehler eines einzelnen Sensors"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 1000], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0288','C','Yaw Rate Sensor Range','Gierratensensor Funktionsbereich','The stability control module has detected that the yaw rate sensor signal is outside the plausible range during stable driving. This typically indicates a sensor offset, an incorrect mounting or a degraded sensor element.','Das ESP-Steuergerät hat erkannt, dass das Gierratensignal bei stabiler Fahrt außerhalb des plausiblen Bereichs liegt. Üblicherweise weist dies auf einen Sensoroffset, eine falsche Montage oder ein verschlissenes Sensorelement hin.','["yaw_rate_sensor", "sensor_cluster", "esp_control_module"]','[{"id": "yaw_sensor_calibration", "p": "high", "en": "Sensor not calibrated", "de": "Sensor nicht kalibriert"}, {"id": "yaw_sensor_failed", "p": "medium", "en": "Yaw rate sensor failed", "de": "Gierratensensor defekt"}, {"id": "sensor_cluster_mounting", "p": "low", "en": "Sensor cluster mounted incorrectly", "de": "Sensorblock falsch montiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0290','C','Brake Pedal Stroke Sensor Circuit Malfunction','Bremspedalweg-Sensor Stromkreis-Fehlfunktion','The brake control module has detected an out-of-range signal from the brake pedal stroke sensor. Pedal travel information is required for brake assist and electronically boosted braking.','Das Bremssteuergerät hat ein Signal des Bremspedalweg-Sensors außerhalb des gültigen Bereichs erkannt. Die Pedalweg-Information ist für Bremsassistent und elektronisch unterstützte Bremsung erforderlich.','["brake_pedal_stroke_sensor", "brake_control_module", "sensor_wiring"]','[{"id": "stroke_sensor_failed", "p": "high", "en": "Pedal stroke sensor failed", "de": "Pedalweg-Sensor defekt"}, {"id": "sensor_misadjusted", "p": "medium", "en": "Sensor mounting or pedal linkage misadjusted", "de": "Sensorbefestigung oder Pedalmechanik dejustiert"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [120, 600], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0291','C','Brake Pedal Apply Sensor Circuit Malfunction','Bremspedal-Betätigungssensor Stromkreis-Fehlfunktion','Electrical fault in the brake pedal apply sensor circuit. The module cannot reliably detect whether the brake pedal is pressed, which affects ABS, ESP and brake assist functions.','Elektrischer Fehler im Stromkreis des Bremspedal-Betätigungssensors. Das Steuergerät kann nicht mehr zuverlässig erkennen, ob das Bremspedal getreten ist, was ABS, ESP und Bremsassistent betrifft.','["brake_apply_sensor", "brake_control_module", "sensor_wiring"]','[{"id": "apply_sensor_failed", "p": "high", "en": "Pedal apply sensor failed", "de": "Bet\u00e4tigungssensor defekt"}, {"id": "wiring_or_connector_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 500], "estimated_hours": [0.5, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0295','C','Steering Sensor Indicates Bias','Lenkwinkelsensor zeigt Offset','The stability control module has detected that the steering wheel position sensor reports a non-zero angle when the vehicle is driving straight. This bias makes ESP intervene incorrectly and the system requires recalibration.','Das ESP-Steuergerät hat erkannt, dass der Lenkwinkelsensor bei Geradeausfahrt einen Wert ungleich Null meldet. Dieser Offset führt zu fehlerhaften ESP-Eingriffen und das System muss neu kalibriert werden.','["steering_angle_sensor", "esp_control_module", "alignment_components"]','[{"id": "steering_angle_calibration", "p": "high", "en": "Steering angle sensor calibration required", "de": "Kalibrierung des Lenkwinkelsensors erforderlich"}, {"id": "alignment_off", "p": "medium", "en": "Wheel alignment incorrect", "de": "Achsvermessung fehlerhaft"}, {"id": "steering_angle_sensor_failed", "p": "low", "en": "Steering angle sensor failed", "de": "Lenkwinkelsensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [60, 600], "estimated_hours": [0.3, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0300','C','Inlet Valve Front Left Performance','Einlassventil vorne links Leistung','The front left inlet solenoid valve does not respond hydraulically as expected during ABS self-test.','Das Einlass-Magnetventil vorne links reagiert hydraulisch nicht wie erwartet im ABS-Selbsttest.','["abs_solenoid_valve_fl", "abs_hydraulic_block"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck due to brake fluid debris", "de": "Ventil durch Bremsfluessigkeitsablagerungen klemmend"}, {"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance drift", "de": "Spulenwiderstands-Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0301','C','Air Suspension Compressor Relay','Luftfederkompressor-Relais','The air suspension control module has detected a fault in the compressor relay circuit. The compressor cannot be energized which prevents the system from refilling the air struts and ride height drops over time.','Das Luftfederungs-Steuergerät hat einen Fehler im Stromkreis des Kompressor-Relais erkannt. Der Kompressor kann nicht angesteuert werden, das System kann die Luftfederbälge nicht befüllen und das Fahrzeugniveau sinkt mit der Zeit ab.','["compressor_relay", "air_compressor", "air_suspension_module"]','[{"id": "compressor_relay_failed", "p": "high", "en": "Compressor relay failed", "de": "Kompressor-Relais defekt"}, {"id": "relay_wiring_fault", "p": "medium", "en": "Relay wiring or fuse fault", "de": "Relaisverkabelung oder Sicherung defekt"}, {"id": "air_suspension_module_internal", "p": "low", "en": "Internal module fault", "de": "Interner Steuerger\u00e4t-Fehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 500], "estimated_hours": [0.3, 2]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0302','C','Outlet Valve Front Left Performance','Auslassventil vorne links Leistung','The front left outlet solenoid valve does not respond hydraulically as expected.','Das Auslass-Magnetventil vorne links reagiert hydraulisch nicht wie erwartet.','["abs_solenoid_valve_fl", "abs_hydraulic_block"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck", "de": "Ventil klemmend"}, {"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance drift", "de": "Spulenwiderstands-Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
