INSERT OR IGNORE INTO dtc_codes VALUES('C0305','C','Inlet Valve Rear Left Performance','Einlassventil hinten links Leistung','The rear left inlet solenoid valve does not respond hydraulically as expected.','Das Einlass-Magnetventil hinten links reagiert hydraulisch nicht wie erwartet.','["abs_solenoid_valve_rl", "abs_hydraulic_block"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck", "de": "Ventil klemmend"}, {"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance drift", "de": "Spulenwiderstands-Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0306','C','Ride Height Sensor Front Left','Niveausensor vorne links','Ride Height Sensor Front Left: the control module has detected this fault condition. Without this signal the suspension control module cannot self-level the vehicle.','Niveausensor vorne links: das Steuergerät hat diesen Fehlerzustand erkannt. Ohne dieses Signal kann das Fahrwerks-Steuergerät das Fahrzeug nicht nivellieren.','["ride_height_sensor", "air_suspension_module", "sensor_linkage"]','[{"id": "ride_height_sensor_failed", "p": "high", "en": "Ride height sensor failed", "de": "Niveausensor defekt"}, {"id": "sensor_linkage_broken", "p": "medium", "en": "Sensor linkage broken or detached", "de": "Sensorgest\u00e4nge gebrochen oder gel\u00f6st"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0307','C','Inlet Valve Rear Right Performance','Einlassventil hinten rechts Leistung','The rear right inlet solenoid valve does not respond hydraulically as expected.','Das Einlass-Magnetventil hinten rechts reagiert hydraulisch nicht wie erwartet.','["abs_solenoid_valve_rr", "abs_hydraulic_block"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck", "de": "Ventil klemmend"}, {"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance drift", "de": "Spulenwiderstands-Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0308','C','Ride Height Sensor Front Right','Niveausensor vorne rechts','Ride Height Sensor Front Right: the control module has detected this fault condition. Without this signal the suspension control module cannot self-level the vehicle.','Niveausensor vorne rechts: das Steuergerät hat diesen Fehlerzustand erkannt. Ohne dieses Signal kann das Fahrwerks-Steuergerät das Fahrzeug nicht nivellieren.','["ride_height_sensor", "air_suspension_module", "sensor_linkage"]','[{"id": "ride_height_sensor_failed", "p": "high", "en": "Ride height sensor failed", "de": "Niveausensor defekt"}, {"id": "sensor_linkage_broken", "p": "medium", "en": "Sensor linkage broken or detached", "de": "Sensorgest\u00e4nge gebrochen oder gel\u00f6st"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0309','C','Outlet Valve Rear Right Performance','Auslassventil hinten rechts Leistung','The rear right outlet solenoid valve does not respond hydraulically as expected.','Das Auslass-Magnetventil hinten rechts reagiert hydraulisch nicht wie erwartet.','["abs_solenoid_valve_rr", "abs_hydraulic_block"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck", "de": "Ventil klemmend"}, {"id": "coil_resistance_drift", "p": "medium", "en": "Coil resistance drift", "de": "Spulenwiderstands-Drift"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0310','C','Ride Height Sensor Rear Left','Niveausensor hinten links','Ride Height Sensor Rear Left: the control module has detected this fault condition. Without this signal the suspension control module cannot self-level the vehicle.','Niveausensor hinten links: das Steuergerät hat diesen Fehlerzustand erkannt. Ohne dieses Signal kann das Fahrwerks-Steuergerät das Fahrzeug nicht nivellieren.','["ride_height_sensor", "air_suspension_module", "sensor_linkage"]','[{"id": "ride_height_sensor_failed", "p": "high", "en": "Ride height sensor failed", "de": "Niveausensor defekt"}, {"id": "sensor_linkage_broken", "p": "medium", "en": "Sensor linkage broken or detached", "de": "Sensorgest\u00e4nge gebrochen oder gel\u00f6st"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0312','C','Ride Height Sensor Rear Right','Niveausensor hinten rechts','Ride Height Sensor Rear Right: the control module has detected this fault condition. Without this signal the suspension control module cannot self-level the vehicle.','Niveausensor hinten rechts: das Steuergerät hat diesen Fehlerzustand erkannt. Ohne dieses Signal kann das Fahrwerks-Steuergerät das Fahrzeug nicht nivellieren.','["ride_height_sensor", "air_suspension_module", "sensor_linkage"]','[{"id": "ride_height_sensor_failed", "p": "high", "en": "Ride height sensor failed", "de": "Niveausensor defekt"}, {"id": "sensor_linkage_broken", "p": "medium", "en": "Sensor linkage broken or detached", "de": "Sensorgest\u00e4nge gebrochen oder gel\u00f6st"}, {"id": "sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0317','C','Compressor Relay Circuit','Kompressor-Relais Schaltung','The air suspension control module has detected a circuit fault on the compressor relay output — typically open circuit, short to ground or short to power. Self-levelling is disabled and the vehicle may sit lower than normal.','Das Luftfederungs-Steuergerät hat einen Schaltungsfehler am Ausgang des Kompressor-Relais erkannt — meist Unterbrechung, Kurzschluss nach Masse oder Plus. Die Niveauregulierung wird deaktiviert und das Fahrzeug kann tiefer als normal stehen.','["compressor_relay", "air_compressor", "air_suspension_module", "relay_wiring"]','[{"id": "compressor_relay_failed", "p": "high", "en": "Compressor relay failed (stuck or open)", "de": "Kompressor-Relais defekt (klebt oder unterbrochen)"}, {"id": "compressor_motor_shorted", "p": "medium", "en": "Compressor motor shorted, dragging supply down", "de": "Kompressormotor mit Kurzschluss, zieht Versorgung herunter"}, {"id": "relay_wiring_fault", "p": "low", "en": "Relay wiring or connector fault", "de": "Relaisverkabelung oder Stecker defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 700], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0327','C','Encoder Motor','Encoder-Motor','The transfer case control module has detected a fault in the encoder motor used to shift between 2WD and 4WD ranges. A fault prevents range changes and may leave the transfer case in an undefined position.','Das Verteilergetriebe-Steuergerät hat einen Fehler am Encoder-Motor erkannt, der zwischen 2WD- und 4WD-Stufen schaltet. Ein Fehler verhindert das Umschalten und kann das Verteilergetriebe in einer undefinierten Stellung belassen.','["encoder_motor", "transfer_case_module", "encoder_position_switch"]','[{"id": "encoder_motor_failed", "p": "high", "en": "Encoder motor failed (worn brushes or seized)", "de": "Encoder-Motor defekt (B\u00fcrstenverschlei\u00df oder festgefressen)"}, {"id": "encoder_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "transfer_case_module_internal", "p": "low", "en": "Internal control module fault", "de": "Interner Steuerger\u00e4t-Fehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0374','C','4WD Drive Coupling','4WD Antriebskupplung','The 4WD or AWD control module has detected a fault on the electronic drive coupling that distributes torque between axles. Reduced torque transfer or a complete loss of all-wheel drive function may result.','Das 4WD- oder AWD-Steuergerät hat einen Fehler an der elektronischen Antriebskupplung erkannt, die das Drehmoment zwischen den Achsen verteilt. Eine reduzierte Drehmomentübertragung oder ein vollständiger Verlust der Allradfunktion können die Folge s','["awd_coupling", "awd_control_module", "coupling_actuator"]','[{"id": "awd_coupling_actuator_failed", "p": "high", "en": "Coupling actuator failed", "de": "Kupplungsaktuator defekt"}, {"id": "awd_oil_temperature_high", "p": "medium", "en": "Coupling oil overheated", "de": "Kupplungs\u00f6l \u00fcberhitzt"}, {"id": "awd_wiring_fault", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1.5, 6]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0376','C','Front Axle Disconnect','Vorderachs-Abkopplung','The 4WD control module has detected a fault on the front axle disconnect actuator. On part-time AWD vehicles this actuator decouples the front axle for fuel saving, and a fault prevents engagement or disengagement of front-wheel drive.','Das 4WD-Steuergerät hat einen Fehler am Aktuator der Vorderachs-Abkopplung erkannt. Bei zugeschalteten AWD-Fahrzeugen koppelt dieser Aktuator zur Kraftstoffersparnis die Vorderachse ab; ein Fehler verhindert das Zu- oder Abschalten des Vorderradantri','["front_axle_disconnect_actuator", "awd_control_module", "axle_position_switch"]','[{"id": "disconnect_actuator_failed", "p": "high", "en": "Disconnect actuator failed (motor or solenoid)", "de": "Abkopplungs-Aktuator defekt (Motor oder Magnetventil)"}, {"id": "actuator_wiring_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "position_switch_failed", "p": "low", "en": "Axle position switch failed", "de": "Achsstellungsschalter defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1500], "estimated_hours": [1, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0387','C','Transfer Case Position Sensor','Verteilergetriebe-Positionssensor','The transfer case control module has detected an implausible signal from the position sensor that reports the current shift position (2HI, 4HI, 4LO, neutral). Without a valid position the system cannot complete a range change.','Das Verteilergetriebe-Steuergerät hat ein unplausibles Signal vom Positionssensor erkannt, der die aktuelle Schaltstellung (2HI, 4HI, 4LO, Neutral) meldet. Ohne gültige Position kann das System einen Stufenwechsel nicht abschließen.','["transfer_case_position_sensor", "transfer_case_module", "encoder_motor"]','[{"id": "position_sensor_failed", "p": "high", "en": "Transfer case position sensor failed", "de": "Verteilergetriebe-Positionssensor defekt"}, {"id": "position_sensor_wiring", "p": "medium", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}, {"id": "encoder_motor_failed", "p": "low", "en": "Encoder motor stuck between positions", "de": "Encoder-Motor zwischen Stellungen blockiert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1200], "estimated_hours": [0.8, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0388','C','Transfer Case High Range Switch Circuit Malfunction','Verteilergetriebe-Schalter Hochbereich Stromkreis-Fehlfunktion','The transfer case control module has detected an implausible state from the high range (4H) position switch. Range selection in 4WD mode may be limited.','Das Verteilergetriebe-Steuergerät hat einen unplausiblen Zustand des Hochbereich-Stellungsschalters (4H) erkannt. Die Bereichswahl im Allradbetrieb kann eingeschränkt sein.','["transfer_case_switch", "transfer_case_module", "shift_actuator"]','[{"id": "range_switch_failed", "p": "high", "en": "High range position switch failed", "de": "Hochbereich-Schalter defekt"}, {"id": "actuator_misaligned", "p": "medium", "en": "Shift actuator out of position", "de": "Stellmotor au\u00dferhalb der Sollstellung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0389','C','Transfer Case Low Range Switch Circuit Malfunction','Verteilergetriebe-Schalter Geländebereich Stromkreis-Fehlfunktion','The transfer case control module has detected an implausible state from the low range (4L) position switch. Engagement of low range may be inhibited.','Das Verteilergetriebe-Steuergerät hat einen unplausiblen Zustand des Geländebereich-Stellungsschalters (4L) erkannt. Das Einlegen der Geländeuntersetzung kann blockiert sein.','["transfer_case_switch", "transfer_case_module", "shift_actuator"]','[{"id": "range_switch_failed", "p": "high", "en": "Low range position switch failed", "de": "Gel\u00e4ndebereich-Schalter defekt"}, {"id": "actuator_misaligned", "p": "medium", "en": "Shift actuator out of position", "de": "Stellmotor au\u00dferhalb der Sollstellung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0399','C','4WD Mode Switch Circuit Malfunction','Allrad-Modusschalter Stromkreis-Fehlfunktion','The transfer case or 4WD control module has detected an invalid signal from the driver-operated 4WD mode selector. Mode requests from the dashboard may be ignored.','Das Verteilergetriebe- bzw. Allrad-Steuergerät hat ein ungültiges Signal des fahrerseitigen Allrad-Wahlschalters erkannt. Modusanforderungen vom Armaturenbrett werden ggf. ignoriert.','["mode_selector_switch", "transfer_case_module", "switch_wiring"]','[{"id": "mode_switch_failed", "p": "high", "en": "Mode selector switch failed", "de": "Modus-Wahlschalter defekt"}, {"id": "wiring_or_connector_fault", "p": "medium", "en": "Wiring or connector fault", "de": "Kabel- oder Steckerfehler"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [60, 300], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0400','C','Traction Control Solenoid Valve Circuit','Traktionskontrolle Magnetventil Stromkreis','The dedicated traction control isolation valve in the hydraulic block reports an electrical fault.','Das spezielle Traktionskontroll-Isolationsventil im Hydraulikblock meldet einen elektrischen Fehler.','["tcs_isolation_valve", "abs_hydraulic_block", "abs_control_module"]','[{"id": "solenoid_coil_open", "p": "high", "en": "Solenoid coil open", "de": "Magnetspule unterbrochen"}, {"id": "short_to_ground", "p": "medium", "en": "Short to ground", "de": "Kurzschluss nach Masse"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 1600], "estimated_hours": [2, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0401','C','Traction Control Switch Circuit','Traktionskontroll-Schalter Stromkreis','The TCS on/off switch reports an implausible state.','Der TCS-Ein/Aus-Schalter meldet einen unplausiblen Zustand.','["tcs_switch", "dashboard_wiring"]','[{"id": "switch_failed", "p": "high", "en": "Switch failed", "de": "Schalter defekt"}, {"id": "wiring_short", "p": "medium", "en": "Wiring shorted", "de": "Verkabelung kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0402','C','Traction Control Lamp Circuit','Traktionskontroll-Lampe Stromkreis','The TCS indicator lamp control circuit is shorted or open.','Der Steuerstromkreis der TCS-Kontrollleuchte ist kurzgeschlossen oder unterbrochen.','["tcs_indicator_lamp", "instrument_cluster"]','[{"id": "bulb_failed", "p": "medium", "en": "Indicator bulb/LED failed", "de": "Kontrollleuchte defekt"}, {"id": "wiring_short", "p": "medium", "en": "Wiring shorted", "de": "Verkabelung kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": false, "estimated_cost_eur": [40, 350], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0405','C','Traction Control Active Too Long','Traktionskontrolle zu lange aktiv','TCS regulation has been continuously active longer than allowed, suggesting persistent low-friction conditions or a sensor fault.','Die TCS-Regelung war ueber laengere Zeit ununterbrochen aktiv; dies deutet auf andauernde Glaette oder einen Sensorfehler hin.','["abs_control_module", "wheel_speed_sensors"]','[{"id": "long_low_friction", "p": "medium", "en": "Persistent low-friction surface", "de": "Andauernd rutschiger Untergrund"}, {"id": "wheel_speed_sensor_drift", "p": "medium", "en": "Wheel speed sensor drift", "de": "Drift am Raddrehzahlsensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0410','C','Adaptive Cruise Control Sensor Circuit Malfunction','ACC-Sensor Stromkreis-Fehlfunktion','The adaptive cruise control module has detected a fault in its forward-looking radar or lidar sensor circuit. ACC and forward collision warning are unavailable while the fault is active.','Das ACC-Steuergerät hat einen Fehler im nach vorn gerichteten Radar- oder Lidar-Sensor-Stromkreis erkannt. ACC und Auffahrwarnung sind bei aktivem Fehler nicht verfügbar.','["acc_radar_sensor", "acc_module", "sensor_wiring"]','[{"id": "radar_sensor_blocked", "p": "high", "en": "Radar sensor blocked by snow, ice or dirt", "de": "Radarsensor durch Schnee, Eis oder Schmutz verdeckt"}, {"id": "radar_sensor_misaligned", "p": "medium", "en": "Sensor misaligned after front-end impact", "de": "Sensor nach Frontaufprall dejustiert"}, {"id": "radar_sensor_failed", "p": "medium", "en": "Radar/lidar sensor failed", "de": "Radar- bzw. Lidar-Sensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0420','C','Adaptive Cruise Control Module Internal Performance','ACC-Steuergerät Interne Leistung','The adaptive cruise control module has reported an internal performance fault — for example self-test failure, supply voltage out of range or invalid configuration. ACC is disabled.','Das ACC-Steuergerät hat einen internen Leistungsfehler gemeldet — etwa fehlgeschlagener Selbsttest, Versorgungsspannung außerhalb des Bereichs oder ungültige Konfiguration. ACC ist deaktiviert.','["acc_module", "vehicle_power_supply", "communication_bus"]','[{"id": "module_internal_fault", "p": "high", "en": "ACC module internal fault", "de": "ACC-Steuerger\u00e4t interner Fehler"}, {"id": "voltage_out_of_range", "p": "medium", "en": "Supply voltage out of range", "de": "Versorgungsspannung au\u00dferhalb des Bereichs"}, {"id": "configuration_invalid", "p": "low", "en": "Module configuration invalid after part exchange", "de": "Steuerger\u00e4t-Codierung nach Tausch ung\u00fcltig"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [300, 1800], "estimated_hours": [0.5, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0440','C','Steering Wheel Position Sensor Circuit','Lenkwinkelsensor Stromkreis','The steering angle sensor reports an electrical fault. ESC and lane keeping assistance functions are typically disabled.','Der Lenkwinkelsensor meldet einen elektrischen Fehler. ESC und Spurhalteassistent werden in der Regel deaktiviert.','["steering_angle_sensor", "clock_spring", "abs_control_module"]','[{"id": "sensor_failed", "p": "high", "en": "Steering angle sensor failed", "de": "Lenkwinkelsensor defekt"}, {"id": "clock_spring_fault", "p": "medium", "en": "Clock spring damaged", "de": "Wickelfeder beschaedigt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 900], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0445','C','Steering Wheel Position Sensor Calibration','Lenkwinkelsensor Kalibrierung','The steering angle sensor has not been calibrated after a service operation, or the calibration value is implausible.','Der Lenkwinkelsensor wurde nach einer Wartung nicht kalibriert oder der Kalibrierwert ist unplausibel.','["steering_angle_sensor"]','[{"id": "missing_calibration", "p": "high", "en": "Calibration not performed after alignment/repair", "de": "Kalibrierung nach Achsvermessung/Reparatur nicht durchgefuehrt"}]','{"difficulty": "easy", "diy_possible": false, "estimated_cost_eur": [40, 200], "estimated_hours": [0.2, 1]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0450','C','Rear Wheel Steering Position Sensor Circuit','Hinterradlenkungs-Positionssensor Stromkreis','On vehicles with active rear wheel steering, the rear position sensor reports an electrical fault. The system disables rear steering.','Bei Fahrzeugen mit aktiver Hinterradlenkung meldet der hintere Positionssensor einen elektrischen Fehler. Das System deaktiviert die Hinterradlenkung.','["rear_steering_position_sensor", "rear_steering_actuator"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "actuator_wiring_chafe", "p": "medium", "en": "Actuator harness chafe", "de": "Aktor-Leitungsbaum durchgescheuert"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2000], "estimated_hours": [1.5, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0455','C','Steering Wheel Position Sensor Circuit','Lenkwinkelsensor Schaltung','The chassis or stability control module has detected a fault in the steering wheel position sensor circuit. ESP and lane assist systems require an accurate steering angle and may be deactivated.','Das Fahrwerks- oder ESP-Steuergerät hat einen Fehler im Stromkreis des Lenkwinkelsensors erkannt. ESP- und Spurhaltesysteme benötigen einen genauen Lenkwinkel und können deaktiviert werden.','["steering_angle_sensor", "esp_control_module", "clock_spring"]','[{"id": "steering_angle_sensor_failed", "p": "high", "en": "Steering angle sensor failed", "de": "Lenkwinkelsensor defekt"}, {"id": "steering_angle_calibration", "p": "medium", "en": "Sensor not calibrated after alignment", "de": "Sensor nach Achsvermessung nicht kalibriert"}, {"id": "steering_sensor_wiring", "p": "low", "en": "Wiring or connector fault", "de": "Verkabelungs- oder Steckerfehler"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 800], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0460','C','Steering Position Signal Implausible','Lenkwinkelsignal unplausibel','Steering angle signal is implausible compared with yaw rate, lateral acceleration and wheel speeds.','Das Lenkwinkelsignal ist im Vergleich zu Gierrate, Querbeschleunigung und Raddrehzahlen unplausibel.','["steering_angle_sensor", "yaw_rate_sensor", "abs_control_module"]','[{"id": "alignment_off", "p": "medium", "en": "Wheel alignment off after impact", "de": "Achseinstellung nach Stoss verstellt"}, {"id": "sensor_drift", "p": "medium", "en": "Sensor drift", "de": "Sensor-Drift"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0496','C','Yaw Rate Sensor Circuit','Gierratensensor Stromkreis','The yaw rate sensor reports an electrical fault. ESC is disabled while the fault is active.','Der Gierratensensor meldet einen elektrischen Fehler. Bei aktivem Fehler wird ESC deaktiviert.','["yaw_rate_sensor", "abs_control_module", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Yaw rate sensor failed", "de": "Gierratensensor defekt"}, {"id": "wiring_short", "p": "medium", "en": "Wiring shorted", "de": "Verkabelung kurzgeschlossen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0497','C','Yaw Rate Sensor Range/Performance','Gierratensensor Bereich/Leistung','The yaw rate sensor signal is implausible relative to steering angle and lateral acceleration.','Das Gierratensensor-Signal ist im Vergleich zu Lenkwinkel und Querbeschleunigung unplausibel.','["yaw_rate_sensor", "lateral_g_sensor", "steering_angle_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor drift with age", "de": "Sensor-Drift mit Alter"}, {"id": "mounting_loose", "p": "medium", "en": "Sensor mounting loose", "de": "Sensorbefestigung lose"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0498','C','Lateral Acceleration Sensor Circuit','Querbeschleunigungssensor Stromkreis','The lateral acceleration sensor reports an electrical fault.','Der Querbeschleunigungssensor meldet einen elektrischen Fehler.','["lateral_g_sensor", "abs_control_module", "sensor_wiring"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}, {"id": "wiring_open", "p": "medium", "en": "Wiring open", "de": "Leitung unterbrochen"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0499','C','Lateral Acceleration Sensor Range/Performance','Querbeschleunigungssensor Bereich/Leistung','The lateral acceleration sensor signal is outside the plausibility range.','Das Querbeschleunigungssensor-Signal liegt ausserhalb des Plausibilitaetsbereichs.','["lateral_g_sensor", "abs_control_module"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor drift", "de": "Sensor-Drift"}, {"id": "mounting_loose", "p": "medium", "en": "Sensor mounting loose", "de": "Sensorbefestigung lose"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 800], "estimated_hours": [1, 3]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0500','C','Anti-lock Brake System Disabled','Antiblockiersystem deaktiviert','A general status code indicating that ABS function has been disabled by the brake control module. It is set in addition to the underlying root-cause code that disabled ABS.','Allgemeiner Statuscode — die ABS-Funktion wurde vom Bremssteuergerät deaktiviert. Er wird zusätzlich zum eigentlichen Ursachencode abgelegt.','["abs_control_module", "brake_system", "communication_bus"]','[{"id": "secondary_fault_present", "p": "high", "en": "Underlying ABS fault disables function", "de": "Zugrundeliegender ABS-Fehler deaktiviert die Funktion"}, {"id": "communication_bus_fault", "p": "medium", "en": "Communication bus fault to ABS module", "de": "Kommunikationsbusfehler zum ABS-Steuerger\u00e4t"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 1200], "estimated_hours": [0.3, 4]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0501','C','ESC Active Performance','ESC-Eingriff Leistung','ESC interventions occur but do not produce the expected vehicle response. May indicate hydraulic or mechanical limitation.','ESC-Eingriffe erfolgen, fuehren aber nicht zur erwarteten Fahrzeugreaktion. Hinweis auf hydraulische oder mechanische Einschraenkung.','["abs_hydraulic_block", "abs_control_module", "brake_friction"]','[{"id": "brake_pads_worn", "p": "medium", "en": "Brake pads heavily worn", "de": "Bremsbelaege stark verschlissen"}, {"id": "hydraulic_block_internal_wear", "p": "medium", "en": "Hydraulic block internal wear", "de": "Innenverschleiss im Hydraulikblock"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1600], "estimated_hours": [1, 5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0502','C','Left Front Wheel Speed Sensor A Circuit Low','Links vorne Raddrehzahlsensor A Schaltkreis niedrig','Left-front wheel speed sensor A signal voltage below expected range. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Signalspannung Raddrehzahlsensor A links vorne unter Sollbereich. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_lf", "sensor_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0503','C','Left Front Wheel Speed Sensor A Circuit High','Links vorne Raddrehzahlsensor A Schaltkreis hoch','Left-front wheel speed sensor A signal voltage above expected range. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Signalspannung Raddrehzahlsensor A links vorne über Sollbereich. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_lf", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open or short to power", "de": "Signalleitung unterbrochen oder Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0504','C','Left Front Wheel Speed Sensor A Intermittent/Erratic','Links vorne Raddrehzahlsensor A sporadisch/unstetig','Intermittent or erratic signal from left-front wheel speed sensor A. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Sporadisches oder unruhiges Signal vom Raddrehzahlsensor A links vorne. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatu','["wss_lf", "sensor_wiring"]','[{"id": "connector_loose", "p": "high", "en": "Connector loose or chafed wiring", "de": "Stecker locker oder Verkabelung gescheuert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0505','C','ESC Switch Circuit','ESC-Schalter Stromkreis','The ESC on/off switch reports an implausible state.','Der ESC-Ein/Aus-Schalter meldet einen unplausiblen Zustand.','["esc_switch", "dashboard_wiring"]','[{"id": "switch_failed", "p": "high", "en": "Switch failed", "de": "Schalter defekt"}, {"id": "wiring_short", "p": "medium", "en": "Wiring shorted", "de": "Verkabelung kurzgeschlossen"}]','{"difficulty": "easy", "diy_possible": true, "estimated_cost_eur": [30, 200], "estimated_hours": [0.3, 1.5]}',0);
INSERT OR IGNORE INTO dtc_codes VALUES('C0506','C','Right Front Wheel Speed Sensor A Circuit/Open','Rechts vorne Raddrehzahlsensor A Schaltkreis unterbrochen','Open circuit on right-front wheel speed sensor A. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Unterbrochener Schaltkreis am Raddrehzahlsensor A rechts vorne. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_rf", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wire broken or connector unplugged", "de": "Kabelbruch oder Stecker ab"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0507','C','Right Front Wheel Speed Sensor A Range/Performance','Rechts vorne Raddrehzahlsensor A Bereich/Leistung','Right-front wheel speed sensor A reading implausible. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Wert des Raddrehzahlsensors A rechts vorne unstimmig. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_rf"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0508','C','Right Front Wheel Speed Sensor A Circuit Low','Rechts vorne Raddrehzahlsensor A Schaltkreis niedrig','Right-front WSS A signal voltage below expected range. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Signalspannung WSS A rechts vorne unter Sollbereich. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_rf", "sensor_wiring"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0509','C','Right Front Wheel Speed Sensor A Circuit High','Rechts vorne Raddrehzahlsensor A Schaltkreis hoch','Right-front WSS A signal voltage above expected range. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Signalspannung WSS A rechts vorne über Sollbereich. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_rf", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open or short to power", "de": "Signalleitung unterbrochen oder Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C050A','C','Right Front Wheel Speed Sensor A Intermittent/Erratic','Rechts vorne Raddrehzahlsensor A sporadisch/unstetig','Intermittent signal from right-front WSS A. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Sporadisches Signal vom WSS A rechts vorne. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_rf", "sensor_wiring"]','[{"id": "connector_loose", "p": "high", "en": "Connector loose or chafed wiring", "de": "Stecker locker oder Verkabelung gescheuert"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [40, 350], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C050B','C','Right Front Wheel Speed Sensor A Correlation','Rechts vorne Raddrehzahlsensor A Korrelation','Right-front WSS A reading does not correlate with the other wheel speed sensors during straight-line driving. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functi','Rechts-vorne-WSS A korreliert bei Geradeausfahrt nicht mit den anderen Raddrehzahlsensoren. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktio','["wss_rf"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor or tone ring drifted", "de": "Sensor oder Polrad verschoben"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 400], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C050C','C','Left Rear Wheel Speed Sensor A Circuit/Open','Links hinten Raddrehzahlsensor A Schaltkreis unterbrochen','Open circuit on left-rear WSS A. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Unterbrochener Schaltkreis am WSS A links hinten. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_lr", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wire broken or connector unplugged", "de": "Kabelbruch oder Stecker ab"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C050D','C','Left Rear Wheel Speed Sensor A Range/Performance','Links hinten Raddrehzahlsensor A Bereich/Leistung','Left-rear WSS A reading implausible. Wheel-speed signals feed ABS, ESC, traction control, transmission and odometer — a single dropped signal disables all of these safety functions until repaired.','Wert des WSS A links hinten unstimmig. Raddrehzahl-Signale speisen ABS, ESP, Traktionskontrolle, Getriebe und Tachometer — ein einziges ausgefallenes Signal deaktiviert all diese Sicherheitsfunktionen bis zur Reparatur.','["wss_lr"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [60, 400], "estimated_hours": [0.5, 2]}',1);
