INSERT OR IGNORE INTO dtc_codes VALUES('C0599','C','Brake Booster Control Module Missing Calibration','Bremskraftverstärker-Steuermodul Kalibrierung fehlt','Brake booster control module not calibrated — typically required after replacement. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Booster-Steuermodul nicht kalibriert — meist nach Tausch erforderlich. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck li','["brake_booster_module"]','[{"id": "missing_calibration", "p": "high", "en": "Calibration not performed", "de": "Kalibrierung fehlt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
