INSERT OR IGNORE INTO dtc_codes VALUES('C05AF','C','Brake Booster Motor B Current Sensor Circuit Range/Performance','Bremskraftverstärker Motor B Stromsensor Bereich/Leistung','Brake Booster Motor B Current Sensor Circuit Range/Performance: the signal is implausible or outside the valid range. The electric brake booster generates the braking assist; a motor or sensor fault can reduce or disable power-assisted braking. Safet','Bremskraftverstärker Motor B Stromsensor Bereich/Leistung: das Signal ist unplausibel bzw. außerhalb des gültigen Bereichs. Der elektrische Bremskraftverstärker erzeugt die Bremsunterstützung; ein Motor- oder Sensorfehler kann die Bremskraftunterstüt','["booster_motor_b_current_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B0','C','Brake Hydraulic Circuit C Leak','Bremshydraulikkreis C Leck','Pressure loss in brake hydraulic circuit C.','Druckverlust im Bremshydraulikkreis C.','["brake_circuit_c"]','[{"id": "hydraulic_leak", "p": "high", "en": "Brake fluid leak in circuit C", "de": "Bremsfl\u00fcssigkeitsleck in Kreis C"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B1','C','Brake Hydraulic Circuit D Leak','Bremshydraulikkreis D Leck','Pressure loss in brake hydraulic circuit D.','Druckverlust im Bremshydraulikkreis D.','["brake_circuit_d"]','[{"id": "hydraulic_leak", "p": "high", "en": "Brake fluid leak in circuit D", "de": "Bremsfl\u00fcssigkeitsleck in Kreis D"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B2','C','Steering Wheel Angle Sensor Signal - Yaw Rate Sensor Signal Correlation','Lenkradwinkelsensor zu Gierrate-Sensor Korrelation','Steering wheel angle and yaw rate sensor signals do not correlate during driving.','Lenkradwinkel- und Gierraten-Sensor korrelieren während der Fahrt nicht.','["steering_angle_sensor", "yaw_rate_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B3','C','Brake Booster Temperature Sensor C Circuit Low','Bremskraftverstärker Temperatursensor C niedrig','Brake booster temperature sensor C signal voltage below expected range. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Signalspannung Temperatursensor C unter Sollbereich. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["brake_booster_temp_sensor_c"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B4','C','Brake Booster Temperature Sensor C Circuit High','Bremskraftverstärker Temperatursensor C hoch','Brake booster temperature sensor C signal voltage above expected range. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Signalspannung Temperatursensor C über Sollbereich. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["brake_booster_temp_sensor_c"]','[{"id": "short_to_power", "p": "high", "en": "Signal wire shorted to battery", "de": "Signalleitung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05B5','C','Brake Booster Temperature Sensor C Circuit/Open','Bremskraftverstärker Temperatursensor C unterbrochen','Open circuit on brake booster temperature sensor C. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Unterbrochener Schaltkreis am Temperatursensor C. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["brake_booster_temp_sensor_c"]','[{"id": "open_wiring", "p": "high", "en": "Signal wire open", "de": "Signalleitung unterbrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [1, 4]}',1);
