INSERT OR IGNORE INTO dtc_codes VALUES('C05B7','C','Brake Booster Temperature Sensor C Circuit Intermittent/Erratic','Bremskraftverstärker Temperatursensor C sporadisch/unstetig','Intermittent signal from brake booster temperature sensor C. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Sporadisches Signal vom Temperatursensor C. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefern.','["brake_booster_temp_sensor_c"]','[{"id": "connector_loose", "p": "high", "en": "Connector loose", "de": "Stecker locker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 3]}',1);
