INSERT OR IGNORE INTO dtc_codes VALUES('C05C7','C','Brake Pressure Sensor F Circuit High','Bremsdrucksensor F Schaltkreis hoch','Brake pressure sensor F signal voltage above expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the locatio','Signalspannung Bremsdrucksensor F über Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler','["brake_pressure_sensor_f", "sensor_wiring"]','[{"id": "short_to_power", "p": "high", "en": "Signal wire shorted to battery", "de": "Signalleitung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05C8','C','Brake Pressure Sensor F Circuit/Open','Bremsdrucksensor F unterbrochen','Open circuit on brake pressure sensor F.','Unterbrochener Schaltkreis am Bremsdrucksensor F.','["brake_pressure_sensor_f", "sensor_wiring"]','[{"id": "open_wiring", "p": "high", "en": "Wire broken", "de": "Kabel gebrochen"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05C9','C','Brake Pressure Sensor Supply Circuit','Bremsdrucksensor Versorgung','Generic fault on the supply voltage shared between brake pressure sensors.','Allgemeiner Fehler an der gemeinsamen Versorgungsspannung der Bremsdrucksensoren.','["brake_pressure_sensor_supply"]','[{"id": "supply_fault", "p": "high", "en": "Supply wiring fault", "de": "Versorgungsleitung defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 400], "estimated_hours": [0.5, 2]}',1);
