INSERT OR IGNORE INTO dtc_codes VALUES('C05CD','C','Brake Master Cylinder Piston Position Sensor B Circuit Voltage High','Bremshauptzylinder Kolben-Positionssensor B Spannung hoch','Brake master cylinder piston position sensor B signal voltage above expected range.','Signalspannung Hauptzylinder-Kolben-Positionssensor B über Sollbereich.','["master_cylinder_pos_sensor_b"]','[{"id": "short_to_power", "p": "high", "en": "Signal wire shorted to battery", "de": "Signalleitung mit Plus-Schluss"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05CE','C','Brake Master Cylinder Piston Position Sensor B Circuit Voltage Low','Bremshauptzylinder Kolben-Positionssensor B Spannung niedrig','Master cylinder piston position sensor B signal voltage below expected range.','Signalspannung Hauptzylinder-Kolben-Positionssensor B unter Sollbereich.','["master_cylinder_pos_sensor_b"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05CF','C','Brake Master Cylinder Piston Position Sensor B Circuit Range/Performance','Bremshauptzylinder Kolben-Positionssensor B Bereich/Leistung','Brake Master Cylinder Piston Position Sensor B Circuit Range/Performance: the signal is implausible or outside the valid range.','Bremshauptzylinder Kolben-Positionssensor B Bereich/Leistung: das Signal ist unplausibel bzw. außerhalb des gültigen Bereichs.','["master_cylinder_pos_sensor_b"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D0','C','Brake Master Cylinder Piston Position Sensor A/B Correlation','Bremshauptzylinder Kolben-Positionssensor A/B Korrelation','Master cylinder piston position sensors A and B disagree beyond plausible deviation.','Hauptzylinder-Positionssensoren A und B weichen über plausibles Maß ab.','["master_cylinder_pos_sensor_a", "master_cylinder_pos_sensor_b"]','[{"id": "sensor_drift", "p": "high", "en": "One sensor drifted", "de": "Einer der Sensoren verschoben"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D1','C','Brake Master Cylinder Piston Position Sensor Supply Circuit','Bremshauptzylinder Kolben-Positionssensor Versorgung','Generic fault on master cylinder piston position sensor supply circuit.','Allgemeiner Fehler an der Versorgung des Hauptzylinder-Kolben-Positionssensors.','["master_cylinder_pos_sensor_supply"]','[{"id": "supply_fault", "p": "high", "en": "Supply wiring fault", "de": "Versorgungsleitung defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D2','C','Master Cylinder Piston Position Higher Than Expected','Hauptzylinder-Kolbenposition höher als erwartet','Master cylinder piston position higher than expected — typically too much pedal travel for the commanded brake pressure.','Hauptzylinder-Kolbenposition höher als erwartet — meist zu viel Pedalweg für den angeforderten Bremsdruck.','["master_cylinder"]','[{"id": "brake_system_air", "p": "high", "en": "Air in brake system or fluid leak", "de": "Luft im Bremssystem oder Leck"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D3','C','Driver Applied Pressure Higher Than Expected','Vom Fahrer aufgebrachter Druck höher als erwartet','Driver-applied brake pressure measured higher than expected for the pedal travel — points to a stuck valve or restricted hydraulic path.','Vom Fahrer aufgebrachter Bremsdruck höher als für den Pedalweg erwartet — Hinweis auf klemmendes Ventil oder behinderten Hydraulikweg.','["hcu", "brake_lines"]','[{"id": "hydraulic_blockage", "p": "high", "en": "Hydraulic restriction or stuck valve", "de": "Hydraulische Drosselung oder klemmendes Ventil"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D4','C','Brake Master Cylinder Piston Position Sensor Calibration Not Learned','Bremshauptzylinder Kolben-Positionssensor Kalibrierung nicht gelernt','Master cylinder piston position sensor calibration not learned.','Kalibrierung des Hauptzylinder-Kolben-Positionssensors nicht gelernt.','["master_cylinder_pos_sensors"]','[{"id": "missing_calibration", "p": "high", "en": "Calibration not performed", "de": "Kalibrierung fehlt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [50, 300], "estimated_hours": [0.3, 1.5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D5','C','Brake Master Cylinder Cut Off Valve','Bremshauptzylinder Trennventil','Fault on master cylinder cut-off valve — used in brake-by-wire systems to isolate the master cylinder during normal electric boost.','Fehler am Trennventil des Hauptzylinders — bei Brake-by-Wire-Systemen zum Trennen des Hauptzylinders während elektrischer Bremskraftverstärkung.','["master_cylinder_cutoff_valve"]','[{"id": "valve_stuck", "p": "high", "en": "Valve stuck or coil failed", "de": "Ventil klemmt oder Spule defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D6','C','Power Steering Control Module Processor Performance','Servolenkungs-Steuermodul Prozessor Leistung','Power steering control module processor reports an internal performance fault.','Prozessor des Servolenkungs-Moduls meldet einen internen Leistungsfehler.','["eps_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}, {"id": "needs_reflash", "p": "low", "en": "Module software outdated, reflash may resolve", "de": "Modul-Software veraltet, Reflash kann helfen"}, {"id": "voltage_supply_issue", "p": "low", "en": "Supply voltage outside specification", "de": "Versorgungsspannung au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D7','C','Brake Transmission Shift Interlock (BTSI) Control Circuit','Bremspedal-Schaltsperre (BTSI) Schaltkreis','Fault on the brake transmission shift interlock (BTSI) circuit — prevents shifting from Park unless brake pedal is depressed.','Fehler am Schaltkreis der Bremspedal-Schaltsperre (BTSI) — verhindert Wahlhebel aus Park ohne getretenes Bremspedal.','["btsi_solenoid"]','[{"id": "solenoid_fault", "p": "high", "en": "BTSI solenoid fault", "de": "BTSI-Magnetventil defekt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D8','C','4WD/AWD Clutch A Actuator Control Circuit/Open','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis unterbrochen','4WD/AWD Clutch A Actuator Control Circuit/Open: the control circuit is open. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis unterbrochen: der Steuerkreis ist unterbrochen. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_actuator"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05D9','C','4WD/AWD Clutch A Actuator Control Circuit Performance','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis Leistung','4WD/AWD Clutch A Actuator Control Circuit Performance: the control circuit has an electrical fault. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis Leistung: im Steuerkreis liegt ein elektrischer Fehler vor. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_actuator"]','[{"id": "actuator_drift", "p": "high", "en": "Actuator response drifted", "de": "Aktuator-Reaktion verschoben"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 6]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DA','C','4WD/AWD Clutch A Actuator Control Circuit Low','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis niedrig','4WD/AWD Clutch A Actuator Control Circuit Low: the control-circuit voltage is below the expected range. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis niedrig: die Spannung im Steuerkreis liegt unter dem erwarteten Bereich. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_actuator"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DB','C','4WD/AWD Clutch A Actuator Control Circuit High','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis hoch','4WD/AWD Clutch A Actuator Control Circuit High: the control-circuit voltage is above the expected range. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Aktuator-Steuerschaltkreis hoch: die Spannung im Steuerkreis liegt über dem erwarteten Bereich. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_actuator"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DC','C','4WD/AWD Clutch A Temperature Too High','4WD/AWD Kupplung A Temperatur zu hoch','4WD/AWD Clutch A Temperature Too High: the component is overheating, typically from extended load or slip. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Temperatur zu hoch: das Bauteil überhitzt, meist durch andauernde Last oder Schlupf. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a"]','[{"id": "thermal_overload", "p": "high", "en": "Thermal overload from slip", "de": "Thermische \u00dcberlast durch Schlupf"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DD','C','4WD/AWD Clutch A Performance/Stuck Disengaged','4WD/AWD Kupplung A Leistung/klemmt offen','4WD/AWD Clutch A Performance/Stuck Disengaged: the actuator will not engage when commanded. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Leistung/klemmt offen: das Stellglied rückt auf Befehl nicht ein. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a"]','[{"id": "clutch_worn", "p": "high", "en": "Clutch plates worn or actuator stuck", "de": "Kupplungslamellen verschlissen oder Aktuator klemmt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DE','C','4WD/AWD Clutch A Stuck Engaged','4WD/AWD Kupplung A klemmt geschlossen','4WD/AWD Clutch A Stuck Engaged: the actuator stays engaged even when commanded off. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A klemmt geschlossen: das Stellglied bleibt trotz Abschaltbefehl eingerückt. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a"]','[{"id": "clutch_stuck_engaged", "p": "high", "en": "Clutch stuck engaged or actuator binding", "de": "Kupplung verklebt oder Aktuator hakt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05DF','C','4WD/AWD Clutch A Engagement Fault','4WD/AWD Kupplung A Schaltfehler','4WD/AWD Clutch A Engagement Fault: engagement is sluggish, partial, or incomplete. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Schaltfehler: das Einrücken ist träge, teilweise oder unvollständig. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a"]','[{"id": "clutch_worn", "p": "high", "en": "Clutch plates worn", "de": "Kupplungslamellen verschlissen"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [2, 8]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05E0','C','4WD/AWD Clutch A Position Sensor Circuit','4WD/AWD Kupplung A Positionssensor Schaltkreis','Generic fault on AWD clutch A position sensor.','Allgemeiner Fehler am Positionssensor der AWD-Kupplung A.','["awd_clutch_a_pos_sensor"]','[{"id": "sensor_failed", "p": "high", "en": "Position sensor failed", "de": "Positionssensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05E1','C','4WD/AWD Clutch A Position Sensor Circuit Range/Performance','4WD/AWD Kupplung A Positionssensor Bereich/Leistung','AWD clutch A position sensor reading implausible. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Wert des Kupplungs-Positionssensors A unstimmig. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler of','["awd_clutch_a_pos_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05E2','C','4WD/AWD Clutch A Position Sensor Circuit Low','4WD/AWD Kupplung A Positionssensor niedrig','4WD/AWD Clutch A Position Sensor Circuit Low: the signal voltage is below the expected range. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Positionssensor niedrig: die Signalspannung liegt unter dem erwarteten Bereich. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_pos_sensor"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 1000], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05E3','C','4WD/AWD Clutch A Position Sensor Circuit High','4WD/AWD Kupplung A Positionssensor hoch','4WD/AWD Clutch A Position Sensor Circuit High: the signal voltage is above the expected range. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Kupplung A Positionssensor hoch: die Signalspannung liegt über dem erwarteten Bereich. Dies betrifft das Einrücken der Allrad-Kupplung.','["awd_clutch_a_pos_sensor"]','[{"id": "short_to_power", "p": "high", "en": "Signal wire shorted to battery", "de": "Signalleitung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 1000], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05E4','C','4WD/AWD Clutch A Position Sensor Circuit Intermittent','4WD/AWD Kupplung A Positionssensor sporadisch','Intermittent signal from AWD clutch A position sensor. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Sporadisches Signal vom Positionssensor. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["awd_clutch_a_pos_sensor"]','[{"id": "connector_loose", "p": "high", "en": "Connector loose", "de": "Stecker locker"}, {"id": "connector_intermittent", "p": "low", "en": "Connector with intermittent contact under vibration", "de": "Stecker mit sporadischem Kontakt unter Vibration"}, {"id": "harness_vibration", "p": "low", "en": "Harness routed against vibrating component", "de": "Kabelbaum verl\u00e4uft an vibrierender Komponente"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 800], "estimated_hours": [0.5, 3]}',1);
