INSERT OR IGNORE INTO dtc_codes VALUES('C05FC','C','4WD/AWD Range Actuator Position Sensor Circuit Range/Performance','4WD/AWD Bereichswähler-Positionssensor Bereich/Leistung','Range actuator position sensor reading implausible. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Wert des Positionssensors unstimmig. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["range_pos_sensor"]','[{"id": "sensor_drift", "p": "high", "en": "Sensor reading drifted", "de": "Sensorwert verschoben"}, {"id": "sensor_aged", "p": "low", "en": "Sensor element aged beyond calibration window", "de": "Sensorelement gealtert \u00fcber Kalibrierfenster hinaus"}, {"id": "mounting_loose", "p": "low", "en": "Sensor mounting loose - signal damping", "de": "Sensorbefestigung lose - Signald\u00e4mpfung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C05FD','C','4WD/AWD Range Actuator Position Sensor Circuit Low','4WD/AWD Bereichswähler-Positionssensor niedrig','4WD/AWD Range Actuator Position Sensor Circuit Low: the signal voltage is below the expected range. This affects engagement of the all-wheel-drive clutch.','4WD/AWD Bereichswähler-Positionssensor niedrig: die Signalspannung liegt unter dem erwarteten Bereich. Dies betrifft das Einrücken der Allrad-Kupplung.','["range_pos_sensor"]','[{"id": "short_to_ground", "p": "high", "en": "Signal wire shorted to ground", "de": "Signalleitung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
