INSERT OR IGNORE INTO dtc_codes VALUES('C0616','C','Park Brake Control Module Control Circuit Performance','Feststellbrems-Steuermodul Schaltkreis Leistung','Park brake control module reports a performance fault on its actuator drive circuit.','Feststellbrems-Steuermodul meldet Leistungsfehler an der Aktuator-Ansteuerung.','["epb_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0617','C','Park Brake Control Module Control Circuit Low','Feststellbrems-Steuermodul Schaltkreis niedrig','Park brake control module supply voltage below expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the locat','Versorgungsspannung des EPB-Moduls unter Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehl','["epb_module", "power_supply"]','[{"id": "low_battery", "p": "high", "en": "Low battery or weak supply", "de": "Schwache Batterie oder Versorgung"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [80, 600], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0618','C','Park Brake Control Module Control Circuit High','Feststellbrems-Steuermodul Schaltkreis hoch','Park brake control module supply voltage above expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the locat','Versorgungsspannung des EPB-Moduls über Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehle','["epb_module", "alternator"]','[{"id": "overvoltage", "p": "high", "en": "Charging system overvoltage", "de": "\u00dcberspannung im Ladesystem"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [100, 1000], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0619','C','Brake Pedal Position Sensor A Offset Exceeded Learning Limit','Bremspedal-Positionssensor A Lerngrenze überschritten','Brake Pedal Position Sensor A Offset Exceeded Learning Limit: the control module has detected this fault condition.','Bremspedal-Positionssensor A Lerngrenze überschritten: das Steuergerät hat diesen Fehlerzustand erkannt.','["brake_pedal_sensor_a"]','[{"id": "pedal_misalignment", "p": "high", "en": "Pedal mechanically misaligned", "de": "Pedal mechanisch verschoben"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061A','C','Brake Pedal Position Sensor B Offset Exceeded Learning Limit','Bremspedal-Positionssensor B Lerngrenze überschritten','Brake Pedal Position Sensor B Offset Exceeded Learning Limit: the control module has detected this fault condition.','Bremspedal-Positionssensor B Lerngrenze überschritten: das Steuergerät hat diesen Fehlerzustand erkannt.','["brake_pedal_sensor_b"]','[{"id": "pedal_misalignment", "p": "high", "en": "Pedal mechanically misaligned", "de": "Pedal mechanisch verschoben"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [80, 500], "estimated_hours": [0.5, 2]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061B','C','ECM Request - Forced Traction Control Disable','ECM-Anforderung – Traktionskontrolle erzwungen aus','Engine control module requests forced disable of traction control — typically when the engine cannot deliver requested torque reduction.','Motorsteuerung fordert das Abschalten der Traktionskontrolle an — meist wenn die geforderte Drehmomentreduktion nicht möglich ist.','["ecm", "tcs_module"]','[{"id": "ecm_communication_fault", "p": "high", "en": "ECM/TCS communication issue", "de": "Kommunikationsfehler ECM/TCS"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061C','C','Variable Effort Steering Actuator Control Circuit/Open','Variable Lenkkraft-Aktuator Steuerschaltkreis unterbrochen','Open circuit on variable effort steering (VES) actuator. VES varies steering assist with vehicle speed.','Unterbrochener Schaltkreis am Aktuator der variablen Lenkkraft (VES). VES verändert die Lenkunterstützung je nach Geschwindigkeit.','["ves_actuator"]','[{"id": "open_wiring", "p": "high", "en": "Wiring break", "de": "Kabelbruch"}, {"id": "connector_back_out", "p": "low", "en": "Pin pushed back out of connector body", "de": "Pin aus dem Steckergeh\u00e4use zur\u00fcckgedr\u00fcckt"}, {"id": "solder_joint_cracked", "p": "low", "en": "Cracked solder joint inside the module or sensor", "de": "Gerissene L\u00f6tstelle im Modul oder Sensor"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1200], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061D','C','Variable Effort Steering Actuator Control Circuit Low','Variable Lenkkraft-Aktuator niedrig','VES actuator control voltage below expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Steuerspannung VES-Aktuator unter Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["ves_actuator"]','[{"id": "short_to_ground", "p": "high", "en": "Wiring shorted to ground", "de": "Verkabelung mit Masseschluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061E','C','Variable Effort Steering Actuator Control Circuit High','Variable Lenkkraft-Aktuator hoch','VES actuator control voltage above expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Steuerspannung VES-Aktuator über Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler oft.','["ves_actuator"]','[{"id": "short_to_power", "p": "high", "en": "Wiring shorted to battery", "de": "Verkabelung mit Plus-Schluss"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "supply_pinch", "p": "low", "en": "Supply wire pinched against B+ source", "de": "Versorgungsleitung gegen B+-Quelle eingeklemmt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 800], "estimated_hours": [0.5, 3]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C061F','C','Variable Effort Steering Actuator Control Circuit Performance','Variable Lenkkraft-Aktuator Leistung','VES actuator does not respond as expected.','VES-Aktuator reagiert nicht erwartungsgemäß.','["ves_actuator"]','[{"id": "actuator_drift", "p": "high", "en": "Actuator drift or mechanical bind", "de": "Aktuator-Drift oder mechanischer H\u00e4nger"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0620','C','Park Assist Module Communication','Park-Assistent Steuergerät Kommunikation','The chassis control module has detected a communication fault with the park assist module. Parking sensors, surround view and automatic parking functions are unavailable until communication is restored.','Das Fahrwerks-Steuergerät hat einen Kommunikationsfehler mit dem Park-Assistent-Steuergerät erkannt. Einparksensoren, Umgebungssicht und automatisches Einparken stehen bis zur Wiederherstellung der Kommunikation nicht zur Verfügung.','["park_assist_module", "communication_bus", "chassis_control_module"]','[{"id": "communication_bus_fault", "p": "high", "en": "Communication bus fault", "de": "Kommunikationsbus-Fehler"}, {"id": "park_assist_module_failed", "p": "medium", "en": "Park assist module failed", "de": "Park-Assistent-Steuerger\u00e4t defekt"}, {"id": "power_supply_module", "p": "low", "en": "Power supply or ground fault to module", "de": "Versorgungs- oder Masseschluss am Steuerger\u00e4t"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [100, 1000], "estimated_hours": [0.5, 3]}',0);
