INSERT OR IGNORE INTO dtc_codes VALUES('C0623','C','Variable Effort Steering Lock/Safety Actuator Control Circuit Performance','Variable Lenkkraft Sperr-/Sicherheits-Aktuator Leistung','VES safety lock actuator does not respond as expected.','Sicherheits-Sperr-Aktuator reagiert nicht erwartungsgemäß.','["ves_lock_actuator"]','[{"id": "actuator_stuck", "p": "high", "en": "Actuator stuck", "de": "Aktuator klemmt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [200, 1500], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0624','C','Variable Effort Steering Sensor Circuit','Variable Lenkkraft Sensor Schaltkreis','Generic fault on VES feedback sensor.','Allgemeiner Fehler am Rückkopplungssensor der variablen Lenkkraft.','["ves_sensor"]','[{"id": "sensor_failed", "p": "high", "en": "Sensor failed", "de": "Sensor defekt"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1000], "estimated_hours": [1, 3]}',1);
