INSERT OR IGNORE INTO dtc_codes VALUES('C0628','C','Variable Effort Steering Module Performance','Variable Lenkkraft Modul Leistung','VES control module reports an internal performance fault.','VES-Steuermodul meldet einen internen Leistungsfehler.','["ves_module"]','[{"id": "module_internal_fault", "p": "high", "en": "Module internal fault", "de": "Interner Modulfehler"}, {"id": "needs_reflash", "p": "low", "en": "Module software outdated, reflash may resolve", "de": "Modul-Software veraltet, Reflash kann helfen"}, {"id": "voltage_supply_issue", "p": "low", "en": "Supply voltage outside specification", "de": "Versorgungsspannung au\u00dferhalb der Spezifikation"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0629','C','Variable Effort Steering Control Module Incorrect Component Installed','Variable Lenkkraft Modul falsche Komponente verbaut','VES module detects a mismatched or incorrect component installed.','VES-Modul erkennt eine nicht passende oder falsche Komponente.','["ves_module"]','[{"id": "wrong_part", "p": "high", "en": "Wrong replacement part", "de": "Falsches Ersatzteil verbaut"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C062A','C','Variable Effort Steering Module Temperature Too High','Variable Lenkkraft Modul Temperatur zu hoch','VES module exceeded its safe operating temperature.','VES-Modul hat die zulässige Betriebstemperatur überschritten.','["ves_module"]','[{"id": "thermal_overload", "p": "high", "en": "Thermal overload from extended high-effort steering", "de": "Thermische \u00dcberlast bei dauerhaftem starkem Lenken"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [200, 2000], "estimated_hours": [1, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C062B','C','Variable Effort Steering Module Temperature Too Low','Variable Lenkkraft Modul Temperatur zu niedrig','VES module reports an implausibly low operating temperature.','VES-Modul meldet unplausibel niedrige Betriebstemperatur.','["ves_module"]','[{"id": "temp_sensor_fault", "p": "high", "en": "Internal temperature sensor fault", "de": "Interner Temperatursensor defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [1, 5]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C062C','C','Brake Booster Motor B Performance','Bremskraftverstärker Motor B Leistung','Brake booster motor B does not deliver expected performance. Boost control tracks commanded vs. actual manifold pressure; persistent deviation means wastegate, vanes, hose or actuator are not delivering the requested pressure.','Bremskraftverstärker-Motor B liefert nicht die erwartete Leistung. Die Ladedruck-Regelung vergleicht Soll- und Ist-Saugrohrdruck; anhaltende Abweichung bedeutet, dass Wastegate, VTG-Schaufeln, Schlauch oder Aktuator nicht den geforderten Druck liefer','["brake_booster_motor_b"]','[{"id": "motor_worn", "p": "high", "en": "Motor worn or weak", "de": "Motor verschlissen oder schwach"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 3000], "estimated_hours": [2, 6]}',1);
