INSERT OR IGNORE INTO dtc_codes VALUES('C062E','C','Active Air Dam Supply Voltage Circuit Low','Aktiver Luftleitspoiler Versorgungsspannung niedrig','Active air dam supply voltage below expected range. Wiring faults of this kind typically come from chafing, water ingress at connector seals, or pin push-back — a wiggle test on the harness while the code is active often confirms the location.','Versorgungsspannung Luftspoiler unter Sollbereich. Verkabelungsfehler dieser Art kommen typischerweise von Scheuern, Wassereintritt an Steckerdichtungen oder zurückgedrückten Pins — ein Wackeltest am Kabelbaum bei aktivem Code lokalisiert den Fehler ','["active_air_dam_actuator", "power_supply"]','[{"id": "supply_fault", "p": "high", "en": "Supply wiring fault", "de": "Versorgungsleitung defekt"}, {"id": "connector_corrosion", "p": "low", "en": "Connector pins corroded - high contact resistance", "de": "Steckerkontakte korrodiert - hoher \u00dcbergangswiderstand"}, {"id": "harness_chafe", "p": "low", "en": "Harness chafing through insulation", "de": "Kabelbaum scheuert sich durch die Isolation"}]','{"difficulty": "medium", "diy_possible": true, "estimated_cost_eur": [50, 500], "estimated_hours": [0.5, 2]}',1);
