INSERT OR IGNORE INTO dtc_codes VALUES('C0630','C','Active Air Dam Stuck','Aktiver Luftleitspoiler klemmt','Active air dam stuck mechanically — does not extend or retract.','Aktiver Luftspoiler mechanisch klemmend — fährt nicht aus oder ein.','["active_air_dam"]','[{"id": "mechanical_bind", "p": "high", "en": "Mechanical bind from debris or damage", "de": "Mechanischer H\u00e4nger durch Schmutz oder Besch\u00e4digung"}]','{"difficulty": "medium", "diy_possible": false, "estimated_cost_eur": [150, 1500], "estimated_hours": [0.5, 4]}',1);
INSERT OR IGNORE INTO dtc_codes VALUES('C0631','C','Front Axle Disconnect Actuator','Vorderachs-Trennkupplung Aktuator','Generic fault on front axle disconnect actuator. The disconnect decouples the front axle from the drivetrain to save fuel in 2WD mode.','Allgemeiner Fehler am Aktuator der Vorderachs-Trennkupplung. Die Trennung entkoppelt im 2WD-Modus die Vorderachse vom Antriebsstrang zur Kraftstoffersparnis.','["front_axle_disconnect_actuator"]','[{"id": "actuator_failed", "p": "high", "en": "Actuator failed", "de": "Aktuator defekt"}]','{"difficulty": "hard", "diy_possible": false, "estimated_cost_eur": [400, 2500], "estimated_hours": [2, 6]}',1);
